import { primarySessionBadge } from '/js/primary-session-render.mjs';

// ── Sales Nav Board ──────────────────────────────────────────────────────────
let snCurrentEmail = '';
async function loadOperatorEmail() {
  try { const r = await fetch('/api/operator-identity'); const d = await r.json(); snCurrentEmail = (d && d.email) || ''; }
  catch { snCurrentEmail = ''; }
}

// Viewer's LOGIN identity + admin flag (from /api/me, driven by ADMIN_EMAILS).
// Admin sees every cloud campaign + the Conductor filter; everyone else sees
// only their own. Distinct from snCurrentEmail (the per-machine operator).
let _viewerEmail = '';
let _viewerIsAdmin = false;
async function loadViewerIdentity() {
  try { const d = await (await fetch('/api/me')).json(); _viewerEmail = (d && d.email) || ''; _viewerIsAdmin = !!(d && d.admin); }
  catch { _viewerEmail = ''; _viewerIsAdmin = false; }
}

let _snPollTimer = null;
let _snPollInFlight = false; // guard so slow polls don't stack (each poll every 2.5s)
let _snEverLoaded = false;   // have we rendered the board successfully at least once?
let _snConsecFail = 0;       // consecutive failed polls before the first success
// Navigate to the Sales Nav board (its own top-level route #/salesnav). The
// router (applyRoute) calls openSalesNavBoard() on entry to load + start polling.
function goSalesNav() { window.location.hash = '#/salesnav'; }
window.goSalesNav = goSalesNav;

// Route-entry initializer for the board. View visibility is handled by the
// #/salesnav route (body.route-salesnav in the router + CSS), NOT by toggling
// section display here.
// Last good board, persisted. The campaigns dashboard renders from local files
// and paints instantly; this board has no local state at all — every strip is
// derived from the engine's /api/jobs, which currently ships ~15MB. So opening
// the tab meant staring at "Loading scrapes…" for the length of a cold round
// trip to the VM, every single time.
//
// The cache is DISPLAY ONLY: it paints immediately, then the normal 2.5s poll
// overwrites it with live data. Stored whole (never truncated) because the
// strips' action handlers read search URLs straight off the rendered data — a
// shortened URL here would mean a Re-run firing at the wrong search.
const SN_CACHE_KEY = 'snBoardCache1';

function _snSaveCache(campaigns) {
  // Shrink on quota failure rather than giving up: a handful of scrapes carry
  // 80KB search URLs, so the full board can exceed the localStorage budget on
  // its own. Half the strips cached still beats a cold board.
  for (const cap of [80, 40, 15, 5]) {
    try {
      localStorage.setItem(SN_CACHE_KEY, JSON.stringify({ at: Date.now(), campaigns: campaigns.slice(0, cap) }));
      return;
    } catch (_) { /* quota — try a smaller slice */ }
  }
  try { localStorage.removeItem(SN_CACHE_KEY); } catch (_) { /* */ }
}

function _snLoadCache() {
  try {
    const raw = localStorage.getItem(SN_CACHE_KEY);
    if (!raw) return null;
    const d = JSON.parse(raw);
    return (d && Array.isArray(d.campaigns) && d.campaigns.length) ? d.campaigns : null;
  } catch (_) { return null; }
}

async function openSalesNavBoard() {
  // Paint the cached board BEFORE any await, so the tab is never empty. Guarded
  // so a corrupt cache can't stop the live load that follows.
  const cached = _snLoadCache();
  if (cached && !_snEverLoaded) {
    try {
      renderSalesNavBoard(cached);
      // Don't let cached statuses seed the handover detector — comparing a live
      // poll against a cache from an hour ago fires phantom "X stopped" toasts.
      _snPrevStatus = new Map();
    } catch (_) { /* fall through to the normal cold load */ }
  }
  await loadOperatorEmail();
  await pollSalesNavBoard();
  clearInterval(_snPollTimer);
  _snPollTimer = setInterval(pollSalesNavBoard, 2500);
}
window.openSalesNavBoard = openSalesNavBoard;

async function pollSalesNavBoard() {
  // Self-cancel once we leave the board route (the poller outlives the view otherwise).
  if (!document.body.classList.contains('route-salesnav')) { clearInterval(_snPollTimer); _snPollTimer = null; return; }
  const host = document.getElementById('sn-board');
  if (!host || document.hidden) return;
  if (_snPollInFlight) return; // a previous poll is still waiting on a slow engine — don't stack
  _snPollInFlight = true;
  // Before the FIRST successful load, show an animated "Loading scrapes…" while the
  // /api/jobs fetch runs (it can take several seconds) so the board reads as loading,
  // not empty/stalled. Only when the board isn't already showing strips.
  if (!_snEverLoaded && !host.querySelector('.sn-strip')) {
    host.innerHTML = '<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Loading scrapes…</div>';
  }
  try {
    const r = await fetch('/api/scrape/campaigns');
    const d = await r.json();
    if (d && d.error) throw new Error(d.error);
    _snEverLoaded = true; _snConsecFail = 0;
    renderSalesNavBoard(d.campaigns || []);
    _snSaveCache(d.campaigns || []);
  } catch (err) {
    _snConsecFail++;
    // Never blank a board we've already rendered: keep the last render and let the
    // next 2.5s poll recover silently (the engine is just briefly slow/busy). Only
    // show a message BEFORE the first successful load — a friendly "connecting…"
    // first, escalating to the real error after several failures so a genuine
    // outage still surfaces instead of spinning forever.
    if (!_snEverLoaded) {
      host.innerHTML = _snConsecFail >= 4
        ? `<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Still loading — the engine is slow to respond (${escHtml((err && err.message) || 'timeout')}). Retrying…</div>`
        : `<div class="sn-loading"><span class="sp" aria-hidden="true"></span> Loading scrapes…</div>`;
    }
  } finally {
    _snPollInFlight = false;
  }
}

function _snStatusDot(status) {
  const cls = status === 'running' ? 'run' : status === 'queued' ? 'q' : status === 'error' ? 'red' : 'mon';
  return `<span class="dot ${cls}"></span>`;
}

let _snPrevStatus = new Map(); // cid -> status
function _snDetectHandover(campaigns) {
  const nowStatus = new Map(campaigns.map((c) => [c.id, c.status]));
  let stopped = null, started = null;
  for (const [cid, prev] of _snPrevStatus) {
    const cur = nowStatus.get(cid);
    if (prev === 'running' && (cur === 'done' || cur === 'error' || cur === undefined)) stopped = cid;
  }
  for (const c of campaigns) {
    if (_snPrevStatus.get(c.id) === 'queued' && c.status === 'running') started = c.id;
  }
  // Stamp the finish time ONLY when we witness a live scrape turn done/error this
  // session (so pre-existing done scrapes stay time-less instead of "just now").
  let stampedAny = false;
  for (const c of campaigns) {
    const prev = _snPrevStatus.get(c.id);
    const isDoneNow = c.status === 'done' || c.status === 'error';
    const wasLive = prev === 'running' || prev === 'queued';
    if (isDoneNow && wasLive && !_snDoneSeen[c.id]) { _snDoneSeen[c.id] = Date.now(); stampedAny = true; }
  }
  if (stampedAny) _snSaveDoneSeen();
  _snPrevStatus = nowStatus;
  if (stopped || started) _snShowHandover(campaigns, stopped, started);
}
function _snName(campaigns, cid) { const c = campaigns.find((x) => x.id === cid); return c ? (c.name || 'a scrape') : 'a scrape'; }
function _snShowHandover(campaigns, stopped, started) {
  const ho = document.getElementById('sn-handover'), txt = document.getElementById('sn-handover-txt');
  if (!ho || !txt) return;
  if (stopped && started) {
    ho.className = 'sn-handover show launching';
    txt.innerHTML = `<b>Handover</b> — ${escHtml(_snName(campaigns, stopped))} stopped, now launching <b>${escHtml(_snName(campaigns, started))}</b>.`;
  } else if (stopped) {
    ho.className = 'sn-handover show stopping';
    txt.innerHTML = `<b>Stopped</b> ${escHtml(_snName(campaigns, stopped))}.`;
  } else {
    ho.className = 'sn-handover show launching';
    txt.innerHTML = `<b>Launching</b> ${escHtml(_snName(campaigns, started))}…`;
  }
  clearTimeout(ho._t); ho._t = setTimeout(() => { ho.className = 'sn-handover'; }, 5000);
}

// cid → { profileIds, tabName, owner, mine } from the last render, so the
// delegated toggle/stop handlers can drive the right engine profiles and gate
// by ownership (strips are engine-derived; there's no local record to look up).
const _snStrips = new Map();

let _snLastCampaigns = null; // last rendered board data — for optimistic re-renders
function renderSalesNavBoard(campaigns) {
  campaigns = (campaigns || []).map(_snEnrich); // backfill name/owner/profiles the engine dropped
  _snLastCampaigns = campaigns;
  _snDetectHandover(campaigns);
  _snStrips.clear();
  for (const c of campaigns) _snStrips.set(c.id, { profileIds: c.profileIds || [], tabName: c.tabName || '', owner: c.owner || '', mine: !!c.mine });
  const host = document.getElementById('sn-board');
  const running = campaigns.filter((c) => c.status === 'running');
  const queued = campaigns.filter((c) => c.status === 'queued');
  document.getElementById('sn-qmeta').textContent =
    `${running.length} running · ${queued.length} queued`;
  const rail = (label, list) => list.length
    ? `<div class="sn-railhead">${label}</div>` + list.map(renderStrip).join('') : '';
  // Running → queued → done rails for one subset of scrapes. showClear gates the
  // "Clear done" button so it appears once (under Your scrapes / the flat board),
  // not under someone else's done rail where clearing everyone's reads as wrong.
  const railsFor = (list, { showClear = true } = {}) => {
    const r = list.filter((c) => c.status === 'running');
    const q = list.filter((c) => c.status === 'queued');
    const d = list
      .filter((c) => c.status === 'done' || c.status === 'error')
      .filter((c) => !_snDismissed.has(c.id));
    let h = rail('▶ Now running', r) + rail('• Up next in the queue', q);
    if (d.length) {
      h += `<div class="sn-railhead">✓ Done <span class="sn-railcount">${d.length}</span>`
        + (showClear ? `<button type="button" class="sn-clear-done">Clear done</button>` : '')
        + `</div>` + d.map(renderStrip).join('');
    }
    return h;
  };
  let html = '';
  // Mirror the campaigns board: admins see "Your scrapes" vs "Other people's
  // scrapes"; everyone else gets a single flat board. `mine` is computed by the
  // engine grouping (owner email / operator id match).
  if (typeof _snIsAdmin === 'function' && _snIsAdmin()) {
    const mine = campaigns.filter((c) => c.mine);
    const others = campaigns.filter((c) => !c.mine);
    const mineHtml = railsFor(mine, { showClear: true }) || '<div class="sn-empty">You have no scrapes running right now.</div>';
    const othersHtml = railsFor(others, { showClear: false }) || '<div class="sn-empty">No one else has scrapes right now.</div>';
    html = `<div class="sn-sectionhead">Your scrapes</div>${mineHtml}`
      + `<div class="sn-sectionhead">Other people’s scrapes</div>${othersHtml}`;
  } else {
    html = railsFor(campaigns, { showClear: true });
  }
  // Empty state when NO strips are visible — covers both "no scrapes at all"
  // and "all scrapes dismissed / in a non-shown status" (previously blank).
  if (!html) html = _scrapeEmptyState();
  host.innerHTML = html;
  // Fill each expanded strip's cloned card. Only expanded strips have one.
  const _byId = new Map(campaigns.map((c) => [c.id, c]));
  host.querySelectorAll('.sn-strip > .vj-card').forEach((root) => {
    const strip = root.closest('.sn-strip');
    const c = strip && _byId.get(strip.dataset.cid);
    if (c) { try { _snFillStripCard(root, c); } catch (_) { /* a broken card must not blank the board */ } }
  });
  // The rebuild reset every logs pane to its "…" placeholder — refill the ones
  // showing the Logs tab so an open live log survives the 2.5s re-render.
  if (_snLogsTab.size) {
    host.querySelectorAll('.sn-pane.on .sn-logbox').forEach((box) => {
      if (box.dataset.logsfor && _snLogsTab.has(box.dataset.logsfor)) { try { _snLoadLogs(box); } catch (_) { /* */ } }
    });
  }
}

// Every strip is collapsed to a slim summary BY DEFAULT (queued always; running
// & done otherwise) so the board reads as a scannable list, not a wall of job
// rows. This set holds the cids the operator explicitly expanded; it survives
// re-renders (the board rebuilds its innerHTML on every 2.5s poll).
const _snExpanded = new Set();
// cids whose strip should show the LOGS tab active (vs the default Jobs tab).
// Persisted like _snExpanded so the 2.5s board re-render doesn't snap the pane
// back to Jobs — set when the operator opens a running scrape's log or clicks
// the Logs tab, cleared when they click back to Jobs.
const _snLogsTab = new Set();

// Done strips the operator has hidden from THEIR board (local only — the board is
// shared, so this never touches the engine or other operators). Persisted to
// localStorage so dismissals survive reloads.
const _snDismissed = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snDismissedDone') || '[]'); } catch (_) { return []; }
})());
function _snSaveDismissed() {
  try { localStorage.setItem('snDismissedDone', JSON.stringify([..._snDismissed])); } catch (_) { /* */ }
}

// Scrapes the operator explicitly stopped. The engine reports a user-stopped
// scrape as plain "done", so we remember the stop action locally to render it red
// as "Stopped" (persisted so it survives reloads).
const _snStopped = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snStopped') || '[]'); } catch (_) { return []; }
})());
function _snSaveStopped() {
  try { localStorage.setItem('snStopped', JSON.stringify([..._snStopped])); } catch (_) { /* */ }
}

// Scrapes the operator PAUSED via the strip's On/Off toggle. The engine doesn't
// report a paused state (pause just signals the pod; the job stays "running"), so
// we track it locally to render the strip as "Paused" instead of "Running".
const _snPaused = new Set((() => {
  try { return JSON.parse(localStorage.getItem('snPaused') || '[]'); } catch (_) { return []; }
})());
function _snSavePaused() {
  try { localStorage.setItem('snPaused', JSON.stringify([..._snPaused])); } catch (_) { /* */ }
}

// Local launch registry — the engine drops campaignName/ownerEmail/profileId from
// its /api/jobs list, so the board can't show the real name or drive toggle/stop
// for our own scrapes. On launch we stash {name, profileId, ownerEmail} keyed by
// each dispatched search URL, then backfill strips in _snEnrich(). localStorage so
// it survives reloads. (Only covers THIS operator's launches — which is exactly
// the set we're allowed to control.)
const _snLaunchReg = (() => {
  try { return JSON.parse(localStorage.getItem('snLaunchReg') || '{}'); } catch (_) { return {}; }
})();
function _snSaveLaunchReg() {
  try { localStorage.setItem('snLaunchReg', JSON.stringify(_snLaunchReg)); } catch (_) { /* */ }
}
function _snRegisterLaunch(searchUrl, info) {
  if (!searchUrl) return;
  _snLaunchReg[searchUrl] = { ...info, ts: Date.now() };
  _snSaveLaunchReg();
}
// Backfill a strip from the launch registry when the engine didn't echo the
// real name / owner / profiles.
function _snEnrich(c) {
  let regName = null; const regProfiles = []; let regOwner = null;
  for (const u of (c.searchUrls || [])) {
    const e = _snLaunchReg[u];
    if (!e) continue;
    regName = regName || e.name;
    regOwner = regOwner || e.ownerEmail;
    if (e.profileId) regProfiles.push(e.profileId);
  }
  if (regName) c.name = regName;
  if (regOwner) { c.owner = regOwner; c.mine = true; }
  if (regProfiles.length) c.profileIds = [...new Set([...(c.profileIds || []), ...regProfiles])];
  return c;
}

// "Done N ago" — prefer a real finish timestamp off the engine jobs if present;
// otherwise stamp when THIS client first saw the scrape as done (localStorage).
const _snDoneSeen = (() => {
  try { return JSON.parse(localStorage.getItem('snDoneSeen2') || '{}'); } catch (_) { return {}; }
})();
function _snSaveDoneSeen() {
  try { localStorage.setItem('snDoneSeen2', JSON.stringify(_snDoneSeen)); } catch (_) { /* */ }
}
// The ONLY trustworthy finish time: the moment we witnessed this scrape turn
// done this session (set in _snDetectHandover). We deliberately do NOT read
// timestamps off the engine jobs — the engine sends no reliable finish epoch,
// and guessing fields produced garbage ("20636d ago"). Unknown → 0 → plain "Done".
function _snDoneTs(c) {
  return _snDoneSeen[c.id] || 0;
}
function fmtAgo(ts) {
  const t = Number(ts);
  if (!Number.isFinite(t) || t <= 0) return ''; // no known time → caller shows plain "Done"
  const d = Date.now() - t;
  if (!(d >= 0)) return '';
  const m = Math.floor(d / 60000);
  if (m < 1) return 'just now';
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function renderStrip(c) {
  const isQueued = c.status === 'queued';
  const isDone = c.status === 'done' || c.status === 'error';
  const collapsed = isQueued ? true : !_snExpanded.has(c.id);
  const owner = c.owner || 'unknown';
  const nJobs = (c.jobs || []).length || (c.searchUrls || []).length;
  const flow = `<b>${(c.searchUrls || []).length} searches</b> → <b>${nJobs} jobs</b> → feeds <b>${escHtml(c.name || c.tabName || '')}</b> · tab "${escHtml(c.tabName || 'Results')}"`;
  const doneAgo = isDone ? fmtAgo(_snDoneTs(c)) : '';
  // "Stopped" (red) only if the operator's stop actually cut short running work.
  // If EVERY job finished ('done'), the scrape completed on its own → show neutral
  // "Done" even though Stop was pressed (it landed after completion). Clean the
  // stale stopped-mark so it doesn't linger red.
  const _jobStates = (c.jobs || []).map((j) => String((j && j.state) || ''));
  const _allJobsDone = _jobStates.length > 0 && _jobStates.every((s) => s === 'done');
  if (isDone && _allJobsDone && _snStopped.has(c.id)) { _snStopped.delete(c.id); try { _snSaveStopped(); } catch (_) {} }
  const wasStopped = isDone && _snStopped.has(c.id) && !_allJobsDone;
  // Paused = the operator toggled it off while it's still active (not terminal).
  const isPaused = !isDone && _snPaused.has(c.id);
  const isBad = c.status === 'error' || wasStopped; // render red
  const doneLabel = c.status === 'error' ? 'Error' : wasStopped ? 'Stopped' : 'Done';
  const statusTxt = isPaused ? 'Paused'
    : isQueued ? `Queued${c.minPosition ? ` · #${c.minPosition}` : ''}${c.etaMs ? ` · ${fmtEta(c.etaMs)}` : ''}`
    : c.status === 'running' ? 'Running'
    : `${doneLabel}${doneAgo ? ` · ${doneAgo}` : ''}`;
  // Running cards show live throughput (rows-so-far only — the engine reports no
  // expected total, so no % bar; see /api/jobs shape). Rendered under the flow.
  const progLine = c.status === 'running'
    ? `<div class="sn-progtxt"><b>${(c.totalProfiles || 0).toLocaleString()}</b> rows so far · ${c.done}/${nJobs} jobs done${c.etaMs ? ` · ${fmtEta(c.etaMs)} left` : ''}</div>`
    : '';
  const jobsPane = (c.jobs || []).map((j) => {
    const label = j.searchUrl ? j.searchUrl.slice(0, 60) : 'search';
    const st = j.state === 'running' ? `<span class="dot run"></span> Running · ${j.profiles || 0} rows`
      : j.state === 'done' ? `<span class="dot mon"></span> Done · ${j.profiles || 0} rows`
      : j.state === 'error' ? `<span class="dot red"></span> Error`
      : `<span class="dot q"></span> Queued`;
    return `<div class="job"><div><div class="jt">${escHtml(label)}</div></div><div class="jstat">${st}</div></div>`;
  }).join('') || '<div class="sn-empty">No jobs.</div>';
  const canOpen = !isQueued || _snCanControl(c);
  // Open → the scrape's setup WIZARD (config populated) with its live Activity log
  // at the bottom — the analogue of a campaign's Open → wizard-with-log. Available
  // for every status (running/queued/done) so you can always inspect config + log.
  const openCls = isDone ? 'mini' : 'mini solid'; // on done strips Re-run is primary
  const openBtn = canOpen
    ? `<button class="${openCls}" title="Open this scrape's wizard (config + log)" onclick="openScrapeSetupFor('${escHtml(c.id)}')">Open</button>`
    : `<button class="mini locked" title="Only ${escHtml(owner)} can open this">Open 🔒</button>`;
  // Re-run → DIRECTLY start the scrape again with the same config (no wizard),
  // for a FINISHED or STOPPED scrape you own (or admin). The engine has no
  // page-offset resume; a re-run restarts from page 1 and the sheet-level dedup
  // skips rows already captured, so it mainly fills in what a stopped run missed.
  // A STOPPED scrape reads "Continue" (re-runs with the same config; sheet dedup
  // skips already-captured rows, so it effectively picks up where it left off).
  // A naturally-FINISHED scrape reads "Re-run" (start it over).
  const rerunLabel = wasStopped ? 'Continue' : 'Re-run';
  const rerunTitle = wasStopped
    ? 'Continue this scrape — re-runs with the same config; already-captured rows are skipped'
    : 'Start this scrape again with the same config';
  const rerunBtn = (isDone && _snCanControl(c))
    ? `<button class="mini solid" title="${rerunTitle}" onclick="rerunScrape('${escHtml(c.id)}',this)">${rerunLabel}</button>`
    : '';
  // 👁 View — live MJPEG of a running job's browser on the VM, exactly like the
  // campaign board's 👁 Show. Views the first running job of this scrape (a scrape
  // can run several browsers; this opens one — the per-job Jobs pane lists the rest).
  const runningJob = (c.jobs || []).find((j) => j.state === 'running' && j.id);
  const viewBtn = runningJob
    ? `<button class="mini" onclick="openScrapeJobView('${escHtml(runningJob.id)}','${escHtml(c.name || c.tabName || 'scrape')}')" title="Watch this scrape running on the VM">👁 View</button>`
    : '';
  // Stop shows while running OR still queued. Anyone can press it, but a
  // "not yours" confirm gates non-owners (handled in stopScrapeCampaign).
  const canStop = c.status === 'running' || isQueued;
  const stopBtn = canStop
    ? `<button class="mini" onclick="stopScrapeCampaign('${escHtml(c.id)}')">Stop</button>` : '';
  // Done strips get a dismiss (✕) that hides them from THIS operator's board only.
  const dismissBtn = isDone
    ? `<button class="mini sn-dismiss" data-cid="${escHtml(c.id)}" title="Hide from your board">✕</button>` : '';
  // Non-queued strips carry the Jobs/Logs pane, folded by default. The expand
  // control is pinned to the strip's top-right corner (CSS-absolute) so it stays
  // put when the pane opens instead of riding the footer down the page.
  const expandBtn = isQueued ? ''
    : `<button class="sn-collapse sn-expand" title="Expand / collapse"><svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6l4 4 4-4"/></svg></button>`;
  // The toggle reads Running/Paused. It's OFF (Paused) when the operator paused it
  // — the engine keeps reporting the job "running", so factor in the local paused
  // mark, else the switch would snap back to Running on the next poll.
  const toggleOn = (c.enabled !== false) && !isPaused;
  // Which tab is active survives re-renders via _snLogsTab (default: Jobs).
  const logsActive = _snLogsTab.has(c.id);
  const switchBlock = isQueued ? '' : `
    <div class="sn-switch">
      <div class="sn-switchtabs"><span class="sn-st ${logsActive ? '' : 'on'}" data-t="jobs">Jobs</span><span class="sn-st ${logsActive ? 'on' : ''}" data-t="logs">Logs</span></div>
      <div class="sn-pane ${logsActive ? '' : 'on'}" data-p="jobs">${jobsPane}</div>
      <div class="sn-pane ${logsActive ? 'on' : ''}" data-p="logs"><div class="sn-logbox" data-logsfor="${escHtml(c.id)}" data-tab="${escHtml(c.tabName || '')}">…</div></div>
    </div>`;
  // Expanded strips render the SAME .vj-card as the campaigns board (app.js:8804)
  // and as Steven's scrape launch card — one shell, no markup drift.
  //
  // Unlike the campaigns board this skips COLLAPSED strips too, not just queued
  // ones. vjCardSkeleton deep-clones #active-card, and this board renders 282
  // strips every 2.5s; cloning a card nobody can see 282 times per tick is a
  // measurable freeze for zero pixels. Expanding a strip re-renders it anyway.
  const richCard = (isQueued || collapsed) ? '' : vjCardSkeleton(c.id);
  return `
  <div class="sn-strip ${c.mine ? 'mine' : ''} ${c.status === 'running' && !isPaused ? 'run' : ''} ${isPaused ? 'paused' : ''} ${isQueued ? 'queued' : ''} ${collapsed ? 'sn-collapsed' : ''} ${isDone ? 'done' : ''} ${isBad ? 'stopped' : ''}" data-cid="${escHtml(c.id)}">
    ${expandBtn}
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Sales Nav Scraper</span>${c.mine ? '<span class="sn-you">You</span>' : `<span class="sn-owner">· ${escHtml(owner)}</span>`}
      <span class="sn-status">${isPaused ? '<span class="dot paused"></span>' : isBad ? '<span class="dot red"></span>' : _snStatusDot(c.status)} ${escHtml(statusTxt)}</span></div>
    <div class="sn-name">${escHtml(c.name || '')}</div>
    <div class="sn-flow">${flow}</div>
    ${progLine}
    ${switchBlock}
    </div>
    ${richCard}
    <div class="sn-foot">
      <div class="togwrap"><div class="toggle ${toggleOn ? '' : 'off'}" data-owner="${escHtml(owner)}" data-cid="${escHtml(c.id)}" title="${toggleOn ? 'Running — flip to pause' : 'Paused — flip to resume'}"><i></i></div><span class="lbl">${toggleOn ? 'Running' : 'Paused'}</span></div>
      <div class="right">${dismissBtn}${viewBtn}${stopBtn}${openBtn}${rerunBtn}</div>
    </div>
  </div>`;
}

// Fill one expanded strip's cloned card with THIS scrape's numbers.
//
// Deliberately not fillVjCard(): that renders campaign controls, the reply-check
// panel and campaign live-activity, none of which a scrape has. Fields are set
// directly, the same way Steven's _setScrapeVjCard fills the launch card, and it
// reuses his _SCRAPE_VJ label map so the board and the launch console say the
// same words for the same state ("Collecting", not "Sending").
// The scrape card's action dock, mirroring the campaign card's: an Open pill
// then an icon toolbar. Every button maps to an action the strip footer already
// had — nothing new is invented, and the same ownership gates apply.
//
// Pause/resume keeps the `.toggle` class and its data-cid/data-owner, because
// that button is driven by a DELEGATED handler that matches `.toggle` and reads
// the `off` class to decide direction. Restyling it as a dock-btn changes how it
// looks, not how it works — including the "this isn't your scrape" confirm.
function _snCardControlsHtml(c) {
  const cid = escHtml(c.id);
  const isQueued = c.status === 'queued';
  const isDone = c.status === 'done' || c.status === 'error';
  const isPaused = _snPaused.has(c.id);
  const canControl = _snCanControl(c);
  const owner = c.owner || '';
  const dib = (svg, tip, onclick, cls = '') =>
    `<button type="button" class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;

  let dock = '';
  if (!isDone && !isQueued) {
    const on = (c.enabled !== false) && !isPaused;
    dock += `<button type="button" class="dock-btn toggle ${on ? '' : 'off'}" data-cid="${cid}" data-owner="${escHtml(owner)}"`
      + ` data-tip="${on ? 'Pause' : 'Resume'}" aria-label="${on ? 'Pause' : 'Resume'}">${on ? V3_SVG_PAUSE : V3_SVG_PLAY}</button>`;
  }

  let actions = '';
  const runningJob = (c.jobs || []).find((j) => j.state === 'running' && j.id);
  if (runningJob) {
    actions += `<button type="button" class="dock-btn" data-tip="Show" aria-label="Show"`
      + ` onclick="openScrapeJobView('${escHtml(runningJob.id)}','${escHtml(c.name || c.tabName || 'scrape')}')">👁</button>`;
  }
  if (c.status === 'running' || isQueued) {
    actions += dib(V3_SVG_STOP, 'Stop', `stopScrapeCampaign('${cid}')`, 'danger');
  }
  if (isDone && canControl) {
    // A stopped scrape reads Continue, a finished one Re-run — same call either
    // way; the engine restarts from page 1 and sheet dedup skips captured rows.
    const stopped = _snStopped.has(c.id) || c.status === 'error';
    actions += dib(stopped ? V3_SVG_PLAY : V3_SVG_RESTART,
      stopped ? 'Continue where it left off' : 'Re-run', `rerunScrape('${cid}',this)`);
  }
  if (isDone) {
    actions += `<button type="button" class="dock-btn sn-dismiss" data-cid="${cid}"`
      + ` data-tip="Hide from your board" aria-label="Hide from your board">${V3_SVG_TRASH}</button>`;
  }

  const openHtml = canControl
    ? `<button class="btn-pill" onclick="openScrapeSetupFor('${cid}')">Open</button>`
    : `<button class="btn-pill" disabled title="Only ${escHtml(owner)} can open this">Open 🔒</button>`;
  return `${openHtml}<div class="dock" role="toolbar" aria-label="Scrape actions">${dock}<div class="dock-actions">${actions}</div></div>`;
}

function _snFillStripCard(root, c) {
  if (!root || !c) return;
  const strip = root.closest('.sn-strip');
  const isPaused = _snPaused.has(c.id);
  const isBad = _snStopped.has(c.id) || c.status === 'error';
  const state = isBad ? 'error'
    : c.status === 'queued' ? 'queued'
      : c.status === 'done' ? 'done'
        : 'running';
  const V = _SCRAPE_VJ[state] || _SCRAPE_VJ.idle;

  const jobs = c.jobs || [];
  const total = jobs.length || (c.searchUrls || []).length;
  const done = Number(c.done) || 0;
  const leads = Number(c.totalProfiles) || 0;
  const pages = jobs.reduce((n, j) => n + (Number(j && j.pages) || 0), 0);
  const accounts = (c.profileIds || []).length;
  const pct = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : 0;

  // Relabel the hero ONCE per clone — the campaign card counts sent/accepted,
  // a scrape counts searches/pages/leads.
  if (!root.dataset.snLabelled) {
    const meta = root.querySelector('.vj-meta');
    if (meta) meta.innerHTML =
      '<span><b data-f="activeSent">0</b> of <span data-f="activeTotal">0</span> searches done</span>'
      + '<span><b data-f="scrapePages">0</b> pages · <b data-f="scrapeLeads">0</b> leads</span>';
    const stats = root.querySelector('.vj-stats');
    if (stats) stats.innerHTML =
      '<span><b data-f="activeAccounts">0</b> accounts</span>'
      + '<span>· <b data-f="sendingLbl">Idle</b></span>';
    root.dataset.snLabelled = '1';
  }

  // The card gets the campaign card's control dock — an Open pill plus an icon
  // toolbar — instead of the strip's text buttons and paused ticker. Same
  // .btn-pill / .dock / .dock-btn markup _vjControlsHtml builds, so the two
  // cards are visually identical; only the actions differ, and every action
  // here is one the strip footer already had.
  const ctrl = root.querySelector('.vj-controls');
  if (ctrl) ctrl.innerHTML = _snCardControlsHtml(c);

  // Fill the card's live log. The strip's log used to live in the Jobs/Logs pane
  // inside .sn-compact, which expanding hides — so the card showed "No events
  // yet" for every scrape. Reuse the strip log loader against the card's box.
  const logBox = root.querySelector('[data-f="active-log"], .vj-log');
  if (logBox && !logBox.dataset.snWired) {
    logBox.dataset.snWired = '1';
    logBox.dataset.logsfor = c.id;
    logBox.dataset.tab = c.tabName || '';
    try { _snLoadLogs(logBox); } catch (_) { /* a log failure must not break the card */ }
  }

  const setF = (f, v) => { const e = root.querySelector(`[data-f="${f}"]`); if (e) e.textContent = String(v); };
  setF('activeName', c.name || c.tabName || 'Sales Nav Scrape');
  setF('activeEyebrow', isPaused ? 'Paused' : V.eyebrow);
  setF('sendingLbl', isPaused ? 'Paused' : V.state);
  setF('activeSent', done);
  setF('activeTotal', total);
  setF('activePct', pct);
  setF('scrapePages', pages.toLocaleString());
  setF('scrapeLeads', leads.toLocaleString());
  setF('activeAccounts', accounts);
  const bar = root.querySelector('[data-f="activeBar"]');
  if (bar) bar.style.width = pct + '%';
  setF('activeLiveL1', V.l1);
}

function _snIsAdmin() {
  return _isAdminEmail(snCurrentEmail);
}
// Can the viewer control this strip WITHOUT the "not yours" confirm? True when
// it's their own scrape (server-computed `mine`) or they're the admin.
function _snCanControl(c) {
  return !!(c && c.mine) || _snIsAdmin();
}

// The scrape flow spans three real wizard sections: the 2b config, the shared
// account picker (section 3), and the scrape launch console. To show the setup
// INLINE on the board (no navigation), we relocate those DOM nodes into the
// board's #sn-setup-body, leaving a placeholder so we can move them back exactly.
const SN_SETUP_SECTIONS = ['nav-scrape', 'nav-accounts', 'nav-scrape-launch'];
let _snSetupOpen = false;
// The composer borrows the wizard's ONE campaign-mode select. Remember what it
// was so closing puts it back — otherwise the wizard stays in scrape layout
// (2b showing, Throughput/Templates/Sheet/Launch hidden) until the operator
// happens to click a campaign-type tile.
let _snPrevMode = null;

function _snMoveSetupIn() {
  const body = document.getElementById('sn-setup-body');
  if (!body) return;
  SN_SETUP_SECTIONS.forEach((id) => {
    const sec = document.getElementById(id);
    if (!sec) return;
    if (!sec._snPlaceholder) {
      const ph = document.createComment('sn-setup:' + id);
      sec.parentNode.insertBefore(ph, sec);
      sec._snPlaceholder = ph;
    }
    body.appendChild(sec);
  });
}

// Pull the campaign-name field out of the Destination panel and pin it to the
// very top of the composer as the editable hero (drawing 3 / sketch). A comment
// placeholder marks its home so _snRestoreHeroName() puts it back for the wizard.
function _snHeroName() {
  const body = document.getElementById('sn-setup-body');
  const field = document.getElementById('scrape-name-field');
  if (!body || !field || field._snHeroPlaceholder) return;
  const ph = document.createComment('sn-heroname');
  field.parentNode.insertBefore(ph, field);
  field._snHeroPlaceholder = ph;
  body.insertBefore(field, body.firstChild);
}
function _snRestoreHeroName() {
  const field = document.getElementById('scrape-name-field');
  if (field && field._snHeroPlaceholder && field._snHeroPlaceholder.parentNode) {
    field._snHeroPlaceholder.parentNode.insertBefore(field, field._snHeroPlaceholder);
    field._snHeroPlaceholder.remove();
    field._snHeroPlaceholder = null;
  }
}

function _snRestoreSetup() {
  SN_SETUP_SECTIONS.forEach((id) => {
    const sec = document.getElementById(id);
    if (sec && sec._snPlaceholder && sec._snPlaceholder.parentNode) {
      sec._snPlaceholder.parentNode.insertBefore(sec, sec._snPlaceholder);
      sec._snPlaceholder.remove();
      sec._snPlaceholder = null;
    }
  });
}

// Reveal the scrape setup INLINE on the board (blank for a new scrape, or
// prefilled when editing a campaign). No route change.
async function openScrapeSetupFor(cid) {
  const host = document.getElementById('sn-setup');
  if (!host) return;
  _scrapePausedLocal = false; // fresh open — don't inherit a prior scrape's paused state
  const sel = document.getElementById('campaign-mode');
  if (sel) {
    // Only capture on the FIRST open — re-opening the composer must not record
    // 'sales_nav_scrape' as the mode to restore.
    if (_snPrevMode === null && sel.value !== 'sales_nav_scrape') _snPrevMode = sel.value;
    sel.value = 'sales_nav_scrape';
  }
  _snMoveSetupIn();
  if (typeof onModeChange === 'function') onModeChange(); // reveals the scrape sections
  _snHeroName();
  host.style.display = 'block';
  const newBtn = document.getElementById('sn-new-btn');
  if (newBtn) newBtn.style.display = 'none'; // already composing — hide the entry button
  const board = document.getElementById('sn-board');
  if (board) board.style.display = 'none'; // focus this scrape — hide the queue list below
  _snSetupOpen = true;
  if (cid) {
    // BLANK the fields immediately (before the fetch that populates them). The
    // /api/scrape/campaigns round-trip can be slow when the engine is busy; showing
    // the PREVIOUS scrape's config while we wait is worse than showing nothing.
    const urls = document.getElementById('scrape-urls'); if (urls) urls.value = '';
    const sheet = document.getElementById('scrape-sheet'); if (sheet) sheet.value = '';
    const tab = document.getElementById('scrape-tab'); if (tab) tab.value = '';
    const nm = document.getElementById('scrape-name'); if (nm) nm.value = '';
    _setScrapeSetupTitle('Loading scrape…', true);
    _setScrapeSaveVisible(true); // editing an existing scrape → offer Save config
    // Track the opened scrape so pollScrapeLogs shows ITS log (scrape-specific,
    // cross-session) instead of this session's global feed. Clear the console now.
    _snOpenedScrape = { cid, tabName: '' };
    try { scrapeLogLines = []; scrapeLogSince = 0; if (typeof renderScrapeLogPanel === 'function') renderScrapeLogPanel(); } catch (_) { /* */ }
    try {
      // Single record, not the whole board — the list response is ~22MB.
      const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}`);
      const d = await r.json();
      const rec = d.campaign;
      if (rec) {
        if (urls) urls.value = (rec.searchUrls || []).join('\n');
        if (sheet) sheet.value = rec.sheetUrl || '';
        if (tab) tab.value = rec.tabName || 'Results';
        if (nm) nm.value = rec.name || '';
        _snOpenedScrape.tabName = rec.tabName || '';
        _setScrapeSetupTitle(rec.name || rec.tabName || 'Scrape');
        // Pre-select the SAME GoLogin accounts this scrape used (section 3), so a
        // wizard re-run reuses them unless the operator changes them — matching the
        // direct Re-run button. rec.profileIds are the scrape's job profileIds,
        // which are GoLogin profile ids (== p.id in the picker).
        if (Array.isArray(rec.profileIds) && rec.profileIds.length) {
          selectedProfileIds = rec.profileIds.filter(Boolean);
          for (const id of selectedProfileIds) {
            const p = (allProfilesData || []).find((x) => x.id === id);
            if (p) selectedProfileNames[id] = p.name;
          }
          try { if (typeof renderProfiles === 'function' && (allProfilesData || []).length) renderProfiles(allProfilesData); } catch (_) { /* */ }
          try { if (typeof renderSelectedPanel === 'function') renderSelectedPanel(); } catch (_) { /* */ }
        }
      } else {
        _setScrapeSetupTitle('Scrape');
      }
    } catch (_) { _setScrapeSetupTitle('Scrape'); }
    try { if (typeof pollScrapeLogs === 'function') pollScrapeLogs(); } catch (_) { /* */ }
  } else {
    _snOpenedScrape = null; // a genuinely new scrape — global session log applies
    _setScrapeSetupTitle('New scrape');
    _setScrapeSaveVisible(false); // nothing to save-onto yet for a brand-new scrape
  }
  if (typeof updateScrapePairing === 'function') updateScrapePairing();
  try { host.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) { /* */ }
}
// The composer's hero title — "New scrape" for a fresh one, the scrape's name when
// opening an existing running/done scrape (so it never mislabels a live scrape as new).
function _setScrapeSetupTitle(text, loading = false) {
  const el = document.querySelector('#sn-setup .sn-setup-title');
  if (!el) return;
  el.innerHTML = (loading ? '<span class="sn-setup-spinner" aria-hidden="true"></span>' : '') + `<span>${escHtml(text)}</span>`;
}
// Which existing scrape the composer is showing (null = a new scrape). Drives
// pollScrapeLogs to fetch THIS scrape's log instead of the session's global feed.
let _snOpenedScrape = null;
window.openScrapeSetupFor = openScrapeSetupFor;

// Re-run a finished/stopped scrape DIRECTLY (no wizard): re-dispatch the exact same
// config (searchUrls × accounts → sheet/tab) to the engine, mirroring startScrapeJob's
// per-URL /api/scrape/start dispatch. The engine restarts the search from page 1;
// sheet-level dedup skips already-captured rows.
async function rerunScrape(cid, btn) {
  if (btn) btn.disabled = true;
  const toast = (m) => { try { showCampaignToast(m, 4500); } catch (_) { try { alert(m); } catch (_) {} } };
  try {
    // Single record, not the whole board — the list response is ~22MB.
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}`);
    const d = await r.json();
    const rec = d.campaign;
    if (!rec) { toast('Re-run: couldn’t find this scrape’s config — try Open instead.'); return; }
    const urls = (rec.searchUrls || []).filter(Boolean);
    const sheetUrl = rec.sheetUrl || '';
    const baseTab = (rec.tabName || 'Results').trim();
    const campaignName = (rec.name || baseTab).trim();
    const accts = (rec.profileIds || []).filter(Boolean);
    if (!urls.length || !sheetUrl || !accts.length) {
      toast('Re-run: this scrape is missing its URLs, sheet, or accounts — Open it and start manually.');
      return;
    }
    toast(`Re-running “${campaignName}” — ${urls.length} job${urls.length === 1 ? '' : 's'} on ${accts.length} account${accts.length === 1 ? '' : 's'}…`);
    let started = 0; const errors = [];
    for (let i = 0; i < urls.length; i++) {
      const profileId = accts[i % accts.length];              // round-robin URL→account, like startScrapeJob
      const tabName = urls.length > 1 ? `${baseTab} ${i + 1}` : baseTab;
      try {
        const rr = await fetch('/api/scrape/start', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ searchUrls: [urls[i]], sheetUrl, tabName, profileId, slowMode: false, campaignName }),
        });
        const res = await rr.json();
        if (res && res.error) errors.push(res.error); else started++;
      } catch (e) { errors.push(e && e.message ? e.message : String(e)); }
    }
    toast(started
      ? `Re-run started — ${started} job${started === 1 ? '' : 's'} dispatched${errors.length ? `, ${errors.length} failed` : ''}. Watch it under “Now running”.`
      : `Re-run failed: ${errors[0] || 'unknown error'}`);
    if (started) {
      // Optimistic move to "Now running" so the strip jumps immediately instead of
      // waiting for the slow /api/jobs poll (~10s). Clear the stopped mark and flip
      // the cached campaign's status; the poll burst below reconciles with the
      // engine as the new jobs register.
      _snStopped.delete(cid); try { _snSaveStopped(); } catch (_) {}
      if (Array.isArray(_snLastCampaigns)) {
        const c = _snLastCampaigns.find((x) => x.id === cid);
        if (c) { c.status = 'running'; c.running = Math.max(1, c.running || 0); c.done = 0; }
        try { renderSalesNavBoard(_snLastCampaigns); } catch (_) { /* */ }
      }
      // Catch-up polls: the board fetch has an in-flight guard, so fire a few over
      // ~12s to reflect the real engine state as soon as the new jobs appear.
      [1500, 4000, 8000, 12000].forEach((ms) => setTimeout(() => { try { pollSalesNavBoard(); } catch (_) { /* */ } }, ms));
    }
  } catch (e) { toast('Re-run failed: ' + (e && e.message ? e.message : e)); }
  finally { if (btn) btn.disabled = false; }
}
window.rerunScrape = rerunScrape;

// Save the current wizard config for the OPENED scrape (keyed by its board id) so
// the edits persist and win on re-open — the server merges saved overrides into
// /api/scrape/campaigns. Only meaningful while viewing an existing scrape.
async function saveScrapeConfig(btn) {
  if (!_snOpenedScrape || !_snOpenedScrape.cid) {
    try { showCampaignToast('Open a scrape first, then Save.', 3500); } catch (_) {}
    return;
  }
  if (btn) btn.disabled = true;
  try {
    const body = {
      searchUrls: (typeof getScrapeInputUrls === 'function' ? getScrapeInputUrls() : []),
      sheetUrl: (document.getElementById('scrape-sheet')?.value || '').trim(),
      tabName: (document.getElementById('scrape-tab')?.value || 'Results').trim(),
      name: (document.getElementById('scrape-name')?.value || '').trim(),
      profileIds: (typeof scrapeSelectedAccounts === 'function' ? scrapeSelectedAccounts() : []),
    };
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(_snOpenedScrape.cid)}/config`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const d = await r.json().catch(() => ({}));
    if (d && d.ok) { _snOpenedScrape.tabName = body.tabName; try { showCampaignToast('✓ Config saved — it’ll be here next time you open this scrape.', 4000); } catch (_) {} }
    else { try { showCampaignToast('Save failed: ' + ((d && d.error) || 'unknown'), 5000); } catch (_) {} }
  } catch (e) { try { showCampaignToast('Save failed: ' + (e && e.message ? e.message : e), 5000); } catch (_) {} }
  finally { if (btn) btn.disabled = false; }
}
window.saveScrapeConfig = saveScrapeConfig;
// Show the Save-config button only while an existing scrape is open (editing it).
function _setScrapeSaveVisible(show) {
  const b = document.getElementById('btn-scrape-save');
  if (b) b.style.display = show ? '' : 'none';
}

function startNewScrapeSetup() {
  _snOpenedScrape = null; // fresh scrape — not viewing an existing one's log
  const urls = document.getElementById('scrape-urls'); if (urls) urls.value = '';
  const nm = document.getElementById('scrape-name'); if (nm) nm.value = '';
  openScrapeSetupFor('');
}
window.startNewScrapeSetup = startNewScrapeSetup;

// Hide the inline setup and move the relocated sections back into the wizard so
// the campaign wizard stays intact for every other mode.
function closeScrapeSetup() {
  const host = document.getElementById('sn-setup');
  if (host) host.style.display = 'none';
  const newBtn = document.getElementById('sn-new-btn');
  if (newBtn) newBtn.style.display = '';
  const board = document.getElementById('sn-board');
  if (board) board.style.display = ''; // restore the queue list
  _snRestoreHeroName();
  _snRestoreSetup();
  _snSetupOpen = false;
  _snOpenedScrape = null; // back to the board — stop showing an opened scrape's log
  _setScrapeSaveVisible(false);
  // Hand the wizard back the mode it had. Restoring the select alone isn't
  // enough — onModeChange() is what re-shows Throughput/Templates/Sheet/Launch
  // and hides 2b, so the wizard was carrying scrape layout into a normal
  // campaign until a type tile was clicked.
  const sel = document.getElementById('campaign-mode');
  if (sel && sel.value === 'sales_nav_scrape') {
    sel.value = _snPrevMode || 'connect_only';
    if (typeof onModeChange === 'function') { try { onModeChange(); } catch (_) { /* */ } }
  }
  _snPrevMode = null;
}
window.closeScrapeSetup = closeScrapeSetup;

document.addEventListener('click', (e) => {
  const tab = e.target.closest('.sn-st');
  if (tab) {
    const sw = tab.closest('.sn-switch');
    sw.querySelectorAll('.sn-st').forEach((x) => x.classList.toggle('on', x === tab));
    sw.querySelectorAll('.sn-pane').forEach((p) => p.classList.toggle('on', p.dataset.p === tab.dataset.t));
    // Remember the choice so the 2.5s re-render keeps this tab active.
    const cid = tab.closest('.sn-strip')?.dataset.cid;
    if (cid) { if (tab.dataset.t === 'logs') _snLogsTab.add(cid); else _snLogsTab.delete(cid); }
    if (tab.dataset.t === 'logs') {
      const box = sw.querySelector('.sn-logbox');
      if (box && box.dataset.logsfor) _snLoadLogs(box);
    }
  }
});
// Fold / unfold a finished-or-running strip's Jobs/Logs pane.
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.sn-collapse');
  if (!btn) return;
  const strip = btn.closest('.sn-strip');
  const cid = strip?.dataset.cid;
  if (!cid) return;
  if (_snExpanded.has(cid)) _snExpanded.delete(cid); else _snExpanded.add(cid);
  strip.classList.toggle('sn-collapsed', !_snExpanded.has(cid));
  // Cloud strips fetch their per-lead log only when running/expanded — kick a
  // background cloud refresh on expand so the log fills promptly (it re-renders
  // when it lands), and render now for the instant collapse/expand feel.
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  if (_snExpanded.has(cid) && typeof _refreshCloudItems === 'function') _refreshCloudItems();
});

// Dismiss a done strip (local-only) and the "Clear done" bulk action.
document.addEventListener('click', (e) => {
  const x = e.target.closest('.sn-dismiss');
  if (x && x.dataset.cid) {
    // Deleting a scrape must kill any lingering activity on the VM, not just hide
    // it — stop each of its accounts' jobs first (best-effort; a no-op for a scrape
    // that already finished). Then hide it from the board.
    const cid = x.dataset.cid;
    const meta = _snStrips.get(cid) || {};
    (meta.profileIds || []).filter(Boolean).forEach((pid) => {
      fetch('/api/scrape/stop', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ profileId: pid }) }).catch(() => {});
    });
    _snDismissed.add(cid); _snSaveDismissed();
    const strip = x.closest('.sn-strip');
    if (strip) strip.remove(); // instant — the next poll already filters it out
    return;
  }
  const clr = e.target.closest('.sn-clear-done');
  if (clr) {
    const head = clr.closest('.sn-railhead');
    document.querySelectorAll('#sn-board .sn-strip.done').forEach((s) => {
      if (s.dataset.cid) _snDismissed.add(s.dataset.cid);
      s.remove();
    });
    if (head) head.remove();
    _snSaveDismissed();
  }
});

let _snPendingToggle = null;
let _snPendingStop = null;
function _snApplyToggle(el, cid) {
  const goingOn = el.classList.contains('off'); // currently off → turning on
  // Immediate visual feedback — flip the switch and pulse the strip so the
  // operator sees the state change without waiting for the next poll.
  el.classList.toggle('off', !goingOn);
  const lbl = el.parentNode?.querySelector('.lbl');
  if (lbl) lbl.textContent = goingOn ? 'Running' : 'Paused';
  const strip = el.closest('.sn-strip');
  if (strip) {
    strip.classList.remove('starting', 'stopping');
    strip.classList.add(goingOn ? 'starting' : 'stopping');
  }
  // Track the paused state locally so the strip reads "Paused" (the engine keeps
  // reporting the job as running). ON → resume (clear); OFF → pause (mark).
  if (goingOn) _snPaused.delete(cid); else _snPaused.add(cid);
  try { _snSavePaused(); } catch (_) { /* */ }
  const meta = _snStrips.get(cid) || {};
  fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}/toggle`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ on: goingOn, profileIds: meta.profileIds || [] }),
  }).then(() => pollSalesNavBoard()).catch(() => {});
}
document.addEventListener('click', (e) => {
  const t = e.target.closest('.toggle');
  if (!t || !t.dataset.cid) return;
  const cid = t.dataset.cid;
  const strip = _snStrips.get(cid) || {};
  const owner = t.dataset.owner || strip.owner || '';
  if (!_snCanControl({ mine: strip.mine })) {
    _snPendingToggle = { el: t, cid };
    const goingTo = t.classList.contains('off') ? 'ON' : 'OFF';
    document.getElementById('snm-body').innerHTML =
      `This isn't your campaign — it belongs to <b>${escHtml(owner)}</b>. Turning it <b>${goingTo}</b> affects their scrape and its place in the queue. Continue?`;
    document.getElementById('snm-scrim').classList.add('open');
    return;
  }
  _snApplyToggle(t, cid); // owner or admin → immediate
});
document.getElementById('snm-cancel')?.addEventListener('click', () => {
  _snPendingToggle = null; _snPendingStop = null; document.getElementById('snm-scrim').classList.remove('open');
});
document.getElementById('snm-ok')?.addEventListener('click', () => {
  if (_snPendingToggle) _snApplyToggle(_snPendingToggle.el, _snPendingToggle.cid);
  if (_snPendingStop) _snDoStop(_snPendingStop);
  _snPendingToggle = null; _snPendingStop = null; document.getElementById('snm-scrim').classList.remove('open');
});

function _snDoStop(cid) {
  const meta = _snStrips.get(cid) || {};
  _snStopped.add(cid); _snSaveStopped(); // remember so it renders red as "Stopped"
  _snPaused.delete(cid); try { _snSavePaused(); } catch (_) { /* */ } // stopping clears any paused mark
  // Immediate visual feedback: pulse the strip red and show the button working.
  const strip = document.querySelector(`.sn-strip[data-cid="${cid}"]`);
  if (strip) {
    strip.classList.remove('starting');
    strip.classList.add('stopping');
    const btn = strip.querySelector('.sn-foot .right .mini');
    if (btn) { btn.textContent = 'Stopping…'; btn.disabled = true; }
  }
  // Hard STOP each account's job — /api/scrape/stop broadcasts stop to the owning
  // pod AND cancels that profile's queued jobs. (The /toggle endpoint only PAUSES,
  // which left the strip stuck on "RUNNING" — that was the bug.) Once stopped, the
  // jobs go terminal, so the strip's status flips to Done/Stopped and it moves to
  // the Done section on the next board poll.
  const profileIds = (meta.profileIds || []).filter(Boolean);
  const stops = profileIds.length
    // cid rides along so the stop is written to THIS strip's log — stopping a
    // shared board's scrape is the most audit-worthy action there is, and it
    // used to leave no trace at all.
    ? profileIds.map((pid) => fetch('/api/scrape/stop', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ profileId: pid, campaignId: cid }),
      }).catch(() => {}))
    : [];
  Promise.all(stops).then(() => { try { pollSalesNavBoard(); } catch (_) {} }).catch(() => {});
}

function stopScrapeCampaign(cid) {
  const meta = _snStrips.get(cid) || {};
  // Confirm-then-allow: stopping someone else's scrape asks first (admin skips).
  if (!_snCanControl({ mine: meta.mine })) {
    _snPendingStop = cid;
    document.getElementById('snm-body').innerHTML =
      `This isn't your campaign — it belongs to <b>${escHtml(meta.owner || 'another operator')}</b>. Stopping it ends their scrape and frees its queue slot. Continue?`;
    document.getElementById('snm-scrim').classList.add('open');
    return;
  }
  _snDoStop(cid);
}
window.stopScrapeCampaign = stopScrapeCampaign;

function _snFmtLogTime(ts) { try { return new Date(ts).toLocaleTimeString(); } catch (_) { return ''; } }
// Severity: trust the line's own `level` when the app wrote it; fall back to the
// same text sniff the launch console already uses, since the engine's lines
// carry no level (only an emoji prefix).
function _snLogLevel(l) {
  if (l && l.level) return l.level === 'ok' ? 'ok' : (l.level === 'info' ? '' : 'err');
  const m = String((l && l.message) || '');
  if (/error|✗|⛔|fail|🚫|⚠/i.test(m)) return 'err';
  if (/done|✓|Σ|success|complete/i.test(m)) return 'ok';
  return '';
}
function _snLogRow(l) {
  const cls = _snLogLevel(l);
  return `<div><span class="t">${_snFmtLogTime(l.ts)}</span> <span class="${cls}">${escHtml(l.message)}</span></div>`;
}
async function _snLoadLogs(box) {
  const cid = box.dataset.logsfor;
  const meta = _snStrips.get(cid) || {};
  // For the operator's OWN scrape, mirror the SAME live log the launch console
  // shows (the in-memory scrapeLogLines) — that log actually works, and the
  // engine has no reliable per-campaign log to fetch.
  if (meta.mine && Array.isArray(scrapeLogLines) && scrapeLogLines.length) {
    box.innerHTML = scrapeLogLines.map(_snLogRow).join('');
    box.scrollTop = box.scrollHeight;
    return;
  }
  // Fallback for others / prior-session scrapes: the per-campaign server endpoint.
  try {
    const tab = box.dataset.tab ? `?tabName=${encodeURIComponent(box.dataset.tab)}` : '';
    const r = await fetch(`/api/scrape/campaigns/${encodeURIComponent(cid)}/logs${tab}`);
    const d = await r.json();
    box.innerHTML = (d.lines || []).map(_snLogRow).join('')
      || 'No stored logs for this scrape. The engine keeps a live log only while a scrape is running.';
    box.scrollTop = box.scrollHeight;
  } catch { box.textContent = 'Logs unavailable.'; }
}
