// ─────────────────────────────────────────────────────────────────────────────
// Placeholder tags
// ─────────────────────────────────────────────────────────────────────────────
function updatePlaceholderTags() {
  // v2.14.x: chip list is now mode-aware.
  //   - Empty/whitespace sheet columns dropped (a trailing-comma column
  //     header in the CSV used to produce a stray `{}` chip).
  //   - In CC+IC mode, {intro X} chips are hidden because they're aliases
  //     of {primary X} (auto-intro.js sets introName = primaryName). Showing
  //     both confused operators.
  //   - In IB mode, {primary X} chips are hidden — that mode has no primary
  //     concept; the introduction target is configured via the intro
  //     section's name field.
  //   - {primary name} renamed to {primary full name} for clarity vs
  //     {primary first name} / {primary last name}. auto-intro.js maps both
  //     keys to the same value so old templates with {primary name} still
  //     resolve.
  const mode = document.getElementById('campaign-mode')?.value || 'connect_only';
  const isCcIc = mode === 'connect_and_introduce';
  const isIb   = mode === 'introduce_back';

  const senderChips  = ['senderFirstName', 'senderName'];
  const introChips   = ['intro first name', 'intro last name'];
  const primaryChips = ['primary full name', 'primary first name', 'primary last name', 'primary url'];

  // v2.58.x — IC mode now mirrors CC+IC's chip layout: show {primary ...}
  // chips, hide {intro ...} chips. Both intro flows present the same
  // template variables so operators don't have to learn two vocabularies.
  // outreach.js's IC fast-path maps templates.introName into both intro-*
  // AND primary-* substitution keys, so existing presets that still use
  // {intro X} keep working — the chip UI is what changed.
  const isIntroFlow = isCcIc || isIb;
  const extras = [
    ...senderChips,
    ...(isIntroFlow ? [] : introChips),
    ...(isIntroFlow ? primaryChips : (isIb ? [] : primaryChips)),
  ];

  const sheetCols = (Array.isArray(sheetColumns) ? sheetColumns : [])
    .filter((c) => typeof c === 'string' && c.trim().length > 0);

  document.querySelectorAll('.placeholder-tags').forEach(container => {
    const tags = [...sheetCols, ...extras].map(col =>
      `<span class="tag" data-val="{${col}}">{${col}}</span>`
    ).join('');
    container.innerHTML = tags;
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Sheet preview
// ─────────────────────────────────────────────────────────────────────────────

// "Open Sheet" buttons — pop the campaign Google Sheet in the operator's
// default browser (Electron's setWindowOpenHandler routes window.open
// http* calls through shell.openExternal). Two callsites:
//   - Setup section, next to Preview Sheet — reads #sheet-url
//   - Cockpit row, next to Bulk check connections — reads __cockpit.sheetUrl,
//     auto-disabled when no URL is available
function _isValidHttpUrl(u) {
  return typeof u === 'string' && /^https?:\/\//i.test(u.trim());
}
function openSheetInBrowser() {
  const url = (document.getElementById('sheet-url')?.value || '').trim();
  if (!url) { alert('Enter a Google Sheet URL first.'); return; }
  if (!_isValidHttpUrl(url)) { alert("That doesn't look like a valid URL."); return; }
  window.open(url, '_blank', 'noopener,noreferrer');
}
function openRunningSheet() {
  // Prefer the running campaign's actual sheetUrl so the cockpit button
  // always opens the live sheet even if the operator has since edited
  // the setup input. Fall back to the setup input so the button is
  // usable BEFORE a campaign has started.
  const running = ((__cockpit && __cockpit.sheetUrl) || '').trim();
  const setup = (document.getElementById('sheet-url')?.value || '').trim();
  const url = running || setup;
  if (!url) { alert('Enter a Google Sheet URL first.'); return; }
  if (!_isValidHttpUrl(url)) { alert("That doesn't look like a valid URL."); return; }
  window.open(url, '_blank', 'noopener,noreferrer');
}
function _refreshOpenSheetButtons() {
  const btn = document.getElementById('btn-open-sheet-cockpit');
  if (!btn) return;
  const running = _isValidHttpUrl((__cockpit && __cockpit.sheetUrl) || '');
  const setup = _isValidHttpUrl((document.getElementById('sheet-url')?.value || '').trim());
  const has = running || setup;
  btn.disabled = !has;
  btn.title = running
    ? 'Open the running campaign sheet in your browser'
    : (setup ? 'Open the sheet you entered above' : 'Enter a sheet URL first');
}

// ─────────────────────────────────────────────────────────────────────────────
// Task 6: multi-tab lead-source guard
// ─────────────────────────────────────────────────────────────────────────────

// System tab names that should never be used as a lead source.
const SYSTEM_TAB_NAMES = new Set([
  'recent connections', 'recent messages', 'savedsearch/batches',
  'savedsearch', 'batches', 'soo', 'linkedin accounts',
  'ops log', 'events', 'config',
]);

function _isSystemTabName(name) {
  return SYSTEM_TAB_NAMES.has((name || '').trim().toLowerCase());
}

// Decide if header array + preview rows look like a lead tab.
// Requires: a "First Name" column AND a LinkedIn-URL-ish column.
function _looksLikeLeadHeader(headers) {
  if (!headers || headers.length === 0) return false;
  const lh = headers.map(h => (h || '').toString().trim().toLowerCase());
  const hasFirstName = lh.some(h => /^first[\s_]?name$/.test(h));
  const hasLinkedIn  = lh.some(h => /linkedin|profile\s*url|slug/i.test(h) || h === 'url');
  return hasFirstName && hasLinkedIn;
}

let _tabPickDebounceTimer = null;

// Called on #sheet-url input/blur — fetches tabs, shows picker if multi-tab.
async function refreshSheetTabPicker() {
  const urlEl = document.getElementById('sheet-url');
  const picker = document.getElementById('sheet-tab-picker');
  const select = document.getElementById('sheet-tab-select');
  const label  = document.getElementById('sheet-tab-picker-label');
  if (!urlEl || !picker || !select) return;

  const url = urlEl.value.trim();
  if (!url || !url.includes('docs.google.com/spreadsheets')) {
    picker.style.display = 'none';
    window._tabsData = [];
    window._tabPickerMulti = false;
    window._chosenSheetGid = '';
    window._tabLeadOk = true;
    return;
  }

  let tabs;
  try {
    const res = await fetch('/api/sheet/tabs?sheetUrl=' + encodeURIComponent(url));
    const data = await res.json();
    if (!res.ok || !data.tabs) { picker.style.display = 'none'; return; }
    tabs = data.tabs;
  } catch { picker.style.display = 'none'; return; }

  window._tabsData = tabs;
  window._tabPickerMulti = tabs.length > 1;

  if (tabs.length <= 1) {
    // Single-tab: auto-select, store gid, hide picker
    if (tabs.length === 1) {
      window._chosenSheetGid = String(tabs[0].gid || '');
      window._tabLeadOk = !_isSystemTabName(tabs[0].name) && _looksLikeLeadHeader(tabs[0].header || []);
    }
    picker.style.display = 'none';
    return;
  }

  // Multi-tab: show picker
  if (label) label.textContent = `This workbook has ${tabs.length} tabs — choose the campaign's lead list`;

  // Pre-select tab whose gid matches what's already in the URL
  const urlGid = (url.match(/[#&?]gid=(\d+)/) || [])[1] || '';

  select.innerHTML = tabs.map(tab => {
    const isSys = _isSystemTabName(tab.name);
    const tabLabel = isSys ? `${tab.name} — not leads` : tab.name;
    const detail = `· ${tab.rowCount} rows`;
    const selected = (urlGid && String(tab.gid) === urlGid) ? ' selected' : '';
    return `<option value="${tab.gid}"${selected} data-sys="${isSys}" data-name="${escHtml(tab.name)}">${escHtml(tabLabel)} ${detail}</option>`;
  }).join('');

  picker.style.display = '';
  // Trigger preview for the currently selected option
  onSheetTabChange();
}

function _debounceTabPicker() {
  clearTimeout(_tabPickDebounceTimer);
  _tabPickDebounceTimer = setTimeout(refreshSheetTabPicker, 500);
}

// Called on <select> change — preview the chosen tab.
async function onSheetTabChange() {
  const select   = document.getElementById('sheet-tab-select');
  const previewEl = document.getElementById('sheet-tab-preview');
  const blockEl  = document.getElementById('sheet-tab-leadblock');
  const blockBody = document.getElementById('sheet-tab-leadblock-body');
  if (!select) return;

  const gid = select.value;
  window._chosenSheetGid = gid;

  // Keep the URL field's gid in lockstep with the picked tab so the field, the
  // preview, and launch never diverge. The operator once picked Sheet2 while the
  // URL field still carried Sheet5's gid — confusing, and a foot-gun for any path
  // that reads the raw URL. Programmatic .value set fires no input/change event,
  // so this won't re-trigger the tab picker. Mirrors server withGid().
  if (gid) {
    const _urlEl = document.getElementById('sheet-url');
    const _g = String(gid).replace(/\D/g, '');
    if (_urlEl && _urlEl.value && _g) {
      let _u = _urlEl.value;
      _u = _u.replace(/([?&])gid=\d+/g, '$1gid=' + _g).replace(/#gid=\d+/g, '#gid=' + _g);
      if (!/[?&]gid=/.test(_u) && !/#gid=/.test(_u)) _u += (_u.includes('#') ? '' : '#') + 'gid=' + _g;
      _urlEl.value = _u;
    }
  }

  const opt = select.options[select.selectedIndex];
  const isSys = opt?.dataset?.sys === 'true';
  const tabName = opt?.dataset?.name || gid;

  if (!gid) {
    if (previewEl) previewEl.style.display = 'none';
    if (blockEl) blockEl.style.display = 'none';
    window._tabLeadOk = false;
    return;
  }

  // Find tab header from cached data
  const tabInfo = (window._tabsData || []).find(t => String(t.gid) === String(gid));
  const header = tabInfo ? (tabInfo.header || []) : [];

  if (isSys || !_looksLikeLeadHeader(header)) {
    // Show block
    window._tabLeadOk = false;
    if (previewEl) previewEl.style.display = 'none';
    if (blockEl) {
      blockEl.style.display = '';
      if (blockBody) {
        if (isSys) {
          blockBody.innerHTML = `The selected tab <code>${escHtml(tabName)}</code> is a system tab (LinkedIn data log), not your leads. Pick the campaign's lead tab — the one with <b>First Name</b> + a <b>LinkedIn URL</b> column.`;
        } else {
          blockBody.innerHTML = `The selected tab <code>${escHtml(tabName)}</code> doesn't look like a lead list — it's missing a <b>First Name</b> column and/or a <b>LinkedIn URL</b> column. Pick the right tab.`;
        }
      }
    }
    return;
  }

  // Looks like leads — show preview
  window._tabLeadOk = true;
  if (blockEl) blockEl.style.display = 'none';

  // Build 3-row preview from header + up to 3 rows if available
  if (previewEl) {
    const topCols = header.slice(0, 5); // first 5 cols
    const colPills = topCols.map(h => {
      const isKey = /^first[\s_]?name$/i.test(h) || /linkedin|profile\s*url/i.test(h);
      return isKey ? `<b>${escHtml(h)} ✓</b>` : escHtml(h);
    }).join(' · ');

    let html = `<div class="tabpick-cols">Detected columns: ${colPills}</div>`;

    // Try to fetch a small preview via the existing /api/sheet/preview endpoint with the gid
    try {
      const urlEl = document.getElementById('sheet-url');
      const baseUrl = (urlEl?.value || '').trim();
      // Build url with this gid
      const previewUrl = baseUrl.replace(/[#&?]gid=\d+/g, '').replace(/#$/, '') + '#gid=' + gid;
      const res = await fetch('/api/sheet/preview?url=' + encodeURIComponent(previewUrl));
      const data = await res.json();
      if (!data.error && data.preview && data.preview.length > 0) {
        const cols = data.columns.slice(0, 5);
        html += '<table class="mini"><thead><tr>';
        cols.forEach(c => { html += `<th>${escHtml(c)}</th>`; });
        html += '</tr></thead><tbody>';
        data.preview.slice(0, 3).forEach(row => {
          html += '<tr>';
          cols.forEach(c => { html += `<td>${escHtml(String(row[c] || ''))}</td>`; });
          html += '</tr>';
        });
        html += '</tbody></table>';
      }
    } catch { /* preview fetch failed — still show col pills */ }

    html += `<div class="tabpick-ok">✓ Looks like a lead list — ready to launch.</div>`;
    previewEl.innerHTML = html;
    previewEl.style.display = '';
  }
}

// Show the rerun tab-change confirm modal.
// Resolves true (proceed) or false (cancel).
function _showTabChangeModal(fromLabel, toLabel) {
  return new Promise(resolve => {
    const scrim = document.getElementById('tab-change-modal');
    const bodyEl = document.getElementById('tab-change-modal-body');
    const confirmBtn = document.getElementById('tab-change-confirm');
    const cancelBtn  = document.getElementById('tab-change-cancel');
    if (!scrim) { resolve(true); return; }

    if (bodyEl) {
      bodyEl.innerHTML = `This rerun will pull leads from a <b>different tab</b> than last time:<br><br>from <span class="from">"${escHtml(fromLabel)}"</span><br>to <span class="to">"${escHtml(toLabel)}"</span>`;
    }
    scrim.classList.add('open');

    function cleanup() { scrim.classList.remove('open'); confirmBtn.onclick = null; cancelBtn.onclick = null; }
    confirmBtn.onclick = () => { cleanup(); resolve(true); };
    cancelBtn.onclick  = () => { cleanup(); resolve(false); };
  });
}

window.onSheetTabChange = onSheetTabChange;
window.refreshSheetTabPicker = refreshSheetTabPicker;

// True if any sample row's value for `col` looks like a LinkedIn profile URL
// (contains linkedin.com) or a generic http(s) URL. Used to guard the
// LinkedIn-URL column picker against a wrong (non-URL) column choice.
function _looksLikeUrlColumn(col, rows) {
  for (const row of (rows || [])) {
    const v = String((row && row[col]) || '').toLowerCase();
    if (v.includes('linkedin.com') || /^https?:\/\//.test(v)) return true;
  }
  return false;
}

async function previewSheet() {
  const url = document.getElementById('sheet-url').value.trim();
  const preview = document.getElementById('sheet-preview');
  if (!url) { alert('Enter a Google Sheet URL first.'); return; }
  preview.classList.remove('hidden');
  preview.innerHTML = 'Loading…';
  try {
    const res = await fetch(`/api/sheet/preview?url=${encodeURIComponent(url)}`);
    const data = await res.json();
    if (data.error) { preview.innerHTML = `<p style="color:#f85149">Error: ${escHtml(data.error)}</p>`; return; }
    // v2.62: count becomes data-count so the CSS in .sheet-hero-preview can
    // render it as the big hero stat via ::before. Plain text fallback also
    // reads sensibly outside the hero context.
    let html = `<p data-count="${data.totalRows}">rows pulled · just now</p>`;
    if (data.preview.length > 0) {
      html += '<table class="preview-table"><thead><tr>';
      data.columns.forEach(col => { html += `<th>${escHtml(col)}</th>`; });
      html += '</tr></thead><tbody>';
      data.preview.forEach(row => {
        html += '<tr>';
        data.columns.forEach(col => { html += `<td>${escHtml(row[col] || '')}</td>`; });
        html += '</tr>';
      });
      html += '</tbody></table>';
    }
    // Column selector — auto-detect by scanning sample rows for linkedin.com.
    // v2.59: restyled to use the ic-row layout (label-block on left, select
    // on right) so it matches the '1st Connection Column' picker below.
    let autoDetectCol = null;
    if (data.preview && data.preview.length > 0) {
      for (const col of data.columns) {
        for (const row of data.preview) {
          const val = (row[col] || '').toLowerCase();
          if (val.includes('linkedin.com')) { autoDetectCol = col; break; }
        }
        if (autoDetectCol) break;
      }
    }
    let _urlOpts = '';
    data.columns.forEach((col) => {
      const sel = (autoDetectCol && col === autoDetectCol) ? 'selected' : '';
      _urlOpts += `<option value="${escHtml(col)}" ${sel}>${escHtml(col)}</option>`;
    });
    html += `<div class="tabpick" id="linkedin-col-pick" style="margin-top:12px; border:1px solid var(--card-border); border-radius:12px;">
      <div class="tabpick-head"><span class="dot"></span> Which column holds the LinkedIn profile URL?</div>
      <select id="linkedin-col-select">${_urlOpts}</select>
      <div id="linkedin-col-autodetect" style="font-family:var(--mono); font-size:0.78rem; color:var(--green); margin-top:8px; ${autoDetectCol ? '' : 'display:none'}">✓ Auto-detected${autoDetectCol ? ` from “${escHtml(autoDetectCol)}”` : ''} — values look like linkedin.com/in/… profiles.</div>
      <div id="linkedin-col-guard" class="leadblock" style="display:none; margin-top:10px;">
        <div class="lb-title">⛔ That doesn't look like a URL column</div>
        <div class="lb-body">This column's cells aren't <code>linkedin.com/in/…</code> links. Pick the column whose values are LinkedIn profile URLs, or the app can't open the right person.</div>
      </div>
    </div>`;
    // v2.59: the duplicated 'Which column contains the LinkedIn 1st
    // connections?' dropdown previously added here was removed — the IC
    // extras section below already exposes the same picker (#ic-sender-col-select)
    // with a richer label-block layout, and surfacing it twice was confusing.

    // v2.58.x — IC-only extras: sender-column picker + "all leads already
    // connected" checkbox. Rendered inline next to the URL picker so it
    // sits in the same visual block. Visibility is toggled by
    // updateIcExtrasVisibility(), wired into onModeChange(). Block is
    // hidden in non-IC modes so other campaigns are unaffected.
    //
    // Auto-detect for the sender column:
    //   1. Header match (case-insensitive): prefer headers commonly used by
    //      Ortus operators — 'Sender', 'LinkedIn 1st Connections', 'Account',
    //      'Account Used', 'Owner'.
    //   2. Value match: first column whose sample rows contain '@' (email-
    //      style values, e.g. alecx@ortus.solutions).
    //   3. Fallback: no preselection — operator picks manually.
    let autoSenderCol = null;
    const SENDER_HEADER_PRIORITY = [
      'sender', 'linkedin 1st connections', 'linkedin 1st connection',
      'account used', 'account', 'owner',
    ];
    for (const wanted of SENDER_HEADER_PRIORITY) {
      const found = data.columns.find((c) => (c || '').toString().trim().toLowerCase() === wanted);
      if (found && found !== autoDetectCol) { autoSenderCol = found; break; }
    }
    if (!autoSenderCol && data.preview && data.preview.length > 0) {
      for (const col of data.columns) {
        if (col === autoDetectCol) continue;
        for (const row of data.preview) {
          const val = (row[col] || '').toString();
          if (val.includes('@')) { autoSenderCol = col; break; }
        }
        if (autoSenderCol) break;
      }
    }

    preview.innerHTML = html;

    // Wire the LinkedIn-URL column guard. The auto-detected column passes the
    // initial check (green ✓ line stays); picking a non-URL column (e.g. a bio
    // text column) swaps in the red leadblock warning.
    const _urlSel = document.getElementById('linkedin-col-select');
    if (_urlSel) {
      const _rows = data.preview || [];
      const _validateUrlCol = () => {
        const ok = _looksLikeUrlColumn(_urlSel.value, _rows);
        const guard = document.getElementById('linkedin-col-guard');
        const auto = document.getElementById('linkedin-col-autodetect');
        if (guard) guard.style.display = ok ? 'none' : 'block';
        if (auto) auto.style.display = ok ? '' : 'none';
      };
      _urlSel.addEventListener('change', _validateUrlCol);
      _validateUrlCol(); // initial check (auto-detected col should pass)
    }

    sheetColumns = data.columns;
    window.sheetTotalRows = typeof data.totalRows === 'number' ? data.totalRows : null;
    try { window.__sheetPreviewCache = { count: (typeof data.totalRows === 'number' ? data.totalRows : 0), at: Date.now() }; } catch (_) {}
    try { if (typeof updateSectionSummaries === 'function') updateSectionSummaries(); } catch (_) {}
    updatePlaceholderTags();
    updateCampaignSummary();

    // v2.58.x — IC sheet mapping (Variant C — progressive disclosure).
    // Flip the empty state hidden, show the filled form, populate dropdown
    // options. Auto-detect badge appears only if the operator hasn’t already
    // manually picked a column (tracked via data-manual-pick).
    try {
      const empty = document.getElementById('ic-extras-empty');
      const filled = document.getElementById('ic-extras-filled');
      const sel = document.getElementById('ic-sender-col-select');
      const badge = document.getElementById('ic-auto-detected-badge');
      if (empty) empty.classList.add('hidden');
      if (filled) filled.classList.remove('hidden');
      if (sel) {
        const isManual = sel.dataset.manualPick === '1';
        const cur = sel.value;
        const keepCur = isManual && cur && data.columns.includes(cur);
        const chosen = keepCur ? cur : (autoSenderCol || '');
        const opts = [`<option value="">— Use "Sender" column —</option>`];
        data.columns.forEach((col) => {
          const selected = (col === chosen) ? 'selected' : '';
          opts.push(`<option value="${escHtml(col)}" ${selected}>${escHtml(col)}</option>`);
        });
        sel.innerHTML = opts.join('');
        // Badge shows only when we did the auto-detect, not when the
        // operator manually picked. Manual pick state survives across
        // preview re-runs (operator's choice is sticky).
        const showBadge = !isManual && !!autoSenderCol && chosen === autoSenderCol;
        sel.classList.toggle('is-detected', showBadge);
        if (badge) badge.classList.toggle('hidden', !showBadge);
      }
    } catch (_) {}
  } catch (err) {
    preview.innerHTML = `<p style="color:#f85149">${escHtml(err.message)}</p>`;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Campaign summary calculator
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────
// v2.11.0 — Throughput panel. The leads/hour knob (alpha-leads-per-hour) has
// been removed entirely. The campaign now runs as fast as the queue can rotate
// with a 6-min per-account turn floor enforced server-side. Only the per-account
// campaign limit remains user-tunable.
// alphaSyncRate / alphaStepLeads kept as no-op stubs because some inline
// onclick="" handlers and old presets still reference them; deletion would
// surface ReferenceErrors in console without behavioral benefit.
function alphaSyncRate() { updateCampaignSummary(); }
function alphaStepLeads(_delta) { updateCampaignSummary(); }

// Campaign-limit-per-account (was "Daily limit"). Mirrors the visible input to
// the hidden #daily-limit input that app.js submits to the backend.
// v2.60.x: oninput-safe sync. The previous version auto-rewrote an empty
// or sub-1 field back to 50 on EVERY keystroke, which made it impossible
// to backspace the existing value to type a new one (delete last digit →
// field empty → handler refills with 50 → can't ever go blank). Now:
//  - empty / in-progress input is allowed during typing (no rewrite)
//  - upper bound (500) is clamped live so "9999" can't sneak through
//  - lower bound + default fallback runs on blur via alphaBlurDailyLimit
function alphaSyncDailyLimit() {
  const visEl = document.getElementById('daily-limit-input');
  const hidEl = document.getElementById('daily-limit');
  if (!visEl || !hidEl) return;
  const raw = visEl.value;
  if (raw === '' || raw === '-') {
    updateCampaignSummary();
    return;
  }
  let v = parseInt(raw, 10);
  if (!Number.isFinite(v)) {
    updateCampaignSummary();
    return;
  }
  if (v > 500) {
    visEl.value = '500';
    v = 500;
  }
  hidEl.value = String(v);
  updateCampaignSummary();
}

// Blur-time clamp + fallback. Restores 50 when the field is empty/invalid
// so we never submit a blank or below-min value to the backend.
function alphaBlurDailyLimit() {
  const visEl = document.getElementById('daily-limit-input');
  const hidEl = document.getElementById('daily-limit');
  if (!visEl || !hidEl) return;
  let v = parseInt(visEl.value, 10);
  if (!Number.isFinite(v) || v < 1) v = 50;
  v = Math.max(1, Math.min(500, v));
  visEl.value = String(v);
  hidEl.value = String(v);
  updateCampaignSummary();
}
window.alphaBlurDailyLimit = alphaBlurDailyLimit;

function alphaStepDaily(delta) {
  const visEl = document.getElementById('daily-limit-input');
  if (!visEl) return;
  const cur = parseInt(visEl.value, 10) || 50;
  visEl.value = String(Math.max(1, Math.min(500, cur + delta)));
  alphaSyncDailyLimit();
}

// v2.61: Concurrency stepper. Mirrors alphaStepDaily — adjusts the
// concurrency-count input and triggers a forecast refresh. Bounded by the
// input's own min/max (2–5).
function alphaStepConcurrency(delta) {
  const el = document.getElementById('concurrency-count');
  if (!el || el.disabled) return;
  const cur = parseInt(el.value, 10) || 2;
  const min = parseInt(el.min, 10) || 2;
  const max = parseInt(el.max, 10) || 5;
  el.value = String(Math.max(min, Math.min(max, cur + delta)));
  updateCampaignSummary();
}

// 2.9.8: Concurrency toggle. Enables/disables the count input and updates
// the campaign summary. Visibility (≥5 accounts) is handled in alphaRecalc.
function alphaSyncConcurrency() {
  const tog = document.getElementById('concurrency-toggle');
  const cnt = document.getElementById('concurrency-count');
  if (!tog || !cnt) return;
  cnt.disabled = !tog.checked;
  updateCampaignSummary();
}

// Task 4 (2026-06-19): B1 delay-danger disclaimer — show when #within-batch-min < 30.
function checkDelayDanger() {
  const min = parseInt(document.getElementById('within-batch-min')?.value || '30', 10);
  const block = document.getElementById('delay-danger-block');
  if (block) block.classList.toggle('show', min < 30);
}

// Task 4 (2026-06-19): B2 pause-on-throttle help text update.
function syncPauseOnThrottleHelp() {
  const tog = document.getElementById('pause-on-throttle');
  const help = document.getElementById('pause-on-throttle-help');
  if (!tog || !help) return;
  help.innerHTML = tog.checked
    ? '<b>On:</b> the account stops sending and backs off when throttled, then resumes slower — protects it from restriction. Other accounts keep running.'
    : '<b>Off:</b> the account keeps sending through throttling. Faster, but risks more skips and pushes the account toward restriction. Not recommended.';
}

// Is this launch going to the VM? Same two conditions the dispatch itself uses
// (app.js ~6281): an engine-supported mode AND the run-target checkbox. Shared so
// the Throughput panel can never disagree with where the campaign actually runs.
const CLOUD_CAPABLE_MODES = new Set(['connect_only', 'message_only', 'introduce_back',
  'connect_and_introduce', 'connect_and_message', 'follower_growth',
  'inmail_only', 'open_profile_only', 'check_status']);
function isCloudRunOn() {
  return CLOUD_CAPABLE_MODES.has(document.getElementById('campaign-mode')?.value)
    && !!document.getElementById('cloud-run-checkbox')?.checked;
}

function alphaRecalc() {
  // v2.11.0: simpler model. Total max invites this run = N accounts × campaign limit.
  // v2.61 redesign removed the alpha-total-leads/acct-count/per-acct/eq-total
  // hero elements from index.html. The OLD `if (!totalEl) return` guard then
  // short-circuited this whole function — so the concurrency-unlock block below
  // (the ONLY place that adds .is-unlocked) never ran, leaving "Parallel
  // accounts" permanently locked in EVERY mode no matter how many accounts were
  // selected. Don't gate on those removed elements; every write below is
  // individually null-guarded, so the function safely no-ops when they're absent.
  const totalEl = document.getElementById('alpha-total-leads');
  const acctCountEl = document.getElementById('alpha-acct-count');
  const perAcctEl = document.getElementById('alpha-per-acct');
  const eqTotalEl = document.getElementById('alpha-eq-total');

  const numAccounts = Array.isArray(selectedProfileIds) ? selectedProfileIds.length : 0;
  const dailyLimit = parseInt(document.getElementById('daily-limit')?.value, 10) || 50;
  const total = dailyLimit * numAccounts;

  if (totalEl) totalEl.textContent = total > 0 ? String(total) : '—';
  if (acctCountEl) acctCountEl.textContent = String(numAccounts);
  if (perAcctEl)   perAcctEl.textContent   = String(dailyLimit);
  if (eqTotalEl)   eqTotalEl.textContent   = String(total);

  // Concurrency toggle unlocked at ≥5 accounts. The server only honors
  // concurrency>1 when ≥5 accounts are selected (server.js buildCampaignConfig),
  // so the UI threshold MUST match — otherwise the toggle is enabled but a
  // silent no-op for 2-4 accounts (the bug this restores the fix for).
  // v2.61 briefly lowered this to ≥2 to match a then-incorrect assumption;
  // reverted to ≥5 to stay honest with the backend gate.
  // Row is always rendered; the .is-unlocked class controls whether the
  // controls are interactive or dimmed (CSS handles the visual state and
  // shows the "available with 5+ accounts" pill when locked).
  const concurrencyRow = document.getElementById('alpha-concurrency-row');
  const concurrencyToggle = document.getElementById('concurrency-toggle');
  const concurrencyCount = document.getElementById('concurrency-count');
  // Cloud: swap the whole knob for the pacing explanation. handleStartCloud never
  // reads `concurrency`, so on the VM this control is a no-op — and the engine
  // already works accounts in parallel under the shared account lock.
  const cloudPacing = document.getElementById('alpha-cloud-pacing');
  const onCloud = isCloudRunOn();
  if (concurrencyRow) concurrencyRow.hidden = onCloud;
  if (cloudPacing) cloudPacing.hidden = !onCloud;
  if (onCloud) {
    // Force the local multiplier back to 1 so a stale toggle can't feed the
    // forecast a parallel speed-up the cloud will never deliver.
    if (concurrencyToggle) concurrencyToggle.checked = false;
    if (concurrencyCount) concurrencyCount.disabled = true;
  }
  if (concurrencyRow && !onCloud) {
    const unlocked = numAccounts >= 5;
    concurrencyRow.classList.toggle('is-unlocked', unlocked);
    if (!unlocked) {
      // Auto-disable + uncheck when locked so the math falls back to 1
      if (concurrencyToggle) concurrencyToggle.checked = false;
      if (concurrencyCount) concurrencyCount.disabled = true;
    } else if (concurrencyCount) {
      // When unlocked, count is enabled iff the toggle is on
      concurrencyCount.disabled = !concurrencyToggle?.checked;
    }
  }
}

// ── Capacity forecast (feature ⑥) ──────────────────────────────────────────
// Quiet mono line under the daily-limit knob: target leads × capacity →
// projected finish. Recomputed by updateCampaignSummary whenever the sheet
// preview, account selection, or daily limit changes. Amber when the run
// would exceed 14 days — same threshold as the list_vs_limit pre-flight lint.
function updateCapacityForecast() {
  const el = document.getElementById('capacity-forecast-line');
  if (!el) return;
  const targetCount = (typeof window.sheetTotalRows === 'number' && window.sheetTotalRows > 0)
    ? window.sheetTotalRows : 0;
  const dailyLimit = parseInt(document.getElementById('daily-limit')?.value, 10) || 0;
  const accountCount = Array.isArray(selectedProfileIds) ? selectedProfileIds.length : 0;
  const fc = forecastCapacity({ targetCount, dailyLimit, accountCount });
  if (!fc) { el.style.display = 'none'; el.classList.remove('is-warn'); return; }
  const dateStr = fc.finishDate.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short' });
  const acctWord = accountCount === 1 ? 'account' : 'accounts';
  const warn = fc.days > WARN_DAYS;
  el.innerHTML =
    `Capacity: <b>${dailyLimit}</b>/day × <b>${accountCount}</b> ${acctWord} = <b>${fc.perDay}</b>/day → ` +
    `~<b>${fc.days}</b> day${fc.days === 1 ? '' : 's'} for <b>${targetCount}</b> leads (done by <b>${escapeHtml(dateStr)}</b>)` +
    (warn ? ' — over two weeks of sending' : '');
  el.classList.toggle('is-warn', warn);
  el.style.display = '';
}

function updateCampaignSummary() {
  // Phase 2.8.14: alpha throughput panel recalculates whenever this fires
  // (account toggle, rate/pause edit). Safe to call before alpha is ready —
  // it null-guards every element lookup.
  alphaRecalc();
  updateCapacityForecast();
  const mode = document.getElementById('campaign-mode')?.value || 'connect_only';

  // Keep the Sales Nav Scrape pairing summary live as accounts are toggled.
  if (mode === 'sales_nav_scrape') { try { updateScrapePairing(); } catch (_) {} }

  // v2.11.0: vocabulary kept for hero copy. Rate/limit labels are gone from UI;
  // these strings only feed the summary block.
  const MODE_WORDS = {
    connect_only:        { action: 'connections',            actionVerb: 'sending'  },
    message_only:        { action: 'messages',               actionVerb: 'sending'  },
    inmail_only:         { action: 'InMails',                actionVerb: 'sending'  },
    open_profile_only:   { action: 'Open Profile messages',  actionVerb: 'sending'  },
    check_status:        { action: 'checks',                 actionVerb: 'checking' },
  };
  const words = MODE_WORDS[mode] || MODE_WORDS.connect_only;

  // Cap the daily-limit input at the sheet row count once known.
  const limitInput = document.getElementById('daily-limit');
  const rows = typeof window.sheetTotalRows === 'number' && window.sheetTotalRows > 0 ? window.sheetTotalRows : null;
  if (limitInput && rows) {
    limitInput.max = String(rows);
    const current = parseInt(limitInput.value, 10) || 0;
    if (current > rows) limitInput.value = String(rows);
  }

  const limit = parseInt(document.getElementById('daily-limit').value, 10) || 50;
  const numAccounts = selectedProfileIds.length;

  // v2.11.0: throughput math — each account does up to 5 leads per turn with a
  // 6-min minimum between turns → ceiling of ~50 leads/hr per active worker.
  // With C concurrent workers, real throughput ≈ 50 × C leads/hr (capped by
  // total invites = limit × numAccounts).
  const concurrencyToggle = document.getElementById('concurrency-toggle');
  const concurrencyCount = document.getElementById('concurrency-count');
  // Gate matches alphaRecalc visual gate AND the server gate (≥5 accounts).
  // Below 5 accounts the server forces concurrency=1, so the forecast must
  // not promise a parallel multiplier it won't deliver.
  const concurrency = (concurrencyToggle?.checked && numAccounts >= 5)
    ? Math.max(1, Math.min(5, parseInt(concurrencyCount?.value, 10) || 2))
    : 1;
  const TURN_FLOOR_MIN = 6;
  const LEADS_PER_BATCH = 5;
  const perAccountLeadsPerHour = (60 / TURN_FLOOR_MIN) * LEADS_PER_BATCH; // 50
  const effectiveLeadsPerHour = perAccountLeadsPerHour * concurrency;

  const dailyTotal = limit * numAccounts;
  // Total leads to process — only known once the operator has previewed the
  // sheet. Falls back to today's batch (dailyTotal) when unknown so the
  // "select accounts to see forecast" path keeps working.
  const leadsInSheet = (typeof window.sheetTotalRows === 'number' && window.sheetTotalRows > 0)
    ? window.sheetTotalRows
    : null;
  const isMultiDay = leadsInSheet !== null && leadsInSheet > dailyTotal && dailyTotal > 0;

  // "Actions" cell shows total leads to process when the campaign spans more
  // than today; otherwise today's batch.
  const totalActions = isMultiDay ? leadsInSheet : dailyTotal;

  // Duration:
  // - single-day:  totalActions / leadsPerHour, expressed in minutes
  // - multi-day:   ceil(leadsInSheet / dailyTotal) days, expressed in days/weeks
  let durationStr, finishStr, minutesNeededSingleDay = 0;
  if (isMultiDay) {
    const daysNeeded = Math.ceil(leadsInSheet / dailyTotal);
    durationStr = daysNeeded < 7
      ? `${daysNeeded} day${daysNeeded === 1 ? '' : 's'}`
      : daysNeeded < 14
        ? `${daysNeeded} days · ~${Math.round(daysNeeded / 7)} week`
        : `${daysNeeded} days · ~${Math.round(daysNeeded / 7)} weeks`;
    const finishDate = new Date(Date.now() + daysNeeded * 86400000);
    finishStr = finishDate.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  } else {
    minutesNeededSingleDay = totalActions > 0
      ? Math.max(1, Math.ceil((totalActions / effectiveLeadsPerHour) * 60))
      : 0;
    durationStr = minutesNeededSingleDay === 0
      ? '—'
      : minutesNeededSingleDay < 60
        ? `${minutesNeededSingleDay} min`
        : `${Math.floor(minutesNeededSingleDay / 60)}h ${minutesNeededSingleDay % 60}m`;
    const finishTime = new Date(Date.now() + minutesNeededSingleDay * 60 * 1000);
    finishStr = minutesNeededSingleDay === 0
      ? '—'
      : finishTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  }

  const el = document.getElementById('summary-stats');
  if (el) {
    const accountWord = numAccounts === 1 ? 'account' : 'accounts';
    const summaryFinish = isMultiDay ? `around ${finishStr}` : finishStr;
    el.innerHTML = `
      <div><strong>${numAccounts} ${accountWord}</strong>, up to <strong>${limit}</strong> ${words.action} per account per day</div>
      <div>= up to <strong>${dailyTotal}</strong> ${words.action}/day · <strong>${leadsInSheet ?? '?'}</strong> in sheet</div>
      <div style="margin-top:6px">&#9200; Starts now &#8594; ${isMultiDay ? `finishes ~<strong>${finishStr}</strong>` : `finishes ~<strong>${summaryFinish}</strong>`}</div>
    `;
  }

  // Launch hero mirror
  const ln = document.getElementById('launch-number');
  if (ln) ln.textContent = String(dailyTotal); // big number = daily rate
  const lc = document.getElementById('launch-connections');
  if (lc) {
    lc.textContent = leadsInSheet
      ? `${dailyTotal}/day · ${leadsInSheet} in sheet`
      : `${dailyTotal} ${words.action}/day`;
  }
  const la = document.getElementById('launch-accounts');
  if (la) la.textContent = String(numAccounts);
  const le = document.getElementById('launch-eta');
  // Same correction as the Throughput headline: on the VM an hour-count ETA is
  // meaningless, so the launch strip reports days of capacity too.
  if (le) {
    if (isCloudRunOn()) {
      const _cv = cloudThroughputView({ accounts: numAccounts, dailyLimit: limit, leadsInSheet });
      le.textContent = _cv.finish;
    } else {
      le.textContent = durationStr;
    }
  }

  // Settings-section campaign hero
  const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  const accountWord = numAccounts === 1 ? 'account' : 'accounts';
  // Phase 2.8.16: when no accounts selected, show "—" everywhere instead of
  // misleading numbers derived from a default-of-1.
  // CLOUD: describe capacity/day, not wall-clock. The local model above divides
  // by "~50 leads/hr × parallel browsers", which does not describe the VM — work
  // spreads over autoscaled pods and the parallel knob is never sent to the
  // engine. What bounds a cloud campaign is the daily cap the engine enforces per
  // account per day, so say that instead of inventing an hour count.
  if (isCloudRunOn()) {
    const cv = cloudThroughputView({
      accounts: numAccounts,
      dailyLimit: limit,
      leadsInSheet,
    });
    setText('hero-actions', cv.actions);
    setText('hero-actions-sub', cv.actionsSub);
    setText('hero-duration-k', cv.durationK);
    setText('hero-duration', cv.duration);
    setText('hero-duration-sub', cv.durationSub);
    setText('hero-finish-k', cv.finishK);
    setText('hero-finish', cv.finish);
    setText('hero-finish-sub', cv.finishSub);
    return;
  }
  // Local runs keep the wall-clock forecast — and the labels, which the cloud
  // branch above rewrites.
  setText('hero-duration-k', 'Duration');
  setText('hero-finish-k', 'Finishes');
  if (numAccounts === 0) {
    setText('hero-actions', '—');
    setText('hero-actions-sub', `select accounts to see forecast`);
    setText('hero-duration', '—');
    setText('hero-duration-sub', '—');
    setText('hero-finish', '—');
    setText('hero-finish-sub', '—');
  } else {
    setText('hero-actions', String(totalActions));
    setText(
      'hero-actions-sub',
      isMultiDay
        ? `leads to process · ${dailyTotal}/day cap`
        : `${numAccounts} ${accountWord} × ${limit} per day`,
    );
    setText('hero-duration', durationStr);
    setText(
      'hero-duration-sub',
      isMultiDay
        ? `~${effectiveLeadsPerHour} ${words.action}/hr active`
        : `~${effectiveLeadsPerHour} ${words.action}/hr (${concurrency} parallel)`,
    );
    setText('hero-finish', finishStr);
    setText('hero-finish-sub', isMultiDay ? `estimated · LinkedIn caps may slow this` : `from now · local time`);
  }
}

// Stepper helper — increments/decrements a number input and fires its oninput
function stepInput(inputId, delta) {
  const el = document.getElementById(inputId);
  if (!el) return;
  const cur = parseInt(el.value, 10) || 0;
  const min = parseInt(el.min, 10);
  const max = parseInt(el.max, 10);
  let next = cur + delta;
  if (!isNaN(min)) next = Math.max(min, next);
  if (!isNaN(max)) next = Math.min(max, next);
  el.value = String(next);
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

// ── Pre-flight linter (spec 2026-07-07) ────────────────────────────────────
let _pfState = null; // { findings, ack, payload, opts }

async function runPreflight(payload) {
  const r = await fetch('/api/preflight', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok || !data.ok) throw new Error(data.error || r.statusText);
  return data;
}

function renderPreflight({ findings }) {
  const fill = (id, list, isFinding) => {
    const el = document.getElementById(id);
    el.innerHTML = list.map((f) => {
      if (!isFinding) {
        return `<div class="pf-row pf-pass"><span class="rowno">✓</span><span class="reason">${escapeHtml(f.detail)}</span></div>`;
      }
      if (f.rowIndex == null) {
        // Sheet-level finding — no row number; "Sheet" label spans the first two columns.
        return `<div class="pf-row pf-sheet-level"><span class="rowno">Sheet</span><span class="lead"></span><span class="reason">${escapeHtml(f.detail)}</span></div>`;
      }
      return `<div class="pf-row"><span class="rowno">Row ${escapeHtml(String(f.rowIndex))}</span><span class="lead">${escapeHtml(f.leadName || '')}</span><span class="reason">${escapeHtml(f.detail)}</span></div>`;
    }).join('') || '<div class="pf-row pf-sheet-level"><span class="rowno">—</span><span class="lead"></span><span class="reason">none</span></div>';
  };
  fill('pf-blockers', findings.blockers, true);
  fill('pf-warnings', findings.warnings, true);
  fill('pf-passed', findings.passed, false);
  document.getElementById('pf-count-blockers').textContent = findings.blockers.length;
  document.getElementById('pf-count-warnings').textContent = findings.warnings.length;
  document.getElementById('pf-count-passed').textContent = findings.passed.length;
  document.getElementById('pf-blockers-n').textContent = findings.blockers.length;
  document.getElementById('pf-warnings-n').textContent = findings.warnings.length;
  document.getElementById('pf-passed-n').textContent = findings.passed.length;
  // Blocklist findings are never overridable — adapt button label accordingly.
  const hasBl = findings.blockers.some((f) => f.check === 'blocklist_match');
  const anyway = document.getElementById('pf-anyway');
  anyway.textContent = hasBl ? 'Keep flagged, launch anyway (blocklisted still excluded)' : 'Launch anyway';
  anyway.style.display = findings.blockers.length || findings.warnings.length ? '' : 'none';
  // Show/hide warning tally chip
  const warnChip = document.getElementById('pf-tally-warnings');
  if (warnChip) warnChip.style.display = findings.warnings.length ? '' : 'none';
  document.getElementById('pf-scrim').style.display = 'flex';
}

function closePreflight() { document.getElementById('pf-scrim').style.display = 'none'; }

// Disable/enable the 4 overlay action buttons + show a "re-checking…" note
// while the blocklist-triggered re-lint runs.
function _setPfActionsDisabled(disabled) {
  ['pf-fix', 'pf-exclude', 'pf-anyway', 'pf-cancel'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.disabled = disabled;
  });
  const sub = document.getElementById('pf-sub');
  if (sub) {
    if (disabled) {
      if (sub.getAttribute('data-prev-text') == null) sub.setAttribute('data-prev-text', sub.innerHTML);
      sub.innerHTML = '<span style="color:var(--gray);font-style:italic">re-checking against the updated blocklist…</span>';
    } else {
      const prev = sub.getAttribute('data-prev-text');
      if (prev != null) { sub.innerHTML = prev; sub.removeAttribute('data-prev-text'); }
    }
  }
}

// If the pre-flight overlay is open with stored results, re-run the lint so
// blocklist edits are reflected immediately (no Cancel + Start-again needed).
async function _recheckPreflightIfOpen() {
  if (!_pfState) return;
  const scrim = document.getElementById('pf-scrim');
  if (!scrim || scrim.style.display === 'none') return;
  _setPfActionsDisabled(true);
  try {
    const fresh = await runPreflight(_pfState.payload);
    _pfState = { findings: fresh.findings, ack: fresh.ack, payload: _pfState.payload, opts: _pfState.opts };
    renderPreflight(fresh);
  } catch (err) {
    showCampaignToast('Blocklist saved — pre-flight re-check failed: ' + (err && err.message || 'unknown error') + '. Showing previous results.', 7000);
  } finally {
    _setPfActionsDisabled(false);
  }
}

async function stampExcluded(stampables) {
  if (!stampables.length) return { ok: true, stamped: 0, failed: [] };
  const r = await fetch('/api/preflight/stamp', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      sheetUrl: _pfState.payload.sheetUrl,
      linkedinColumn: _pfState.payload.linkedinColumn,
      stamps: stampables.map((f) => ({ url: f.url, stampText: f.stampText })),
    }),
  });
  return r.json().catch(() => ({ ok: false, stamped: 0, failed: [] }));
}

function _launchWithAck() {
  startCampaign({ ..._pfState.opts, _preflightAck: _pfState.ack, _skipPreflight: true });
}

document.addEventListener('DOMContentLoaded', () => {
  // Pre-flight overlay buttons
  const pfCancel = document.getElementById('pf-cancel');
  const pfFix = document.getElementById('pf-fix');
  const pfExclude = document.getElementById('pf-exclude');
  const pfAnyway = document.getElementById('pf-anyway');
  const pfManageBl = document.getElementById('pf-manage-bl');
  const pfPassToggle = document.getElementById('pf-pass-toggle');
  if (pfCancel) pfCancel.onclick = closePreflight;
  if (pfFix) pfFix.onclick = () => {
    if (_pfState?.payload?.sheetUrl) window.open(_pfState.payload.sheetUrl, '_blank');
  };
  if (pfExclude) pfExclude.onclick = async () => {
    const stampables = (_pfState?.findings?.blockers || []).filter((f) => f.url && f.stampText);
    const res = await stampExcluded(stampables);
    if (!res.ok) showCampaignToast(`${res.failed.length} of ${stampables.length} stamps failed — those rows may reappear next launch`, 7000);
    closePreflight();
    _launchWithAck();
  };
  if (pfAnyway) pfAnyway.onclick = async () => {
    // Blocklisted rows are always stamped+excluded even on "launch anyway".
    const bl = (_pfState?.findings?.blockers || []).filter((f) => f.check === 'blocklist_match');
    if (bl.length) {
      const res = await stampExcluded(bl);
      if (!res.ok) showCampaignToast(`${res.failed.length} of ${bl.length} blocklist stamps failed — rows may reappear next launch`, 7000);
    }
    closePreflight();
    _launchWithAck();
  };
  if (pfManageBl) pfManageBl.onclick = openBlocklistPanel;
  if (pfPassToggle) pfPassToggle.onclick = () => {
    document.getElementById('grp-pass')?.classList.toggle('collapsed');
  };

  // Blocklist panel buttons
  const blAdd = document.getElementById('bl-add');
  const blClose = document.getElementById('bl-close');
  if (blAdd) blAdd.onclick = async () => {
    const value = document.getElementById('bl-value').value.trim();
    if (!value) return;
    await fetch('/api/blocklist', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ value, reason: document.getElementById('bl-reason').value.trim(), addedBy: (window.operatorEmail || '') }),
    });
    document.getElementById('bl-value').value = '';
    document.getElementById('bl-reason').value = '';
    await openBlocklistPanel();
    if (typeof renderWizardBlocklist === 'function') renderWizardBlocklist();
    _recheckPreflightIfOpen();
  };
  if (blClose) blClose.onclick = () => {
    document.getElementById('bl-scrim').style.display = 'none';
    _recheckPreflightIfOpen();
  };
});

// ── Inline wizard blocklist (Section 2, under the sheet URL) — same data as
// the #bl-scrim panel. Chips + inline add; refreshed after add/remove.
async function renderWizardBlocklist() {
  const chips = document.getElementById('wiz-bl-chips');
  if (!chips) return;
  const r = await fetch('/api/blocklist').then((x) => x.json()).catch(() => ({ entries: [] }));
  chips.innerHTML = (r.entries || []).map((e) =>
    `<span class="wiz-bl-chip" title="${escapeHtml(e.reason || '')}">${escapeHtml(e.value)}<button type="button" class="wiz-bl-x" data-v="${escapeHtml(e.value)}" aria-label="Remove ${escapeHtml(e.value)} from blocklist">×</button></span>`
  ).join('') || '<span class="wiz-bl-empty">No blocklisted companies yet</span>';
  chips.querySelectorAll('.wiz-bl-x').forEach((btn) => btn.onclick = async () => {
    await fetch('/api/blocklist', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value: btn.dataset.v }) });
    renderWizardBlocklist();
    _recheckPreflightIfOpen();
  });
}

document.addEventListener('DOMContentLoaded', () => {
  const wizAdd = document.getElementById('wiz-bl-add');
  const wizInput = document.getElementById('wiz-bl-value');
  const doAdd = async () => {
    const value = (wizInput?.value || '').trim();
    if (!value) return;
    await fetch('/api/blocklist', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ value, reason: '', addedBy: (window.operatorEmail || '') }),
    });
    wizInput.value = '';
    renderWizardBlocklist();
    _recheckPreflightIfOpen();
  };
  if (wizAdd) wizAdd.onclick = doAdd;
  if (wizInput) wizInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); doAdd(); } });
  renderWizardBlocklist(); // populate chips on wizard render
});

async function openBlocklistPanel() {
  const r = await fetch('/api/blocklist').then((x) => x.json()).catch(() => ({ entries: [] }));
  const list = document.getElementById('bl-list');
  list.innerHTML = (r.entries || []).map((e) =>
    `<div class="bl-row"><span class="bl-entry">${escapeHtml(e.value)}</span><span class="bl-reason-cell">${escapeHtml(e.reason || '')}</span><span class="bl-meta">${escapeHtml(e.addedBy || '')} · ${escapeHtml((e.addedAt || '').slice(0, 10))}</span><button class="bl-remove" data-v="${escapeHtml(e.value)}">Remove</button></div>`
  ).join('') || '<div style="font-family:var(--mono);font-size:0.72rem;color:var(--gray);padding:12px 4px">No entries yet</div>';
  list.querySelectorAll('.bl-remove').forEach((btn) => btn.onclick = async () => {
    await fetch('/api/blocklist', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value: btn.dataset.v }) });
    await openBlocklistPanel();
    if (typeof renderWizardBlocklist === 'function') renderWizardBlocklist();
    _recheckPreflightIfOpen();
  });
  document.getElementById('bl-scrim').style.display = 'flex';
}

// ─────────────────────────────────────────────────────────────────────────────
// Campaign control
// ─────────────────────────────────────────────────────────────────────────────
async function addToQueueCampaign() { return startCampaign({ queueOnly: true }); }
async function startCampaign(opts = {}) {
  // 2.9.5: when mode is check_dms, this is a separate flow with its own
  // endpoint and no campaign templates. Delegate to startCheckDms() and
  // return — the rest of this function only applies to outreach campaigns.
  const _modeEarly = document.getElementById('campaign-mode').value;
  if (_modeEarly === 'check_dms') {
    return startCheckDms();
  }
  // v3.0 (Phase 2): Post Amp has its own flow — no sheet, no templates, no
  // SoO sender resolution, own backend endpoint.
  if (_modeEarly === 'post_amplification') {
    return startPostAmplification();
  }

  // One-at-a-time: a campaign in the monitoring phase occupies the single
  // campaign slot. Launching a new one resets that state (campaign.js
  // startCampaign), silently ending the acceptance watch. Warn first.
  try {
    if (typeof __cockpit !== 'undefined' && __cockpit && __cockpit.state === 'monitoring') {
      const ok = confirm('A campaign is currently monitoring for acceptances. Starting a new campaign will end that monitoring. Continue?');
      if (!ok) return;
    }
  } catch { /* if __cockpit is unavailable, don't block the launch */ }

  // 2.8.29 / 2.8.31: check_status and message_only auto-derive profiles from
  // the sheet's Account Used column. UI selection ignored — skip validation.
  // v2.58.x: introduce_back (Introduction Campaign) is also auto-routed from
  // the chosen Sender column — the profile picker is hidden for this mode
  // (see onModeChange at line ~1459), so requiring a manual pick was a
  // pre-existing gate bug that surfaced once IC ran on a no-Stage sheet.
  const _modeForValidation = _modeEarly;
  const _autoRoutedModes = new Set(['check_status', 'message_only', 'introduce_back']);
  if (!_autoRoutedModes.has(_modeForValidation) && selectedProfileIds.length === 0) {
    alert('Select at least one GoLogin profile.'); return;
  }
  // v2.112.26 (#1): the "Before you start…" assigned/in-use confirm dialog was
  // removed as obsolete — the persistent banner in the accounts picker already
  // surfaces this, so Start no longer interrupts with a popup. (The banner stays;
  // only the blocking dialog is gone.)
  const sheetUrl = document.getElementById('sheet-url').value.trim();
  if (!sheetUrl) { alert('Enter a Google Sheet URL.'); return; }
  const dailyLimit = parseInt(document.getElementById('daily-limit').value, 10);
  if (!dailyLimit || dailyLimit < 1) { alert('Limit must be at least 1.'); return; }

  // "Message Open Profiles Directly" in Connection Campaign mode sends either
  // an OP message (if the lead is OP) or a connection request (if not), so
  // both templates must be filled before the campaign can start.
  const _mode = document.getElementById('campaign-mode').value;
  const _opMsgOn = !!document.getElementById('open-profile-msg')?.checked;
  if (_mode === 'connect_only' && _opMsgOn) {
    const opBody = (document.getElementById('tpl-op-body')?.value || '').trim();
    if (!opBody) { alert('Open Profile body template is required when "Message Open Profiles Directly" is on.'); return; }
  }

  // v2.14.x: Hard-block Start for Connect + Introduce Back when the primary
  // person fields are empty. Without them, the campaign would send connection
  // requests but every accepted lead would silently SKIP the intro DM (the
  // server logs a warning but the operator never sees it). Block at click-time
  // and scroll/focus the first empty field so the operator can fix it.
  if (_mode === 'connect_and_introduce') {
    const _pName = (document.getElementById('primary-person-name')?.value || '').trim();
    const _pUrl  = (document.getElementById('primary-person-url')?.value  || '').trim();
    const _pBody = (document.getElementById('primary-intro-body')?.value || '').trim();
    if (!_pName || !_pBody) {
      const missing = [];
      if (!_pName) missing.push('• Primary Person · Full name');
      if (!_pBody) missing.push('• Intro DM Body');
      alert(
        'Connect + Introduce Back can\'t start without the primary person.\n\n' +
        'Missing:\n' + missing.join('\n') + '\n\n' +
        'Without these, accepted invites can\'t be auto-introduced to anyone. ' +
        'Fill in the missing field(s) and try again.'
      );
      const firstEmpty = !_pName ? 'primary-person-name' : 'primary-intro-body';
      const el = document.getElementById(firstEmpty);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => el.focus(), 400);
      }
      return;
    }
  }
  // v2.62: CC+DM validation — the post-acceptance body is required.
  // Without it, every accepted invite would silently skip the DM
  // (auto-dm.js logs a warning but the operator never sees it).
  if (_mode === 'connect_and_message') {
    const _ccDmBody = (document.getElementById('tpl-cc-dm-body')?.value || '').trim();
    if (!_ccDmBody) {
      alert(
        "Connect + DM can't start without the post-acceptance DM body.\n\n" +
        'Missing:\n• Post-acceptance DM\n\n' +
        "Without it, accepted invites can't be auto-messaged. " +
        'Fill in the field and try again.'
      );
      const el = document.getElementById('tpl-cc-dm-body');
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => el.focus(), 400);
      }
      return;
    }
  }

  // v2.58.x — IC validation: intro-name (the primary person) + Intro DM Body
  // (primary-intro-body) must both be filled. Same gate as CC+IC's primary
  // checks above but scoped to IC's actual fields.
  if (_mode === 'introduce_back') {
    // Name now comes from the Primary Person block (full CC+IC mirror), falling
    // back to the legacy intro-name for un-migrated campaigns.
    const _icName = (document.getElementById('primary-person-name')?.value || '').trim()
      || (document.getElementById('intro-name')?.value || '').trim();
    const _icBody = (document.getElementById('primary-intro-body')?.value || '').trim();
    if (!_icName || !_icBody) {
      const missing = [];
      if (!_icName) missing.push('• Primary Person · Full name');
      if (!_icBody) missing.push('• Intro DM Body');
      alert(
        "Introduction Campaign can't start without these fields.\n\n" +
        'Missing:\n' + missing.join('\n') + '\n\n' +
        'Fill in the missing field(s) and try again.'
      );
      const firstEmpty = !_icName ? 'primary-person-name' : 'primary-intro-body';
      const el = document.getElementById(firstEmpty);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => el.focus(), 400);
      }
      return;
    }
  }

  // v2.112: primary URL is REQUIRED to launch CC+IC — it's the identity the
  // connected-to-primary check + auto-accept + the persistent store all key on.
  // (Structural check only, no network lookup, so it can block without false-flagging.)
  // v2.119: ICB does NOT require the URL — its leads are already connected, so the
  // URL is only used for the {primary url} placeholder. Empty just omits the token.
  if (_mode === 'connect_and_introduce') {
    const _pUrlEl = document.getElementById('primary-person-url');
    const _pUrlVal = (_pUrlEl?.value || '').trim();
    if (!_pUrlVal) {
      const _msg = 'Primary person URL is required for this mode.';
      showPrimaryUrlError(_msg);
      alert(_msg + '\n\nAdd the Primary Person · LinkedIn profile URL and try again.');
      if (_pUrlEl) {
        _pUrlEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => _pUrlEl.focus(), 400);
      }
      return;
    }
    const _v = validatePrimaryUrl(_pUrlVal);
    if (!_v.ok) {
      showPrimaryUrlError(_v.reason);
      alert(
        "That doesn't look like the Primary person's LinkedIn profile URL.\n\n" +
        _v.reason + '\n\n' +
        'Fix the Primary Person · LinkedIn profile URL and try again.'
      );
      if (_pUrlEl) {
        _pUrlEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => _pUrlEl.focus(), 400);
      }
      return;
    }
    clearPrimaryUrlError();
  }

  // Task 6: tab picker lock — block launch when multi-tab workbook has no
  // valid lead tab chosen.
  if (window._tabPickerMulti) {
    if (!window._chosenSheetGid) {
      const _pickerEl = document.getElementById('sheet-tab-picker');
      if (_pickerEl) _pickerEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      alert('This workbook has multiple tabs — pick the lead tab before launching.');
      return;
    }
    if (!window._tabLeadOk) {
      const _select = document.getElementById('sheet-tab-select');
      const _tabName = _select?.options[_select.selectedIndex]?.dataset?.name || window._chosenSheetGid;
      const _blockEl = document.getElementById('sheet-tab-leadblock');
      if (_blockEl) _blockEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      alert(`Can't launch — the selected tab "${_tabName}" isn't a lead list. Pick the correct lead tab.`);
      return;
    }
  }

  // Resolve sender first names per profile (SoO column D, or local-browser input).
  // Resolver runs silently — the operator-facing preview popup was dropped
  // in favour of the post-launch tips card. Sheet-snapshot disclaimer lives
  // there now too.
  const senderFirstNames = {};
  for (const id of selectedProfileIds) {
    const pName = selectedProfileNames[id] || id;
    senderFirstNames[id] = resolveSenderFirstName(id, pName);
  }

  const mode = document.getElementById('campaign-mode').value;
  // v2.13.x — Group conversation title + primary-person / Intro DM Body fields
  // belong ONLY to the two intro flows (CC+IC connect_and_introduce, IC
  // introduce_back). Switching CC+IC → CC+DM only hides those inputs, it
  // doesn't clear them, so a leftover CC+IC config would otherwise leak into
  // the campaign config and the post-campaign sweep (which fires a real group
  // intro on primaryName+primaryIntroBody). Gate them at the source. Mirrors
  // gatherCampaignFormState's preview gating; backed by the sweep's mode gate
  // (post-campaign-bulk-check.js shouldFirePostCampaignIntro) as defense-in-depth.
  const _isIntroFlow = (mode === 'connect_and_introduce' || mode === 'introduce_back');
  // ICB full-mirror: primary name from the Primary Person block, falling back to
  // the legacy intro-name for un-migrated campaigns. Keeps introName (the value
  // typed into LinkedIn's typeahead) populated.
  const _icPrimaryName2 = (document.getElementById('primary-person-name')?.value?.trim() || '')
    || (document.getElementById('intro-name')?.value?.trim() || '');

  // Phase 11.2 (D-02, D-07): within-batch gap comes from explicit steppers for
  // non-message modes. Message mode keeps the #message-gap stepper because
  // messaging existing connections has different cadence semantics.
  let delayMin, delayMax;
  if (mode === 'message_only') {
    const gap = parseInt(document.getElementById('message-gap')?.value, 10) || 60;
    delayMin = Math.max(5, Math.round(gap * 0.8));
    delayMax = Math.max(delayMin + 5, Math.round(gap * 1.3));
  } else {
    delayMin = parseInt(document.getElementById('within-batch-min')?.value, 10) || 30;
    delayMax = parseInt(document.getElementById('within-batch-max')?.value, 10) || 60;
    if (delayMax < delayMin) [delayMin, delayMax] = [delayMin, delayMin + 5];
  }

  // v2.11.0: batchesPerHour removed. Backend hardcodes a 6-min per-account
  // turn floor and lets the queue rotation pace the rest.

  // If the user answered "No" to the "add a note while connecting?" question,
  // drop the connection note regardless of what's in the textarea.
  const addNoteOn = localStorage.getItem('ortus-add-note') === '1';
  // v2.58.x — IC routes its body through primary-intro-body (CC+IC's body
  // field) so the wizard shows the SAME Intro DM Body section as CC+IC.
  // Backend still reads templates.followUpMessage (via the followUp1 alias
  // in campaign.js:1187), so we map the value here. Other modes unchanged.
  const _icBody = (mode === 'introduce_back')
    ? (document.getElementById('primary-intro-body')?.value || document.getElementById('tpl-followup').value || '')
    : document.getElementById('tpl-followup').value;
  const templates = {
    // v2.59: drop addNoteOn gate — textarea value IS the note.
    connectionNote: document.getElementById('tpl-note').value,
    followUp1: _icBody,
    inmailSubject: document.getElementById('tpl-inmail-subject').value,
    inmailBody: document.getElementById('tpl-inmail-body').value,
    openProfileSubject: document.getElementById('tpl-op-subject')?.value || '',
    openProfileBody: document.getElementById('tpl-op-body')?.value || '',
    opChannel: document.getElementById('tpl-op-channel')?.value || 'sn_first',
    opSpendInMail: !!document.getElementById('tpl-op-spend-inmail')?.checked,
    // 2.8.50: Introduction Messages sub-mode (active only when mode is message_only)
    // v2.11.13: in-memory state instead of localStorage (storage may be blocked).
    introMode: mode === 'introduce_back',
    introName: (mode === 'introduce_back') ? _icPrimaryName2 : (document.getElementById('intro-name')?.value?.trim() || ''),
    // Intro-flows-only — blank for CC+DM / connect_only / message_only / InMail /
    // Open Profile so a leftover CC+IC config can't leak into the campaign
    // config or the post-campaign sweep.
    introTitle: _isIntroFlow
      ? (document.getElementById('intro-title')?.value || 'Introduction: {first name} <> {intro name}')
      : '',
    // Connect + Introduce Back: primary person + intro DM body. Backend
    // stores these on the campaign config; auto-send-after-acceptance is
    // the next chunk of work. Gated to intro flows for the same reason.
    primaryName: (mode === 'introduce_back') ? _icPrimaryName2 : (_isIntroFlow ? (document.getElementById('primary-person-name')?.value?.trim() || '') : ''),
    primaryUrl:  _isIntroFlow ? (document.getElementById('primary-person-url')?.value?.trim() || '') : '',
    primaryIntroBody: _isIntroFlow ? (document.getElementById('primary-intro-body')?.value || '') : '',
    // v2.91: CC+IC auto-accept + automated first follow-up. DOM-read at launch,
    // gated to intro flows. Backend normalizeTemplates passes these through.
    autoAcceptPrimary: _isIntroFlow ? !!document.getElementById('auto-accept-toggle')?.checked : false,
    autoAcceptAllPending: _isIntroFlow ? !!document.getElementById('auto-accept-all-toggle')?.checked : false,
    followUpEnabled: _isIntroFlow ? !!document.getElementById('follow-up-toggle')?.checked : false,
    followUpBody: _isIntroFlow ? (document.getElementById('follow-up-body')?.value || '') : '',
    followUpDelayMinutes: _isIntroFlow ? (Number(document.getElementById('follow-up-delay')?.value) || 10) : 10,
    primarySource: _isIntroFlow ? readPrimarySource() : 'local-browser',
    // v2.62: CC+DM post-acceptance body — read at launch time too.
    // v2.160.126: mode-gated, matching the preview path. Every consumer
    // already checks mode === 'connect_and_message' (campaign.js:2956, 4205,
    // 4263, 6192), so this changes nothing for a real CC+DM run — it just
    // stops a stray body being persisted into a CC+IC campaign's templates,
    // where a future consumer could read it without checking the mode.
    ccDmBody: mode === 'connect_and_message' ? (document.getElementById('tpl-cc-dm-body')?.value || '') : '',
  };

  // v2.94.x: if either primary-side action is on and the primary is set to a
  // GoLogin profile, a profile must be chosen — else there's no browser to use.
  if (_isIntroFlow) {
    const _aaOn = !!document.getElementById('auto-accept-toggle')?.checked;
    const _fuOn = !!document.getElementById('follow-up-toggle')?.checked;
    const _src = document.querySelector('input[name="primary-source"]:checked')?.value;
    if ((_aaOn || _fuOn) && _src === 'gologin' && !(document.getElementById('primary-source-profile-id')?.value || '')) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast('Pick which GoLogin profile your primary uses, or switch to your local browser.');
      }
      return;
    }
  }

  // Unique campaign name within YOUR campaigns (non-FG). On a collision, auto
  // append/increment a letter suffix (_a, _b … _d→_e) and update the input so
  // the launched campaign — and its dashboard row — carry the unique name.
  // Skipped in cloud-edit redispatch mode (that keeps the campaign's own name).
  try {
    if (mode !== 'follower_growth' && !(_cloudEdit && _cloudEdit.paused)) {
      const ni = document.getElementById('campaign-name-input');
      const desired = (ni?.value || '').trim();
      if (desired) {
        const unique = _uniqueCampaignName(desired, _existingMineCampaignNames());
        if (ni && unique !== desired) {
          ni.value = unique;
          if (typeof showCampaignToast === 'function') showCampaignToast(`That name is taken — saved as "${unique}".`, 4500);
        }
      }
    }
  } catch (_) { /* naming is best-effort — never block a launch */ }

  // Show account queue
  renderAccountQueue(selectedProfileIds.map(id => selectedProfileNames[id] || id), null);

  const body = {
    profileIds: selectedProfileIds,
    // v2.78: accounts to start benched (out of the rotation).
    benchedProfileIds: [...benchedProfileIds].filter((id) => selectedProfileIds.includes(id)),
    sheetUrl,
    sheetGid: window._chosenSheetGid || '',
    multiTab: !!window._tabPickerMulti,
    templates,
    dailyLimit,
    mode,
    primaryName: templates.primaryName,
    messageOpenProfiles: !!document.getElementById('open-profile-msg')?.checked,
    delayMin,
    delayMax,
    linkedinColumn: document.getElementById('linkedin-col-select')?.value || '',
    // v2.58.x — Introduction Campaign (introduce_back) optional overrides.
    // v2.61: Extended to Direct Messages (message_only) — same wizard
    // extras block (#ic-extras) is shared so both modes pick a sender
    // column and can toggle "all leads connected". Server coerces to
    // empty/false for other modes (server.js:635-636).
    senderColumn: (mode === 'introduce_back' || mode === 'message_only')
      ? (document.getElementById('ic-sender-col-select')?.value || '')
      : '',
    allLeadsConnected: (mode === 'introduce_back' || mode === 'message_only')
      ? !!document.getElementById('ic-all-connected-toggle')?.checked
      : false,
    senderFirstNames,
    // 2.9.8: parallel-accounts knob. Server only honors it when ≥5
    // accounts are selected and the toggle is on.
    concurrency: (() => {
      const tog = document.getElementById('concurrency-toggle');
      const cnt = document.getElementById('concurrency-count');
      if (!tog?.checked) return 1;
      const n = parseInt(cnt?.value, 10);
      return Number.isFinite(n) && n >= 2 ? Math.min(5, n) : 2;
    })(),
    // Campaign Name from the wizard's top-of-page input. Empty string is
    // valid — the dashboard row falls back to "Add name" inline-editable.
    name: (document.getElementById('campaign-name-input')?.value || '').trim(),
    // Pre-flight Check Status sweep. Toggle lives inside each mode's
    // coverage section (Section 2b for message_only, 2c for
    // introduce_back). v2.57.7 — IC toggle (preflight-check-toggle-ib)
    // reinstated; read whichever toggle matches the current mode. Server
    // ignores the field for any other mode.
    preflightCheckStatus: (() => {
      if (mode === 'message_only')   return !!document.getElementById('preflight-check-toggle-mo')?.checked;
      if (mode === 'introduce_back') return !!document.getElementById('preflight-check-toggle-ib')?.checked;
      return false;
    })(),
    // Operator-chosen cadence for the monitoring auto-trigger. Honoured for
    // EVERY mode that monitors for acceptance (CC+IC and CC+DM) — gated on the
    // same usesMonitoringCadence() predicate that shows the dropdown, so the
    // two can never drift. (Previously this read only fired for CC+IC, so the
    // CC+DM dropdown was shown but its value silently dropped → default 60.)
    // Server clamps to [60, 720] (shared clampCadenceMinutes) and ignores the field for other modes.
    checkIntervalMinutes: (() => {
      if (!usesMonitoringCadence(mode)) return undefined;
      const v = parseInt(document.getElementById('check-cadence-select')?.value, 10);
      return Number.isFinite(v) ? v : 60;
    })(),
    // v2.112: operator can launch with the after-sending automatic checks OFF
    // (default on). Only meaningful for monitoring modes; gated like cadence so
    // the two never drift. Backend defaults absent → enabled.
    autoChecksEnabled: usesMonitoringCadence(mode)
      ? (document.getElementById('auto-checks-toggle')?.checked !== false)
      : undefined,
    // #7: when the primary connect/check happens. Only meaningful for CC+IC;
    // omitted otherwise so the server keeps its default.
    primaryCheckTiming: (mode === 'connect_and_introduce')
      ? (document.getElementById('primary-timing-select')?.value || 'immediately')
      : undefined,
    // Task 4 (2026-06-19): pause the account when LinkedIn returns 429.
    // Default true (ON) — operator can disable in Advanced section.
    pauseOnThrottle: document.getElementById('pause-on-throttle')?.checked === true,
  };

  // v2.58.x — IC preflight: catch "no sender column" / "no matching profile"
  // cases BEFORE the campaign starts, so the operator gets a targeted popup
  // instead of finding the failure in the post-start log rail.
  if (body.mode === 'introduce_back') {
    const ok = await _runIcPreflight(body.sheetUrl, body.senderColumn);
    if (!ok) return; // modal shown by _runIcPreflight; operator must fix
  }

  // v2.59 resume: if the operator stopped a campaign from this wizard and
  // is now pressing Start without leaving the page, treat it as a resume
  // of that campaign — name match required so editing the name then
  // starting becomes a fresh run (operator's explicit intent). The flag
  // is cleared after the start either way.
  try {
    const raw = localStorage.getItem('wizardStoppedFromContext');
    if (raw) {
      const ctx = JSON.parse(raw);
      if (ctx && ctx.name && ctx.name === (body.name || '').trim()) {
        body.resumeContext = { totalProcessed: Number(ctx.totalProcessed) || 0 };
      }
    }
  } catch {}

  // Task 6: rerun tab-change confirm — when the campaign has a saved sheetGid
  // and the operator chose a different tab, show the confirm modal.
  // Fold in the window-level savedSheetGid set by rerunPastCampaign() so the
  // modal fires even when startCampaign is called with opts={} from a button click.
  if (!opts.savedSheetGid && window._savedSheetGid) {
    opts = { ...opts, savedSheetGid: window._savedSheetGid };
  }
  if (!opts.skipTabChangeConfirm) {
    try {
      const _savedGid = String(opts.savedSheetGid || '');
      const _chosenGid = String(window._chosenSheetGid || '');
      if (_savedGid && _chosenGid && _savedGid !== _chosenGid) {
        // Find display names
        const _fromTab = (window._tabsData || []).find(t => String(t.gid) === _savedGid);
        const _toTab   = (window._tabsData || []).find(t => String(t.gid) === _chosenGid);
        const _fromLabel = (_fromTab?.name || `gid ${_savedGid}`);
        const _toLabel   = (_toTab?.name   || `gid ${_chosenGid}`);
        const _proceed = await _showTabChangeModal(_fromLabel, _toLabel);
        if (!_proceed) return;
      }
    } catch { /* non-blocking — proceed */ }
  }
  // Rerun context consumed — clear so a subsequent fresh launch isn't treated as a rerun.
  window._savedSheetGid = '';

  // ⑤+①: instant launch feedback. Only for an immediate Start (not Queue), and
  // only now that every validation early-return above is behind us. Shown BEFORE
  // pre-flight so it covers the full dead-air (client pre-flight + start fetch),
  // and it keeps the previous campaign's card hidden until the new run boots.
  if (!opts.queueOnly) beginLaunching((document.getElementById('campaign-name-input')?.value || '').trim());

  // ── Pre-flight gate (spec 2026-07-07) ──────────────────────────────────────
  if (!opts._skipPreflight) {
    try {
      const pf = await runPreflight({
        sheetUrl: body.sheetUrl, linkedinColumn: body.linkedinColumn,
        mode: body.mode, templates: body.templates,
        dailyLimit: body.dailyLimit, profileIds: body.profileIds,
        sheetGid: body.sheetGid || window._chosenSheetGid || '',
      });
      _pfState = { findings: pf.findings, ack: pf.ack, payload: body, opts };
      if (pf.findings.blockers.length || pf.findings.warnings.length) {
        endLaunching();        // ⑤: hide the launch popup — the pre-flight overlay takes over
        renderPreflight(pf);   // overlay takes over; its buttons re-enter with _skipPreflight
        return;
      }
      body.preflightAck = pf.ack; // clean run — attach ack and continue
      // A clean pre-flight used to launch silently, which reads as "the check
      // didn't run" — especially when rows stamped "Skipped: …" by an earlier
      // pre-flight are being excluded invisibly. Say what happened.
      const _pfPrev = (pf.findings.passed || []).find((p) => p.check === 'previously_excluded');
      const _pfPrevN = _pfPrev ? parseInt(_pfPrev.detail, 10) : 0;
      showCampaignToast(
        `Pre-flight ✓ — ${pf.findings.targetCount} target(s) clean`
        + (_pfPrevN ? ` · ${_pfPrevN} row(s) already excluded by an earlier pre-flight (see their Stage column)` : ''),
        _pfPrevN ? 9000 : 5000,
      );
    } catch (err) {
      endLaunching();          // ⑤: hide the launch popup on a pre-flight failure
      showCampaignToast(`Pre-flight failed: ${err.message}`, 7000);
      return;
    }
  } else if (opts._preflightAck) {
    body.preflightAck = opts._preflightAck;
  }
  // ── End pre-flight gate ───────────────────────────────────────────────────

  // Cloud dispatch: only for an immediate "Start" (not Queue/Schedule/Draft) and
  // only for engine-supported modes. Gated on the mode so a non-cloud mode NEVER
  // routes to cloud even if the (hidden) checkbox is checked. The checkbox mirrors
  // the run-target tabs (setRunTarget); default is 💻 This machine (unchecked → local).
  const _cloudModeNow = new Set(['connect_only', 'message_only', 'introduce_back',
    'connect_and_introduce', 'connect_and_message', 'follower_growth',
    'inmail_only', 'open_profile_only', 'check_status']).has(document.getElementById('campaign-mode')?.value);
  const _cloudOn = _cloudModeNow && !!document.getElementById('cloud-run-checkbox')?.checked;
  if (_cloudOn && !opts.queueOnly) {
    opts = { ...opts, cloud: true };
    // Schedule on the VM: same dispatch, one extra field. The engine parks the
    // campaign in 'scheduled' and starts it itself at this instant — no cron on
    // this machine, so the app can be closed the whole time.
    if (opts.startAt) body.startAt = opts.startAt;
    // Follower Growth cloud extras (server defaults the URL to the Ortus page).
    if (document.getElementById('campaign-mode')?.value === 'follower_growth') {
      body.inviteUrl = document.getElementById('fg-invite-url')?.value?.trim() || '';
      const _b = parseInt(document.getElementById('fg-monthly-budget')?.value, 10);
      body.monthlyBudget = Number.isFinite(_b) && _b > 0 ? _b : 30;
    }
  }

  const _outcome = await submitStartCampaign(body, opts);
  // ⑤+①: retire the launch popup. On an immediate LOCAL start the new run needs
  // a beat to flip `running` true — leave the popup up and let pollStatus dismiss
  // it the instant the new campaign boots, so the card never flashes the previous
  // one. Every other outcome (cloud dispatched, queued, or failed) is terminal
  // here: refresh the card once so it reflects reality, then hide.
  if (!(_outcome && _outcome.started)) {
    try { if (typeof pollStatus === 'function') await pollStatus(); } catch (_) { /* */ }
    endLaunching();
  }
}

// Show the "Run in cloud" toggle only for modes the engine supports; hide (and
// clear) it otherwise. Called from onModeChange + on init.
function refreshCloudToggle() {
  const wrap = document.getElementById('cloud-run-toggle');
  if (!wrap) return;
  const mode = document.getElementById('campaign-mode')?.value || '';
  const CLOUD_MODES = new Set(['connect_only', 'message_only', 'introduce_back',
    'connect_and_introduce', 'connect_and_message', 'follower_growth',
    'inmail_only', 'open_profile_only', 'check_status']);
  const show = CLOUD_MODES.has(mode);
  wrap.style.display = show ? '' : 'none';
  const cb = document.getElementById('cloud-run-checkbox');
  // Don't force the checkbox here — the run-target tabs (setRunTarget) own its
  // state (default 💻 This machine = unchecked). Forcing it would fight the tab
  // selection + the operator's manual choice (onchange calls us).
  // FG extras: visible only for follower_growth while the cloud toggle is on.
  const fg = document.getElementById('cloud-fg-extras');
  if (fg) fg.style.display = (show && mode === 'follower_growth' && cb?.checked) ? '' : 'none';
  // The Cloud Campaigns section is only relevant once the engine is in play —
  // reveal it whenever a cloud-eligible mode is selected.
  const panel = document.getElementById('cloud-campaigns-section');
  if (panel && show) panel.style.display = '';
}

// ─── Run-target tabs (💻 This machine / ☁︎ Cloud VM) ────────────────────────
// Task 2.3: wires up the tabs markup + CSS shipped inert in Task 2.2.
// getRunTarget() is the single read path (backed by #run-target's
// data-target); setRunTarget() is the only write path and keeps
// #cloud-run-checkbox.checked in sync so the launch-time cloud dispatch gate
// above (untouched) needs no changes — cloud tab → checked → cloud dispatch
// for cloud-supported modes, local tab → unchecked → local dispatch.
function getRunTarget() {
  return document.getElementById('run-target')?.dataset.target || DEFAULT_RUN_TARGET;
}
function setRunTarget(t) {
  const root = document.getElementById('run-target');
  if (!root) return;
  if (t === 'cloud' && !_engineConfigured) t = 'local'; // engine unconfigured → cloud unavailable
  root.dataset.target = t;
  root.querySelectorAll('.rt-tab').forEach((b) => b.classList.toggle('on', b.dataset.rt === t));
  const cb = document.getElementById('cloud-run-checkbox');
  if (cb) cb.checked = (t === 'cloud');   // keep the launch source-of-truth in sync
  refreshRunTarget();
}
function refreshRunTarget() {
  const t = getRunTarget();
  const facts = document.getElementById('run-target-facts');
  if (facts) facts.innerHTML = runTargetFacts(t).map((f) =>
    `<span class="rt-fact"><span class="i">${f.ok ? '✓' : '—'}</span><span>${escHtml(f.text)}</span></span>`).join('');
  if (typeof renderModeSelector === 'function') renderModeSelector();
  if (typeof renderManifest === 'function') renderManifest();
  refreshCloudToggle();
  refreshLaunchForRunTarget();
  if (typeof refreshAccountPickerForRunTarget === 'function') refreshAccountPickerForRunTarget();
  // Section 4 reads differently per target — capacity/day on the VM, wall-clock
  // locally — and the Parallel-accounts knob is hidden in cloud. Without this the
  // panel kept whichever target was selected when it last rendered.
  if (typeof alphaRecalc === 'function') alphaRecalc();
  if (typeof updateCampaignSummary === 'function') updateCampaignSummary();
}
// #btn-queue is a local-only launch path (Queue → addToQueueCampaign, which
// never dispatches cloud) — hidden under the VM tab. #btn-schedule works on BOTH
// targets: locally it writes a node-cron schedule, on the VM it dispatches the
// campaign with a startAt and the ENGINE holds it until then (launchScheduleIt).
// #launch-run-note was added (empty) to the launch card in Task 2.2.
function refreshLaunchForRunTarget() {
  const cloud = getRunTarget() === 'cloud';
  const q = document.getElementById('btn-queue');
  const s = document.getElementById('btn-schedule');
  if (q) q.style.display = cloud ? 'none' : '';
  if (s) {
    s.style.display = '';
    s.textContent = cloud ? 'Schedule on the VM' : 'Schedule it';
    s.title = cloud
      ? 'Pick a date and time — the VM starts it itself, with the app closed'
      : 'Schedule for a specific date and time';
  }
  const note = document.getElementById('launch-run-note');
  if (note) note.textContent = cloud
    ? 'Starts on the VM — close the laptop whenever. Watch it live with 👁 Show on the board.'
    : 'Runs on this Mac while the app is open — pause & resume anytime.';
  // Follower Growth "Team Launch" button copy ("Launch N in cloud" vs
  // "…sequentially") is composed in fgtlRenderCart — re-render it here so
  // flipping the run-target tab updates the label immediately.
  if (typeof fgtlRenderCart === 'function' && document.getElementById('fgtl-go')) fgtlRenderCart();
}
function refreshAccountPickerForRunTarget() {
  const cloud = getRunTarget() === 'cloud';
  const localHost = document.getElementById('local-browser-host');
  // A cloud VM has no local browser — the "Local Browser" sender can't run there.
  if (localHost) localHost.style.display = cloud ? 'none' : '';
  if (cloud && selectedProfileIds.includes('local-browser')) {
    selectedProfileIds = selectedProfileIds.filter((id) => id !== 'local-browser');
    delete selectedProfileNames['local-browser'];
    if (typeof renderSelectedPanel === 'function') renderSelectedPanel();
    if (typeof updateCampaignSummary === 'function') updateCampaignSummary();
  }
}
// Disable the ☁︎ Cloud VM tab when the engine isn't configured (no SCRAPER_ENGINE_URL);
// a disabled <button> can't be clicked, and we coerce any programmatic cloud selection to local.
function refreshVmTabAvailability() {
  const cloudTab = document.querySelector('#run-target .rt-tab[data-rt="cloud"]');
  if (!cloudTab) return;
  cloudTab.disabled = !_engineConfigured;
  cloudTab.classList.toggle('rt-tab-disabled', !_engineConfigured);
  cloudTab.title = _engineConfigured ? '' : 'Cloud engine not configured';
  if (!_engineConfigured && getRunTarget() === 'cloud') setRunTarget('local');
}
async function refreshEngineConfigured() {
  try {
    const r = await fetch('/api/health');
    const h = await r.json();
    _engineConfigured = !!h.scraperConfigured;
  } catch (_) { /* keep default (true) — don't disable on a transient fetch error */ }
  refreshVmTabAvailability();
  // Engine reachability is now confirmed — re-assert the FG cloud default in case
  // the earlier attempt was coerced/clobbered before the check resolved.
  applyFgRunTargetDefault();
}
if (typeof window !== 'undefined') { window.setRunTarget = setRunTarget; window.getRunTarget = getRunTarget; }
document.addEventListener('DOMContentLoaded', () => {
  if (typeof setRunTarget === 'function') setRunTarget(DEFAULT_RUN_TARGET);
  // If the app loaded directly into Follower Growth (persisted mode), the line
  // above just reset the target to local — re-apply the FG cloud default after it.
  applyFgRunTargetDefault();
});
document.addEventListener('DOMContentLoaded', () => { refreshEngineConfigured(); });

// ─── Cloud Campaigns panel ──────────────────────────────────────────────────
let _cloudPollTimer = null;

// Cloud campaigns render as the SAME Sales-Nav-queue board (sn-strip cards,
// Now-running / Up-next / Done rails) — the board already handles many running
// in parallel, which is exactly what the VM does. We reuse the sn-strip markup
// (its expand/collapse + tab handlers are document-level delegation, so cloud
// strips get them for free); Stop/Open/dismiss are cloud-specific onclicks.
const CLOUD_MODE_LABELS = {
  connect_only: 'Connect Only', connect_and_introduce: 'Connect + Introduce',
  connect_and_message: 'Connect + DM', message_only: 'Direct Messages',
  introduce_back: 'Introduction', follower_growth: 'Follower Growth',
  inmail_only: 'InMail', open_profile_only: 'Message', check_status: 'Check Status',
};
const CLOUD_MODE_BADGES = {
  connect_only: 'CC', connect_and_introduce: 'C+I', connect_and_message: 'C+D',
  message_only: 'DM', introduce_back: 'IB', follower_growth: 'FG',
  inmail_only: 'IM', open_profile_only: 'OP', check_status: 'CS',
};
const _cloudModeLabel = (m) => CLOUD_MODE_LABELS[m] || m || '';
const _cloudBadge = (m) => CLOUD_MODE_BADGES[m] || (typeof v3ModeBadge === 'function' ? v3ModeBadge(m) : '—');

// Cloud "done" strips the operator hid from THEIR board (local-only, mirrors the
// scrape board's _snDismissed). Persisted so dismissals survive reloads.
const _cloudDismissed = new Set((() => {
  try { return JSON.parse(localStorage.getItem('cloudDismissedDone') || '[]'); } catch (_) { return []; }
})());
function _cloudSaveDismissed() {
  try { localStorage.setItem('cloudDismissedDone', JSON.stringify([..._cloudDismissed])); } catch (_) { /* */ }
}
// Sheet URLs stashed per campaign (from the detail fetch) so "Open" can jump to
// the source Google Sheet.
const _cloudSheetUrls = new Map();

// Reconstruct a per-lead log (parity with a local campaign's live log) from the
// cloud engine's per-lead status rows (GET /api/campaign/:id/leads). Ordered
// chronologically (oldest → newest) so the render's slice(-8) shows the most
// recent lines — matching how a local log reads — with a summary line last.
// Returns TIMESTAMPED entries [{t, line}] (t: ms epoch, null = undated, ±Infinity
// pins first/last) so _mergeCloudLog can interleave per-lead rows with the
// engine's event feed in TRUE chronological order — previously the two streams
// rendered as separate blocks ("ok" rows first, "log" events after), which read
// as out-of-order to the operator.
function _cloudLeadsToLog(leads, isFG = false, monitor = {}) {
  leads = Array.isArray(leads) ? leads : [];
  const hhmm = (iso) => {
    if (!iso) return '';
    const d = new Date(iso);
    return isNaN(d.getTime()) ? '' : d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };
  const ts = (iso) => { const t = Date.parse(iso || ''); return Number.isFinite(t) ? t : null; };
  // profileId → sender email (from the campaign config the engine ships on the
  // single-campaign detail). Lets each CC-sent line name the account that sent it.
  const emails = (monitor && monitor.config && monitor.config.accountEmails) || {};
  // Compact the lead's LinkedIn URL to its /in/<slug> so the line stays readable.
  const shortUrl = (u) => {
    const s = String(u || '');
    const m = s.match(/linkedin\.com\/(?:in|sales\/(?:people|lead))\/([^/?#]+)/i);
    if (m) return `linkedin.com/in/${m[1]}`;
    return s ? s.replace(/^https?:\/\/(www\.)?/, '').slice(0, 48) : '';
  };
  // Pre-actioned leads (sheet already had a Connection Request Status on import
  // — the engine parks them, never re-opens the profile). Not events of THIS
  // run: exclude from the per-lead lines, surface as one summary line instead.
  const _isPre = (l) => String((l && l.stage) || '') === 'pre-actioned';
  const preCount = leads.filter(_isPre).length;
  const actioned = leads.filter((l) => l && (l.status === 'sent' || l.status === 'error') && !_isPre(l));
  actioned.sort((a, b) => {
    const ta = a.sentAt ? Date.parse(a.sentAt) : Infinity; // errors (no sentAt) last
    const tb = b.sentAt ? Date.parse(b.sentAt) : Infinity;
    return ta - tb;
  });
  const entries = actioned.map((l) => {
    const name = String(l.fullName || l.leadUrl || 'Lead').trim();
    if (l.status === 'sent') {
      // "already_processed" means the lead was already actioned in a prior run
      // (e.g. invite already pending) — the engine skipped it, it was NOT a fresh
      // send. Word it clearly so the log doesn't read as a new connection request.
      const _stg = String(l.stage || '');
      const verb = isFG ? 'invited'
        : /already_processed|already[_ ]?processed/i.test(_stg) ? 'already invited (skipped — not re-sent)'
        : (_stg ? `${_stg} sent` : 'sent');
      const when = hhmm(l.sentAt);
      // CC/CC+IC: name the sending account's email + the lead's LinkedIn URL.
      const email = !isFG ? (emails[l.account] || l.account || '') : '';
      const url = !isFG ? shortUrl(l.leadUrl) : '';
      const extra = `${email ? ` · via ${email}` : ''}${url ? ` · ${url}` : ''}`;
      return { t: ts(l.sentAt), line: `✓ ${name} · ${verb}${when ? ` · ${when}` : ''}${extra}` };
    }
    // Error rows: timestamped from dateLastAction (engine v93 stamps the error
    // moment) so ✗ lines carry a time and sort chronologically like the rest.
    const errWhen = hhmm(l.sentAt || l.dateLastAction);
    return { t: ts(l.sentAt) || ts(l.dateLastAction), line: `✗ ${name} · ${l.error || 'error'}${errWhen ? ` · ${errWhen}` : ''}` };
  });
  if (preCount) {
    entries.unshift({ t: -Infinity, line: `⏭ ${preCount} lead${preCount === 1 ? '' : 's'} already had a Connection Request Status in the sheet — excluded from this run (not re-sent)` });
  }
  // CC+IC / CC+DM lifecycle events straight from the lead rows — so the VM log
  // shows acceptances + introductions (mirroring the local machine), not just the
  // initial connection send. Skipped for Follower Growth (no accept/intro phase).
  // Timestamped via dateLastAction (engine v89 ships it) so they interleave
  // chronologically; older engines → undated (sorts after dated lines).
  if (!isFG) {
    leads
      .filter((l) => l && !_isPre(l) && /connected|accepted/i.test(String(l.connectionAcceptedStatus || '')))
      .forEach((l) => {
        const when = hhmm(l.dateLastAction);
        entries.push({ t: ts(l.dateLastAction), line: `✓ ${String(l.fullName || l.leadUrl || 'Lead').trim()} · connection accepted${when ? ` · ${when}` : ''}` });
      });
    leads
      .filter((l) => l && !_isPre(l) && String(l.introductionStatus || '').trim())
      .forEach((l) => {
        const name = String(l.fullName || l.leadUrl || 'Lead').trim();
        const s = String(l.introductionStatus).trim();
        const when = hhmm(l.dateLastAction);
        entries.push(/fail|error|not in your connections|couldn'?t|unable/i.test(s)
          ? { t: ts(l.dateLastAction), line: `✗ ${name} · introduction failed · ${s}` }
          : { t: ts(l.dateLastAction), line: `✓ ${name} · introduced${when ? ` · ${when}` : ''}` });
      });
  }
  // Check status is a real timestamped event → keep it in the chronological block,
  // above the summary footer.
  const checkDone = monitor.monitor_check_completed_at;
  const checkStarted = monitor.monitor_check_started_at;
  const checkWhen = hhmm(checkDone || checkStarted);
  if (checkDone) {
    const accepted = Math.max(0, Number(monitor.monitor_check_newly_accepted) || 0);
    const checkError = String(monitor.monitor_check_error || '').trim();
    entries.push({ t: ts(checkDone), line: checkError
      ? `✗ Check finished with an error${checkWhen ? ` · ${checkWhen}` : ''} · ${checkError}`
      : `✓ Check complete${checkWhen ? ` · ${checkWhen}` : ''} · ${accepted} newly accepted` });
  } else if (checkStarted) {
    entries.push({ t: ts(checkStarted), line: `◌ Check in progress${checkWhen ? ` · ${checkWhen}` : ''}` });
  }
  // SUMMARY — always the very last line(s), visually separated so it's clearly a
  // running total (NOT a chronological entry). Pre-actioned leads excluded from
  // Σ sent (they were never sent by this run).
  const sent = leads.filter((l) => l && l.status === 'sent' && !_isPre(l)).length;
  const err = leads.filter((l) => l && l.status === 'error').length;
  const pending = Math.max(0, leads.length - sent - err - preCount);
  entries.push({ t: Infinity, line: '──────────' });
  entries.push({ t: Infinity, line: `Σ Total · ${sent} ${isFG ? 'invited' : 'sent'} · ${err} error${err === 1 ? '' : 's'}${pending > 0 ? ` · ${pending} pending` : ''}` });
  return entries;
}

// Adapt one cloud campaign ({campaign, leadCounts}) into an sn-strip.
function renderCloudStrip(c, lc, logLines = null) {
  const status = c.status || '';
  const isQueued = status === 'pending' || status === 'queued';
  const isRunning = status === 'running';
  const isDone = ['done', 'cancelled', 'error'].includes(status);
  const isBad = status === 'error' || status === 'cancelled';
  const isFG = c.mode === 'follower_growth';
  const mine = !!(snCurrentEmail && c.owner && String(c.owner).toLowerCase() === String(snCurrentEmail).toLowerCase());
  const owner = c.owner || 'unknown';
  // Exclude _preActioned (sheet rows that already had a Connection Request
  // Status on import — never re-opened) from both sides of "X of Y sent".
  const _pre = Number(lc._preActioned || 0);
  const total = Object.entries(lc).reduce((a, [k, b]) => a + (k.startsWith('_') ? 0 : (Number(b) || 0)), 0) - _pre;
  const sent = Math.max(0, Number(lc.sent || 0) - _pre);
  const accounts = (c.profile_ids || c.profileIds || []).length;
  const collapsed = isQueued ? true : !_snExpanded.has(c.id);
  const badge = _cloudBadge(c.mode);
  const acctWord = accounts === 1 ? 'account' : 'accounts';

  const flow = isFG
    ? `<b>${total || '—'} invites</b> → <b>${accounts || 1} account${(accounts || 1) === 1 ? '' : 's'}</b> → page · Follower Growth`
    : `<b>${total} leads</b> → <b>${accounts} ${acctWord}</b> → feeds <b>${escHtml(c.name || '')}</b> · ${escHtml(_cloudModeLabel(c.mode))}`;

  const statusTxt = isQueued ? 'Queued'
    : isRunning ? (isFG ? 'Inviting' : 'Running')
    : isBad ? (status === 'cancelled' ? 'Stopped' : 'Error')
    : 'Done';
  const dot = status === 'error' ? '<span class="dot red"></span>'
    : isBad ? '<span class="dot cancel"></span>'   // cancelled — gray, not red
    : isRunning ? '<span class="dot run"></span>'
    : isQueued ? '<span class="dot q"></span>'
    : '<span class="dot done"></span>';            // done — ink

  const progLine = isRunning
    ? `<div class="sn-progtxt"><b>${sent}</b> of ${total} ${isFG ? 'invites' : 'sent'}`
      + `${lc.claimed ? ` · ${lc.claimed} in flight` : ''}${lc.error ? ` · ${lc.error} error` : ''}</div>`
    : '';

  // Expandable Log / Counts pane (running + done only; queued stays slim). The
  // Log pane is a placeholder until the engine's per-lead endpoint is deployed.
  const expandBtn = isQueued ? ''
    : `<button class="sn-collapse sn-expand" title="Expand / collapse"><svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6l4 4 4-4"/></svg></button>`;
  const countsHtml = Object.entries(lc).map(([k, v]) => `${escHtml(k)}: <b style="color:var(--ink)">${v}</b>`).join(' · ') || 'no leads';
  // Real per-lead log when we have it (running/expanded); otherwise a live-status
  // note. The endpoint is deployed now, so this is no longer a "coming soon".
  const logBoxInner = (logLines && logLines.length)
    ? logLines.slice(-8).map((l) => escHtml(l)).join('<br>')
    : `${sent ? 'Live per-lead log — expand to watch it fill.' : 'Per-lead log appears here as the cloud engine sends.'} Status so far: <span class="ok">${sent}/${total} ${isFG ? 'invites' : 'sent'}</span>.`;
  const switchBlock = isQueued ? '' : `
    <div class="sn-switch">
      <div class="sn-switchtabs"><span class="sn-st on" data-t="log">Log</span><span class="sn-st" data-t="counts">Counts</span></div>
      <div class="sn-pane on" data-p="log"><div class="sn-logbox">${logBoxInner}</div></div>
      <div class="sn-pane" data-p="counts"><div style="font-size:12px;color:var(--gray);padding:4px 0">${countsHtml}</div></div>
    </div>`;

  // Primary needs-login (Task 9): only 'needs_login' surfaces anything — see
  // /js/primary-session-render.mjs. Repeated on every affected strip BY
  // DESIGN so a blocked campaign is visible when scanning many strips.
  const psBadge = primarySessionBadge(c.primarySession);
  const psBadgeHtml = psBadge.show ? `<div class="${psBadge.cls}">${escHtml(psBadge.text)}</div>` : '';

  const stopBtn = (isRunning || isQueued) ? `<button class="mini" onclick="stopCloudCampaignUI('${escHtml(c.id)}')">Stop</button>` : '';
  const _vLabel = String(c.name || c.id).replace(/['"\\<>]/g, '');
  const showBtn = isRunning ? `<button class="mini" onclick="openCloudCampaignView('${escHtml(c.id)}','${escHtml(_vLabel)}')" title="Watch the campaign's browser live">👁 Show</button>` : '';
  const openBtn = `<button class="mini solid" onclick="viewCloudCampaign('${escHtml(c.id)}')">Open</button>`;
  const dismissBtn = isDone ? `<button class="mini sn-dismiss-cloud" onclick="dismissCloudDone('${escHtml(c.id)}', this)" title="Hide from your board">✕</button>` : '';

  return `
  <div class="sn-strip ${mine ? 'mine' : ''} ${isRunning ? 'run' : ''} ${isQueued ? 'queued' : ''} ${collapsed ? 'sn-collapsed' : ''} ${isDone ? 'done' : ''} ${status === 'error' ? 'stopped' : ''} ${isBad && status !== 'error' ? 'cancelled' : ''}" data-cid="${escHtml(c.id)}">
    ${expandBtn}
    <div class="sn-top"><span class="sn-type">Cloud Campaign · ${escHtml(badge)}</span>${mine ? '<span class="sn-you">You</span>' : `<span class="sn-owner">· ${escHtml(owner)}</span>`}
      <span class="sn-status">${dot} ${escHtml(statusTxt)}</span></div>
    <div class="sn-name">${escHtml(c.name || '')}</div>
    <div class="sn-flow">${flow}</div>
    ${psBadgeHtml}
    ${progLine}
    ${switchBlock}
    <div class="sn-foot"><div class="right">${dismissBtn}${showBtn}${stopBtn}${openBtn}</div></div>
  </div>`;
}

// Render the cloud campaigns as an sn-board (Now running / Up next / Done rails).
async function renderCloudCampaigns() {
  const list = document.getElementById('cloud-campaigns-list');
  if (!list) return;
  let data;
  try {
    const res = await fetch('/api/campaign/cloud-list');
    data = await res.json();
  } catch (e) {
    list.innerHTML = `<p class="empty-state">Couldn't reach the cloud engine: ${escHtml(e.message)}</p>`;
    return;
  }
  if (data.error) { list.innerHTML = `<p class="empty-state">${escHtml(data.error)}</p>`; return; }
  const campaigns = data.campaigns || [];
  if (!campaigns.length) { list.innerHTML = `<div class="sn-empty">No cloud campaigns yet.</div>`; return; }

  // Fetch per-campaign lead counts (best-effort, parallel). Also pull the
  // per-lead log for running/expanded strips so their Log pane shows real rows.
  const details = await Promise.all(campaigns.map(async (c) => {
    let d;
    try { d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}`)).json(); }
    catch { d = { campaign: c, leadCounts: {} }; }
    const st = ((d && d.campaign) || c).status;
    if (st === 'running' || _snExpanded.has(c.id)) {
      try {
        const lr = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}/leads`)).json();
        if (lr && Array.isArray(lr.leads)) d._logLines = _mergeCloudLog(_cloudLeadsToLog(lr.leads, ((d && d.campaign) || c).mode === 'follower_growth', (d && d.campaign) || c), null);
      } catch { /* best-effort — the status note stays */ }
    }
    return d;
  }));

  const items = details.map((d) => ({ c: d.campaign || {}, lc: d.leadCounts || {}, log: d._logLines || null }));
  for (const it of items) { if (it.c.sheet_url) _cloudSheetUrls.set(it.c.id, it.c.sheet_url); }

  const running = items.filter((x) => x.c.status === 'running');
  const queued = items.filter((x) => x.c.status === 'pending' || x.c.status === 'queued');
  const done = items.filter((x) => ['done', 'cancelled', 'error'].includes(x.c.status) && !_cloudDismissed.has(x.c.id));

  const qmeta = document.getElementById('cloud-qmeta');
  if (qmeta) qmeta.textContent = `${running.length} running · ${queued.length} queued`;

  const rail = (label, arr, extra = '') => arr.length
    ? `<div class="sn-railhead">${label}${extra}</div>` + arr.map((x) => renderCloudStrip(x.c, x.lc, x.log)).join('') : '';
  let html = '';
  html += rail('▶ Now running', running);
  html += rail('• Up next in the queue', queued);
  html += rail('✓ Done', done, done.length ? ` <span class="sn-railcount">${done.length}</span>` : '');
  list.className = 'sn-board';
  list.innerHTML = html || `<div class="sn-empty">No cloud campaigns yet.</div>`;
}

// "Open" a cloud campaign — jump to its source Google Sheet if we have the URL.
function viewCloudCampaign(id) {
  const url = _cloudSheetUrls.get(id);
  if (url) { try { window.open(url, '_blank', 'noopener'); return; } catch (_) { /* */ } }
  // No sheet URL yet — expand the strip so the operator sees its log/counts.
  const strip = document.querySelector(`#cloud-campaigns-list .sn-strip[data-cid="${id}"]`);
  if (strip && strip.classList.contains('sn-collapsed')) {
    _snExpanded.add(id);
    strip.classList.remove('sn-collapsed');
  }
}
window.viewCloudCampaign = viewCloudCampaign;

// ── Live status CAMPAIGN card for cloud campaigns (see feedback_two_live_status_cards).
// This is CARD #2: the one INSIDE the campaign tab (#active-card relocated into
// #wiz-live-slot) that you land on after launching / when you press Open. Local
// campaigns get it for free (renderActiveCard is driven by the local cockpit);
// cloud campaigns didn't — Open used to dump the operator in the blank wizard.
// We give cloud the SAME card by feeding renderActiveCard a status object mapped
// from engine data, gated behind _viewingCloudId so the local flow is untouched
// when it's null (and it always yields to a genuinely-running LOCAL campaign).
let _viewingCloudId = null;
let _cloudCardTimer = null;

// VM operational event log (per campaign). The per-lead log lines are derived
// fresh each poll from the engine's lead rows (sent / accepted / introduced);
// these events — the VM opening an account's browser, and start/stop/pause the
// operator triggers — aren't in the lead rows, so we accumulate them here and
// merge them into the log so section 7 reads like the local machine's log.
const _cloudEventLog = new Map();        // campaignId -> [{ t, line }]  (user actions)
const _cloudMonitorLog = new Map();      // campaignId -> [{ t, line }]  (engine per-account check events)
const _cloudAccountsById = new Map();    // campaignId -> [{ email, dailyCount, dailyLimit, parked, parkReason, needsLogin }]
// Last hero state we logged per cloud campaign, so the "check due" line is
// EDGE-triggered. The dashboard polls every 5s; logging on level would write
// the same line ~24 times per wake.
const _lastHeroState = new Map();
function _pushCloudEvent(id, line) {
  if (!id || !line) return;
  let arr = _cloudEventLog.get(id);
  if (!arr) { arr = []; _cloudEventLog.set(id, arr); }
  if (arr.length && arr[arr.length - 1].line === line) return; // dedup consecutive
  arr.push({ t: Date.now(), line });
  if (arr.length > 60) arr.splice(0, arr.length - 60); // keep the tail bounded
}
window._pushCloudEvent = _pushCloudEvent;
// Combine the two event streams — user actions (start/stop/pause/check-now, logged
// immediately app-side) and the engine's per-account check-sweep events (from the
// campaign detail's monitorLog) — into one time-ordered list.
function _combineCloudEvents(id) {
  const app = _cloudEventLog.get(id) || [];
  const eng = (_cloudMonitorLog.get(id) || []).map((e) => ({ t: Number(e && e.t) || 0, line: String((e && e.line) || '') })).filter((e) => e.line);
  return app.concat(eng).sort((a, b) => (a.t || 0) - (b.t || 0));
}
// ONE chronological list (operator feedback 2026-07-24: "log and ok were
// separated — should be the same list in chronological order"). Takes the
// timestamped lead entries [{t, line}] from _cloudLeadsToLog plus the engine
// event feed [{t, line}], merges, and sorts by time: -Infinity pins first
// (pre-actioned summary), undated lines sort after all dated ones, +Infinity
// pins the Σ footer last. Stable sort keeps same-time lines in emit order.
function _mergeCloudLog(leadEntries, events) {
  leadEntries = Array.isArray(leadEntries) ? leadEntries : [];
  const stamp = (t) => { const d = new Date(t); return isNaN(d.getTime()) ? '' : d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); };
  const evEntries = (Array.isArray(events) ? events : []).map((e) => {
    const hh = stamp(e.t);
    return { t: Number(e.t) || null, line: hh ? `${e.line} · ${hh}` : e.line };
  });
  const key = (e) => (e.t === -Infinity ? -8.64e15 : e.t === Infinity ? 8.64e15 : (e.t == null ? 8.63e15 : e.t));
  return leadEntries.concat(evEntries)
    .sort((a, b) => key(a) - key(b))
    .map((e) => e.line);
}

function _buildCloudActiveStatus(c, leads, counts) {
  c = c || {}; leads = Array.isArray(leads) ? leads : []; counts = counts || {};
  const isMon = c.status === 'monitoring';
  // A freshly-created cloud campaign sits at pending/queued for a couple of
  // minutes while the worker pod scales up and claims it. During that window
  // running is false and there's no monitoring state — but the campaign has
  // NOT finished. Flag it so renderActiveCard shows "Launching…" instead of
  // falling through to the Finished branch (which reads as "done — press Start
  // again"). Mirrors renderCloudStrip's isQueued exactly.
  const isQueued = c.status === 'pending' || c.status === 'queued';
  const total = Object.values(counts).reduce((a, b) => a + (Number(b) || 0), 0) || leads.length;
  const sent = Number(counts.sent || 0) || leads.filter((l) => l && l.sentAt).length;
  const accepted = leads.filter((l) => l && /connected/i.test(String(l.connectionAcceptedStatus || ''))).length;
  // Edge-trigger the operator-visible "a sweep is coming" line.
  try {
    const _hero = monitorHeroState({
      monitorTaskStatus: c.monitorTaskStatus || null,
      monitorTaskDueAt: c.monitorTaskDueAt || null,
      monitorCheckStartedAt: c.monitor_check_started_at || null,
    });
    if (_lastHeroState.get(c.id) !== _hero.state) {
      if (_hero.state === 'waking') _pushCloudEvent(c.id, '⏰ Check due — waking a worker, sweeping in ~2 min');
      _lastHeroState.set(c.id, _hero.state);
    }
  } catch (_) { /* the log line must never break the status render */ }
  return {
    _cloud: true, id: c.id, running: c.status === 'running' || c.status === 'paused', paused: c.status === 'paused',
    state: isMon ? 'monitoring' : undefined, queued: isQueued,
    // Raw engine status ('cancelled'/'error'/'done'/…) — drives the live-status
    // card's ▶ Continue / ⟲ Restart swap for stopped campaigns.
    engineStatus: c.status || '',
    name: c.name || '(unnamed)', mode: c.mode,
    totalTargets: total, totalProcessed: sent,
    // Leads that still have to be sent. 'claimed' is counted with 'pending': a
    // campaign stopped mid-batch leaves claims behind, and the engine's reaper
    // releases them — they are work still owed, not work done. Drives the
    // ▶ Resume sending control on a stopped / monitoring connect campaign.
    pendingCount: (Number(counts.pending) || 0) + (Number(counts.claimed) || 0),
    profileIds: c.profile_ids || [], participatingProfileIds: c.profile_ids || [],
    acceptedCount: accepted, logs: _mergeCloudLog(_cloudLeadsToLog(leads, c.mode === 'follower_growth', c), _combineCloudEvents(c.id)),
    nextCheckAt: c.next_check_at, monitoringUntil: c.monitoring_until,
    // Monitor task row → the hero's three states (see monitorHeroState). Absent
    // on a pre-fix engine, which monitorHeroState renders as a plain countdown.
    monitorTaskStatus: c.monitorTaskStatus || null,
    monitorTaskDueAt: c.monitorTaskDueAt || null,
    monitorCheckStartedAt: c.monitor_check_started_at || null,
    autoChecksEnabled: c.auto_checks_enabled !== false, checkIntervalMinutes: c.check_interval_minutes || 60,
    // Task 9 — primary needs-login surfacing on card #2 (Task 5's c.primarySession).
    primarySession: c.primarySession,
    // Needed to run the local primary handshake for an account ADDED to a paused
    // CC+IC campaign (the new sender must reach the primary or intros can't fire).
    primaryUrl: (c.config && (c.config.primaryUrl || c.config.primaryPersonUrl)) || '',
    // v2.160.35: follow-up dual countdown on the cloud card-#2 takeover — lights
    // up once the engine exposes follow_up {count,dueAt,sender} on the detail.
    followUp: c.follow_up || null,
  };
}

// When each cloud campaign's detail last came back. The live stage's heartbeat
// reads this: "updated 3s ago" is a fact about the app↔engine link, and a link
// that has gone quiet is exactly what "it looks crashed" feels like.
const _cloudPolledAt = new Map();
// When each campaign's /accounts payload was last fetched for the board (the
// opened campaign has its own poll).
const _cloudAccountsAt = new Map();

// The engine's live stamp (cmp:live:<id>) → the card's currentAction. Without
// this mapping buildLiveActivity has nothing to say during a cloud send and
// falls through to the literal placeholder "Working…" with an empty sub-line.
// Returns null when the engine hasn't stamped a phase — never invents one.
// "⏳ No account free right now — 1 at the daily limit · 2 parked (…) · retrying
// automatically" — the engine says this every 10 minutes while a campaign is
// running with nothing it can send from. Pull the newest one (Redis returns
// newest-first) and keep it only while it's current, so a stale line from
// hours ago can't claim a live stall.
const _WAIT_FRESH_MS = 15 * 60 * 1000;
function _cloudWaitingReason(monitorLog) {
  const hit = (Array.isArray(monitorLog) ? monitorLog : [])
    .find((e) => e && /No account free/i.test(String(e.line || '')));
  if (!hit) return '';
  if (Number(hit.t) && Date.now() - Number(hit.t) > _WAIT_FRESH_MS) return '';
  const tail = String(hit.line).split('—').slice(1).join('—').trim();
  return tail.replace(/\s*·\s*retrying automatically\s*$/i, '').trim();
}

// The most recent invite the engine actually sent: which account, and when.
// A follower campaign publishes no liveProgress, so this is the only evidence of
// what it is doing right now.
function _fgLastActivity(leads) {
  let best = null;
  for (const l of leads || []) {
    if (l.status !== 'sent' || !l.sentAt) continue;
    const t = Number(new Date(l.sentAt)) || 0;
    if (!best || t > best.t) best = { t, account: String(l.account || ''), name: l.fullName || '' };
  }
  return best;
}

function _cloudCurrentAction(d) {
  const lp = d && d.liveProgress;
  if (!lp || !lp.phase) {
    // No browser open. If the engine is telling us why, say THAT — never
    // "Working…", which is the word that made a ten-hour stall look healthy.
    const c = (d && d.campaign) || {};
    if (c.status !== 'running') return null;
    const why = _cloudWaitingReason(d && d.monitorLog);
    // Asleep on the engine's blocked_until: no account can work before then, so
    // the VM stepped back and stops writing log lines. Read the column directly —
    // the "No account free" line it slept on goes stale within 15 minutes, and
    // without this the card falls back to the "Working…" that hid a ten-hour
    // stall. See the engine's campaigns.blocked_until (scraper v130).
    const wake = c.blocked_until ? new Date(c.blocked_until).getTime() : 0;
    if (wake > Date.now()) {
      const when = new Date(wake).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      return { phase: 'waiting', label: 'Waiting for a free account',
        account: '', lead: 'No account free',
        sub: `${why || 'every account is at a limit or benched'} · the VM stands down until ${when} to save cost, then picks itself back up` };
    }
    // A follower campaign never publishes liveProgress, so without this it fell
    // through to the generic "Working…" with no account, no lead and no time —
    // the exact blankness a CC campaign's stage was built to avoid. The last
    // sent invite tells us which account is up and how long ago it moved.
    if (c.mode === 'follower_growth' && d && d._fgLast) {
      const who = _acctLabel({ profileId: d._fgLast.account, email: '' });
      const secs = Math.max(0, Math.round((Date.now() - d._fgLast.t) / 1000));
      const ago = secs < 90 ? `${secs}s ago` : `${Math.round(secs / 60)} min ago`;
      return { phase: 'sending', label: `Inviting from ${who}`,
        account: d._fgLast.account, lead: d._fgLast.name || '',
        sub: `last invite ${ago}` };
    }
    if (!why) return null;
    return { phase: 'waiting', label: 'Waiting for a free account',
      account: '', lead: 'No account free', sub: why };
  }
  const who = String(lp.selecting || '').trim();
  const acct = String((d && d.liveAccount) || '').trim();
  const n = Number(lp.done) || 0, tot = Number(lp.total) || 0;
  if (lp.phase === 'checking') {
    // `selecting` IS the account being swept here — there's no lead in a sweep.
    return { phase: 'checking', label: who ? `Checking ${who} for acceptances` : 'Checking for new acceptances',
      account: who || acct, lead: '', sub: tot ? `account ${n} of ${tot}` : '' };
  }
  if (lp.phase === 'introducing') {
    return { phase: 'introducing', label: who ? `Introducing ${who}` : 'Writing introductions',
      account: acct, lead: who, sub: tot ? `${n} of ${tot} accepted connections` : '' };
  }
  return { phase: 'sending', label: who ? `Sending connection to ${who}` : 'Sending connection',
    account: acct, lead: who, sub: '' };
}

// A finished FG run that sent 258 of 1567 says nothing about WHY the other 1309
// never went — and the answer is almost always "LinkedIn had no free invites
// left", not a bug. Read it off the same per-account bench reasons the pills
// use, in the same voice as the live line, so a done card explains itself.
// Returns null when there is nothing to explain (everything sent).
function _fgFinishedNote(status) {
  if (!status || !status.isFG || status.bucket !== 'done') return null;
  const left = Math.max(0, Number(status.total || 0) - Number(status.sent || 0));
  if (!left) return null;
  const accounts = Array.isArray(status.benchAccounts) ? status.benchAccounts : [];
  let credits = 0, login = 0, errored = 0, refill = '';
  for (const a of accounts) {
    const r = String((a && a.bench) || '').toLowerCase();
    if (r.includes('credit')) {
      credits += 1;
      const m = /refills?\s+([^·)]+)/i.exec(String(a.bench || ''));
      if (m && !refill) refill = m[1].trim();
    } else if ((a && a.needsLogin) || r.includes('logged out') || r.includes('login')) login += 1;
    else if (r) errored += 1;
  }
  const nf = (n) => n.toLocaleString('en-GB');
  const bits = [];
  if (credits) bits.push(`${credits} of ${accounts.length} accounts out of invite credits`);
  if (login) bits.push(`${login} logged out`);
  if (errored) bits.push(`${errored} errored`);
  // No per-account detail to stand on — say only what we actually know.
  if (!bits.length) {
    return { icon: '•', l1: `${nf(left)} of ${nf(status.total || 0)} never sent`,
      l2: 'Reason not recorded for this run — the log has the per-account lines.' };
  }
  const l1 = credits >= Math.max(login, errored)
    ? 'Stopped — the accounts ran out of LinkedIn invite credits'
    : login >= errored ? 'Stopped — accounts needed re-login' : 'Stopped — account errors';
  const tail = refill ? ` · credits refill ${refill}` : '';
  return { icon: '🚫', l1,
    l2: `${bits.join(' · ')} · ${nf(left)} people left for the next run${tail}` };
}

async function _refreshCloudActiveStatus(id) {
  try {
    const d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`)).json();
    let leads = [];
    try { const lr = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/leads`)).json(); if (lr && Array.isArray(lr.leads)) leads = lr.leads; } catch (_) { /* */ }
    // Live Status is a SECOND render path — the board's _refreshCloudItems does
    // this same enrichment, and without it here the card on this route falls back
    // to a bare "Working…" with no pills while the dashboard's card is complete.
    if (leads.length) {
      _cloudAcctCounts.set(id, _cloudCountsByAccount(leads));
      if (d) d._fgLast = _fgLastActivity(leads);
    }
    // The detail cache is what renderCloudAccountsPanel reads the mode off.
    if (d) _cloudDetailCache.set(id, d);
    // Engine's per-account check-sweep events (reliable — one line per account the
    // VM opens, e.g. "🖥️ Checking liza.advocate@ortus.solutions…"). Captured here
    // and merged into the log by _combineCloudEvents. Newest-first from Redis.
    if (d && Array.isArray(d.monitorLog)) _cloudMonitorLog.set(id, d.monitorLog);
    // Per-account status (daily used vs limit, throttled/weekly-cap, needs-login)
    // for the Live Status "Accounts" panel — best-effort, degrades to no panel.
    try {
      const ar = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/accounts`)).json();
      if (ar && Array.isArray(ar.accounts)) _cloudAccountsById.set(id, ar.accounts);
    } catch (_) { /* engine may not expose it yet — panel just won't show */ }
    try { if (_viewingCloudId === id) renderCloudAccountsPanel(id); } catch (_) { /* */ }
    window.__cloudActiveStatus = _buildCloudActiveStatus((d && d.campaign) || {}, leads, (d && d.leadCounts) || {});
    // Live-browser flag from the engine (top-level of the /:id detail) — drives
    // the LIVE dot on card #2's Show button (component 5 → component 7).
    if (window.__cloudActiveStatus) {
      window.__cloudActiveStatus.live = !!(d && d.live);
      window.__cloudActiveStatus.liveAccount = (d && d.liveAccount) || '';
      window.__cloudActiveStatus.paused = !!(d && d.campaign && d.campaign.status === 'paused');
      window.__cloudActiveStatus.currentAction = _cloudCurrentAction(d);
      _cloudPolledAt.set(id, Date.now());
    }
  } catch (_) { if (!window.__cloudActiveStatus) window.__cloudActiveStatus = { _cloud: true, id, name: 'Cloud campaign', running: true, logs: [] }; }
}

// Render the per-account status panel below the Live Status card (Account | Status)
// for a cloud CC+IC campaign. Hidden when there's no account data or not viewing a
// cloud campaign. Data comes from _cloudAccountsById (engine /accounts endpoint).
function renderCloudAccountsPanel(id) {
  const panel = document.getElementById('cloud-accounts-panel');
  if (!panel) return;
  const accounts = (id && _cloudAccountsById.get(id)) || [];
  if (!accounts.length) { panel.hidden = true; panel.innerHTML = ''; return; }
  // A follower campaign runs 66 accounts. Listing them as 66 full-width rows —
  // most of them "0/50 today" because they have not had their turn — buries the
  // card. The card's pills carry the same per-account state in one line.
  const _fgCamp = ((_cloudDetailCache.get(id) || {}).campaign || {}).mode === 'follower_growth';
  if (_fgCamp) { panel.hidden = true; panel.innerHTML = ''; return; }
  const badge = (cls, text) => `<span class="cap-badge ${cls}">${escHtml(text)}</span>`;
  const counts = _cloudAcctCounts.get(id);
  const rows = accounts.map((a) => {
    // Resolve the GoLogin id to a name — the engine omits `email` on follower
    // campaigns, which left this panel listing raw profile ids.
    const who = escHtml(a.email || _acctLabel(a) || 'account');
    const badges = [];
    // Blocking status first (most important), then daily usage, then primary link.
    const benched = !!(a.weeklyCap || a.parkReason === 'weekly');
    if (a.needsLogin) badges.push(badge('bad', '⚠ Not logged in'));
    // Parked by 3 consecutive proxy 407s — the VM literally cannot open this
    // profile's browser. Distinct from a throttle: waiting won't fix it.
    else if (a.parkReason === 'proxy') badges.push(badge('bad', '⛔ Proxy refused — fix the GoLogin profile, then Retry'));
    else if (benched) badges.push(badge('bad', `🚫 Benched — weekly invitation limit · resets ${_nextMondayText()}`));
    else if (a.parked || a.parkReason === 'throttle') badges.push(badge('warn', '⏸ Throttled'));
    else if ((a.dailyLimit || 0) > 0 && (a.dailyCount || 0) >= a.dailyLimit) badges.push(badge('warn', 'Daily limit reached'));
    else badges.push(badge('ok', '✓ Active'));
    // This run's invites when we have them (the daily quota is meaningless on a
    // follower campaign — it counts connection requests), else the daily usage.
    const tally = counts && counts.get(String(a.profileId || ''));
    badges.push(tally
      ? badge('muted', `${tally.sent} of ${tally.total} invited`)
      : badge('muted', `${a.dailyCount || 0}/${a.dailyLimit || 0} today`));
    // Primary-connection (CC+IC only; null when N/A).
    if (a.primaryConnected === true) badges.push(badge('ok', '🔗 Connected to primary'));
    else if (a.primaryConnected === false) badges.push(badge('muted', 'Primary not yet connected'));
    // Benched → operator override: Retry clears the bench engine-side, and the
    // account is eligible again from the next turn (three fresh 429 strikes
    // re-bench it automatically if LinkedIn is still capping).
    // A weekly cap gets no Retry — it's a window, not a cooldown. Offering one
    // here while the live stage says "don't retry before Monday" is the app
    // arguing with itself, and taking it spends strikes for nothing.
    if (benched && !a.needsLogin && !(a.weeklyCap || a.parkReason === 'weekly')) {
      badges.push(`<button type="button" class="cap-retry" onclick="unbenchCloudAccount('${escHtml(id)}','${escHtml(a.profileId || '')}',this)" title="Clear the bench and let this account try again">Retry</button>`);
    }
    // Editable (paused/stopped) → a toggle that REMOVES the account from the
    // campaign, mirroring the local pause-edit panel. Never offered on the last
    // account (a campaign needs at least one) — the engine rejects that too.
    const tog = _cloudAccountsEditable() && accounts.length > 1
      ? `<button type="button" class="cap-toggle on" role="switch" aria-checked="true"`
        + ` title="Remove this account from the campaign" aria-label="Remove ${who} from the campaign"`
        + ` onclick="removeCloudCampaignAccount('${escHtml(id)}','${escHtml(a.profileId || '')}',this)"></button>`
      : '';
    return `<div class="cap-row"><span class="cap-acct">${who}</span><span class="cap-status">${badges.join('')}${tog}</span></div>`;
  }).join('');
  panel.innerHTML = `<div class="cap-head"><span>Accounts</span><span>${accounts.length} account${accounts.length === 1 ? '' : 's'}</span></div>${rows}`
    + _cloudAccountsAddHtml(id);
  panel.hidden = false;
}

// REMOVING races a worker that may be mid-send from that very account, so it
// needs a pause — the engine enforces the same rule and 409s otherwise.
function _cloudAccountsEditable() {
  const s = window.__cloudActiveStatus;
  if (!s || !s._cloud) return false;
  const st = String(s.engineStatus || '');
  if (!st) return false; // detail fetch failed — don't offer an edit we can't validate
  return !['running', 'queued', 'pending'].includes(st);
}

// ADDING is safe in any status (a lead carries no account until claim time), so
// the picker is always reachable. Gating it behind a pause is what left the
// operator ticking accounts in the wizard with nothing to commit them.
function _cloudAccountsAddable() {
  const s = window.__cloudActiveStatus;
  return !!(s && s._cloud && String(s.engineStatus || ''));
}

function _cloudAccountsAddHtml(id) {
  if (!_cloudAccountsAddable()) return '';
  // One canonical picker. A second, raw <select> of every GoLogin profile here
  // was unusable (474 profiles, shown by raw profile name, no SoO state) — so
  // this just sends the operator up to §3's real tile grid instead.
  const hint = _cloudAccountsEditable() ? '' : ' <span class="cap-add-lbl">· pause it to remove one</span>';
  return `<div class="cap-add">
      <label class="cap-add-lbl">＋ Add account</label>
      <button type="button" class="cap-add-btn" onclick="openCloudAccountPicker('${escHtml(id)}')">Choose in the account picker ↑</button>${hint}
    </div>`;
}

// ── Add/remove a live cloud campaign's accounts via the wizard's §3 picker ────
// Takes the operator to the canonical GoLogin selector with this campaign's
// accounts pre-ticked, then patches the account set in place from the diff.
// NOT the edit-redispatch flow: no new campaign id, no leads moved.
let _acctAdd = null; // { cloudId, name, before:[…], prevSelection:[…], mode, primaryUrl }
let _acctAddTouched = false; // operator has ticked something — stop re-asserting over them

// Re-enable anything inside §3 that a PREVIOUS read-only lock pass disabled.
// _setCloudEditLock only clears its dataset flag on an explicit unlock, and we
// don't want to unlock the whole wizard (an active campaign's config must stay
// frozen) — so clear it for the picker alone.
function _unlockAcctPicker() {
  for (const sel of ['#nav-accounts', '#wizard-acct-add-banner']) {
    const root = document.querySelector(sel);
    if (!root) continue;
    root.querySelectorAll('[data-cloud-edit-locked]').forEach((el) => {
      el.disabled = false; delete el.dataset.cloudEditLocked;
    });
  }
}

async function openCloudAccountPicker(id) {
  _acctAddTouched = false;
  const st = window.__cloudActiveStatus || {};
  const before = ((_cloudAccountsById.get(id) || []).map((a) => a.profileId)).filter(Boolean);
  _acctAdd = {
    cloudId: id, name: st.name || 'this campaign', before,
    prevSelection: selectedProfileIds.slice(),
    mode: st.mode || '', primaryUrl: st.primaryUrl || '',
  };
  selectedProfileIds = before.slice();
  goCreateCampaign();
  // The grid may not be loaded yet on a cold wizard — loadProfiles() renders it.
  if (allProfilesData && allProfilesData.length) renderProfiles(allProfilesData);
  else { try { await loadProfiles(); } catch (_) { /* the picker shows its own error */ } }
  _renderAcctAddBanner();
  _unlockAcctPicker();
  const sect = document.getElementById('nav-accounts');
  if (sect) {
    sect.classList.remove('collapsed'); // it ships collapsed — open it or the grid is invisible
    try { sect.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) { sect.scrollIntoView(); }
  }
  // goCreateCampaign() set location.hash, whose deferred hashchange handler and
  // the wizard pollers run AFTER this synchronous setup and can re-render the
  // grid off other state. Same remedy _enforceCloudReadOnlyView uses: re-assert
  // idempotently once those have run, rather than chase each clobber.
  [120, 600, 1500].forEach((ms) => setTimeout(() => {
    if (!_acctAdd || _acctAdd.cloudId !== id) return;
    const want = _acctAdd.before;
    const same = selectedProfileIds.length === want.length && want.every((p) => selectedProfileIds.includes(p));
    if (!same && !_acctAddTouched) {
      selectedProfileIds = want.slice();
      try { if (allProfilesData && allProfilesData.length) renderProfiles(allProfilesData); } catch (_) { /* */ }
    }
    _renderAcctAddBanner();
    _unlockAcctPicker(); // the 5s cloud poll re-asserts the read-only lock
  }, ms));
}
window.openCloudAccountPicker = openCloudAccountPicker;

// Live-updating summary of what Apply will do. Called from renderSelectedPanel()
// so it tracks every tick/untick in the grid.
function _renderAcctAddBanner() {
  const banner = document.getElementById('wizard-acct-add-banner');
  const bar = document.getElementById('acct-add-bar');
  if (!banner && !bar) return;
  if (!_acctAdd) {
    if (banner) banner.style.display = 'none';
    if (bar) bar.style.display = 'none';
    return;
  }
  const { add, remove } = _acctAddDiff();
  const title = document.getElementById('acct-add-banner-title');
  const detail = document.getElementById('acct-add-banner-detail');
  if (banner) banner.style.display = '';
  if (bar) bar.style.display = '';
  if (title) title.textContent = `Choosing accounts for "${_acctAdd.name}".`;
  const bits = [];
  if (add.length) bits.push(`${add.length} to add`);
  if (remove.length) bits.push(`${remove.length} to remove`);
  const removeBlocked = remove.length && !_cloudAccountsEditable();
  const text = removeBlocked
    ? `${bits.join(' · ')} — but removing needs a pause. Adding is fine while it runs.`
    : bits.length
      ? `${bits.join(' · ')} for "${_acctAdd.name}" — the campaign keeps running, nothing is redispatched.`
      : `Choosing accounts for "${_acctAdd.name}" — tick one below to add it, untick one to remove it.`;
  if (detail) detail.textContent = text;
  const barTxt = document.getElementById('acct-add-bar-txt');
  if (barTxt) barTxt.textContent = text;
  for (const el of [document.getElementById('btn-acct-add-apply'), document.getElementById('btn-acct-add-apply-2')]) {
    if (!el) continue;
    el.disabled = !bits.length;
    el.textContent = bits.length ? `Apply (${bits.join(', ')})` : 'Apply';
  }
}

// Cloud campaigns run on the VM, which has no operator Chrome — 'local-browser'
// can never be one of their accounts, so it never counts either way.
function _acctAddDiff() {
  if (!_acctAdd) return { add: [], remove: [] };
  const before = _acctAdd.before.filter((p) => p !== 'local-browser');
  const after = selectedProfileIds.filter((p) => p && p !== 'local-browser');
  return {
    add: after.filter((p) => !before.includes(p)),
    remove: before.filter((p) => !after.includes(p)),
  };
}

function acctAddCancel() {
  if (_acctAdd) selectedProfileIds = _acctAdd.prevSelection.slice();
  const id = _acctAdd && _acctAdd.cloudId;
  _acctAdd = null;
  _renderAcctAddBanner();
  try { if (allProfilesData && allProfilesData.length) renderProfiles(allProfilesData); } catch (_) { /* */ }
  if (id) { try { openCloudLive(id); } catch (_) { /* */ } }
}
window.acctAddCancel = acctAddCancel;

async function acctAddApply() {
  if (!_acctAdd) return;
  const { cloudId, mode, primaryUrl } = _acctAdd;
  const { add, remove } = _acctAddDiff();
  if (!add.length && !remove.length) return;
  // Match the engine: removals need a pause, additions don't. Say so instead of
  // letting Apply come back with a 409 after the operator has already picked.
  if (remove.length && !_cloudAccountsEditable()) {
    showCampaignToast('Pause the campaign first to remove an account — adding is fine while it runs.', 6000);
    return;
  }
  // CC+IC: a new sender must be connected to the primary person or its intros can
  // never fire. Same local Phase-0 handshake the wizard runs at launch — the VM
  // has no operator Chrome, so it has to happen on this machine.
  const isIntroMode = mode === 'connect_and_introduce';
  if (isIntroMode && add.length && !primaryUrl) {
    showCampaignToast('Can’t add an account — this CC+IC campaign has no primary person URL, so the new sender could never send its intros.', 7000);
    return;
  }
  if (remove.length && !(_acctAdd.before.length - remove.length + add.length)) {
    showCampaignToast('A campaign needs at least one account.', 5000);
    return;
  }
  const btn = document.getElementById('btn-acct-add-apply');
  if (btn) { btn.disabled = true; btn.textContent = 'Applying…'; }
  try {
    for (const profileId of (isIntroMode ? add : [])) {
      const who = selectedProfileNames[profileId] || profileId;
      showCampaignToast(`Connecting ${who} to the primary — keep this app open…`, 8000);
      const ok = await _runAddAccountHandshake(profileId, primaryUrl);
      if (!ok) return; // _runAddAccountHandshake toasts the reason
    }
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(cloudId)}/accounts`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        // email is a fallback label only — the server re-resolves each added
        // account's real SoO email with the same matcher launch uses.
        add: add.map((profileId) => ({ profileId, email: selectedProfileNames[profileId] || '' })),
        remove,
      }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) { showCampaignToast(d.error || 'Could not update the accounts.', 6000); return; }
    for (const p of add) _pushCloudEvent(cloudId, `➕ ${selectedProfileNames[p] || p} added to the campaign`);
    for (const p of remove) _pushCloudEvent(cloudId, `➖ ${p} removed from the campaign`);
    showCampaignToast(`Accounts updated — ${add.length} added, ${remove.length} removed.`, 5000);
    selectedProfileIds = _acctAdd.prevSelection.slice();
    _acctAdd = null;
    _renderAcctAddBanner();
    try { if (allProfilesData && allProfilesData.length) renderProfiles(allProfilesData); } catch (_) { /* */ }
    try { await openCloudLive(cloudId); } catch (_) { /* */ }
    await _refreshCloudActiveStatus(cloudId);
    renderCloudAccountsPanel(cloudId);
  } catch (e) {
    showCampaignToast('Could not update the accounts: ' + e.message, 6000);
  } finally {
    if (btn) { btn.disabled = false; }
    _renderAcctAddBanner();
  }
}
window.acctAddApply = acctAddApply;

// Toggle an account OFF — drops it from the campaign's account set on the engine.
// Its already-sent leads keep being swept for acceptances (the engine unions
// accounts that actually sent), and its unsent leads are simply picked up by the
// remaining accounts, since cloud leads are only assigned at send time.
async function removeCloudCampaignAccount(id, profileId, btn) {
  const accounts = _cloudAccountsById.get(id) || [];
  const who = (accounts.find((a) => a.profileId === profileId) || {}).email || profileId;
  if (!confirm(`Remove ${who} from this campaign?\n\nIt stops sending. Leads it already invited are still checked for acceptances; its unsent leads go to the remaining accounts.`)) return;
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/accounts`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ remove: [profileId] }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) { showCampaignToast(d.error || 'Could not remove the account.', 6000); return; }
    _pushCloudEvent(id, `➖ ${who} removed from the campaign`);
    showCampaignToast(`${who} removed — it won't send when you resume.`, 4500);
    await _refreshCloudActiveStatus(id);
    renderCloudAccountsPanel(id);
  } catch (e) { showCampaignToast('Could not remove the account: ' + e.message, 6000); }
  finally { if (btn) btn.disabled = false; }
}
window.removeCloudCampaignAccount = removeCloudCampaignAccount;


// Drive the local single-sender handshake and wait for it. Returns true when the
// sender reached the primary (or already was connected).
async function _runAddAccountHandshake(profileId, primaryUrl) {
  try {
    const start = await (await fetch('/api/campaign/cloud-preflight-handshake', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ senderProfileIds: [profileId], primaryUrl, autoAcceptAllPending: true }),
    })).json();
    if (start && start.ok === false) {
      showCampaignToast(start.error || 'Could not start the primary handshake.', 6000);
      return false;
    }
    // Poll until the job settles (the job's own watchdog caps it at ~8 min).
    for (let i = 0; i < 200; i++) {
      await new Promise((r) => setTimeout(r, 3000));
      let j = {};
      try { j = await (await fetch('/api/campaign/cloud-preflight-handshake/status')).json(); } catch (_) { continue; }
      if (!j || !j.active) continue;
      if (!j.done) continue;
      if (j.error) { showCampaignToast(`Handshake failed: ${j.error}`, 8000); return false; }
      // 'connected' is the only state that means the primary link is live (see
      // cloud-preflight-handshake: sent / sent-no-identity / error are not).
      const s = ((j.senders || []).find((x) => x.profileId === profileId) || {});
      if (String(s.state || '') === 'connected') return true;
      showCampaignToast(`The account didn't reach the primary (state: ${s.state || 'unknown'}). Not added — fix it and try again.`, 9000);
      return false;
    }
    showCampaignToast('Handshake is taking too long — not added. Try again once the local browsers settle.', 8000);
    return false;
  } catch (e) {
    showCampaignToast('Handshake error: ' + e.message, 6000);
    return false;
  }
}
window.renderCloudAccountsPanel = renderCloudAccountsPanel;

// Operator "Retry" on a benched (weekly-cap) account — clears the bench on the
// engine; the account is eligible again from the next turn.
// `quiet` suppresses the success toast so the bulk Retry (stageRetryBlocked)
// doesn't fire one per account — it reports once, on its own button.
async function unbenchCloudAccount(campaignId, profileId, btn, quiet) {
  if (!campaignId || !profileId) return;
  if (btn) { btn.disabled = true; btn.textContent = '…'; }
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(campaignId)}/accounts/${encodeURIComponent(profileId)}/unbench`, { method: 'POST' });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Retry isn’t live yet — engine update pending.', 6000);
      if (btn) { btn.disabled = false; btn.textContent = 'Retry'; }
      return;
    }
    if (!quiet) showCampaignToast('▶ Account un-benched — it will try again on its next turn. Three fresh rate-limits re-bench it automatically.', 7000);
    if (_viewingCloudId) { try { await _refreshCloudActiveStatus(_viewingCloudId); } catch (_) { /* */ } }
  } catch (e) {
    showCampaignToast('Could not reach the engine: ' + e.message, 6000);
    if (btn) { btn.disabled = false; btn.textContent = 'Retry'; }
  }
}
window.unbenchCloudAccount = unbenchCloudAccount;

function _stopCloudCardPoll() { if (_cloudCardTimer) { clearInterval(_cloudCardTimer); _cloudCardTimer = null; } }
function _startCloudCardPoll() {
  _stopCloudCardPoll();
  _cloudCardTimer = setInterval(async () => {
    if (!_viewingCloudId) { _stopCloudCardPoll(); return; }
    await _refreshCloudActiveStatus(_viewingCloudId);
    try { renderActiveCard(window.__cloudActiveStatus); } catch (_) { /* */ }
    try { if (typeof _enforceCloudReadOnlyView === 'function') _enforceCloudReadOnlyView(); } catch (_) { /* */ }
  }, 5000);
}
// Leaving the wizard / starting something else stops the cloud-view takeover.
function stopViewingCloudCampaign() { _viewingCloudId = null; window.__cloudActiveStatus = null; _stopCloudCardPoll(); const _ap = document.getElementById('cloud-accounts-panel'); if (_ap) { _ap.hidden = true; _ap.innerHTML = ''; } }
window.stopViewingCloudCampaign = stopViewingCloudCampaign;

// Adapt #active-card's controls when it's showing a cloud campaign: hide the
// local-only Pause/Restart (cloud has no pause/restart), and give a monitoring
// VM campaign a Check-now in the dock (wired to the engine endpoint; degrades to
// "engine update pending" until PR #1 deploys). Stop is handled in
// dashStopActive (it routes to the engine when _viewingCloudId is set). Only
// forces state when cloud; releases the override otherwise so the local card is
// untouched.
function _adaptActiveCardControls(card, status) {
  const cloud = !!_viewingCloudId;
  card.classList.toggle('cloud-view', cloud);
  // Pause/Resume now works for cloud too (engine resume route) — show it for
  // both. Its onclick is dashPauseActive(), which routes to the VM pause/resume
  // when viewing a cloud campaign. (Restart stays local-only — see below.)
  const pauseBtn = document.getElementById('dock-active-pause');
  if (pauseBtn) pauseBtn.style.removeProperty('display');
  const dock = document.getElementById('dock-active');
  const restartBtn = dock ? dock.querySelector('[data-tip="Restart"]') : null;
  if (restartBtn) { if (cloud) restartBtn.style.display = 'none'; else restartBtn.style.removeProperty('display'); }

  // ▶ Continue / ⟲ Restart for a STOPPED (cancelled/errored) cloud campaign —
  // the board strip had these but the live-status card didn't (operator feedback
  // 2026-07-24: "campaign stopped but no play icon in the live status view").
  // In that state Pause/Stop are meaningless → swap the cluster.
  const _stoppedCloud = cloud && status && !status.running && !status.queued
    && status.state !== 'monitoring' && ['cancelled', 'error'].includes(String(status.engineStatus || ''));
  // ▶ Resume sending — a connect campaign that was stopped with "keep checking"
  // sits in 'monitoring' with its unsent leads still pending (37 sent · 116
  // pending). Pause/Stop don't apply and _stoppedCloud excludes monitoring, so
  // there was no way back: the remaining connects could never be sent. This adds
  // the Continue button (and only that — no "restart from the beginning", which
  // here would mean re-sending everything) whenever there is genuinely work left.
  const _pendingLeft = Number((status && status.pendingCount) || 0);
  const _resumeOnly = cloud && !!status && !status.running && !status.queued && !_stoppedCloud
    && /^connect/.test(String(status.mode || ''))
    && _pendingLeft > 0
    && ['monitoring', 'done'].includes(String(status.engineStatus || ''));
  let ctBtn = document.getElementById('dock-cloud-continue');
  let rsBtn = document.getElementById('dock-cloud-restart');
  if ((_stoppedCloud || _resumeOnly) && dock) {
    if (!ctBtn) {
      ctBtn = document.createElement('button');
      ctBtn.id = 'dock-cloud-continue';
      ctBtn.className = 'dock-btn';
      ctBtn.setAttribute('data-tip', 'Continue where it left off'); ctBtn.setAttribute('aria-label', 'Continue where it left off');
      ctBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><polygon points="6 3 20 12 6 21 6 3"/></svg>';
      dock.insertBefore(ctBtn, dock.firstChild);
    }
    if (!rsBtn) {
      rsBtn = document.createElement('button');
      rsBtn.id = 'dock-cloud-restart';
      rsBtn.className = 'dock-btn';
      rsBtn.setAttribute('data-tip', 'Restart from the beginning'); rsBtn.setAttribute('aria-label', 'Restart from the beginning');
      rsBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 1 2.64 6.36L3 16"/><path d="M3 21v-5h5"/></svg>';
      dock.insertBefore(rsBtn, ctBtn.nextSibling);
    }
    ctBtn.onclick = () => { try { window.restartCloudCampaignUI(_viewingCloudId, false); } catch (_) { /* */ } };
    rsBtn.onclick = () => { try { window.restartCloudCampaignUI(_viewingCloudId, true); } catch (_) { /* */ } };
    const _resumeTip = `Resume sending — ${_pendingLeft} still to go`;
    ctBtn.setAttribute('data-tip', _resumeOnly ? _resumeTip : 'Continue where it left off');
    ctBtn.setAttribute('aria-label', _resumeOnly ? _resumeTip : 'Continue where it left off');
    ctBtn.style.display = '';
    // Restart-from-the-beginning only makes sense for a genuinely stopped run.
    // On a monitoring campaign it would re-send every lead — never offer it.
    rsBtn.style.display = _resumeOnly ? 'none' : '';
    // Monitoring keeps its own Pause/Stop (the checks are still running); a
    // stopped campaign has nothing to pause or stop.
    if (!_resumeOnly) {
      if (pauseBtn) pauseBtn.style.display = 'none';
      const stopBtn = dock.querySelector('[data-tip="Stop"]');
      if (stopBtn) stopBtn.style.display = 'none';
    } else {
      const stopBtn = dock.querySelector('[data-tip="Stop"]');
      if (stopBtn) stopBtn.style.removeProperty('display');
    }
  } else {
    if (ctBtn) ctBtn.style.display = 'none';
    if (rsBtn) rsBtn.style.display = 'none';
    if (!cloud || (status && (status.running || status.queued || status.state === 'monitoring'))) {
      const stopBtn = dock ? dock.querySelector('[data-tip="Stop"]') : null;
      if (stopBtn) stopBtn.style.removeProperty('display');
    }
  }
  let cn = document.getElementById('dock-cloud-checknow');
  // Check now is available in EVERY state of a cloud connect_and_* campaign —
  // including one stopped overall (cancelled/error/done). The engine treats a
  // sweep outside 'monitoring' as a one-shot: it checks acceptances + fires the
  // intro/DM backlog without resurrecting recurring monitoring or resuming sends.
  const _cnMode = String((status && status.mode) || '');
  const wantCheck = cloud && !!status && !!dock
    && (_cnMode === 'connect_and_introduce' || _cnMode === 'connect_and_message');
  if (wantCheck) {
    if (!cn) {
      cn = document.createElement('button');
      cn.id = 'dock-cloud-checknow';
      cn.className = 'dock-btn';
      cn.setAttribute('data-tip', 'Check now'); cn.setAttribute('aria-label', 'Check now');
      cn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12a9 9 0 1 1-3-6.7L21 8"/><path d="M21 3v5h-5"/></svg>';
      dock.insertBefore(cn, dock.firstChild);
    }
    cn.onclick = () => { try { window.promptCloudCheckScope(_viewingCloudId, cn); } catch (_) { /* */ } };
    cn.style.display = '';
  } else if (cn) { cn.style.display = 'none'; }

  // 👁 Show live — watch THIS cloud campaign's browser (parity with card #1's
  // strip button). Shown whenever card #2 is a cloud campaign (any state); the
  // viewer itself handles the idle case. A green LIVE dot lights when the engine
  // reports an active browser this poll (status.live, folded in via component 5).
  let sh = document.getElementById('dock-cloud-show');
  const wantShow = cloud && !!dock;
  if (wantShow) {
    if (!sh) {
      sh = document.createElement('button');
      sh.id = 'dock-cloud-show';
      sh.className = 'dock-btn';
      sh.setAttribute('data-tip', 'Show live'); sh.setAttribute('aria-label', 'Show live');
      sh.innerHTML = '<span class="live-dot"></span>👁';
      dock.insertBefore(sh, dock.firstChild);
    }
    const _lbl = String((status && (status.name || status.id)) || '').replace(/['"\\<>]/g, '');
    sh.onclick = () => { try { openCloudCampaignView(String(_viewingCloudId), _lbl); } catch (_) { /* */ } };
    sh.classList.toggle('live-on', !!(status && status.live));
    sh.style.display = '';
  } else if (sh) { sh.style.display = 'none'; }
}

// Cloud "Open" — go to the campaign tab and show THIS campaign's live status
// campaign card (card #2), then scroll down to it. Same as a local Open.
async function openCloudLive(id) {
  _viewingCloudId = id;
  liveStatusForcedOpen = true;
  await _refreshCloudActiveStatus(id);   // seed the card before we reveal it
  goCreateCampaign();                     // → the campaign tab (#/new)
  setTimeout(() => {
    try { renderActiveCard(window.__cloudActiveStatus); } catch (_) { /* */ }
    try { syncLiveStatusVisibility(); } catch (_) { /* */ }
    try { placeLiveCard(); } catch (_) { /* */ }
    const sec = document.getElementById('nav-status');
    if (sec) { try { sec.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) { /* */ } }
  }, 180);
  _startCloudCardPoll();
}
window.openCloudLive = openCloudLive;

// Hide a done cloud strip from THIS operator's board (local-only, next poll keeps it hidden).
function dismissCloudDone(id, btn) {
  _cloudDismissed.add(id); _cloudSaveDismissed();
  const strip = btn && btn.closest ? btn.closest('.sn-strip') : null;
  if (strip) strip.remove();
}
window.dismissCloudDone = dismissCloudDone;

// ─── Unified Campaigns board (v2.129) ───────────────────────────────────────
// One board for EVERY campaign — local + cloud — as sn-strips. Rail colour says
// where it runs: GREEN = cloud/VM, PINK = local machine. Buckets into Now
// running / Up next / Done. Replaces the hero + Up Next + Past for the top-level
// view; the legacy sections stay in the DOM (hidden) so a local strip's "Open"
// can reveal the rich detail card.

// True once the user pressed "Open" on a local strip — keeps the legacy detail
// card (#active-card) revealed instead of letting the board re-hide it.
let _localDetailOpen = false;
// Local done strips the user dismissed with ✕ (parity with cloud ✕).
const _localDismissed = new Set();

// Keep the legacy dashboard sections hidden. Called on EVERY board render (not
// once) so route switches / campaign start-stop / renderActiveCard can't leak
// the old hero, calendar or Past back in. #active-card is the one exception:
// it stays visible while the user has the local detail open.
function _hideLegacyDashboardSections() {
  const hide = (sel) => { const el = document.querySelector(sel); if (el) el.style.display = 'none'; };
  hide('#dashboard-view .section-band.is-queue');
  hide('#dashboard-view .section-band.is-week');
  hide('#dashboard-view .section-band.is-past');
  // The old standalone Cloud Campaigns section is now redundant (folded in here).
  const cloudSec = document.getElementById('cloud-campaigns-section');
  if (cloudSec) cloudSec.style.display = 'none';
  // #active-card: revealed (pink) only while a local detail is open.
  const card = document.getElementById('active-card');
  if (card) {
    // v2.146: #active-card is a SINGLE shared element. On the wizard route,
    // placeLiveCard() relocates it into #wiz-live-slot and owns its
    // visibility. This board renderer runs on every poll REGARDLESS of route,
    // so without this guard it slammed the wizard-hosted card back to
    // display:none every ~5s — the "Live Status card never opens on a local
    // run" bug. When the card is in the wizard, leave its display untouched.
    const inWizard = card.classList.contains('in-wizard')
      || (card.parentElement && card.parentElement.id === 'wiz-live-slot');
    if (inWizard) { /* wizard owns visibility — do not hide */ }
    else if (_localDetailOpen) { card.style.display = ''; card.classList.add('is-local'); }
    else { card.style.display = 'none'; }
  }
}

// Reveal the rich local detail card (live log / bulk-check / monitoring) for the
// running local campaign — pink-railed to match the board strip — and scroll to it.
function openLocalCampaignDetail() {
  _localDetailOpen = true;
  const card = document.getElementById('active-card');
  if (card) {
    card.style.display = '';
    card.classList.add('is-local');
    try { card.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (_) { /* */ }
  }
}
window.openLocalCampaignDetail = openLocalCampaignDetail;

// Dismiss a local Done strip from the board (parity with dismissCloudDone).
function dismissLocalDone(id) { _localDismissed.add(id); renderCampaignsBoard(); }
window.dismissLocalDone = dismissLocalDone;

// Delete a finished/stopped campaign from the board (replaces the old Dismiss).
// Local campaigns are truly deleted from history.json; cloud campaigns have no
// engine delete endpoint yet, so they're stopped (if somehow still active) and
// removed from this dashboard durably. Always confirms first.
async function deleteBoardCampaign(id, btn) {
  const it = _boardItemsById.get(id) || (_snItemsById && _snItemsById.get(id));
  const name = (it && it.name) || 'this campaign';
  if (!confirm(`Delete "${name}"?\n\nThis removes it from your dashboard for good.`)) return;
  try {
    if (it && it.where === 'cloud') {
      // Kill any live engine activity for this campaign FIRST — stop halts sending
      // + monitoring and releases its account locks — THEN durably hide it from the
      // board. Previously delete only hid it, so a running campaign kept sending on
      // the VM (and held its accounts) after being "deleted". Best-effort: hide it
      // even if the stop call fails.
      try { await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/stop`, { method: 'POST' }); } catch (_) { /* still hide it below */ }
      _cloudDismissed.add(id); _cloudSaveDismissed();
    } else if (it && it.histIdx != null) {
      const r = await fetch('/api/history/' + encodeURIComponent(it.histIdx), { method: 'DELETE' });
      if (!r.ok) {
        const e = await r.json().catch(() => ({}));
        alert('Could not delete: ' + (e.error || r.status));
        return;
      }
    } else {
      _localDismissed.add(id);
    }
  } catch (e) {
    alert('Could not delete: ' + e.message);
    return;
  }
  const strip = btn && btn.closest ? btn.closest('.sn-strip') : null;
  if (strip) strip.remove(); // instant feedback; next poll already filters it
  renderCampaignsBoard();
}
window.deleteBoardCampaign = deleteBoardCampaign;

// Copy a campaign strip's log to the clipboard (⧉ button on the black log box).
// Reads the rendered log's plain text (not HTML) so it pastes clean into a
// message / ticket. Brief ✓ feedback on the button; execCommand fallback for
// any context where the async clipboard API is unavailable.
function copyStripLog(btn) {
  const pane = (btn.closest && btn.closest('.sn-pane')) || btn.parentElement;
  const box = pane && pane.querySelector('.sn-logbox');
  const text = box ? (box.innerText || box.textContent || '').replace(/\s+$/, '') : '';
  if (!text) { if (typeof showCampaignToast === 'function') showCampaignToast('No log to copy yet.', 3000); return; }
  const flash = () => {
    btn.classList.add('copied');
    const lbl = btn.querySelector('.sn-logcopy-lbl');
    if (lbl) { lbl.dataset.orig = lbl.dataset.orig || lbl.textContent; lbl.textContent = 'Copied'; }
    setTimeout(() => {
      btn.classList.remove('copied');
      if (lbl && lbl.dataset.orig) lbl.textContent = lbl.dataset.orig;
    }, 1300);
  };
  const fallback = () => {
    try {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); flash();
    } catch (_) { if (typeof showCampaignToast === 'function') showCampaignToast('Could not copy log.', 3000); }
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(flash).catch(fallback);
  } else { fallback(); }
}
window.copyStripLog = copyStripLog;

// ── Duplicate a campaign (Sam #1) → open + New campaign pre-filled ──────────
const _boardItemsById = new Map();  // strip id → normalized item (for actions)
let _ovfWired = false;

// Build a wizard-config object from a history entry's settings (mirrors
// rerunPastCampaign so a duplicated done campaign carries every setting).
function _configFromSettings(mode, s) {
  s = s || {};
  const gid = s.sheetGid ? String(s.sheetGid) : ((s.sheetUrl || '').match(/[#&?]gid=(\d+)/) || [])[1] || '';
  return {
    mode, sheetUrl: s.sheetUrl || '', sheetGid: gid,
    dailyLimit: s.dailyLimit ?? 50, delayMin: s.delayMin ?? 30, delayMax: s.delayMax ?? 60,
    linkedinColumn: s.linkedinColumn || '', messageOpenProfiles: !!s.messageOpenProfiles,
    addNote: !!(s.templates && s.templates.connectionNote), templates: s.templates || {},
    profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
    concurrency: s.concurrency ?? 1, senderFirstNames: s.senderFirstNames || {},
  };
}

// Resolve the source config for a strip, then open the pre-filled wizard.
async function duplicateCampaign(id) {
  const it = _boardItemsById.get(id);
  if (!it) return;
  let config = null; let srcName = it.name || 'Campaign';
  try {
    if (it.where === 'cloud') {
      const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(it.id)}/launch-config`);
      if (r.ok) { const d = await r.json(); config = d.config; srcName = d.name || srcName; }
    } else if (it.bucket === 'queued' && it.rawId) {
      const r = await fetch('/api/queue/' + encodeURIComponent(it.rawId));
      if (r.ok) { const e = await r.json(); config = e.config; srcName = e.name || srcName; }
    } else if (it.bucket === 'done' && it.srcSettings) {
      config = _configFromSettings(it.mode, it.srcSettings);
    } else if (it.id === 'local-active') {
      // Running local campaign: prefer its live settings snapshot (v2.83
      // /api/campaign/active-settings — the exact config it launched with),
      // falling back to the operator's last-used preset.
      const r = await fetch('/api/campaign/active-settings');
      if (r.ok) {
        const d = await r.json();
        if (d && d.ok && d.settings) config = _configFromSettings(it.mode || d.settings.mode, d.settings);
      }
      if (!config) {
        const r2 = await fetch('/api/presets/_last_used');
        if (r2.ok) { const e = await r2.json(); config = e.config || (e.entry && e.entry.config) || null; }
      }
    }
  } catch (_) { /* fall through to the guard below */ }
  if (!config || typeof config !== 'object') {
    alert("Couldn't load this campaign's settings to duplicate.\nOpen ＋ New campaign and set it up manually.");
    return;
  }
  _openDuplicateDraft(srcName, config);
}
window.duplicateCampaign = duplicateCampaign;

// Duplicate a past-campaign row (history entry) into a fresh pre-filled draft.
// Reads from pastCampaignsCache (same source as the details modal / resume).
function duplicatePastCampaign(idx) {
  const entry = (pastCampaignsCache || []).find((e) => e.idx === idx);
  const c = entry && entry.c;
  if (!c || !c.settings) {
    alert("This campaign predates settings snapshots — it can't be duplicated.\nOpen ＋ New campaign and set it up manually.");
    return;
  }
  _openDuplicateDraft(c.name || 'Campaign', _configFromSettings(c.mode, c.settings));
}
window.duplicatePastCampaign = duplicatePastCampaign;

// Stage the config as a fresh draft and open the wizard pre-filled with a
// "… copy" name. Nothing runs until the operator picks Start/Queue/Schedule.
async function _openDuplicateDraft(srcName, config) {
  if (typeof unlockCampaignType === 'function') unlockCampaignType();  // v2.160.42: a duplicate is a new campaign — type editable
  const copyName = /\bcopy\b/i.test(srcName) ? srcName : `${srcName} copy`;
  let draftId = '';
  try {
    const r = await fetch('/api/drafts', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: copyName, config }),
    });
    if (r.ok) draftId = (await r.json())?.draft?.id || '';
  } catch (_) { /* draft staging best-effort */ }
  if (draftId && typeof setActiveDraftId === 'function') setActiveDraftId(draftId);
  if (typeof goCreateCampaign === 'function') goCreateCampaign();
  // Defer until the wizard view is mounted (same pattern as rerunPastCampaign).
  setTimeout(() => {
    const ni = document.getElementById('campaign-name-input');
    if (ni) ni.value = copyName;
    if (typeof applyPresetConfig === 'function') applyPresetConfig(config);
  }, 60);
}

// Delegated open/close + Duplicate action for the strip ⋯ menus.
function _wireStripOverflow() {
  if (_ovfWired) return;
  _ovfWired = true;
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('#campaigns-board .ovf-btn');
    if (btn) {
      const o = btn.closest('.ovf'); const wasOpen = o.classList.contains('open');
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
      if (!wasOpen) o.classList.add('open');
      return;
    }
    const act = e.target.closest('#campaigns-board .ovf-item[data-act="duplicate"]');
    if (act) {
      const cid = act.closest('.sn-strip')?.dataset.cid;
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
      if (cid) duplicateCampaign(cid);
      return;
    }
    if (!e.target.closest('#campaigns-board .ovf')) {
      document.querySelectorAll('#campaigns-board .ovf.open').forEach((x) => x.classList.remove('open'));
    }
  });
}

// ── Campaigns board: filter by type (Sam) ──────────────────────────────────
// A compact dropdown on the header narrows the board to one campaign type.
let _campaignsTypeFilter = 'All';   // 'All' | badge (CC, C+I, C+D, DM, IB, FG…)
let _typeFilterOpen = false;        // menu open — don't rebuild it mid-interaction
let _typeFilterWired = false;

// Rebuild the dropdown control. counts come from ALL items (unfiltered).
function renderCampaignsTypeFilter(allItems) {
  const host = document.getElementById('campaigns-typefilter');
  if (!host) return;
  if (_typeFilterOpen) { _updateTypeFilterTrigger(allItems); return; } // don't clobber open menu
  // Distinct types present, in a stable order, each with its live count.
  const order = ['CC', 'C+I', 'C+D', 'DM', 'IB', 'FG', 'IM', 'OP', 'CS'];
  const present = [];
  for (const it of allItems) { const b = _cloudBadge(it.mode); if (b && !present.includes(b)) present.push(b); }
  present.sort((a, b) => order.indexOf(a) - order.indexOf(b));
  const types = ['All', ...present];
  const count = (t) => t === 'All' ? allItems.length : allItems.filter((x) => _cloudBadge(x.mode) === t).length;
  // If the active filter no longer exists (its campaigns ended), fall back to All.
  if (_campaignsTypeFilter !== 'All' && !present.includes(_campaignsTypeFilter)) _campaignsTypeFilter = 'All';
  const items = types.map((t) =>
    `<div class="fdrop-item ${t === _campaignsTypeFilter ? 'on' : ''}" data-t="${escHtml(t)}">`
    + `<span><span class="tick">${t === _campaignsTypeFilter ? '✓' : ''}</span> ${escHtml(t)}</span>`
    + `<span class="n">${count(t)}</span></div>`).join('');
  host.innerHTML =
    `<button type="button" class="fdrop-btn" id="typeFilterBtn"><span class="cur">Type: <b>${escHtml(_campaignsTypeFilter)}</b> · ${count(_campaignsTypeFilter)}</span>`
    + `<svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6l4 4 4-4"/></svg></button>`
    + `<div class="fdrop-menu" id="typeFilterMenu">${items}</div>`;
  host.classList.toggle('open', _typeFilterOpen);
  _wireTypeFilter();
}

function _updateTypeFilterTrigger(allItems) {
  const btn = document.querySelector('#typeFilterBtn .cur');
  if (!btn) return;
  const count = _campaignsTypeFilter === 'All'
    ? allItems.length : allItems.filter((x) => _cloudBadge(x.mode) === _campaignsTypeFilter).length;
  btn.innerHTML = `Type: <b>${escHtml(_campaignsTypeFilter)}</b> · ${count}`;
}

function _wireTypeFilter() {
  if (_typeFilterWired) return;
  _typeFilterWired = true;
  document.addEventListener('click', (e) => {
    const host = document.getElementById('campaigns-typefilter');
    if (!host) return;
    if (e.target.closest('#typeFilterBtn')) {
      _typeFilterOpen = !_typeFilterOpen; host.classList.toggle('open', _typeFilterOpen); return;
    }
    const item = e.target.closest('.fdrop-item');
    if (item && host.contains(item)) {
      _campaignsTypeFilter = item.dataset.t; _typeFilterOpen = false;
      renderCampaignsBoard();
      return;
    }
    if (!host.contains(e.target)) { _typeFilterOpen = false; host.classList.remove('open'); }
  });
}

// ── Conductor filter (admin only) ──────────────────────────────────────────
let _campaignsConductorFilter = 'Everyone'; // 'Everyone' | owner email
let _conductorFilterOpen = false;
let _conductorFilterWired = false;
const _ownerOf = (it) => it.owner || (it.mine ? _viewerEmail : '') || '';
const _shortOwner = (o) => o === 'Everyone' ? 'Everyone' : String(o).split('@')[0];

function renderCampaignsConductorFilter(allItems) {
  const host = document.getElementById('campaigns-conductorfilter');
  if (!host) return;
  if (!_viewerIsAdmin) { host.style.display = 'none'; host.innerHTML = ''; return; }
  host.style.display = '';
  if (_conductorFilterOpen) { return; } // don't clobber open menu
  const owners = [];
  for (const it of allItems) { const o = _ownerOf(it); if (o && !owners.includes(o)) owners.push(o); }
  owners.sort();
  if (_campaignsConductorFilter !== 'Everyone' && !owners.includes(_campaignsConductorFilter)) _campaignsConductorFilter = 'Everyone';
  const opts = ['Everyone', ...owners];
  const count = (o) => o === 'Everyone' ? allItems.length : allItems.filter((x) => _ownerOf(x) === o).length;
  const items = opts.map((o) =>
    `<div class="fdrop-item ${o === _campaignsConductorFilter ? 'on' : ''}" data-o="${escHtml(o)}">`
    + `<span><span class="tick">${o === _campaignsConductorFilter ? '✓' : ''}</span> ${escHtml(_shortOwner(o))}</span>`
    + `<span class="n">${count(o)}</span></div>`).join('');
  host.innerHTML =
    `<button type="button" class="fdrop-btn" id="conductorFilterBtn"><span class="cur">Conductor: <b>${escHtml(_shortOwner(_campaignsConductorFilter))}</b></span>`
    + `<svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6l4 4 4-4"/></svg></button>`
    + `<div class="fdrop-menu" id="conductorFilterMenu">${items}</div>`;
  host.classList.toggle('open', _conductorFilterOpen);
  _wireConductorFilter();
}

function _wireConductorFilter() {
  if (_conductorFilterWired) return;
  _conductorFilterWired = true;
  document.addEventListener('click', (e) => {
    const host = document.getElementById('campaigns-conductorfilter');
    if (!host) return;
    if (e.target.closest('#conductorFilterBtn')) {
      _conductorFilterOpen = !_conductorFilterOpen; host.classList.toggle('open', _conductorFilterOpen); return;
    }
    const item = e.target.closest('.fdrop-item');
    if (item && host.contains(item)) {
      _campaignsConductorFilter = item.dataset.o; _conductorFilterOpen = false;
      renderCampaignsBoard();
      return;
    }
    if (!host.contains(e.target)) { _conductorFilterOpen = false; host.classList.remove('open'); }
  });
}

// ── Skipped-leads panel state ──────────────────────────────────────────────
// Shared across the board; the panel is only shown for the one local-active strip.
let _skipPanelExpanded = false;
let _skipData = []; // array of skip objects from /api/campaign/skips
let _skipPollTimer = null;

const _SKIP_REASON_LABELS = {
  already_processed:   'Already processed',
  identity_unconfirmed:'Identity unconfirmed',
  watchdog_timeout:    'Watchdog timeout',
  malformed_url:       'Malformed URL',
  duplicate_row:       'Duplicate row',
  failed_repeatedly:   'Failed repeatedly',
  terminal_stage:      'Terminal stage',
  other:               'Other',
};

function _skipReasonLabel(r) {
  return _SKIP_REASON_LABELS[r] || r || 'Other';
}

async function _fetchSkips() {
  try {
    const r = await fetch('/api/campaign/skips');
    const d = await r.json();
    _skipData = Array.isArray(d.skips) ? d.skips : [];
  } catch { /* best-effort */ }
}

function _startSkipPoll() {
  if (_skipPollTimer) return;
  _skipPollTimer = setInterval(_fetchSkipsAndRefresh, 5000);
}

function _stopSkipPoll() {
  if (_skipPollTimer) { clearInterval(_skipPollTimer); _skipPollTimer = null; }
}

// Stop both skip-panel pollers (campaigns-board strip + active-card).
function _stopAllSkipPollers() {
  _stopSkipPoll();
  _stopSkipsPoller();
}

async function _fetchSkipsAndRefresh() {
  await _fetchSkips();
  _renderSkipPanelInPlace();
}

function _renderSkipPanelInPlace() {
  const panel = document.getElementById('skip-panel-body');
  if (!panel) return;
  panel.innerHTML = _buildSkipTableHtml();
}

function _buildSkipTableHtml() {
  if (!_skipData.length) return '<p class="skip-empty">No skips recorded yet.</p>';
  const rows = _skipData.map((sk) => {
    const lead = escHtml(sk.leadName || sk.url || '—');
    const account = escHtml(sk.profileName || '—');
    const reason = escHtml(_skipReasonLabel(sk.reason));
    const detail = escHtml(sk.detail || '');
    return `<tr>
      <td class="skip-rowno">${escHtml(String(sk.rowNumber || '—'))}</td>
      <td>${lead}</td>
      <td>${account}</td>
      <td class="skip-reason"><b>${reason}</b>${detail ? ' — ' + detail : ''}</td>
    </tr>`;
  }).join('');
  return `<table class="skiptab">
    <thead><tr><th>Row</th><th>Lead</th><th>Account</th><th>Reason</th></tr></thead>
    <tbody>${rows}</tbody>
  </table>`;
}

window.toggleSkipPanel = async function toggleSkipPanel() {
  _skipPanelExpanded = !_skipPanelExpanded;
  if (_skipPanelExpanded) {
    await _fetchSkips();
    _startSkipPoll();
  } else {
    _stopSkipPoll();
  }
  // Re-render the board so the toggle takes effect immediately.
  // renderCampaignsBoard is async and will pick up _skipPanelExpanded.
  renderCampaignsBoard();
};

window.copySkipList = function copySkipList() {
  if (!_skipData.length) return;
  const lines = _skipData.map((sk) =>
    [sk.rowNumber || '—', sk.leadName || sk.url || '—', _skipReasonLabel(sk.reason), sk.detail || ''].join('\t')
  );
  navigator.clipboard.writeText(lines.join('\n')).catch(() => {});
};

// Reset skip state when a new campaign starts (called on campaign end detection).
function _clearSkipPanel() {
  _skipPanelExpanded = false;
  _skipData = [];
  _stopSkipPoll();
}

// Build the skipped block HTML for the strip.
function _buildSkippedSection(it) {
  if (!it || it.where !== 'local') return '';
  const n = it.skippedCount || 0;
  if (!n) return '';
  if (!_skipPanelExpanded) {
    return `<div class="skipped-mini">
      <span class="skip-pill">Skipped so far: ${n}</span>
      <a class="skip-view-link" onclick="toggleSkipPanel()">view</a>
    </div>`;
  }
  // Expanded — render from cached _skipData. The expanded flag persists across
  // campaign runs while the pollers get stopped on idle, so re-arm the fetch +
  // poll here: without this, a panel left open before a run renders "No skips
  // recorded yet" forever even as skippedCount climbs.
  _startSkipPoll();
  if (!_skipData.length && n > 0) _fetchSkipsAndRefresh();
  const tableHtml = _buildSkipTableHtml();
  return `<div class="skipped">
    <div class="skipped-head">
      Skipped · <span class="skip-n">${n} leads</span>
      <a class="skip-view-link skip-collapse" onclick="toggleSkipPanel()">Collapse</a>
    </div>
    <div id="skip-panel-body">${tableHtml}</div>
    <div class="skipped-actions">
      <button type="button" class="mini" onclick="copySkipList()">Copy list</button>
      <span class="skipped-note">Skipped rows remain untouched on the sheet.</span>
    </div>
  </div>`;
}
// ── End skipped-leads panel ────────────────────────────────────────────────

// Render one normalized item as an sn-strip. Item shape:
//   { where:'cloud'|'local', id, name, mode, isFG, bucket:'running'|'queued'|'done',
//     sent, total, accounts, mine, owner, bad, paused, sheetUrl }
// ── Expanded-strip card #2 parity ───────────────────────────────────────────
// An expanded dashboard strip renders the SAME .vj-card as the campaign-tab
// live-status card (card #2). vjCardSkeleton clones the real #active-card node
// (id→data-f so ids don't collide) — zero markup drift. fillVjCard populates it
// per-campaign, scoped by data-f. The collapsed strip is unchanged. See
// docs/superpowers/specs/2026-07-11-expanded-strip-card2-parity-design.md
let _snItemsById = new Map();

function vjCardSkeleton(cid) {
  const src = document.getElementById('active-card');
  if (!src) return '';
  const clone = src.cloneNode(true);
  clone.removeAttribute('id');
  clone.classList.add('sn-vjcard', 'is-detailed');
  clone.classList.remove('in-wizard', 'is-empty', 'is-preflight', 'is-monitor', 'is-local', 'is-mini');
  clone.setAttribute('data-cid', cid);
  clone.removeAttribute('aria-hidden');
  // The singleton carries an inline `display:none` while idle (app.js sets
  // card.style.display directly); the clone inherits it, so clear it — the base
  // .vj-card grid rule then makes the expanded card visible.
  clone.style.removeProperty('display');
  // Convert every id → data-f so the clone can't duplicate ids in the document.
  clone.querySelectorAll('[id]').forEach((el) => { el.setAttribute('data-f', el.id); el.removeAttribute('id'); });
  // Strip the LOCAL singleton's live content out of the skeleton. #active-card is
  // kept populated with the local campaign (or "No campaign running") by the 2s
  // pollStatus loop; cloning it verbatim is why expanding a VM strip flashed the
  // local template before fillVjCard ran. Blank every value field + the local
  // controls/bulk panel so an unfilled clone is neutral, never local-looking.
  ['activeName', 'activeEyebrow', 'activePct', 'activeSent', 'activeTotal', 'activeAccounts',
   'activeAccepted', 'sendingLbl', 'activeLiveIco', 'activeLiveL1', 'activeLiveL2', 'monCount', 'monLine',
   'stageVerb', 'stageName', 'stageSub', 'stageBeatTxt', 'stageBeatRight']
    .forEach((fld) => { const el = clone.querySelector(`[data-f="${fld}"]`); if (el) el.textContent = ''; });
  // The live stage arrives carrying the singleton's person, phase glyph and
  // render-guard dataset. Blank it so an unfilled clone can never show someone
  // else's lead, and so renderLiveStage redraws it from scratch for THIS card.
  const _cstage = clone.querySelector('[data-f="active-stage"]');
  if (_cstage) {
    _cstage.hidden = true;
    _cstage.dataset.phase = ''; _cstage.dataset.who = ''; _cstage.dataset.acctkey = ''; _cstage.dataset.cid = '';
    const _cg = _cstage.querySelector('[data-f="stageGly"]'); if (_cg) _cg.innerHTML = '';
    const _ca = _cstage.querySelector('[data-f="stageAccts"]'); if (_ca) _ca.innerHTML = '';
    const _cd = _cstage.querySelector('[data-f="stageDrawer"]'); if (_cd) _cd.innerHTML = '';
    const _cf = _cstage.querySelector('[data-f="stageFix"]'); if (_cf) _cf.innerHTML = '';
  }
  const _cbar = clone.querySelector('[data-f="activeBar"]'); if (_cbar) _cbar.style.width = '0%';
  const _clog = clone.querySelector('[data-f="active-log"]'); if (_clog) _clog.innerHTML = '';
  const _cctrl = clone.querySelector('.vj-controls'); if (_cctrl) _cctrl.innerHTML = '';
  const _cbulk = clone.querySelector('.vj-bulk'); if (_cbulk) _cbulk.style.display = 'none';
  return clone.outerHTML;
}

function _fillVjMonitorHero(root, status) {
  // This card is a cloneNode(true) of card #2's LIVE DOM, so it arrives carrying
  // whatever caption and state class card #2 happened to be showing when it was
  // cloned. Updating only the number left those frozen — a gold "now" caption
  // beside a ticking countdown (operator screenshot 2026-07-31). Render all three
  // from one decision, exactly as v3RenderMonitorHero does.
  const view = monitorHeroView(status, v3FmtCountdown);
  const countEl = root.querySelector('[data-f="monCount"]');
  if (countEl) countEl.textContent = view.count;
  const capEl = root.querySelector('.vj-mon-cap');
  if (capEl) capEl.textContent = view.cap;
  const heroElB = root.querySelector('.vj-mon-hero');
  if (heroElB) {
    heroElB.classList.toggle('is-checking', view.state === 'checking');
    heroElB.classList.toggle('is-waking', view.state === 'waking');
  }
  const lineEl = root.querySelector('[data-f="monLine"]');
  if (lineEl) {
    const sent = Number(status.totalProcessed) || 0;
    const accepted = status.acceptedCount ?? '—';
    const cadMin = Number(status.checkIntervalMinutes) || 60;
    const cad = cadMin >= 60 ? (cadMin / 60) + 'h' : cadMin + ' min';
    let ends = '—';
    if (status.monitoringUntil) ends = new Date(status.monitoringUntil).toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' });
    lineEl.innerHTML = _monLineHtml(sent, accepted, cad, ends, status.followUp);
  }
  // v2.160.35: follow-up dual hero on the strip clone (mirrors card #2).
  const fu = status.followUp;
  const fuHero = root.querySelector('[data-f="active-fu-hero"]');
  if (fuHero) {
    if (fu && fu.count > 0) { _setFuDual(root.querySelector('[data-f="fuCount"]'), fu.dueAt); fuHero.hidden = false; }
    else fuHero.hidden = true;
  }
}

function _vjControlsHtml(c, status) {
  const dib = (svg, tip, onclick, cls = '') => `<button type="button" class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;
  let dock = '';
  if (c.pause) dock += dib(status.paused ? V3_SVG_PLAY : V3_SVG_PAUSE, status.paused ? 'Resume' : 'Pause', c.pause.onclick);
  let actions = '';
  if (c.stop) actions += dib(V3_SVG_STOP, c.stop.tip || 'Stop', c.stop.onclick, 'danger');
  if (c.restart) actions += dib(V3_SVG_RESTART, 'Restart', c.restart.onclick);
  if (c.copy) actions += dib(V3_SVG_COPY, 'Copy to queue', c.copy.onclick);
  for (const e of (c.extra || [])) {
    if (e.kind === 'show') actions += `<button type="button" class="dock-btn" data-tip="Show" aria-label="Show" onclick="${e.onclick}">👁</button>`;
    else {
      const svg = e.kind === 'debrief' ? V3_SVG_DOC : e.kind === 'dup' ? V3_SVG_COPY
        : e.kind === 'play' ? V3_SVG_PLAY : e.kind === 'restart' ? V3_SVG_RESTART
        : e.kind === 'delete' ? V3_SVG_TRASH : V3_SVG_XMARK;
      actions += dib(svg, e.tip, e.onclick);
    }
  }
  const openHtml = c.open ? `<button class="btn-pill" onclick="${c.open.onclick}">Open</button>` : '';
  return `${openHtml}<div class="dock" role="toolbar" aria-label="Campaign actions">${dock}<div class="dock-actions">${actions}</div></div>`;
}

function fillVjCard(root, status) {
  if (!root || !status) return;
  const f = vjCardFields(status);
  const set = (name, text) => { const el = root.querySelector(`[data-f="${name}"]`); if (el) el.textContent = text; };
  root.classList.toggle('is-monitor', f.isMonitor);
  root.classList.add('is-detailed');
  root.classList.remove('is-empty', 'is-preflight');

  set('activeName', f.name);
  set('activeEyebrow', f.eyebrow);
  set('activePct', String(f.pct));
  set('activeSent', String(f.done));
  set('activeTotal', String(f.total));
  set('activeAccounts', String(f.accountsCount));
  set('activeAccepted', f.accepted);
  set('sendingLbl', f.sendingLbl);
  const bar = root.querySelector('[data-f="activeBar"]'); if (bar) bar.style.width = `${f.pct}%`;
  const glyph = root.querySelector('[data-f="activeGlyph"]'); if (glyph && typeof _cloudBadge === 'function') glyph.textContent = _cloudBadge(status.mode);

  try {
    const la = buildLiveActivity(status);
    const live = root.querySelector('[data-f="active-live"]');
    if (live) {
      live.hidden = (la.state === 'idle');
      live.classList.toggle('is-checking', la.state === 'checking');
      live.classList.toggle('is-waking', la.state === 'waking');
      live.classList.toggle('is-paused', la.state === 'paused');
      set('activeLiveIco', la.icon); set('activeLiveL1', la.l1); set('activeLiveL2', la.l2);
    }
    const staged = renderLiveStage(root, status);
    if (live && staged) live.hidden = true;
    // A finished FG run explains itself in the same slot the live line uses —
    // it's the one place the operator already looks for "what is going on".
    const note = _fgFinishedNote(status);
    if (live && note) {
      live.hidden = false;
      live.classList.remove('is-checking', 'is-waking', 'is-paused');
      live.classList.add('is-outcome');
      set('activeLiveIco', note.icon); set('activeLiveL1', note.l1); set('activeLiveL2', note.l2);
    } else if (live) live.classList.remove('is-outcome');
  } catch (_) { /* live line best-effort */ }

  if (f.isMonitor) _fillVjMonitorHero(root, status);

  const logEl = root.querySelector('[data-f="active-log"]');
  if (logEl) {
    const lines = Array.isArray(status.logs) ? status.logs.slice(-15) : [];
    logEl.innerHTML = lines.map((l) => v3RenderLogLine(l)).join('');
    const head = root.querySelector('.vj-log-head .vj-details-head');
    if (head) head.textContent = `Live log · last ${lines.length} events`;
  }

  // The cloned log-action buttons carry singleton-targeting onclicks
  // (openRunningSheet / dashCopyLog read the local cockpit campaign). Rewire
  // "Copy all" to copy THIS card's log; hide "Open sheet" + the wizard-only
  // "Show more" so a strip can't act on the wrong campaign.
  const logActs = root.querySelector('.vj-log-acts');
  if (logActs) {
    logActs.querySelectorAll('.vj-log-act').forEach((b) => {
      const txt = (b.textContent || '').toLowerCase();
      if (b.getAttribute('data-f') === 'wiz-log-more' || txt.includes('open sheet')) { b.style.display = 'none'; return; }
      if (txt.includes('copy')) b.setAttribute('onclick', 'copyVjCardLog(this)');
    });
  }

  // Controls (rewired per-campaign; the cloned onclicks would hit the singleton).
  const c = vjCardControlsFor(status);
  const controls = root.querySelector('.vj-controls');
  if (controls) controls.innerHTML = _vjControlsHtml(c, status);
  const bulkWrap = root.querySelector('.vj-bulk');
  if (bulkWrap) {
    if (c.bulk) {
      bulkWrap.style.display = '';
      const bb = root.querySelector('[data-f="vj-bulk-btn"]'); if (bb) bb.setAttribute('onclick', c.bulk.onclick);
      const lbl = root.querySelector('[data-f="vj-bulk-btn-label"]'); if (lbl) lbl.textContent = c.bulk.label || 'Run check now';
    } else {
      bulkWrap.style.display = 'none';
    }
  }
}

// Copy an expanded strip card's OWN log (not the singleton's __activeFullLogs).
window.copyVjCardLog = function (btn) {
  const card = btn && btn.closest('.sn-vjcard');
  const log = card && card.querySelector('[data-f="active-log"]');
  const text = log ? [...log.children].map((c) => c.textContent.trim()).join('\n') : '';
  try { navigator.clipboard.writeText(text); } catch (_) { /* clipboard best-effort */ }
  const orig = btn.textContent; btn.textContent = 'Copied'; setTimeout(() => { btn.textContent = orig; }, 1200);
};

// Board-strip monitoring countdowns, ticked once a second.
//
// This used to be an interval started from _fillVjCards and stopped by itself
// whenever a tick found no EXPANDED monitor card — which deadlocked. The two
// halves disagreed about when the ticker should exist: _fillVjCards started it
// for any monitoring campaign (collapsed included), the tick required an
// expanded one and destroyed the interval when it found none. So with every
// strip collapsed the ticker killed itself one second in; expanding a strip is
// a local class toggle that doesn't re-render the board; and the board's
// anti-jank skip (`final === _lastBoardHtml → return`) meant _fillVjCards —
// the only thing that could restart it — never ran again. Countdowns froze
// until something else changed the board HTML. The campaign-tab card never had
// this because its ticker is a plain module-level interval.
//
// So: one module-level interval that no-ops when there is nothing to tick,
// never stops, and is never coupled to the render path.
//
// The countdown source is _snItemsById (assigned BEFORE the anti-jank early
// return, so it's fresh even on a skipped render) with the card's dataset as
// the fallback — otherwise a skipped render would leave a stale nextcheck
// ticking past zero into a permanent "now".
function _tickVjCards() {
  // `.sn-board` (class), NOT `#sn-board` (id). There are TWO boards: the
  // dashboard renders into #campaigns-board, the Sales Nav Scraper page into
  // #sn-board — and both carry class="sn-board". The id selector meant this
  // never matched a single dashboard card, so the strip countdown never ticked
  // there at all: what looked like a 5-second tick was the board poll
  // re-rendering the strip, and the freeze was that redraw being skipped.
  const cards = document.querySelectorAll('.sn-board .sn-strip:not(.sn-collapsed) .sn-vjcard.is-monitor');
  if (!cards.length) return; // nothing on screen to tick — NOT a reason to stop
  cards.forEach((card) => {
    const cid = card.closest('.sn-strip')?.dataset.cid;
    const it = cid ? _snItemsById.get(cid) : null;
    let status = null;
    try { status = it ? statusFromItem(it) : null; } catch (_) { status = null; }
    const heroB = card.querySelector('.vj-mon-hero');
    const busy = !!(heroB && (heroB.classList.contains('is-checking') || heroB.classList.contains('is-waking')));
    const text = monitorTickText({
      nextCheckAt: (status && status.nextCheckAt) || card.dataset.nextcheck || null,
      busy,
      fmtCountdown: v3FmtCountdown,
    });
    const el = card.querySelector('[data-f="monCount"]');
    if (el && text !== null) el.textContent = text;
    const fd = (status && status.followUp && status.followUp.dueAt) || card.dataset.fudue;
    if (fd) _setFuDual(card.querySelector('[data-f="fuCount"]'), Number(fd));
  });
}
setInterval(_tickVjCards, 1000);

// Fill every strip's cloned card from its board item. Called after each board
// render. We fill COLLAPSED cards too (cheap text sets on a display:none node):
// that way a strip's clone already holds ITS OWN campaign data before it's ever
// revealed, so expanding a VM strip shows the VM card instantly instead of
// flashing the local #active-card template the skeleton was cloned from.
function _fillVjCards(board) {
  const cards = board.querySelectorAll('.sn-strip .sn-vjcard');
  cards.forEach((card) => {
    const cid = card.closest('.sn-strip')?.dataset.cid;
    const it = cid ? _snItemsById.get(cid) : null;
    if (!it) return;
    const status = statusFromItem(it);
    card.dataset.nextcheck = status.nextCheckAt || '';
    card.dataset.fudue = (status.followUp && status.followUp.dueAt) || '';
    try { fillVjCard(card, status); } catch (_) { /* per-card best-effort */ }
  });
  // No ticker wiring here on purpose — _tickVjCards runs on its own module-level
  // interval. Starting/stopping it from the render path is exactly what froze
  // every board countdown once the anti-jank skip stopped calling this.
}

function renderUnifiedStrip(it) {
  const cloud = it.where === 'cloud';
  const running = it.bucket === 'running';
  const queued = it.bucket === 'queued';
  const done = it.bucket === 'done';
  const monitoring = cloud && it.monitoring;   // Task 3 — post-send acceptance-watch (still ACTIVE)
  const scheduled = queued && !!it.scheduledAt;
  const whenTxt = scheduled && typeof v3FormatScheduledAt === 'function' ? v3FormatScheduledAt(it.scheduledAt) : '';
  const collapsed = queued ? true : !_snExpanded.has(it.id);
  const badge = _cloudBadge(it.mode);
  const acctWord = it.accounts === 1 ? 'account' : 'accounts';

  // Rail (sketch A · muted archive): colour = live + errors only. running cloud →
  // green (.run); running local → pink (.local.run); monitoring → blue
  // (.monitoring, wins over .run); scheduled → gold (.sched); done → ink
  // (.done rail); ERROR → red (.stopped); CANCELLED / operator-Stopped → faded
  // gray (.cancelled, NOT red). Only a genuine LinkedIn/send error is red now.
  // Terminal states keep .done too for the slim collapsed layout; the colour
  // classes override its rail via :not(.stopped):not(.cancelled).
  const errored = it.bad && it.badLabel === 'Error';
  const cancelled = it.bad && !errored;            // 'Cancelled' / 'Stopped' — benign
  const stateCls = [
    it.where === 'local' ? 'local' : '',
    running && !monitoring ? 'run' : '',
    monitoring ? 'monitoring' : '',
    queued ? 'queued' : '',
    scheduled ? 'sched' : '',
    done ? 'done' : '',
    collapsed ? 'sn-collapsed' : '',
    errored ? 'stopped' : '',
    cancelled ? 'cancelled' : '',
  ].filter(Boolean).join(' ');

  const wherePill = cloud
    ? '<span class="sn-where cloud">☁︎ VM</span>'
    : '<span class="sn-where local">💻 This machine</span>';
  const whenPill = scheduled ? '<span class="sn-when-pill">⏰ Scheduled</span>' : '';
  const dot = errored ? '<span class="dot red"></span>'
    : it.bad ? '<span class="dot cancel"></span>'   // cancelled / stopped — gray, not red
    : monitoring ? '<span class="dot mon"></span>'
    : running ? (cloud ? '<span class="dot run"></span>' : '<span class="dot runlocal"></span>')
    : scheduled ? '<span class="dot gold"></span>'
    : queued ? '<span class="dot q"></span>'
    : '<span class="dot done"></span>';            // done — ink (black light / white dark)
  // #17: a cloud campaign sits `queued` from dispatch until a worker picks it up
  // (~2–3 min cold start). Show "warming up" for that window so operators aren't
  // staring at a dead-looking "Queued". After 3 min, fall back to plain "Queued"
  // (a genuinely-stuck queue shouldn't claim it's warming up forever). Reuses the
  // existing queued dot — no new colour (mono design system).
  const warming = cloud && queued && it.createdAt
    && (Date.now() - new Date(it.createdAt).getTime()) < 3 * 60 * 1000;
  let statusTxt = scheduled ? whenTxt
    : warming ? '⏳ Warming up (~2 min)'
    : queued ? 'Queued'
    : monitoring ? 'Monitoring'
    : running ? (it.paused ? 'Paused' : (it.isFG ? 'Inviting' : 'Running'))
    : it.bad ? (it.badLabel || 'Stopped')
    : 'Done';
  // Phase 0 primary-handshake lock (Task 3.4): the engine pauses a cloud
  // campaign in 'awaiting_primary_accept' while this Mac accepts the
  // primary's connection requests as the local primary. Dormant until the
  // engine ships `state` + `senders` on the campaign detail — until then
  // both stay undefined and this never fires (graceful degradation).
  const hsAwaiting = cloud && it.state === 'awaiting_primary_accept' && Array.isArray(it.senders);
  if (hsAwaiting) statusTxt = '🔒 Primary handshake';
  // A launch still running on THIS Mac (handshake → dispatch). Reuses the same
  // handshake panel, but says where it actually is — "Primary handshake" would be
  // a lie once the handshake is done and we're reading the sheet.
  if (it.launching) statusTxt = it.launchPhase === 'dispatching' ? '☁︎ Handing over to the VM…' : '🤝 Connecting to primary';

  // Primary needs-login (Task 9) — only fires when the engine's
  // c.primarySession.state is 'needs_login' (see /js/primary-session-render.mjs).
  // Repeated on every affected strip BY DESIGN.
  const psBadge = primarySessionBadge(it.primarySession);
  const psBadgeHtml = psBadge.show ? `<div class="${psBadge.cls}">${escHtml(psBadge.text)}</div>` : '';

  const flow = it.isFG
    ? `<b>${it.total || '—'} invites</b> → <b>${it.accounts || 1} account${(it.accounts || 1) === 1 ? '' : 's'}</b> → page · Follower Growth`
    : `<b>${it.total || 0} leads</b> → <b>${it.accounts || 0} ${acctWord}</b> → feeds <b>${escHtml(it.name || '')}</b> · ${escHtml(_cloudModeLabel(it.mode))}`;
  const whereNote = cloud ? 'runs in the cloud — keeps going if you close the app'
    : 'runs on this machine — closing the app stops it';
  const progLine = running
    ? `<div class="sn-progtxt"><b>${it.sent || 0}</b> of ${it.total || 0} ${it.isFG ? 'invites' : 'sent'} · ${whereNote}</div>`
    : '';

  const expandBtn = queued ? ''
    : `<button class="sn-collapse sn-expand" title="Expand / collapse"><svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6l4 4 4-4"/></svg></button>`;
  let logHtml;
  if (cloud && it.logs && it.logs.length) {
    // Real per-lead rows from the engine (GET /api/campaign/:id/leads).
    logHtml = `<div class="sn-logbox">${it.logs.slice(-8).map((l) => escHtml(l)).join('<br>')}</div>`;
  } else if (cloud) {
    const note = it.sent ? 'Live per-lead log — expand to watch it fill.' : 'Per-lead log appears here as the cloud engine sends.';
    logHtml = `<div class="sn-logbox">${note} Status: <span class="ok">${it.sent || 0}/${it.total || 0} ${it.isFG ? 'invites' : 'sent'}</span>.</div>`;
  } else if (it.logs && it.logs.length) {
    logHtml = `<div class="sn-logbox">${it.logs.slice(-8).map((l) => escHtml(l)).join('<br>')}</div>`;
  } else if (done && it.histIdx != null) {
    // Done strip from history — the live log is gone from memory; pull the
    // persisted campaign.log lines lazily (cache-first; fetch fills the box
    // in place, next board render inlines from cache).
    const cached = _histLogCache.get(it.histIdx);
    logHtml = cached != null
      ? `<div class="sn-logbox">${cached}</div>`
      : `<div class="sn-logbox" data-histlog="${it.histIdx}">Loading log…</div>`;
  } else {
    logHtml = `<div class="sn-logbox">Live log appears here while this local campaign runs.</div>`;
  }
  const _copyBtn = `<button type="button" class="sn-logcopy" title="Copy log" aria-label="Copy log" onclick="event.stopPropagation(); copyStripLog(this)"><svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"></rect><path d="M5 15V5a2 2 0 0 1 2-2h10"></path></svg><span class="sn-logcopy-lbl">Copy</span></button>`;
  const switchBlock = queued ? '' : `<div class="sn-switch"><div class="sn-pane on">${_copyBtn}${logHtml}</div></div>`;

  // Task 3 — cloud monitoring card (parity with local renderMonitoringCard):
  // ● MONITORING / ENDING SOON badge + live "Next check · ends in" countdown
  // from the engine's next_check_at / monitoring_until. Stop monitoring works
  // now (engine stop endpoint); Check-now + auto-toggle arrive with the engine
  // endpoints (Part B), so no dead buttons here yet.
  let monBlock = '';
  if (monitoring) {
    const now = Date.now();
    const next = it.nextCheckAt ? new Date(it.nextCheckAt) : null;
    const until = it.monitoringUntil ? new Date(it.monitoringUntil) : null;
    const remMs = until ? until.getTime() - now : 0;
    const endingSoon = remMs > 0 && remMs <= 24 * 60 * 60 * 1000;
    const hhmm = (dd) => dd ? `${String(dd.getHours()).padStart(2, '0')}:${String(dd.getMinutes()).padStart(2, '0')}` : '—';
    const fmtRem = (ms) => {
      if (ms <= 0) return '0m';
      const d1 = Math.floor(ms / 86400000), h1 = Math.floor((ms % 86400000) / 3600000), m1 = Math.floor((ms % 3600000) / 60000);
      return d1 > 0 ? `${d1}d ${h1}h` : h1 > 0 ? `${h1}h ${m1}m` : `${m1}m`;
    };
    const line = endingSoon
      ? `Window ends in <b>${fmtRem(remMs)}</b> — then still-pending leads stay <i>Connection Request Sent</i>`
      : `Next check <b>${escHtml(hhmm(next))}</b> · ends in <b>${escHtml(fmtRem(remMs))}</b> · every <b>${it.checkIntervalMinutes || 60}m</b>`;
    monBlock = `<div class="sn-mon${endingSoon ? ' ending' : ''}">`
      + `<span class="sn-mon-badge">${endingSoon ? '● ENDING SOON' : '● MONITORING'}</span>`
      + `<span class="sn-mon-line">${line}</span>`
      + `<span class="sn-mon-ctl">`
      + `<button type="button" class="mini sn-mon-btn" onclick="event.stopPropagation();promptCloudCheckScope('${escHtml(it.id)}',this)" title="Run an acceptance check now">Check now</button>`
      + `<label class="sn-mon-auto" title="When off, the VM won't run automatic checks — use ⚡ Check now."><input type="checkbox" ${it.autoChecksEnabled ? 'checked' : ''} onclick="event.stopPropagation()" onchange="setCloudAutoChecks('${escHtml(it.id)}',this.checked,this)"> Auto</label>`
      + `</span></div>`;
  }

  // Handshake lock panel — replaces the log switchBlock while
  // state==='awaiting_primary_accept'. Two row states only (done/waiting):
  // the engine's senders[] carry only accepted:true|false, no in-progress
  // signal, so there is no "Accepting…" spinner state to render. Targeted
  // accepts only — no accept-all line (would be false; see Task 3.3 reconciler).
  let handshakeBlock = '';
  if (hsAwaiting) {
    const senders = it.senders;
    const accepted = senders.filter((s) => s && s.accepted).length;
    const total = senders.length;
    const pct = total ? Math.round((accepted / total) * 100) : 0;
    const pname = escHtml((it.primary && it.primary.name) || 'the primary');
    const rows = senders.map((s) => {
      const done = !!(s && s.accepted);
      return `<div class="hs-row ${done ? 'done' : ''}">`
        + `<span class="ic">${done ? '<span class="chk">✓</span>' : '<span class="dotwait"></span>'}</span>`
        + `<span class="who">${escHtml((s && s.name) || 'account')}</span>`
        + `<span class="st">${done ? 'Accepted' : 'Waiting'}</span></div>`;
    }).join('');
    const _launching = !!it.launching;
    const _dispatching = _launching && it.launchPhase === 'dispatching';
    handshakeBlock = `
      <div class="hs-panel">
        <div class="hs-eyebrow"><span class="lk">🔒</span> Phase 0 · Primary handshake${_launching ? '' : ' — locked'} <span class="cnt"><span class="hs-count">${accepted}</span> / ${total}</span></div>
        <div class="hs-head">${_dispatching
          ? 'Handshake done — reading your lead sheet and handing the campaign to the VM'
          : _launching
            ? 'Sending connection requests to the primary account, then accepting them here'
            : "Your Mac is accepting the primary's invitations"}</div>
        <div class="hs-bar"><i style="width:${pct}%"></i></div>
        <div class="hs-expl">${_launching
          ? `Your Mac opens each sender in turn, sends <b>${pname}</b> a connection request, then accepts them in your local browser. This is the only step that runs on this machine — the campaign then moves entirely to the VM. It takes a couple of minutes.`
          : `Each account sent <b>${pname}</b> a connection request from the VM. Accepting them in <b>your local browser</b> is the only step that runs on this machine — then the campaign continues entirely on the VM.`}</div>
        <div class="hs-list">${rows}</div>
        <div class="hs-keep">◈ Keep this app open — it's the only local step this campaign needs.</div>
      </div>`;
  }

  // Controls — icon buttons (dock-btn: tooltip via data-tip, .danger = red).
  // Running LOCAL: Pause/Resume + Stop (local supports resume). Running CLOUD:
  // Stop only — the engine has no resume, so a cloud "pause" would strand the
  // campaign. Open (②/③) stays a labeled primary pill → Campaign view. Done:
  // Duplicate + Debrief + ✕ dismiss, all as icons.
  const _dib = (svg, tip, onclick, cls = '') =>
    `<button type="button" class="dock-btn ${cls}" data-tip="${tip}" aria-label="${tip}" onclick="${onclick}">${svg}</button>`;
  const _openPill = `<button class="mini solid" onclick="viewRunningCampaign()">Open</button>`;
  // Cloud campaigns have no local cockpit to restore, so their Open must NOT
  // call viewRunningCampaign() (which drops the operator in the blank New-
  // Campaign wizard). openCloudLive() focuses the campaign's live strip instead.
  const _cloudOpen = `<button class="mini solid" onclick="openCloudLive('${escHtml(it.id)}')">Open</button>`;
  let foot = '';
  if (it.launching) {
    // No controls: there is nothing on the VM yet to stop, pause, watch or open,
    // and every cloud control here would be called with a placeholder id. The
    // handshake modal owns Cancel / Dispatch anyway while it's up.
    foot = '';
  } else if (running && it.where === 'local') {
    foot = (it.paused
        ? _dib(V3_SVG_PLAY, 'Resume', 'window.dashPauseActive && window.dashPauseActive()')
        : _dib(V3_SVG_PAUSE, 'Pause', 'window.dashPauseActive && window.dashPauseActive()'))
      + _dib(V3_SVG_STOP, 'Stop', 'window.dashStopActive && window.dashStopActive()', 'danger')
      + _openPill;
  } else if (running && cloud) {
    // "Show campaign happening" — watch the VM's browser live. Shown in BOTH
    // sending AND monitoring: cloud browsers are short-lived (a few seconds per
    // send/check), so the viewer waits and auto-streams the moment one opens.
    // The green LIVE dot lights when the engine reports an active browser this
    // poll (it.live) — a hint there's something to watch right now.
    const _vLabel = String(it.name || it.id).replace(/['"\\<>]/g, '');
    const _showBtn = `<button class="mini${it.live ? ' live-on' : ''}" onclick="openCloudCampaignView('${escHtml(it.id)}','${escHtml(_vLabel)}')" title="Watch the campaign's browser live">${it.live ? '<span class="live-dot"></span>' : ''}👁 Show</button>`;
    // v2.160.46: OPEN on an active campaign → read-only wizard (its config,
    // locked while it runs) instead of the live sheet. "👁 Show" remains the way
    // to watch the VM browser live.
    const _openRO = `<button class="mini solid" onclick="openRunningCampaignReadOnly('${escHtml(it.id)}')">Open</button>`;
    if (monitoring) {
      foot = _showBtn + _dib(V3_SVG_STOP, 'Stop monitoring', `stopCloudCampaignUI('${escHtml(it.id)}')`, 'danger') + _openRO;
    } else {
      // Pause/Resume — 1:1 with the local running cluster (engine resume flips
      // status paused→running; pause halts sending after the current lead).
      const _pauseBtn = it.paused
        ? _dib(V3_SVG_PLAY, 'Resume', `pauseCloudCampaignUI('${escHtml(it.id)}', true)`)
        : _dib(V3_SVG_PAUSE, 'Pause', `pauseCloudCampaignUI('${escHtml(it.id)}', false)`);
      foot = _showBtn + _pauseBtn + _dib(V3_SVG_STOP, 'Stop', `stopCloudCampaignUI('${escHtml(it.id)}')`, 'danger') + _openRO;
    }
  } else if (queued) {
    if (cloud) {
      // v2.160.46: a cloud "queued"/warming-up campaign has already been
      // dispatched to the engine, so OPEN behaves like a running one — the
      // read-only wizard (its config, locked), NOT the Google Sheet.
      // A SCHEDULED one hasn't started, so the same engine stop reads as "Cancel"
      // (it flips the campaign to cancelled; the due start_campaign task then
      // finds a non-'scheduled' status and declines to start it).
      foot = `<button class="mini" onclick="stopCloudCampaignUI('${escHtml(it.id)}')">${scheduled ? 'Cancel' : 'Stop'}</button><button class="mini solid" onclick="openRunningCampaignReadOnly('${escHtml(it.id)}')">Open</button>`;
    } else if (scheduled) {
      // Local scheduled — Reschedule (edit) / Cancel (remove) / Open (edit).
      foot = `<button class="mini" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Reschedule</button>`
        + `<button class="mini" onclick="window.cancelQueuedCampaign && window.cancelQueuedCampaign('${escHtml(it.rawId)}')">Cancel</button>`
        + `<button class="mini solid" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Open</button>`;
    } else {
      foot = `<button class="mini" onclick="window.cancelQueuedCampaign && window.cancelQueuedCampaign('${escHtml(it.rawId)}')">Cancel</button>`
        + `<button class="mini solid" onclick="window.editQueuedCampaign && window.editQueuedCampaign('${escHtml(it.rawId)}')">Open</button>`;
    }
  } else { // done — Duplicate + Debrief + 🗑 Delete (icons), Open pill.
    const dismiss = _dib(V3_SVG_TRASH || V3_SVG_XMARK, 'Delete', `deleteBoardCampaign('${escHtml(it.id)}', this)`, 'danger');
    const dup = _dib(V3_SVG_COPY, 'Duplicate', `duplicateCampaign('${escHtml(it.id)}')`);
    // Debrief — local done strips only (the snapshot lives on the history entry).
    const debriefBtn = (!cloud && it.hist)
      ? _dib(V3_SVG_DOC, 'Debrief', `window.openDebrief('${escHtml(it.id)}')`)
      : '';
    // Restart — only for a STOPPED/CANCELLED/ERRORED campaign (it.bad), never a
    // cleanly-completed one. ▶ Continue where it left off · ⟲ Restart from the
    // beginning. Both skip already-done rows/leads (no double-outreach).
    const restartBtns = it.bad
      ? _dib(V3_SVG_PLAY, 'Continue where it left off', cloud ? `restartCloudCampaignUI('${escHtml(it.id)}', false)` : `restartLocalFromItem('${escHtml(it.id)}', false)`)
        + _dib(V3_SVG_RESTART, 'Restart from the beginning', cloud ? `restartCloudCampaignUI('${escHtml(it.id)}', true)` : `restartLocalFromItem('${escHtml(it.id)}', true)`)
      : '';
    // OPEN routing for a finished strip: STOPPED/cancelled cloud → prefilled
    // editable setup wizard (edit & re-launch); cleanly-done cloud → live view;
    // local → its cockpit. Mirrors vjcard.mjs's card-#2 routing.
    const _doneOpen = cloud
      ? (it.bad
        ? `<button class="mini solid" onclick="openCampaignForEdit('${escHtml(it.id)}')">Open</button>`
        : _cloudOpen)
      : _openPill;
    // ⚡ Check now on a FINISHED/STOPPED cloud connect_and_* strip — late
    // acceptances still need a sweep + intro/DM backlog flush after the campaign
    // was stopped overall. One-shot on the engine: no re-arm, no resumed sending.
    const _cloudCheck = (cloud && (it.mode === 'connect_and_introduce' || it.mode === 'connect_and_message'))
      ? `<button type="button" class="mini" onclick="event.stopPropagation();promptCloudCheckScope('${escHtml(it.id)}',this)" title="Run an acceptance check now">Check now</button>`
      : '';
    foot = _cloudCheck + restartBtns + dismiss + dup + debriefBtn + _doneOpen;
  }

  // Expanded (non-queued) strips render card #2 (.sn-vjcard) instead of the
  // compact body. The compact body is wrapped in .sn-compact so CSS can swap the
  // two by collapsed state; collapsed strips are byte-for-byte as before.
  // No card #2 clone for a launch: it has no campaign status to fill, and
  // _fillVjCards would paint the generic "running" hero over the handshake panel.
  const richCard = (queued || it.launching) ? '' : vjCardSkeleton(it.id);
  return `
  <div class="sn-strip ${stateCls}" data-cid="${escHtml(it.id)}">
    ${expandBtn}
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Campaign · ${escHtml(badge)}</span>${it.mine ? '<span class="sn-you">You</span>' : (it.owner ? `<span class="sn-owner">· ${escHtml(it.owner)}</span>` : '')}${wherePill}${whenPill}
      <span class="sn-status">${dot} ${escHtml(statusTxt)}</span></div>
    <div class="sn-name">${escHtml(it.name || '(unnamed)')}</div>
    <div class="sn-flow">${flow}</div>
    ${psBadgeHtml}
    ${progLine}
    ${monBlock}
    ${hsAwaiting ? handshakeBlock : switchBlock}
    ${_buildSkippedSection(it)}
    <div class="sn-foot"><div class="right">${foot}${_stripOverflow()}</div></div>
    </div>
    ${richCard}
  </div>`;
}

// Draft strip — a saved-but-not-launched wizard config, surfaced on the board
// inside "Your campaigns" under the DRAFTS rail (railhead CSS uppercases the
// label). Slim collapsed-style strip: Open → wizard (editDraft), 🗑 → delete.
function renderDraftStrip(d) {
  const name = d.name || '(unnamed draft)';
  const created = (typeof dashboardFormatDate === 'function' && dashboardFormatDate(d.createdAt)) || '';
  return `
  <div class="sn-strip done sn-collapsed draft" data-cid="draft:${escHtml(d.id)}">
    <div class="sn-compact">
    <div class="sn-top"><span class="sn-type">Campaign · Draft</span><span class="sn-you">You</span>
      <span class="sn-status"><span class="dot q"></span> Draft</span></div>
    <div class="sn-name">${escHtml(name)}</div>
    <div class="sn-flow">Saved as a draft${created ? ` · created <b>${escHtml(created)}</b>` : ''} · not launched yet</div>
    <div class="sn-foot"><div class="right">`
    + `<button type="button" class="dock-btn danger" data-tip="Delete draft" aria-label="Delete draft" onclick="deleteDraftStrip('${escHtml(d.id)}', this)">${V3_SVG_TRASH || V3_SVG_XMARK}</button>`
    + `<button class="mini solid" onclick="editDraft('${escHtml(d.id)}')">Open</button>`
    + `</div></div>
    </div>
  </div>`;
}

// Delete a draft from its board strip — optimistic strip removal (the 4s board
// poll would otherwise show the stale row), then the same API + wizard-reference
// cleanup as deleteDraft (Drafts & Stops tab), then re-render both surfaces.
async function deleteDraftStrip(id, btn) {
  if (!id) return;
  if (!confirm('Delete this draft?')) return;
  const strip = btn && btn.closest('.sn-strip');
  if (strip) strip.remove();
  try {
    await fetch('/api/drafts/' + encodeURIComponent(id), { method: 'DELETE' });
  } catch (err) { alert('Failed: ' + err.message); return; }
  try { if (getActiveDraftId() === id) clearActiveDraft(); } catch { /* not the active draft */ }
  try { if (typeof refreshDashboardDrafts === 'function') refreshDashboardDrafts(); } catch { /* */ }
  try { renderCampaignsBoard(); } catch { /* next poll repaints */ }
}
window.deleteDraftStrip = deleteDraftStrip;

// The ⋯ overflow menu on each strip (currently: Duplicate → pre-filled draft).
// The ⋯ overflow menu used to hold a single "Duplicate" item; that action now
// has its own visible icon in the strip footer, so the menu is redundant —
// render nothing. (The delegated duplicate handler below stays inert with no
// .ovf elements to match; harmless.)
function _stripOverflow() {
  return '';
}

// ── Campaign debrief overlay ───────────────────────────────────────────────
// Opens from the Debrief pill on local done strips. Data = the history entry
// (incl. the persisted `debrief` snapshot taken at campaign end). Only fields
// that exist on the entry are rendered — no invented stats.

const _DB_PARK_LABELS = { // mirrors prettyParkReason in src/campaign.js
  session_expired:   'logged out / session expired',
  weekly_limit_429:  'weekly invite limit reached',
  consecutive_skips: 'too many consecutive skips / failures',
  challenge:         'LinkedIn checkpoint — needs a human',
  throttle_paused:   'throttled (429) — paused',
};
const _DB_END_LABELS = {
  completed: 'Completed', stopped: 'Stopped by operator', errored: 'Stopped by error',
};
function _dbParkLabel(r) { return _DB_PARK_LABELS[r] || r || 'parked'; }
function _dbDuration(sec) {
  const s = Number(sec) || 0;
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60), h = Math.floor(m / 60);
  return h ? `${h}h ${m % 60}m` : `${m}m ${s % 60}s`;
}
function _dbDate(iso) {
  const d = new Date(iso || 0);
  return Number.isFinite(d.getTime()) && d.getTime() > 0
    ? d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) : '';
}
let _dbCopyText = '';

window.openDebrief = async function openDebrief(stripId) {
  const it = _boardItemsById.get(stripId);
  const h = it && it.hist;
  const scrim = document.getElementById('db-scrim');
  if (!h || !scrim) return;
  const db = h.debrief || null;
  const tpl = (h.settings && h.settings.templates) || {};

  document.getElementById('db-title').textContent = h.name || '(unnamed)';
  const endLbl = _DB_END_LABELS[h.endReason] || h.endReason || '';
  document.getElementById('db-sub').innerHTML =
    `Ran <b>${escHtml(_dbDate(h.date) || '—')}</b> · mode <b>${escHtml(_cloudModeLabel(h.mode))}</b>`
    + ` · <b>${(h.profiles || []).length} account${(h.profiles || []).length === 1 ? '' : 's'}</b>`
    + ` · duration <b>${escHtml(_dbDuration(h.duration))}</b>`
    + (endLbl ? ` · <b>${escHtml(endLbl)}</b>` : '');

  let body = '';

  // Totals — sent / processed / errors / skipped (all real history fields).
  const skipTotal = db ? db.skipTotal : null;
  body += `<div class="db-sec"><div class="db-sec-head">Totals</div><div class="db-funnel">`
    + `<div class="funnel-stage"><div class="st-lbl">Sent</div><div class="st-num">${h.successCount || 0}</div><div class="st-drop">of <b>${h.totalProcessed || 0}</b> processed</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Skipped</div><div class="st-num">${skipTotal != null ? skipTotal : '—'}</div><div class="st-drop">${skipTotal != null ? 'left untouched on the sheet' : 'no snapshot for this run'}</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Errors</div><div class="st-num">${h.errorCount || 0}</div><div class="st-drop">during the run</div></div>`
    + `<div class="funnel-stage"><div class="st-lbl">Duration</div><div class="st-num">${escHtml(_dbDuration(h.duration))}</div><div class="st-drop">${escHtml(endLbl || '')}</div></div>`
    + `</div></div>`;

  // Per-account — Sent + end reason only. We do NOT track per-lead
  // accepted/replied for a normal run, so nothing else is shown here.
  if (db && Array.isArray(db.perAccount) && db.perAccount.length) {
    const rows = db.perAccount.map((a) =>
      `<tr><td class="db-acc">${escHtml(a.name || a.profileId)}</td>`
      + `<td class="db-num">${a.sent}</td>`
      + `<td class="db-reason">${escHtml(a.endReason || '—')}</td></tr>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Per account</div>`
      + `<table class="db-table"><thead><tr><th>Account</th><th>Sent</th><th>Ended</th></tr></thead>`
      + `<tbody>${rows}</tbody></table></div>`;
  }

  // vs your last 5 — factual SENT counts only, no accept/reply comparison.
  let _dbPriorsLine = '';
  try {
    const raw = await (await fetch('/api/history')).json();
    const hist = Array.isArray(raw) ? raw : (raw.history || []);
    const currentHistIdx = it && Number.isFinite(it.histIdx) ? it.histIdx : -1;
    const others = hist
      .map((p, i) => ({ p, i }))
      .filter(({ i }) => i !== currentHistIdx)
      .sort((a, b) => new Date(b.p.date).getTime() - new Date(a.p.date).getTime())
      .slice(0, 5)
      .map(({ p }) => p);
    if (others.length) {
      const avg = Math.round(others.reduce((s, e) => s + (e.successCount || 0), 0) / others.length);
      const mine = h.successCount || 0;
      const delta = mine - avg;
      const arrow = delta > 0 ? '▲' : (delta < 0 ? '▼' : '·');
      body += `<div class="db-sec"><div class="db-sec-head">vs your last ${others.length}</div>`
        + `<div class="db-compare">This run sent <b>${mine}</b> — your last ${others.length} averaged <b>${avg}</b> `
        + `<span class="db-delta">${arrow} ${Math.abs(delta)}</span></div></div>`;
      _dbPriorsLine = `vs last ${others.length}: sent ${mine} (avg ${avg}, ${arrow}${Math.abs(delta)})`;
    }
  } catch (_) { /* history fetch best-effort — comparison section just omitted */ }

  // Why it ended — from the persisted endNotice.
  if (db && db.endNotice && (db.endNotice.reason || db.endNotice.detail)) {
    body += `<div class="db-sec"><div class="db-sec-head">Why it ended</div>`
      + `<div class="db-skipped"><b>${escHtml(db.endNotice.reason || '')}</b>`
      + (db.endNotice.detail ? ` <span class="why">— ${escHtml(db.endNotice.detail)}</span>` : '')
      + `</div></div>`;
  }

  // Skipped leads — reason tallies + expandable capped row list.
  if (db && db.skipTotal > 0) {
    const reasons = Object.entries(db.skipReasons || {})
      .sort((a, b) => b[1] - a[1])
      .map(([r, n]) => `${n} ${_skipReasonLabel(r).toLowerCase()}`).join(' · ');
    const rows = (db.skips || []).map((s) =>
      `<tr><td>${s.rowNumber != null ? 'Row ' + s.rowNumber : ''}</td>`
      + `<td>${escHtml(s.leadName || '(no name)')}</td>`
      + `<td>${escHtml(_skipReasonLabel(s.reason))}</td>`
      + `<td class="dim">${escHtml(s.detail || '')}</td></tr>`).join('');
    const capNote = db.skipTotal > (db.skips || []).length
      ? `<div class="db-empty" style="margin-top:8px">Showing first ${(db.skips || []).length} of ${db.skipTotal}.</div>` : '';
    body += `<div class="db-sec"><div class="db-skipped"><b>${db.skipTotal} skipped</b>`
      + (reasons ? ` <span class="why">— ${escHtml(reasons)}</span>` : '')
      + ` · <a onclick="this.closest('.db-sec').querySelector('.db-skip-rows').classList.toggle('open')">view rows</a></div>`
      + `<div class="db-skip-rows"><table class="db-table"><thead><tr><th>Row</th><th>Lead</th><th>Reason</th><th>Detail</th></tr></thead><tbody>${rows}</tbody></table>${capNote}</div></div>`;
  } else if (db) {
    body += `<div class="db-sec"><div class="db-skipped"><b>0 skipped</b></div></div>`;
  }

  // Parked accounts.
  if (db && (db.parked || []).length) {
    const rows = db.parked.map((p) =>
      `<tr><td>${escHtml(p.pName || p.profileId || 'Account')}</td>`
      + `<td><span class="db-park${p.reason === 'weekly_limit_429' || p.reason === 'throttle_paused' ? ' gold' : ''}">${escHtml(_dbParkLabel(p.reason))}${p.parkedAt ? ' · ' + escHtml(_dbDate(p.parkedAt)) : ''}</span></td></tr>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Parked accounts</div>`
      + `<table class="db-table"><thead><tr><th>Account</th><th>Parked</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }

  // Errors — count + last samples from the snapshot.
  if (db && db.errors && db.errors.count > 0) {
    const lines = (db.errors.samples || []).map((e) => `<div class="e-msg">· ${escHtml(e.message)}</div>`).join('');
    body += `<div class="db-sec"><div class="db-sec-head">Errors · ${db.errors.count}</div><div class="db-errs">${lines || '<span class="db-empty">No samples recorded.</span>'}</div></div>`;
  }

  // Template used — real strings from the settings snapshot.
  const tplParts = [];
  if (tpl.connectionNote) tplParts.push(['Connection note', tpl.connectionNote]);
  if (tpl.followUpMessage) tplParts.push(['Follow-up message', tpl.followUpMessage]);
  if (tpl.primaryIntroBody) tplParts.push(['Intro DM body', tpl.primaryIntroBody]);
  if (tpl.inmailBody) tplParts.push(['InMail', (tpl.inmailSubject ? tpl.inmailSubject + '\n' : '') + tpl.inmailBody]);
  if (tpl.openProfileBody) tplParts.push(['Open-profile message', (tpl.openProfileSubject ? tpl.openProfileSubject + '\n' : '') + tpl.openProfileBody]);
  if (tplParts.length) {
    const first = tplParts[0][1].split('\n')[0];
    const full = tplParts.map(([k, v]) => `${k}: ${v}`).join('\n\n');
    body += `<div class="db-sec"><div class="db-sec-head">Template used · ${escHtml(tplParts[0][0].toLowerCase())}</div>`
      + `<div class="db-tpl" onclick="this.classList.toggle('open')">`
      + `<div class="tpl-first">${escHtml(first)}</div>`
      + `<div class="tpl-more">click to expand ▾</div>`
      + `<div class="tpl-full">${escHtml(full)}</div></div></div>`;
  }

  if (!db) {
    body += `<div class="db-sec"><div class="db-empty">No debrief snapshot was recorded for this run — snapshots are saved for campaigns finished on v2.135+.</div></div>`;
  }

  document.getElementById('db-body').innerHTML = body;

  // Plain-text summary for the Copy button.
  _dbCopyText = [
    `${h.name || '(unnamed)'} — debrief`,
    `Ran ${_dbDate(h.date)} · ${_cloudModeLabel(h.mode)} · ${(h.profiles || []).length} accounts · ${_dbDuration(h.duration)} · ${endLbl}`,
    `Sent ${h.successCount || 0} of ${h.totalProcessed || 0} processed · ${h.errorCount || 0} errors`
      + (db ? ` · ${db.skipTotal} skipped` : ''),
    db && db.endNotice ? `Ended: ${db.endNotice.reason}${db.endNotice.detail ? ' — ' + db.endNotice.detail : ''}` : '',
    db && db.skipTotal > 0 ? `Skips: ${Object.entries(db.skipReasons || {}).map(([r, n]) => `${n} ${_skipReasonLabel(r)}`).join(', ')}` : '',
    db && (db.parked || []).length ? `Parked: ${db.parked.map((p) => `${p.pName || p.profileId} (${_dbParkLabel(p.reason)})`).join(', ')}` : '',
    db && Array.isArray(db.perAccount) && db.perAccount.length
      ? `Per account: ${db.perAccount.map((a) => `${a.name || a.profileId} — ${a.sent} sent${a.endReason ? ' (' + a.endReason + ')' : ''}`).join('; ')}`
      : '',
    _dbPriorsLine,
  ].filter(Boolean).join('\n');

  scrim.style.display = 'flex';
};

window.closeDebrief = function closeDebrief() {
  const scrim = document.getElementById('db-scrim');
  if (scrim) scrim.style.display = 'none';
};

(function _wireDebriefOverlay() {
  const scrim = document.getElementById('db-scrim');
  if (!scrim) return;
  scrim.addEventListener('click', (e) => { if (e.target === scrim) window.closeDebrief(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && scrim.style.display !== 'none') window.closeDebrief();
  });
  const closeBtn = document.getElementById('db-close');
  if (closeBtn) closeBtn.addEventListener('click', () => window.closeDebrief());
  const copyBtn = document.getElementById('db-copy');
  if (copyBtn) copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(_dbCopyText);
      copyBtn.textContent = 'Copied ✓';
      setTimeout(() => { copyBtn.textContent = 'Copy summary'; }, 1600);
    } catch (_) { /* clipboard best-effort */ }
  });
  // Email to me — MANUAL operator click only. No automatic/background send;
  // this fires exclusively in response to the click handler below.
  const emailBtn = document.getElementById('db-email');
  if (emailBtn) emailBtn.addEventListener('click', async () => {
    const titleEl = document.getElementById('db-title');
    const subject = `Debrief — ${(titleEl && titleEl.textContent) || 'campaign'}`;
    try {
      const res = await fetch('/api/debrief/email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ subject, body: _dbCopyText }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.ok) {
        if (typeof showCampaignToast === 'function') showCampaignToast('Debrief emailed.');
      } else {
        if (typeof showCampaignToast === 'function') showCampaignToast(`Email failed: ${data.error || res.statusText}`);
      }
    } catch (err) {
      if (typeof showCampaignToast === 'function') showCampaignToast(`Email failed: ${err.message}`);
    }
  });
})();
// ── End campaign debrief overlay ───────────────────────────────────────────

// One-time handshake modal: pops the first time a cloud campaign enters the
// primary-accept lock, so the operator keeps the app open for the local accept.
// Shown once per campaign id per session (_hsModalShown); dismissable. Inert
// until the engine ships state:'awaiting_primary_accept'.
const _hsModalShown = new Set();
let _hsModalCurrentId = null;
function maybeOpenHandshakeModal(items) {
  const scrim = document.getElementById('hs-scrim');
  if (!scrim) return;
  if (scrim.classList.contains('open')) return; // don't hijack an already-open modal for a different campaign
  const it = (items || []).find((x) => x && x.where === 'cloud'
    && x.state === 'awaiting_primary_accept' && Array.isArray(x.senders) && !_hsModalShown.has(x.id));
  if (!it) return;
  _hsModalShown.add(it.id);
  _hsModalCurrentId = it.id;
  const accepted = it.senders.filter((s) => s && s.accepted).length;
  const total = it.senders.length;
  const pname = escHtml((it.primary && it.primary.name) || 'the primary');
  document.getElementById('hs-modal-count').textContent = String(accepted);
  document.getElementById('hs-modal-sub').textContent = `${accepted} of ${total} accepted`;
  document.getElementById('hs-modal-body').innerHTML =
    `Accepting <b>${pname}</b>'s connection requests in <b>your local browser</b> is the only step that runs on this machine — then <b>${escHtml(it.name || 'the campaign')}</b> runs entirely in the cloud. Keep this app open.`;
  scrim.classList.add('open');
}
function closeHandshakeModal() {
  const scrim = document.getElementById('hs-scrim');
  if (scrim) scrim.classList.remove('open');
  _hsModalCurrentId = null;
}
document.addEventListener('DOMContentLoaded', () => {
  const keep = document.getElementById('hs-modal-keep');
  const stop = document.getElementById('hs-modal-stop');
  const scrim = document.getElementById('hs-scrim');
  if (keep) keep.addEventListener('click', closeHandshakeModal);
  if (stop) stop.addEventListener('click', () => { const id = _hsModalCurrentId; closeHandshakeModal(); if (id && typeof stopCloudCampaignUI === 'function') stopCloudCampaignUI(id); });
  if (scrim) scrim.addEventListener('click', (e) => { if (e.target === scrim) closeHandshakeModal(); });
});

// ── Campaigns board sections (admin split) ──────────────────────────────────
// Per-group collapse state persisted to localStorage. Keys: 'sec:<name>' for
// top-level sections (default expanded), 'sub:<section>:<bucket>' for the Done /
// Cancelled sub-groups (default collapsed). The default lives at the call site
// (defCollapsed arg) so a never-touched group follows its natural default.
const _CB_COLLAPSE_KEY = 'campaignsBoardCollapse_v1';
let _cbCollapse = null;
function _cbState() {
  if (_cbCollapse) return _cbCollapse;
  try { _cbCollapse = JSON.parse(localStorage.getItem(_CB_COLLAPSE_KEY) || '{}') || {}; }
  catch { _cbCollapse = {}; }
  return _cbCollapse;
}
function _cbIsCollapsed(key, defCollapsed) {
  const m = _cbState();
  return key in m ? !!m[key] : defCollapsed;
}
window.toggleBoardGroup = function (key, defCollapsed) {
  const m = _cbState();
  const cur = key in m ? !!m[key] : defCollapsed;
  m[key] = !cur;
  try { localStorage.setItem(_CB_COLLAPSE_KEY, JSON.stringify(m)); } catch { /* non-fatal */ }
  renderCampaignsBoard();
};

// Collapse/expand chevron. A real SVG (not a ▸ glyph, which stays tiny at any
// font-size) so the minimise affordance is unmistakable. Points down when open,
// rotates to point right when collapsed (via CSS .cl).
function _cbCaretSvg(collapsed, big) {
  const sz = big ? 26 : 18;
  return `<svg class="cb-caretsvg${collapsed ? ' cl' : ''}" width="${sz}" height="${sz}" viewBox="0 0 24 24"`
    + ` fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"`
    + ` aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>`;
}

// Per-section user search (Other users' campaigns). Debounced re-render so the
// input keeps focus while typing.
let _otherUserSearch = '';
let _otherSearchTimer = null;
window.onOtherUserSearch = function (val) {
  _otherUserSearch = val || '';
  if (_otherSearchTimer) clearTimeout(_otherSearchTimer);
  _otherSearchTimer = setTimeout(() => { renderCampaignsBoard(); }, 180);
};

// Render one top-level board section: header (caret + title + count) with the
// four buckets inside. Running/Idle are always-visible rails; Done/Cancelled are
// collapsible sub-groups (default collapsed). `opts`:
//   flat        — no section header (non-admin single board)
//   headExtra   — HTML appended into the header (e.g. the user-search input)
//   subtitle    — small muted label after the title
//   alwaysShow  — render the section header even when empty
function _renderBoardSection(key, title, secItems, opts = {}) {
  const running   = secItems.filter((x) => x.bucket === 'running' && !x.paused);
  const paused    = secItems.filter((x) => x.bucket === 'running' && x.paused);
  const idle      = secItems.filter((x) => x.bucket === 'queued');
  const done      = secItems.filter((x) => x.bucket === 'done' && !x.bad);
  const cancelled = secItems.filter((x) => x.bucket === 'done' && x.bad);

  // One bad strip must never abort the whole board render — that would freeze
  // every group (a collapsed sub-group would look un-expandable). Isolate each.
  const _safeStrip = (it) => {
    try { return renderUnifiedStrip(it); }
    catch (e) {
      try { console.error('[board] strip render failed for', it && it.id, e); } catch { /* */ }
      return `<div class="sn-strip"><div class="sn-name">${escHtml((it && it.name) || 'Campaign')}</div>`
        + `<div class="sn-progtxt">Could not render this campaign — see console.</div></div>`;
    }
  };

  const rail = (label, arr) => arr.length
    ? `<div class="sn-railhead">${label}</div>` + arr.map(_safeStrip).join('') : '';
  const subGroup = (bucketKey, label, arr, extra = '') => {
    if (!arr.length) return '';
    const gk = `sub:${key}:${bucketKey}`;
    const collapsed = _cbIsCollapsed(gk, true); // Done/Cancelled default collapsed
    const head = `<div class="sn-railhead cb-subhead" onclick="toggleBoardGroup('${gk}', true)">`
      + `<span class="cb-caret">${_cbCaretSvg(collapsed, false)}</span> ${label} <span class="sn-railcount">${arr.length}</span>${extra}</div>`;
    return head + (collapsed ? '' : arr.map(_safeStrip).join(''));
  };

  // Saved drafts (Sam 2026-07-23): surface under a DRAFTS rail inside this
  // section — pre-rendered strips arrive via opts.draftsHtml (renderDraftStrip),
  // since drafts aren't board items (no bucket / no engine id).
  // Categorized bulk "Delete all" (operators asked for it back, split by
  // category). stopPropagation so it doesn't toggle the group's collapse.
  const clearBtn = (fn, n) => n
    ? `<button type="button" class="sn-clear-cat" onclick="event.stopPropagation(); ${fn}">Delete all</button>` : '';

  const draftsRail = opts.draftsHtml
    ? `<div class="sn-railhead">Drafts <span class="sn-railcount">${opts.draftsCount || ''}</span>${clearBtn('clearAllDrafts()', opts.draftsCount || 0)}</div>` + opts.draftsHtml
    : '';

  // Non-collapsible rails carry NO caret glyph — only genuinely collapsible
  // groups (sections + Done/Cancelled) show a caret, so the affordance reads true.
  const body = rail('Running', running)
    + rail('Paused', paused)
    + rail('Idle', idle)
    + draftsRail
    + subGroup('done', 'Done', done, clearBtn("clearBoardCat('finished')", done.length))
    + subGroup('cancelled', 'Stopped', cancelled, clearBtn("clearBoardCat('cancelled')", cancelled.length));

  // Non-admin flat board: no header, just the buckets.
  if (opts.flat) return body;

  if (!secItems.length && !opts.alwaysShow) return '';

  const secKey = `sec:${key}`;
  const collapsed = _cbIsCollapsed(secKey, false);
  const subtitle = opts.subtitle ? `<span class="cb-secsub">${escHtml(opts.subtitle)}</span>` : '';
  const head = `<div class="cb-sectionhead" onclick="toggleBoardGroup('${secKey}', false)">`
    + `<span class="cb-caret">${_cbCaretSvg(collapsed, true)}</span>`
    + `<span class="cb-sectitle">${title}</span>${subtitle}`
    + `<span class="cb-seccount">${secItems.length + (opts.draftsCount || 0)}</span>`
    + `<span class="cb-headextra">${opts.headExtra || ''}</span></div>`;
  const emptyMsg = opts.emptyMsg || 'There are no campaigns to show at the moment.';
  const inner = collapsed ? ''
    : `<div class="cb-secbody">${body || `<div class="cb-secempty">${escHtml(emptyMsg)}</div>`}</div>`;
  return `<div class="cb-section${collapsed ? ' cb-collapsed' : ''}">${head}${inner}</div>`;
}

let _campaignsBoardTimer = null;
let _lastBoardHtml = '';  // anti-jank: skip the 4s re-render when nothing changed
const _cloudDetailCache = new Map();  // id → detail; terminal campaigns cached (never change)
let _boardRenderInFlight = false;     // don't stack renders (each does N cloud fetches)
let _cloudRaw = [];                   // background snapshot of cloud details; render builds from this
let _cloudRefreshInFlight = false;

// Cloud data comes from the remote engine (0.5–2s per call) — fetching it inside
// the 4s render made every render block ~1.5s. Fetch it on a BACKGROUND timer
// into _cloudRaw instead; the render builds cloud strips from that cache with no
// network wait. Dismiss/ownership filtering still runs live in the render, so
// those stay instant.
async function _refreshCloudItems() {
  if (_cloudRefreshInFlight) return;
  _cloudRefreshInFlight = true;
  try {
    const cl = await (await fetch('/api/campaign/cloud-list')).json();
    const cloudCamps = (cl && cl.campaigns) || [];
    _cloudRaw = await Promise.all(cloudCamps.map(async (c) => {
      let d;
      const terminal = ['done', 'cancelled', 'error'].includes(c.status);
      if (terminal && !_snExpanded.has(c.id) && _cloudDetailCache.has(c.id)) {
        const cached = _cloudDetailCache.get(c.id);
        if (cached && cached.campaign && ['done', 'cancelled', 'error'].includes(cached.campaign.status)) return cached;
      }
      try { d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}`)).json(); }
      catch { d = { campaign: c, leadCounts: {} }; }
      _cloudDetailCache.set(c.id, d);
      _cloudPolledAt.set(c.id, Date.now()); // feeds the live stage's heartbeat
      // A STALLED campaign needs its per-account states on the board, not just
      // in the opened campaign's panel — that's where the stage names which
      // account is capped and which is benched, and offers Retry. Fetched only
      // while it's stalled, so a healthy board costs no extra request.
      // Refreshed on a TTL rather than once: after a Retry the counts and park
      // reasons change, and advice computed from a stale snapshot would keep
      // telling the operator to fix something they just fixed.
      const _acctAge = Date.now() - (_cloudAccountsAt.get(c.id) || 0);
      const _ca = _cloudCurrentAction(d);
      // Also while it is SENDING, not only while stalled. The account pills are
      // built from this payload, so fetching it only in the waiting phase meant a
      // healthy running campaign showed no per-account breakdown at all — you
      // could see 88 of 1567 sent but not which of the 66 accounts sent them.
      const _live = ((d && d.campaign) || c).status === 'running';
      // A FINISHED FG run needs them exactly once, to say why it stopped short.
      // Once fetched the run is over and the answer can't change, so this never
      // repeats — `has()` is the whole gate.
      const _fgDone = ((d && d.campaign) || c).mode === 'follower_growth'
        && !_live && !_cloudAccountsById.has(c.id);
      if (((_ca && _ca.phase === 'waiting') || _live || _fgDone) && _acctAge > 30000) {
        _cloudAccountsAt.set(c.id, Date.now());
        try {
          const ar = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}/accounts`)).json();
          if (ar && Array.isArray(ar.accounts)) _cloudAccountsById.set(c.id, ar.accounts);
        } catch (_) { /* the stage degrades to the reason line alone */ }
      }
      const st = ((d && d.campaign) || c).status;
      if (st === 'running' || _snExpanded.has(c.id)) {
        try {
          const lr = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(c.id)}/leads`)).json();
          if (lr && Array.isArray(lr.leads)) {
            d._logLines = _mergeCloudLog(_cloudLeadsToLog(lr.leads, ((d && d.campaign) || c).mode === 'follower_growth', (d && d.campaign) || c), null);
            _cloudAcctCounts.set(c.id, _cloudCountsByAccount(lr.leads));
            d._fgLast = _fgLastActivity(lr.leads);
          }
        } catch { /* best-effort */ }
      }
      return d;
    }));
  } catch (_) { /* keep last snapshot on engine hiccup */ }
  finally { _cloudRefreshInFlight = false; }
  try { renderCampaignsBoard(); } catch { /* */ }
}
window._refreshCloudItems = _refreshCloudItems;

// Wrapper: the 4s poll must not start a new render while the previous is still
// fetching from the remote engine — overlapping renders fired 2–3× the cloud
// requests and made the fetch time climb to 20s+. Skip the tick instead.
async function renderCampaignsBoard() {
  if (_boardRenderInFlight) return;
  _boardRenderInFlight = true;
  try { await _renderCampaignsBoardInner(); }
  finally { _boardRenderInFlight = false; }
}
// Fetch local (status/queue/history) + cloud campaigns, normalize, render.
async function _renderCampaignsBoardInner() {
  const board = document.getElementById('campaigns-board');
  if (!board) return;
  // Keep the legacy dashboard hidden on EVERY cycle (defeats route/render races).
  _hideLegacyDashboardSections();
  const items = [];

  // 0) A cloud launch in flight — no row exists in Postgres or the local cockpit
  // yet, so without this the board shows only the (not-yet-consumed) draft while
  // the handshake + dispatch run. First, so it sits at the top of "Running".
  try {
    const _lit = (typeof cloudLaunchBoardItem === 'function') ? cloudLaunchBoardItem() : null;
    if (_lit) items.push(_lit);
  } catch (_) { /* never let the launch strip break the board */ }

  // 1) Local running campaign (0 or 1) — from /api/campaign/status.
  // A campaign that ENDED this session still holds its full log in the status
  // payload (in-memory, until the next run or an app restart) — stash it so
  // step 4 can attach it to the matching done strip instead of the
  // "Live log appears here…" placeholder.
  let _endedLogs = null, _endedName = '';
  try {
    const s = await (await fetch('/api/campaign/status')).json();
    if (s && !s.running && s.state !== 'monitoring' && Array.isArray(s.logs) && s.logs.length) {
      _endedLogs = s.logs; _endedName = s.name || '';
    }
    if (s && (s.running || s.state === 'monitoring')) {
      items.push({
        where: 'local', id: 'local-active', name: s.name, mode: s.mode, isFG: s.mode === 'follower_growth',
        bucket: 'running', sent: s.totalProcessed || 0, total: s.totalTargets || 0,
        accounts: (s.profileIds || []).length, mine: true, paused: !!(s.paused || s._paused),
        logs: Array.isArray(s.logs) ? s.logs : [],
        skippedCount: s.skippedCount || 0,
        // v2.160.35: carry the follow-up summary so the strip clone's monitor
        // hero shows the same dual countdown as card #2.
        followUp: s.followUp || null,
      });
    }
  } catch (_) { /* local status best-effort */ }

  // 2) Local queued — from /api/queue.
  try {
    const q = await (await fetch('/api/queue')).json();
    for (const it of (q.queue || [])) {
      items.push({ where: 'local', id: 'q-' + it.id, rawId: it.id, name: it.name, mode: it.mode,
        isFG: it.mode === 'follower_growth', bucket: 'queued', accounts: (it.profileIds || []).length,
        mine: true, scheduledAt: it.scheduledAt || null });
    }
  } catch (_) { /* */ }

  // 3) Cloud campaigns — built from the BACKGROUND snapshot (_cloudRaw), not
  // fetched here, so the render never blocks on the slow remote engine.
  try {
    for (const d of _cloudRaw) {
      const c = d.campaign || {}; const lc = d.leadCounts || {};
      if (['done', 'cancelled', 'error'].includes(c.status) && _cloudDismissed.has(c.id)) continue;
      if (c.sheet_url) _cloudSheetUrls.set(c.id, c.sheet_url);
      const mine = !!(snCurrentEmail && c.owner && String(c.owner).toLowerCase() === String(snCurrentEmail).toLowerCase());
      // Ownership gate: normal accounts see only their OWN cloud campaigns;
      // admins see everyone's. (Local campaigns are always the viewer's.)
      if (!_viewerIsAdmin && !mine) continue;
      // 'monitoring' (post-send acceptance-watch — exactly like a local CC+IC /
      // CC+DM run) is an ACTIVE state: keep it in NOW RUNNING, not DONE. Task 3.
      // 'paused' is a still-ACTIVE state (sending held, resumable) — keep it in
      // NOW RUNNING with the Pause/Resume+Stop cluster, exactly like a paused
      // local campaign (which stays running:true, paused:true).
      // 'scheduled' — dispatched to the VM with a start time; the engine holds it
      // and starts it itself. Same bucket as queued, and scheduledAt makes the
      // strip read "Scheduled · <when>" (the shape the local queue already uses).
      const bucket = (c.status === 'running' || c.status === 'monitoring' || c.status === 'paused') ? 'running'
        : (c.status === 'pending' || c.status === 'queued' || c.status === 'scheduled') ? 'queued' : 'done';
      items.push({
        where: 'cloud', id: c.id, name: c.name, mode: c.mode, isFG: c.mode === 'follower_growth',
        paused: c.status === 'paused',
        // Live-browser flag from the engine (top-level of the /:id detail, NOT
        // inside d.campaign) — drives the green LIVE dot on the Show button.
        live: !!(d && d.live), liveAccount: (d && d.liveAccount) || '',
        // The engine's per-person phase tick → the strip card's live stage.
        currentAction: _cloudCurrentAction(d),
        // _preActioned (Sam 2026-07-23): leads whose sheet row already carried a
        // Connection Request Status on import — the engine parks them in
        // status='sent' so they're never re-opened, but they aren't part of this
        // run. Exclude them from BOTH sides of "X of Y sent".
        bucket, sent: Math.max(0, Number(lc.sent || 0) - Number(lc._preActioned || 0)),
        total: Object.entries(lc).reduce((a, [k, b]) => a + (k.startsWith('_') ? 0 : (Number(b) || 0)), 0) - Number(lc._preActioned || 0),
        accounts: (c.profile_ids || []).length, profileIds: c.profile_ids || [], mine,
        // Per-account states — feeds _fgFinishedNote's "why it stopped short".
        benchAccounts: _cloudAccountsById.get(c.id) || null,
        // When the VM will start it — the engine reads this off the pending
        // start_campaign task itself, so it can't drift from the real timer.
        scheduledAt: c.scheduled_start_at || null,
        owner: c.owner || '', bad: c.status === 'error' || c.status === 'cancelled',
        badLabel: c.status === 'cancelled' ? 'Stopped' : 'Error',
        createdAt: c.created_at, // #17: drives the "warming up (~2 min)" window
        logs: d._logLines || null, // per-lead log rows (running/expanded only)
        // Phase 0 handshake lock (Task 3.4) — undefined until the engine ships
        // them, in which case the lock panel in renderUnifiedStrip stays dormant.
        state: c.state, senders: c.senders, primary: c.primary,
        // Task 9 — primary needs-login surfacing (Task 5's c.primarySession).
        primarySession: c.primarySession,
        // Task 3 — monitoring card (parity with local renderMonitoringCard). The
        // engine carries these top-level; nextCheckAt/monitoringUntil drive the
        // "Next check · ends in" countdown, exactly like the local mon-card.
        monitoring: c.status === 'monitoring',
        nextCheckAt: c.next_check_at, monitoringUntil: c.monitoring_until,
        autoChecksEnabled: c.auto_checks_enabled !== false,
        checkIntervalMinutes: c.check_interval_minutes || 60,
        // v2.160.35: follow-up dual countdown — lights up once the engine
        // exposes c.follow_up {count,dueAt,sender} on the cloud detail.
        followUp: c.follow_up || null,
      });
    }
  } catch (_) { /* cloud best-effort */ }

  // 4) Local done — recent history (limit 8).
  try {
    const h = await (await fetch('/api/history')).json();
    const hist = Array.isArray(h) ? h : (h.history || []);
    for (const { p, histIdx } of hist.map((p, i) => ({ p, histIdx: i })).slice(-8).reverse()) {
      const stopped = p.endReason === 'stopped' || p.fullStop;
      const hid = 'h-' + (p.date || p.name);
      if (_localDismissed.has(hid)) continue;
      // Attach the in-memory log of the campaign that just ended this session
      // (matched by name, most-recent entry only) so the strip keeps showing
      // its log after the running → done transition.
      const endedLogs = (_endedLogs && _endedName && p.name === _endedName) ? _endedLogs : null;
      if (endedLogs) _endedLogs = null; // only the newest matching strip gets it
      items.push({ where: 'local', id: hid, name: p.name, mode: p.mode,
        isFG: p.mode === 'follower_growth', bucket: 'done', sent: p.totalProcessed || 0,
        total: p.totalProcessed || 0, accounts: (p.profiles || []).length, mine: true,
        bad: stopped, badLabel: 'Stopped', srcSettings: p.settings || null, histIdx,
        hist: p,
        logs: endedLogs });
    }
  } catch (_) { /* */ }

  // Lookup for per-strip actions (Duplicate) — keyed by strip id.
  _boardItemsById.clear();
  for (const it of items) _boardItemsById.set(it.id, it);

  // Type filter (Sam): a dropdown on the header narrows the board to one
  // campaign type. Counts on the menu reflect ALL items; the board shows only
  // the selected type. 'All' shows everything.
  renderCampaignsTypeFilter(items);
  // Conductor filter (admin only): narrow to one operator's campaigns.
  renderCampaignsConductorFilter(items);
  let shown = _campaignsTypeFilter === 'All'
    ? items : items.filter((x) => _cloudBadge(x.mode) === _campaignsTypeFilter);
  if (_viewerIsAdmin && _campaignsConductorFilter !== 'Everyone') {
    shown = shown.filter((x) => (x.owner || (x.mine ? _viewerEmail : '')) === _campaignsConductorFilter);
  }

  const running = shown.filter((x) => x.bucket === 'running');
  const queued = shown.filter((x) => x.bucket === 'queued');
  const done = shown.filter((x) => x.bucket === 'done');

  // If no local campaign is running, the detail card has nothing to show —
  // drop the "open" flag so it stops being revealed.
  if (!items.some((x) => x.bucket === 'running' && x.where === 'local')) _localDetailOpen = false;

  const schedCount = queued.filter((x) => x.scheduledAt).length;
  const qmeta = document.getElementById('campaigns-qmeta');
  if (qmeta) {
    const bits = [`${running.length} running`];
    const plainQ = queued.length - schedCount;
    if (plainQ > 0) bits.push(`${plainQ} queued`);
    if (schedCount > 0) bits.push(`${schedCount} scheduled`);
    qmeta.textContent = bits.join(' · ');
  }

  _lastCampaignsDone = done;

  // Saved drafts (Sam 2026-07-23): fetched here so the board's "Your campaigns"
  // section can show them under a DRAFTS rail. Drafts are this machine's own
  // staging area, so they always land in "mine" (never other-users/admin) and
  // hide when a type filter narrows the board (a draft has no committed type).
  let _draftRows = [];
  if (_campaignsTypeFilter === 'All') {
    try {
      const dj = await fetch('/api/drafts').then((r) => r.json());
      if (Array.isArray(dj?.drafts)) _draftRows = dj.drafts;
      _draftRows.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    } catch { /* drafts rail is best-effort — board renders without it */ }
  }
  let _draftsHtml = '';
  for (const d of _draftRows) {
    try { _draftsHtml += renderDraftStrip(d); }
    catch (e) { try { console.error('[board] draft strip render failed for', d && d.id, e); } catch { /* */ } }
  }
  const _draftOpts = _draftsHtml ? { draftsHtml: _draftsHtml, draftsCount: _draftRows.length } : {};

  // ── Board layout ──────────────────────────────────────────────────────────
  // Admins get three minimisable sections (Your / Other users / Admin = Follower
  // Growth); each orders Running → Idle → Done → Cancelled, with Done and
  // Cancelled as collapsible sub-groups. Non-admins keep a single flat board
  // with the same bucket ordering. Cancelled strips are NOT greyed (see CSS
  // .sn-board.cb-nogrey .sn-strip.cancelled).
  board.classList.add('cb-nogrey');
  let html;
  if (_viewerIsAdmin) {
    const mineItems  = shown.filter((x) => !x.isFG && x.mine);
    const otherItems = shown.filter((x) => !x.isFG && !x.mine);
    const adminItems = shown.filter((x) => x.isFG); // Follower Growth (extensible)
    // Other-users section: optional per-section user search.
    const q = (_otherUserSearch || '').trim().toLowerCase();
    const otherShown = q
      ? otherItems.filter((x) => String(_ownerOf(x) || '').toLowerCase().includes(q))
      : otherItems;
    const searchBox = `<span class="cb-searchwrap" onclick="event.stopPropagation()">`
      + `<svg class="cb-searchic" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="M21 21l-4.3-4.3"></path></svg>`
      + `<input type="search" class="cb-usersearch" placeholder="Search by user…" spellcheck="false" autocomplete="off" autocapitalize="off"`
      + ` value="${escHtml(_otherUserSearch || '')}" oninput="onOtherUserSearch(this.value)">`
      + `</span>`;
    html = _renderBoardSection('mine', 'Your campaigns', mineItems, { alwaysShow: true, ..._draftOpts })
      + _renderBoardSection('other', 'Other users’ campaigns', otherShown, {
        headExtra: searchBox, alwaysShow: true,
        emptyMsg: q ? 'No campaigns match that user.' : 'There are no campaigns to show at the moment.',
      })
      + _renderBoardSection('admin', 'Admin campaigns', adminItems, { subtitle: 'Follower Growth' });
  } else {
    html = _renderBoardSection('mine', '', shown, { flat: true, ..._draftOpts });
  }
  _snItemsById = new Map(items.map((x) => [x.id, x]));
  // Anti-jank: the 4s poll used to blow away the whole board every tick — killing
  // clicks/scroll/expanded panes mid-interaction. Skip the rebuild when the
  // rendered HTML is byte-identical to last time (the common case: a board of
  // done/cancelled strips is static). Live strips whose countdowns tick still
  // differ each render, so they keep updating.
  const final = html || _campaignsEmptyState();
  if (board.dataset.rendered === '1' && final === _lastBoardHtml) return;
  _lastBoardHtml = final;
  board.dataset.rendered = '1';
  // Keep the user-search caret alive across the re-render: note whether it held
  // focus BEFORE we blow away innerHTML, then restore after.
  const _searchHadFocus = document.activeElement
    && document.activeElement.classList
    && document.activeElement.classList.contains('cb-usersearch');
  board.innerHTML = final;
  if (_searchHadFocus) {
    const inp = board.querySelector('.cb-usersearch');
    if (inp) { inp.focus(); const n = inp.value.length; try { inp.setSelectionRange(n, n); } catch { /* */ } }
  }
  maybeOpenHandshakeModal(items);
  _fillHistLogBoxes(board);
  _fillVjCards(board); // expanded strips → card #2 parity
  _renderPrimaryNudge(items);
}

// Aggregate nudge: ONE informational line at the top of the board when this
// machine pulled down personal-primary follow-ups LATE (the app had been closed
// past their due time — see cloud-followup-poller). Personal follow-ups can only
// send from the person's own machine, so the honest ask is "keep the app open".
// Non-clickable. `items` is unused now (the old needs_login VM framing is
// retired); kept in the signature so the single caller needn't change.
async function _renderPrimaryNudge(_items) {
  const el = document.getElementById('primary-nudge');
  if (!el) return;
  let late = 0;
  try { const r = await fetch('/api/local-followups/pending').then((x) => x.json()); late = (r && r.late) || 0; } catch { /* best-effort nudge */ }
  if (!late) { el.hidden = true; el.innerHTML = ''; return; }
  el.hidden = false;
  el.innerHTML = `<div class="needs-login">⚠ ${late} follow-up${late === 1 ? '' : 's'} waiting to send from this machine — keep the app open.</div>`;
}

// Lazy-fill done-strip log boxes from the persisted campaign log. Cached per
// history index so the 5s board re-render doesn't refetch; in-flight guard so
// overlapping renders don't double-fetch.
const _histLogCache = new Map();
const _histLogInFlight = new Set();
function _fillHistLogBoxes(board) {
  board.querySelectorAll('[data-histlog]').forEach(async (box) => {
    const idx = Number(box.dataset.histlog);
    if (!Number.isInteger(idx) || _histLogInFlight.has(idx)) return;
    _histLogInFlight.add(idx);
    try {
      const d = await (await fetch(`/api/history/${idx}/log`)).json();
      const lines = Array.isArray(d.lines) ? d.lines.slice(-8) : [];
      const html = lines.length
        ? lines.map((l) => escHtml(l)).join('<br>')
        : 'No stored log lines for this campaign.';
      _histLogCache.set(idx, html);
      // Fill in place if the box is still on screen (board may have re-rendered).
      const live = board.querySelector(`[data-histlog="${idx}"]`);
      if (live) { live.innerHTML = html; live.removeAttribute('data-histlog'); }
    } catch {
      _histLogCache.set(idx, 'Log unavailable.');
    } finally {
      _histLogInFlight.delete(idx);
    }
  });
}

// Bulk-dismiss every Done strip on the campaigns board (local → _localDismissed,
// cloud → _cloudDismissed). Mirrors the Sales Nav "Clear done".
let _lastCampaignsDone = [];
function clearCampaignsDone() {
  for (const it of _lastCampaignsDone) {
    if (it.where === 'cloud') _cloudDismissed.add(it.id);
    else _localDismissed.add(it.id);
  }
  renderCampaignsBoard();
}
window.clearCampaignsDone = clearCampaignsDone;

// App-styled confirm (replaces the native OS dialog). Returns a Promise<bool>.
// Reuses the existing .modal-backdrop/.modal-card design so it matches the app.
function appConfirm(message, opts = {}) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    back.innerHTML = `<div class="modal-card" role="dialog" aria-modal="true" style="max-width:420px">
      <h3 class="modal-title">${escHtml(opts.title || 'Are you sure?')}</h3>
      <div class="modal-body">${escHtml(message)}</div>
      <div class="modal-actions" style="justify-content:flex-end;gap:10px;margin-top:18px">
        <button type="button" class="modal-cancel-link ac-cancel">${escHtml(opts.cancelLabel || 'Cancel')}</button>
        <button type="button" class="btn btn-primary ac-ok">${escHtml(opts.okLabel || 'Delete all')}</button>
      </div></div>`;
    const done = (v) => { document.removeEventListener('keydown', onKey); back.remove(); resolve(v); };
    const onKey = (e) => { if (e.key === 'Escape') done(false); else if (e.key === 'Enter') done(true); };
    back.querySelector('.ac-ok').onclick = () => done(true);
    back.querySelector('.ac-cancel').onclick = () => done(false);
    back.onclick = (e) => { if (e.target === back) done(false); };
    document.body.appendChild(back);
    document.addEventListener('keydown', onKey);
    setTimeout(() => { try { back.querySelector('.ac-ok').focus(); } catch { /* */ } }, 0);
  });
}
window.appConfirm = appConfirm;

// Categorized bulk clear. Campaigns are cloud/local (engine keeps cloud data on
// its own lifecycle) → "clear" hides them from THIS board. Drafts get a real
// soft-delete + 1-week purge via clearAllDrafts.
async function clearBoardCat(cat) {
  const items = [..._snItemsById.values()];
  const targets = cat === 'cancelled'
    ? items.filter((x) => x.bucket === 'done' && x.bad)
    : items.filter((x) => x.bucket === 'done' && !x.bad);
  if (!targets.length) return;
  const word = cat === 'cancelled' ? 'stopped / cancelled' : 'finished';
  if (!(await appConfirm(`Clear all ${targets.length} ${word} campaign(s) from your board?`, { title: 'Clear campaigns', okLabel: 'Clear all' }))) return;
  for (const it of targets) {
    if (it.where === 'cloud') _cloudDismissed.add(it.id);
    else if (it.where === 'email' && typeof dismissEmailDone === 'function') dismissEmailDone(it.id);
    else _localDismissed.add(it.id);
  }
  try { _cloudSaveDismissed(); } catch { /* */ }
  renderCampaignsBoard();
}
window.clearBoardCat = clearBoardCat;

// Soft-delete every draft (hidden now, kept 1 week, then server-purged).
async function clearAllDrafts() {
  let n = 0;
  try { n = ((await (await fetch('/api/drafts')).json()).drafts || []).length; } catch { /* */ }
  if (!n) return;
  if (!(await appConfirm(`Delete all ${n} draft(s)? They stay recoverable for 1 week, then are removed for good.`, { title: 'Delete drafts', okLabel: 'Delete all' }))) return;
  // ONE bulk request (not N deletes) — server trashes them all in a single write.
  try { await fetch('/api/drafts/trash-all', { method: 'POST' }); } catch { /* */ }
  try { if (typeof refreshDashboardDrafts === 'function') refreshDashboardDrafts(); } catch { /* */ }
  renderCampaignsBoard();
}
window.clearAllDrafts = clearAllDrafts;

// Shared prettier empty state for the sn-boards. cfg: { icon, title, sub,
// ctaLabel, ctaFn, legend? }.
function _snEmptyStateHtml(cfg) {
  const legend = cfg.legend
    ? `<div class="sn-emptyx-legend">${cfg.legend}</div>` : '';
  return `
  <div class="sn-emptyx">
    <div class="sn-emptyx-mark" aria-hidden="true">${cfg.icon}</div>
    <div class="sn-emptyx-title">${cfg.title}</div>
    <div class="sn-emptyx-sub">${cfg.sub}</div>
    <button type="button" class="sn-emptyx-cta" onclick="${cfg.ctaFn}">${cfg.ctaLabel}</button>
    ${legend}
  </div>`;
}

const _SN_ICON_CLOUD = `<svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6.5 18a3.5 3.5 0 0 1-.4-6.98A5 5 0 0 1 16 10.2a3.4 3.4 0 0 1 1.5 6.8"/><path d="M9 21h9a2 2 0 0 0 2-2v-2"/></svg>`;
const _SN_ICON_SEARCH = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>`;

// Prettier empty state for the campaigns board.
function _campaignsEmptyState() {
  return _snEmptyStateHtml({
    icon: _SN_ICON_CLOUD,
    title: 'No campaigns yet',
    sub: 'Launch outreach and it lands here as a live strip — locally or on the cloud VM.',
    ctaLabel: '＋ New campaign',
    ctaFn: 'window.startNewCampaign && window.startNewCampaign()',
    legend: '<span><i class="sw green"></i>Cloud · runs on the VM</span><span><i class="sw pink"></i>Local · runs on this machine</span>',
  });
}

// Prettier empty state for the Sales Nav scraper board.
function _scrapeEmptyState() {
  return _snEmptyStateHtml({
    icon: _SN_ICON_SEARCH,
    title: 'No scrapes yet',
    sub: 'Start a Sales Navigator scrape to pull leads into a sheet. Live jobs show up here.',
    ctaLabel: '＋ New scrape',
    ctaFn: 'window.startNewScrapeSetup && window.startNewScrapeSetup()',
  });
}
window.renderCampaignsBoard = renderCampaignsBoard;

// Start the board (hide legacy sections, render, poll every 4s). Idempotent.
let _cloudRefreshTimer = null;
function startCampaignsBoard() {
  _hideLegacyDashboardSections();
  _wireStripOverflow();
  renderCampaignsBoard();
  _refreshCloudItems();   // kick a background cloud fetch (renders again when it lands)
  if (_campaignsBoardTimer) clearInterval(_campaignsBoardTimer);
  _campaignsBoardTimer = setInterval(renderCampaignsBoard, 4000);
  // Cloud snapshot refreshes on its own slower timer — off the render path.
  if (_cloudRefreshTimer) clearInterval(_cloudRefreshTimer);
  _cloudRefreshTimer = setInterval(_refreshCloudItems, 5000);
}
window.startCampaignsBoard = startCampaignsBoard;

// The board is the top-level Campaigns view — it must start on page load
// REGARDLESS of whether a campaign is running. (Previously it was only kicked
// off from startPolling(), which doesn't fire when nothing is active — so the
// board never rendered and the legacy dashboard leaked through.)
function _bootCampaignsBoard() {
  try { startCampaignsBoard(); } catch (_) { /* board best-effort */ }
  // Learn admin status, then re-render so the admin-only controls appear.
  loadViewerIdentity().then(() => { try { renderCampaignsBoard(); } catch (_) { /* */ } });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _bootCampaignsBoard);
} else {
  _bootCampaignsBoard();
}

// Which campaign the shared stop-choice-modal is acting on. cloud:true means the
// two pills route to the ENGINE (keepMonitoring vs cancel) instead of the local
// campaign. Reset whenever the modal closes so a dismissed cloud stop can't leak
// into a later local stop.
let _stopChoiceTarget = { cloud: false, id: null };

// Stop a cloud campaign from the panel. For CC+IC / CC+DM that are still sending,
// show the SAME "stop everything vs. keep monitoring" choice as a local campaign
// (1:1). Other modes — or a campaign already in monitoring/done — get the plain
// confirm → cancel.
async function stopCloudCampaignUI(id) {
  let mode = '', status = '';
  try {
    const d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`, { cache: 'no-store' })).json();
    mode = (d && d.campaign && d.campaign.mode) || '';
    status = (d && d.campaign && d.campaign.status) || '';
  } catch { /* fall through to plain confirm */ }

  const isMonitorMode = (mode === 'connect_and_introduce' || mode === 'connect_and_message');
  // paused counts as "still sending": its unsent leads + pending invitations are
  // exactly the state the choice is about.
  const isSending = (status === 'running' || status === 'queued' || status === 'paused');
  const modal = document.getElementById('stop-choice-modal');
  if (isMonitorMode && isSending && modal) {
    _stopChoiceTarget = { cloud: true, id };
    const isDm = mode === 'connect_and_message';
    const eyebrow = modal.querySelector('.stop-choice-eyebrow');
    const monitorSub = modal.querySelector('.stop-choice-pill.is-monitor .stop-choice-pill-sub');
    if (eyebrow) eyebrow.textContent = isDm ? 'Stop cloud campaign · Connect + DM' : 'Stop cloud campaign · Connect + Introduce Back';
    if (monitorSub) monitorSub.textContent = isDm
      ? 'Sending stops. The VM keeps checking for acceptances (every 60 min, 7 days) and auto-DMs still fire.'
      : 'Sending stops. The VM keeps checking for acceptances (every 60 min, 7 days) and auto-intros still fire.';
    modal.classList.remove('hidden');
    return;
  }
  if (!confirm('Stop this cloud campaign? Leads not yet actioned will not be sent.')) return;
  await _doStopCloud(id, { keepMonitoring: false });
}
window.stopCloudCampaignUI = stopCloudCampaignUI;

// Fire the actual engine stop (shared by the plain confirm + both choice pills).
async function _doStopCloud(id, { keepMonitoring = false } = {}) {
  try {
    const qs = keepMonitoring ? '?keepMonitoring=1' : '';
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/stop${qs}`, { method: 'POST' });
    const d = await res.json();
    if (d.error) { alert('Could not stop: ' + d.error); return; }
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(keepMonitoring
        ? 'Sending stopped — the VM keeps monitoring for acceptances (7 days).'
        : 'Cloud campaign stopped.', 5000);
    }
    _pushCloudEvent(id, keepMonitoring ? '⏹️ Sending stopped — VM keeps monitoring for acceptances' : '⏹️ Campaign stopped');
  } catch (e) { alert('Could not stop: ' + e.message); return; }
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
}

// Pause / Resume a cloud campaign — 1:1 with the local Pause/Resume. isPaused is
// the CURRENT state: true → resume (paused→running, scheduler continues from
// where it left off); false → pause (stop?pause=1; the engine worker re-checks
// status between leads, so sending stops after the lead in flight).
async function pauseCloudCampaignUI(id, isPaused) {
  const path = isPaused ? 'resume' : 'stop?pause=1';
  const verb = isPaused ? 'resume' : 'pause';
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/${path}`, { method: 'POST' });
    const d = await res.json();
    if (d.error) { alert(`Could not ${verb}: ` + d.error); return; }
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(isPaused ? 'Resuming…' : 'Pausing — sending stops after the current lead.', 4000);
    }
    _pushCloudEvent(id, isPaused ? '▶️ Resumed' : '⏸️ Paused — sending stops after the current lead');
  } catch (e) { alert(`Could not ${verb}: ` + e.message); return; }
  // Refresh the viewed card immediately, plus the board.
  if (typeof _refreshCloudActiveStatus === 'function' && _viewingCloudId === id) { try { await _refreshCloudActiveStatus(id); } catch {} }
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
}
window.pauseCloudCampaignUI = pauseCloudCampaignUI;

// ── Cloud campaign OPEN → edit ──────────────────────────────────────────────
// OPEN on a RUNNING cloud campaign drops the operator into the wizard,
// prefilled with the campaign's saved launch config, every field locked, and a
// banner explaining edits need a pause. Pausing unlocks the form; "Save edits
// & resume" re-enters the normal wizard launch path, and submitStartCampaign
// diverts the body to /api/campaign/cloud/:id/edit-redispatch (stop the paused
// original + redispatch its still-pending leads with the edited config).
let _cloudEdit = null; // { cloudId, name, paused }

function _cloudEditBannerEls() {
  return {
    banner: document.getElementById('wizard-cloud-edit-banner'),
    title: document.getElementById('cloud-edit-banner-title'),
    detail: document.getElementById('cloud-edit-banner-detail'),
    pauseBtn: document.getElementById('btn-cloud-edit-pause'),
    saveBtn: document.getElementById('btn-cloud-edit-save'),
  };
}

function _renderCloudEditBanner() {
  const { banner, title, detail, pauseBtn, saveBtn } = _cloudEditBannerEls();
  if (!banner) return;
  if (!_cloudEdit) { banner.style.display = 'none'; return; }
  banner.style.display = '';
  if (_cloudEdit.readOnly) {
    // v2.160.46: OPEN on an ACTIVE campaign → read-only view. No pause/save
    // path here — to edit, the operator stops it from the dashboard (→ Stopped,
    // which OPEN then edits). The banner just explains why fields are locked.
    if (title) title.textContent = `"${_cloudEdit.name || 'This campaign'}" is active.`;
    if (detail) detail.textContent = 'Its configuration is read-only while it runs. Stop the campaign from the dashboard to edit it.';
    if (pauseBtn) pauseBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    return;
  }
  if (_cloudEdit.paused) {
    if (title) title.textContent = `Editing "${_cloudEdit.name || 'cloud campaign'}" (paused).`;
    if (detail) detail.textContent = 'Change the messaging or any other field below, then Save edits & resume — the remaining leads are redispatched with your changes.';
    if (pauseBtn) pauseBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = '';
  } else {
    if (title) title.textContent = `"${_cloudEdit.name || 'This campaign'}" is running.`;
    if (detail) detail.textContent = 'Fields are locked while it sends — pause it to make edits.';
    if (pauseBtn) { pauseBtn.style.display = ''; pauseBtn.disabled = false; pauseBtn.textContent = 'Pause campaign'; }
    if (saveBtn) saveBtn.style.display = 'none';
  }
}

// Lock/unlock every control in the wizard EXCEPT the banner's own buttons and
// the back link. Only elements THIS lock disabled get re-enabled (via the
// data flag) so other disable-owners (setCampaignButtons, validation) are
// never stomped.
function _setCloudEditLock(locked) {
  const root = document.getElementById('wizard-view');
  if (!root) return;
  root.classList.toggle('cloud-edit-locked', !!locked);
  root.querySelectorAll('input, select, textarea, button').forEach((el) => {
    // Never lock the banner's own buttons, any "back to dashboard" link (top
    // .wizard-back-row OR bottom .back-link), or the Live Status card's controls
    // (#nav-status — Run check now / pause / show are campaign controls, not
    // config-edit fields; they must stay usable while viewing an active campaign).
    if (el.closest('#wizard-cloud-edit-banner') || el.closest('.wizard-back-row') || el.closest('.back-link') || el.closest('#nav-status')) return;
    // Picking accounts for a live campaign is a campaign CONTROL, not a config
    // edit — the same reason #nav-status is exempt. Without this the read-only
    // lock (re-asserted by the 5s cloud poll) disabled the very picker the
    // operator was sent to, and every click just toasted "stop it first".
    try { if (_acctAdd && (el.closest('#nav-accounts') || el.closest('#wizard-acct-add-banner'))) return; } catch (_) { /* */ }
    if (locked) {
      if (!el.disabled) { el.disabled = true; el.dataset.cloudEditLocked = '1'; }
    } else if (el.dataset.cloudEditLocked) {
      el.disabled = false; delete el.dataset.cloudEditLocked;
    }
  });
}

async function openRunningCampaignEditor(id) {
  let d = null;
  try {
    const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/launch-config`);
    if (r.ok) d = await r.json();
  } catch (_) { /* fall through to the live view below */ }
  if (!d || !d.config) {
    // Pre-2.133 campaigns have no snapshotted wizard config → old behavior.
    try { await openCloudLive(id); } catch (_) {}
    return;
  }
  // Already paused? Land straight in editable mode.
  let paused = false;
  try {
    const s = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`).then((r) => r.json());
    paused = String(((s && s.campaign) || s || {}).status || '') === 'paused';
  } catch (_) { /* treat as running — the lock is the safe default */ }
  _cloudEdit = { cloudId: id, name: d.name || '', paused };
  const nameInput = document.getElementById('campaign-name-input');
  if (nameInput) nameInput.value = d.name || '';
  try { clearActiveDraft(); } catch (_) { /* editing a live campaign, not a draft */ }
  if (typeof applyPresetConfig === 'function') applyPresetConfig(d.config);
  goCreateCampaign();
  _renderCloudEditBanner();
  _setCloudEditLock(!paused);
  // applyPresetConfig renders some sections async (account picker, tab list) —
  // re-assert the lock once they've landed so late fields don't stay editable.
  if (!paused) setTimeout(() => { if (_cloudEdit && !_cloudEdit.paused) _setCloudEditLock(true); }, 900);
}
window.openRunningCampaignEditor = openRunningCampaignEditor;

async function cloudEditPauseNow() {
  if (!_cloudEdit) return;
  const { pauseBtn } = _cloudEditBannerEls();
  if (pauseBtn) { pauseBtn.disabled = true; pauseBtn.textContent = 'Pausing…'; }
  await pauseCloudCampaignUI(_cloudEdit.cloudId, false);
  // Wait for the engine to actually pause (it finishes the current lead first).
  for (let i = 0; i < 40 && _cloudEdit; i++) {
    try {
      const s = await fetch(`/api/campaign/cloud/${encodeURIComponent(_cloudEdit.cloudId)}`).then((r) => r.json());
      const st = String(((s && s.campaign) || s || {}).status || '');
      if (st && st !== 'running') break;
    } catch (_) { /* transient — keep polling */ }
    await new Promise((r) => setTimeout(r, 1500));
  }
  if (!_cloudEdit) return; // operator navigated away mid-pause
  _cloudEdit.paused = true;
  _renderCloudEditBanner();
  _setCloudEditLock(false);
}
window.cloudEditPauseNow = cloudEditPauseNow;

function cloudEditSaveResume() {
  // Same wizard entry as a real launch so every validation runs; the body is
  // diverted to edit-redispatch inside submitStartCampaign.
  if (typeof startCampaign === 'function') startCampaign({ cloud: true });
}
window.cloudEditSaveResume = cloudEditSaveResume;

function clearCloudEditMode() {
  if (!_cloudEdit) return;
  _cloudEdit = null;
  _setCloudEditLock(false);
  _renderCloudEditBanner();
}
window.clearCloudEditMode = clearCloudEditMode;

// v2.160.46: bind the wizard's LIVE STATUS panel to a specific campaign, so OPEN
// (edit or read-only) shows THAT campaign's card — never a previously-viewed one
// (bug: opening "…_b" still showed "…_a" at the bottom).
// v2.160.51: also KEEP that campaign's log on display — force the Live Status
// section open (liveStatusForcedOpen) and expand it, so the opened campaign's log
// is always visible at the bottom of the wizard, under section 6 (Launch).
function _bindLiveStatusToCampaign(id) {
  try { stopViewingCloudCampaign(); } catch (_) { /* nothing bound yet */ }
  _viewingCloudId = id;
  liveStatusForcedOpen = true;
  Promise.resolve(_refreshCloudActiveStatus(id)).catch(() => {}).then(() => {
    setTimeout(() => {
      if (_viewingCloudId !== id) return; // superseded by another open
      try { renderActiveCard(window.__cloudActiveStatus); } catch (_) { /* */ }
      try { syncLiveStatusVisibility(); } catch (_) { /* */ }
      try { placeLiveCard(); } catch (_) { /* */ }
      // Expand the section on open so the log is on display, not tucked away.
      const sec = document.getElementById('nav-status');
      if (sec) sec.classList.remove('collapsed');
    }, 180);
  });
  _startCloudCardPoll();
}

// v2.160.46: OPEN on an ACTIVE (running/paused/monitoring) cloud campaign → the
// setup wizard, prefilled but READ-ONLY. To edit, the operator stops it from the
// dashboard (→ Stopped, which OPEN then edits). No pause/redispatch path here.
async function openRunningCampaignReadOnly(id) {
  let d = null;
  try {
    const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/launch-config`);
    if (r.ok) d = await r.json();
  } catch (_) { /* fall through to best-effort */ }
  const _it = (_boardItemsById && _boardItemsById.get(id)) || (_snItemsById && _snItemsById.get(id));
  const displayName = (_it && _it.name) || (d && d.name) || '';
  const mode = (d && d.config && d.config.mode) || (_it && _it.mode) || '';
  try { clearActiveDraft(); } catch (_) { /* viewing a live campaign, not a draft */ }
  _cloudEdit = { cloudId: id, name: displayName, paused: false, readOnly: true };
  _wireReadOnlyEditGuard();
  // Win the name-restore race the same way openCampaignForEdit does.
  window._openEditNameOverride = displayName;
  const nameInput = document.getElementById('campaign-name-input');
  if (nameInput) nameInput.value = displayName;
  if (d && d.config && typeof applyPresetConfig === 'function') {
    applyPresetConfig(d.config);
  } else {
    const select = document.getElementById('campaign-mode');
    if (select && mode) { select.value = mode; if (typeof onModeChange === 'function') onModeChange(); }
  }
  goCreateCampaign();
  // v2.160.47: this is a VM campaign — reflect Cloud VM, not This machine.
  try { if (typeof setRunTarget === 'function') setRunTarget('cloud'); } catch (_) { /* */ }
  _renderCloudEditBanner();
  _setCloudEditLock(true);
  _bindLiveStatusToCampaign(id);
  // The invariants above (Cloud VM run-target, Live Status section bound + open,
  // fields locked) get clobbered by async events that fire AFTER this synchronous
  // setup: goCreateCampaign() set location.hash='#/new', whose deferred hashchange
  // handler (applyRoute) + the wizard/status pollers run next and re-render off the
  // LOCAL status. Rather than chase each clobber, re-assert idempotently — now, and
  // again after those deferred events have run. The 5s cloud-card poll + wizard
  // route entry also re-assert (see _startCloudCardPoll, applyRoute).
  _enforceCloudReadOnlyView();
  [120, 600, 1500].forEach((ms) => setTimeout(() => { try { _enforceCloudReadOnlyView(); } catch (_) { /* */ } }, ms));
}
window.openRunningCampaignReadOnly = openRunningCampaignReadOnly;

// Re-assert the cloud read-only view's invariants idempotently. No-op unless we're
// actually viewing a cloud campaign read-only. Called on open, on wizard route
// entry, and on every cloud-card poll tick so the view can't drift back to a
// "This machine / no Live Status" state after an async re-render.
function _enforceCloudReadOnlyView() {
  if (!(_viewingCloudId && _cloudEdit && _cloudEdit.readOnly)) return;
  // Only reset the run-target on actual drift so the 5s poll doesn't needlessly
  // re-render the wizard (setRunTarget → refreshRunTarget cascade).
  try {
    if (typeof getRunTarget === 'function' && typeof setRunTarget === 'function' && getRunTarget() !== 'cloud') setRunTarget('cloud');
  } catch (_) { /* */ }
  liveStatusForcedOpen = true;
  try { if (typeof syncLiveStatusVisibility === 'function') syncLiveStatusVisibility(); } catch (_) { /* */ }
  try { _setCloudEditLock(true); } catch (_) { /* */ }
}
window._enforceCloudReadOnlyView = _enforceCloudReadOnlyView;

// v2.160.46: while an active campaign is open read-only, any attempt to touch a
// field tells the operator to stop it first. The fields are already disabled
// (_setCloudEditLock), so this fires on the surrounding cards/labels/gaps; the
// banner is the always-visible backstop. Throttled so it toasts once per burst.
let _readOnlyToastAt = 0;
function _wireReadOnlyEditGuard() {
  const root = document.getElementById('wizard-view');
  if (!root || root._readOnlyGuardWired) return;
  root._readOnlyGuardWired = true;
  root.addEventListener('mousedown', (e) => {
    if (!(_cloudEdit && _cloudEdit.readOnly)) return;
    if (e.target.closest('#wizard-cloud-edit-banner') || e.target.closest('.wizard-back-row') || e.target.closest('.back-link') || e.target.closest('#nav-status')) return;
    try { if (_acctAdd && (e.target.closest('#nav-accounts') || e.target.closest('#wizard-acct-add-banner'))) return; } catch (_) { /* */ }
    if (!e.target.closest('.mode-card, input, select, textarea, button, label, #mode-grid, .launch-actions')) return;
    const now = (window.performance && performance.now) ? performance.now() : 0;
    if (now - _readOnlyToastAt < 1200) return;
    _readOnlyToastAt = now;
    if (typeof showCampaignToast === 'function') showCampaignToast('This campaign is active — stop it from the dashboard to edit its configuration.', 3800);
  }, true);
}

// OPEN on a STOPPED / cancelled / done cloud campaign → the setup wizard,
// prefilled with its saved launch config (same name at the top, campaign type,
// message, accounts, sheet, delays…), FULLY editable. Launching starts a fresh
// campaign with the (possibly edited) config; the original is left as-is. The
// unique-name rule runs at launch, so re-running the same name auto-suffixes.
// Campaigns launched before the launch-config snapshot existed fall back to the
// live view.
async function openCampaignForEdit(id) {
  let d = null;
  try {
    const r = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/launch-config`);
    if (r.ok) d = await r.json();
  } catch (_) { /* fall through to live view */ }
  // Prefer the name/type shown on the board strip (what the operator actually
  // clicked); fall back to the saved launch-config snapshot.
  const _it = (_boardItemsById && _boardItemsById.get(id)) || (_snItemsById && _snItemsById.get(id));
  const displayName = (_it && _it.name) || (d && d.name) || '';
  const mode = (d && d.config && d.config.mode) || (_it && _it.mode) || '';

  // v2.160.42 bug fix: entering the wizard (#/new) fires syncCampaignNameInput(),
  // whose async /api/draft-name + localStorage fallbacks resolve AFTER we set the
  // name and would clobber it with the *previously* opened campaign's name (e.g.
  // opening "OPiii" showed the earlier "ASII_Inmail"). A one-shot override makes
  // syncCampaignNameInput honor the opened campaign's name and win that race;
  // localStorage is seeded too so a Cmd+R on the wizard keeps this name.
  const _seedName = () => {
    window._openEditNameOverride = displayName;
    try { localStorage.setItem('campaignName', displayName); } catch (_) { /* private mode */ }
    const ni = document.getElementById('campaign-name-input');
    if (ni) ni.value = displayName;
  };

  if (d && d.config) {
    // Full snapshot → prefill the whole wizard from it.
    try { clearCloudEditMode(); } catch (_) { /* not in running-edit lock mode */ }
    try { clearActiveDraft(); } catch (_) { /* editing a finished campaign, not a draft */ }
    _seedName();
    if (typeof applyPresetConfig === 'function') applyPresetConfig(d.config);
    goCreateCampaign();
  } else {
    // No snapshot — an older campaign launched before configs were recorded.
    // We can't recover its message/delays/sheet, but we DO know its name + type
    // from the board, so best-effort: a clean wizard seeded with name + type,
    // everything else blank. startNewCampaign() clears every stale field and
    // spawns a fresh draft; then we re-assert this campaign's name + type.
    try { clearCloudEditMode(); } catch (_) { /* */ }
    await startNewCampaign();
    _seedName();
    const select = document.getElementById('campaign-mode');
    if (select && mode) { select.value = mode; if (typeof onModeChange === 'function') onModeChange(); }
  }
  // Lock the campaign type — an existing campaign's type is fixed; everything
  // else stays editable. Runs last so it survives any nav-triggered re-render.
  if (mode) lockCampaignType(mode);
  // Editing an existing campaign → the save action becomes "Save changes"
  // (writes the edits back onto this campaign; it stays in the Stopped section).
  _editingExistingCampaign = true;
  _editingCampaignId = id;
  _updateSaveButtonLabel();
  // v2.160.47: a cloud campaign re-opened for edit should default back to the
  // Cloud VM (else a re-launch would silently run on This machine).
  if (_it && _it.where === 'cloud') {
    try { if (typeof setRunTarget === 'function') setRunTarget('cloud'); } catch (_) { /* */ }
  }
  // v2.160.46: bind the LIVE STATUS panel to THIS campaign so it shows the one
  // just opened (not a previously-viewed campaign leaking in from below).
  _bindLiveStatusToCampaign(id);
}
window.openCampaignForEdit = openCampaignForEdit;

// ── Unique campaign names within "Your campaigns" ───────────────────────────
// Names of the viewer's OWN non-FG campaigns from the last board render — the
// set a new/edited campaign must be unique against.
function _existingMineCampaignNames() {
  const out = [];
  try {
    for (const it of (_snItemsById ? _snItemsById.values() : [])) {
      if (it && it.mine && !it.isFG && it.name) out.push(String(it.name).trim());
    }
  } catch (_) { /* best-effort */ }
  return out;
}
// Spreadsheet-style letter increment: a→b, z→aa, az→ba.
function _incSeq(s) {
  if (!s) return 'a';
  const arr = s.split(''); let i = arr.length - 1;
  while (i >= 0) {
    if (arr[i] === 'z') { arr[i] = 'a'; i--; } else { arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1); break; }
  }
  if (i < 0) arr.unshift('a');
  return arr.join('');
}
// Return `desired` if free; else append/bump a `_<letters>` suffix until unique.
// "MESSAGE" → "MESSAGE_a"; an existing "…_d" bumps to "…_e".
function _uniqueCampaignName(desired, taken) {
  const raw = String(desired || '').trim();
  if (!raw) return raw; // empty name is allowed (row shows "Add name")
  const set = new Set((taken || []).map((n) => String(n).trim().toLowerCase()));
  if (!set.has(raw.toLowerCase())) return raw;
  const m = raw.match(/^(.*)_([a-z]+)$/i);
  const base = m ? m[1] : raw;
  let seq = m ? _incSeq(m[2].toLowerCase()) : 'a';
  let candidate = `${base}_${seq}`;
  while (set.has(candidate.toLowerCase())) { seq = _incSeq(seq); candidate = `${base}_${seq}`; }
  return candidate;
}

async function _submitCloudEditRedispatch(body) {
  const id = _cloudEdit && _cloudEdit.cloudId;
  if (!id) return;
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/edit-redispatch`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const txt = await res.text();
    let data; try { data = JSON.parse(txt); } catch { data = { error: txt }; }
    if (!res.ok || data.error) {
      alert(`Could not save edits:\n\n${data.error || txt}`);
      return;
    }
    clearCloudEditMode();
    if (typeof showCampaignToast === 'function') showCampaignToast(`☁︎ Edits saved — ${data.leadsAdded} remaining lead(s) redispatched with the new settings.`, 6000);
    if (data.id) { try { await openCloudLive(data.id); } catch (_) { /* board still shows it */ } }
  } catch (e) {
    alert('Could not save edits: ' + e.message);
  }
}

// Restart a STOPPED/CANCELLED local campaign from its saved settings snapshot.
// fromStart=false → Continue (seed resumeContext so the counter picks up where it
// left off; the sheet's already-sent rows are skipped). fromStart=true → Restart
// from the beginning (counter resets to 0; the sheet STILL skips already-done
// rows, so no double-outreach). Reuses the exact /api/campaign/start path the
// resume flow uses — no new backend.
async function restartLocalFromItem(id, fromStart) {
  const it = _boardItemsById.get(id);
  if (!it || !it.srcSettings) {
    if (typeof showCampaignToast === 'function') showCampaignToast('No saved settings for this campaign — use Duplicate instead.', 5000);
    return;
  }
  const s = it.srcSettings;
  const payload = {
    profileIds: Array.isArray(s.profileIds) ? s.profileIds : [],
    sheetUrl: s.sheetUrl || '',
    templates: s.templates || {},
    dailyLimit: s.dailyLimit ?? 50,
    mode: it.mode,
    messageOpenProfiles: !!s.messageOpenProfiles,
    delayMin: s.delayMin ?? 30,
    delayMax: s.delayMax ?? 60,
    linkedinColumn: s.linkedinColumn || '',
    concurrency: s.concurrency ?? 1,
    name: it.name || '',
    checkIntervalMinutes: s.checkIntervalMinutes,
    autoChecksEnabled: s.autoChecksEnabled,
  };
  if (!fromStart) {
    payload.resumeContext = { totalProcessed: Number(it.hist && (it.hist.totalProcessed || it.hist.successCount)) || 0 };
  }
  try {
    const r = await fetch('/api/campaign/start', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!r.ok) {
      const err = await r.text().catch(() => '');
      if (typeof showCampaignToast === 'function') showCampaignToast(`Restart failed: ${err || r.statusText}`, 6000);
      return;
    }
    if (typeof showCampaignToast === 'function') showCampaignToast(fromStart ? 'Restarted from the beginning — already-done rows are skipped.' : 'Continuing where it left off…', 4500);
    if (typeof startPolling === 'function') startPolling();
    if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  } catch (e) {
    if (typeof showCampaignToast === 'function') showCampaignToast(`Restart failed: ${e.message}`, 6000);
  }
}
window.restartLocalFromItem = restartLocalFromItem;

// Restart a STOPPED/CANCELLED/ERRORED cloud campaign — re-activates the SAME
// record on the engine (status → running; leads already sent carry sentAt and
// are skipped). Both buttons hit the same endpoint; fromStart is passed for
// parity (the engine skips done leads either way). Degrades gracefully with a
// clear toast until the engine ships /restart (404).
// startAt (ISO, optional): schedule the restart instead of running it now. The
// engine parks the campaign in 'scheduled' behind a durable task and restarts it
// itself at that instant — this app can be closed.
async function restartCloudCampaignUI(id, fromStart, startAt) {
  try {
    // Carry the wizard's (possibly edited) daily limit so a change made while the
    // campaign was stopped actually takes effect on the engine when it restarts.
    const dlRaw = parseInt(document.getElementById('daily-limit')?.value, 10);
    const dailyLimit = Number.isFinite(dlRaw) && dlRaw > 0 ? dlRaw : undefined;
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/restart`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ fromStart: !!fromStart, ...(dailyLimit ? { dailyLimit } : {}), ...(startAt ? { startAt } : {}) }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      if (typeof showCampaignToast === 'function') showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Restart isn’t live yet — engine update pending.', 6000);
      return;
    }
    if (d.alreadyRunning) {
      if (typeof showCampaignToast === 'function') showCampaignToast('Already sending — nothing to resume.', 4000);
      return;
    }
    if (d.scheduled) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast(`⏰ Scheduled on the VM for ${_fmtCloudStartAt(d.startAt)} — ${d.pending || 0} lead(s) waiting. The laptop can stay shut.`, 7000);
      }
      _pushCloudEvent(id, `⏰ Scheduled to restart ${_fmtCloudStartAt(d.startAt)}`);
      window.location.hash = '#/'; // back to the dashboard, where it shows as Scheduled
      if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
      return;
    }
    const left = Number(d.pending) || 0;
    if (typeof showCampaignToast === 'function') {
      showCampaignToast(fromStart ? 'Restarting the cloud campaign from the beginning…'
        : `Resuming — the VM will send the ${left ? `${left} remaining` : 'remaining'} lead(s).`, 4500);
    }
    _pushCloudEvent(id, fromStart ? '▶️ Started (from the beginning)' : '▶️ Started (continuing where it left off)');
  } catch (e) {
    if (typeof showCampaignToast === 'function') showCampaignToast('Could not reach the engine: ' + e.message, 6000);
    return;
  }
  if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
  if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
}
window.restartCloudCampaignUI = restartCloudCampaignUI;

// Task 3 Part B — cloud monitoring controls (parity with local ⚡ Check now /
// Automatic checks). Degrade gracefully until the engine ships the routes: a
// 404/HTTP error → a clear "engine update pending" toast, no throw.
async function cloudCheckNow(id, btn, scope) {
  scope = scope === 'all' ? 'all' : 'campaign';
  if (btn) btn.disabled = true;
  let queued = false;
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/check-now`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ scope }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Check now isn’t live yet — engine update pending.', 6000);
    } else {
      queued = true;
      _pushCloudEvent(id, scope === 'all' ? '⚡ Check now — every account in the Account Used column' : '⚡ Check now — this campaign’s accounts');
      showCampaignToast(scope === 'all'
        ? '⚡ Check queued — the VM will sweep every account in the sheet’s Account Used column…'
        : '⚡ Check queued — the VM is opening a browser to sweep… (takes ~10s)', 4500);
    }
  } catch (e) { showCampaignToast('Could not reach the engine: ' + e.message, 6000); }
  finally { if (btn) btn.disabled = false; }
  if (!queued) return;

  // Real feedback tied to the actual browser (fixes "no indication when it
  // starts / no logs"): poll the live flag so the operator SEES the sweep begin
  // ("VM checking now") and finish, instead of silence. The VM opens a browser
  // for only a few seconds, so this narrates that short window.
  (async () => {
    let sawLive = false;
    for (let i = 0; i < 40; i++) {                 // ~60s
      await new Promise((r) => setTimeout(r, 1500));
      let dd = {};
      try { dd = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`)).json(); } catch { /* */ }
      if (dd.live && !sawLive) {
        sawLive = true;
        showCampaignToast('🟢 VM checking now — browser is open. Click 👁 Show to watch it live.', 6000);
      } else if (!dd.live && sawLive) {
        showCampaignToast('✓ VM check complete.', 4000);
        if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
        return;
      }
    }
    if (!sawLive) showCampaignToast('VM check ran, but no browser opened — it may already be up to date, or a check was already in progress. Try again in a moment.', 7000);
  })();
}
window.cloudCheckNow = cloudCheckNow;

// Local check of a CLOUD campaign (v2.160.87) — runs the app's OWN GoLogin
// sweep (/api/bulk-check-now — the exact engine local campaigns use: opens each
// account's browser here, stamps Connected, fires intros where Introduction
// Status is blank) against the cloud campaign's sheet. Accounts whose GoLogin
// profile can't open on this machine are skipped and reported, never fatal.
// Afterwards, mirrors the sheet's statuses into the engine (fill-only) so the
// VM's next sweep won't double-intro anyone this local check already handled.
async function cloudCheckLocal(id, btn, scope) {
  if (!id) return;
  scope = scope === 'all' ? 'all' : 'campaign';
  if (btn) btn.disabled = true;
  showCampaignToast('🖥 Local check starting — opening GoLogin browsers on this machine. Keep the app open…', 7000);
  _pushCloudEvent(id, scope === 'all'
    ? '🖥 Local check — every account in the Account Used column (on this machine)'
    : '🖥 Local check — this campaign’s accounts (on this machine)');
  try {
    const d = await (await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}`)).json();
    const camp = d && d.campaign;
    if (!camp || !camp.sheet_url) {
      showCampaignToast('Could not load this campaign (or its sheet) from the engine.', 7000);
      return;
    }
    const cfg = camp.config || {};
    const body = {
      sheetUrl: camp.sheet_url,
      linkedinColumn: cfg.linkedinColumn || '',
      // The local `campaign` singleton may hold an unrelated config — pass the
      // CLOUD campaign's mode + templates so the sweep behaves identically to a
      // local campaign configured the same way.
      mode: camp.mode,
      primaryName: cfg.primaryName || '',
      primaryIntroBody: cfg.primaryIntroBody || '',
      primaryUrl: cfg.primaryUrl || '',
      introTitle: cfg.introTitle || '',
      autoAcceptPrimary: cfg.autoAcceptPrimary,
      primarySource: cfg.primarySource,
      ccDmBody: cfg.ccDmBody || '',
      senderFirstNames: cfg.senderFirstNames || {},
    };
    if (scope === 'all') body.allSenders = true;
    else body.profileIds = camp.profile_ids || camp.profileIds || [];
    const res = await fetch('/api/bulk-check-now', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const j = await res.json().catch(() => ({}));
    if (!res.ok || j.error) {
      showCampaignToast('Local check failed: ' + (j.error || `HTTP ${res.status}`), 9000);
      return;
    }
    const per = Array.isArray(j.perProfile) ? j.perProfile : [];
    const failed = per.filter((p) => p && p.error);
    const okCount = per.length - failed.length;
    const matched = (j.result && j.result.matched) || 0;
    // Write-back: mirror the sheet's statuses into the engine (fill-only there)
    // so a later VM check never re-introduces someone this check handled.
    let synced = 0;
    try {
      const sr = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/sync-sheet-status`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ linkedinColumn: cfg.linkedinColumn || '' }),
      });
      const sj = await sr.json().catch(() => ({}));
      if (sr.ok && !sj.error) synced = sj.matched || 0;
    } catch { /* best-effort — the sheet already has the truth */ }
    const bits = [`${okCount}/${per.length} account${per.length === 1 ? '' : 's'} checked`, `${matched} newly Connected`];
    if (failed.length) bits.push(`${failed.length} couldn’t open on this machine (skipped)`);
    if (synced) bits.push(`${synced} lead${synced === 1 ? '' : 's'} synced to the engine`);
    showCampaignToast(`🖥 Local check done — ${bits.join(' · ')}.`, 12000);
    _pushCloudEvent(id, `🖥 Local check done — ${bits.join(' · ')}`);
    if (typeof renderCloudCampaigns === 'function') renderCloudCampaigns();
    if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard();
  } catch (e) {
    showCampaignToast('Local check failed: ' + e.message, 9000);
  } finally {
    if (btn) btn.disabled = false;
  }
}
window.cloudCheckLocal = cloudCheckLocal;

// Cloud "Run check now" → first ask the same scope question the local check asks:
// this campaign's accounts, or every account in the sheet's "Account Used" column.
// Reuses the shared solo-check scope modal; maps its 'sheet' choice to the engine's
// 'all' scope (Account Used column) and 'campaign' to this campaign's accounts.
function promptCloudCheckScope(id, btn) {
  if (!id) return;
  // Two-step prompt (v2.160.87): scope (this campaign / all senders), THEN
  // where (cloud VMs / this machine). 'local' runs the app's own GoLogin sweep
  // — the exact engine local campaigns use — against this cloud campaign.
  _soloCheckHandler = (mode) => {
    const scope = mode === 'sheet' ? 'all' : 'campaign';
    _checkWhereHandler = (where) => (where === 'local'
      ? cloudCheckLocal(id, btn, scope)
      : cloudCheckNow(id, btn, scope));
    _showCheckWhereModal();
  };
  _showSoloCheckModal();
}
window.promptCloudCheckScope = promptCloudCheckScope;

async function setCloudAutoChecks(id, enabled, el) {
  try {
    const res = await fetch(`/api/campaign/cloud/${encodeURIComponent(id)}/auto-checks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: !!enabled }),
    });
    const d = await res.json().catch(() => ({}));
    if (!res.ok || d.error) {
      showCampaignToast(d.error && !/HTTP 404/.test(d.error) ? d.error : 'Auto-checks toggle isn’t live yet — engine update pending.', 6000);
      if (el) el.checked = !enabled; // revert the switch — the change didn't stick
    } else {
      showCampaignToast(`Automatic checks ${enabled ? 'on' : 'off'}.`, 4000);
    }
  } catch (e) { showCampaignToast('Could not reach the engine: ' + e.message, 6000); if (el) el.checked = !enabled; }
}
window.setCloudAutoChecks = setCloudAutoChecks;

// Start/stop polling when the Cloud Campaigns section is opened/closed.
window.onCloudSectionToggle = function onCloudSectionToggle() {
  const section = document.getElementById('cloud-campaigns-section');
  const open = section && !section.classList.contains('collapsed');
  if (_cloudPollTimer) { clearInterval(_cloudPollTimer); _cloudPollTimer = null; }
  if (open) { renderCloudCampaigns(); _cloudPollTimer = setInterval(renderCloudCampaigns, 8000); }
};

async function _runIcPreflight(sheetUrl, senderColumn) {
  try {
    const res = await fetch('/api/campaign/preflight-ic-senders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sheetUrl, senderColumn: senderColumn || '' }),
    });
    const data = await res.json();
    if (data.error) {
      alert(`Could not validate sender column:\n\n${data.error}`);
      return false;
    }
    if (data.ok) return true;
    _showIcPreflightModal(data);
    return false;
  } catch (err) {
    alert(`Preflight check failed: ${err.message}`);
    return false;
  }
}

function _showIcPreflightModal(data) {
  const modal = document.getElementById('ic-preflight-modal');
  const title = document.getElementById('ic-preflight-title');
  const bodyEl = document.getElementById('ic-preflight-body');
  const primary = document.getElementById('ic-preflight-primary');
  const secondary = document.getElementById('ic-preflight-secondary');
  if (!modal || !title || !bodyEl || !primary || !secondary) return;

  modal.dataset.reason = data.reason || '';

  if (data.reason === 'no_column') {
    title.textContent = 'No sender column selected';
    bodyEl.innerHTML =
      `<p>All ${data.totalRows} rows in your sheet have a blank sender value.</p>` +
      `<p style="color: var(--gray); font-size: 0.85rem; margin-top: 10px;">` +
      `Pick the column that contains the LinkedIn 1st connections in Section 2, then try again.</p>`;
    primary.textContent = 'Take me to the column picker';
    secondary.classList.add('hidden');
  } else {
    // no_match
    const list = (data.unmatched || []).map(u =>
      `<li><code>${escHtml(u.name)}</code> &mdash; ${u.count} row${u.count === 1 ? '' : 's'}</li>`
    ).join('');
    const extra = (data.unmatched || []).length === 5 ? ' (top 5 shown)' : '';
    title.textContent = 'No matching GoLogin profile';
    bodyEl.innerHTML =
      `<p>Your sheet has sender values, but none match a GoLogin profile in this workspace.</p>` +
      (list ? `<ul style="margin: 12px 0 0; padding-left: 20px; font-size: 0.85rem; color: var(--ink);">${list}</ul>` : '') +
      `<p style="color: var(--gray); font-size: 0.8rem; margin-top: 10px;">` +
      `${data.totalRows} total row${data.totalRows === 1 ? '' : 's'}${extra}. Check that the Sender column values exactly match your GoLogin profile display names (case-sensitive).</p>`;
    primary.textContent = 'Open sheet to fix';
    secondary.classList.remove('hidden');
  }

  modal.classList.remove('hidden');
}

function closeIcPreflightModal() {
  const modal = document.getElementById('ic-preflight-modal');
  if (modal) modal.classList.add('hidden');
}

function _icPreflightPrimary() {
  const modal = document.getElementById('ic-preflight-modal');
  const reason = modal?.dataset?.reason || '';
  closeIcPreflightModal();
  if (reason === 'no_match') {
    // Open the sheet so the operator can fix the Sender column values
    if (typeof openSheetInBrowser === 'function') openSheetInBrowser();
  } else {
    // no_column → scroll + focus the IC column dropdown
    _icPreflightScrollToColumnPicker();
  }
}

function _icPreflightSecondary() {
  closeIcPreflightModal();
  _icPreflightScrollToColumnPicker();
}

// v2.58.x — Called from the IC sender-column dropdown's onchange. Marks
// the picker as "manually chosen" so subsequent previewSheet() runs don't
// stomp on the operator's pick, and hides the gold "Auto-detected" badge.
function _icSenderColManualPick() {
  const sel = document.getElementById('ic-sender-col-select');
  const badge = document.getElementById('ic-auto-detected-badge');
  if (sel) {
    sel.dataset.manualPick = '1';
    sel.classList.remove('is-detected');
  }
  if (badge) badge.classList.add('hidden');
}

function _icPreflightScrollToColumnPicker() {
  const sel = document.getElementById('ic-sender-col-select');
  if (!sel) {
    // The IC extras block is rendered by previewSheet(); if not present,
    // scroll to the sheet section so the operator can press Preview first.
    document.getElementById('nav-sheet')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }
  sel.scrollIntoView({ behavior: 'smooth', block: 'center' });
  setTimeout(() => sel.focus(), 350);
}

// Cloud dispatch: run the campaign on the GKE engine instead of locally. Fully
// self-contained + returns early, so the local path below is untouched. The
// ── Launch-in-progress live state (Path A) ──────────────────────────────────
// Between pressing Start on a cloud CC+IC campaign and the engine acknowledging
// the dispatch, two slow steps run with NO campaign row existing anywhere: the
// local primary handshake (minutes — it drives a GoLogin browser per sender) and
// the start-cloud POST (reads the whole lead sheet, builds leads). The handshake
// modal covered the first step and nothing covered the second.
//
// Operator report 2026-08-06: "that handshake disappeared and it was with nothing
// for two minutes… I went back to the dashboard and it says it's just still a
// draft. The hell?" — the draft row is only deleted once start-cloud returns, so
// the board legitimately still showed a draft while the launch was in flight.
//
// Fix: publish the launch as a live state on BOTH surfaces the operator watches —
// the shared #active-card (card #1 on the dashboard / card #2 in the campaign
// tab; one element, relocated by placeLiveCard) and a board strip. Neither needs
// new markup: the card reuses its gold `is-preflight` state (v2.105) and the
// strip reuses the `awaiting_primary_accept` handshake panel.
let _cloudLaunch = null;

// handshake sender state → the pf-list vocabulary renderActiveCard already
// speaks. `error` maps to 'unverified' rather than a hard failure: the operator
// can still Dispatch anyway, and the row should read as unconfirmed, not dead.
const _HS_STATE_TO_PF = {
  pending: 'pending', connecting: 'pending', sent: 'sent',
  'sent-no-identity': 'sent', accepting: 'accepting', connected: 'connected',
  error: 'unverified',
};

// `handshake:false` (every cloud mode except CC+IC-with-local-primary) skips
// straight to the dispatch phase — those launches have no per-sender step, and
// claiming a "Primary handshake" that never runs would be a worse lie than the
// blank screen this replaces.
function beginCloudLaunch({ name, profileIds, handshake = true } = {}) {
  _cloudLaunch = {
    phase: handshake ? 'handshake' : 'dispatching',
    hasHandshake: !!handshake,
    name: name || 'New campaign',
    // 'local-browser' is the primary itself, not a sender — it never appears as
    // a handshake row (same filter the pf-list renderer applies).
    profileIds: (profileIds || []).filter((id) => id && id !== 'local-browser'),
    conn: {},
    startedAt: Date.now(),
  };
  paintCloudLaunch();
}

// The handshake wizard's poll snapshot → our per-sender map. Same data the modal
// paints, so the modal and the two cards can never disagree.
function updateCloudLaunchSenders(senders) {
  if (!_cloudLaunch || !Array.isArray(senders)) return;
  for (const s of senders) {
    if (s && s.profileId) _cloudLaunch.conn[s.profileId] = s.state;
  }
  paintCloudLaunch();
}

// 'handshake' → 'dispatching'. The second phase has no per-sender progress to
// show (the app is reading the sheet and POSTing), so the rows freeze at their
// final handshake state and the copy changes instead.
function setCloudLaunchPhase(phase) {
  if (!_cloudLaunch) return;
  _cloudLaunch.phase = phase;
  paintCloudLaunch();
}

function endCloudLaunch() {
  if (!_cloudLaunch) return;
  _cloudLaunch = null;
  // Repaint both surfaces once more so the synthetic strip/card are replaced by
  // the real campaign (or by the idle state if the launch was cancelled).
  paintCloudLaunch();
}

// The synthetic status object. Shaped for renderActiveCard's `is-preflight`
// branch: phase 'preflight' + primaryConn/profileIds/profileNames.
function cloudLaunchStatus() {
  const L = _cloudLaunch;
  if (!L) return null;
  const nameOf = (id) => (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || id;
  const primaryConn = {};
  for (const id of L.profileIds) primaryConn[id] = _HS_STATE_TO_PF[L.conn[id]] || 'pending';
  const doneN = L.profileIds.filter((id) => primaryConn[id] === 'connected').length;
  return {
    running: true, paused: false, state: 'preflight', phase: 'preflight',
    mode: 'connect_and_introduce',
    name: L.name,
    profileIds: L.profileIds.slice(),
    profileNames: L.profileIds.map(nameOf),
    primaryConn,
    totalTargets: 0, totalProcessed: 0, acceptedCount: '—',
    logs: [], skippedCount: 0,
    preflightL1: L.phase === 'handshake'
      ? 'Sending connections to the primary account'
      : 'Handing the campaign over to the VM',
    preflightSub: L.phase !== 'handshake'
      ? (L.hasHandshake
        ? 'Handshake done — reading your lead sheet and handing the campaign to the VM…'
        : 'Reading your lead sheet and dispatching to the VM…')
      : `${doneN} of ${L.profileIds.length} connected · your Mac is doing this locally, then the campaign moves to the cloud.`,
    _launching: true,
  };
}

// Repaint the card and the board immediately rather than waiting for their 2s /
// 4s polls — during a launch those polls have nothing new to say anyway.
function paintCloudLaunch() {
  try { if (typeof window.renderActiveCard === 'function') window.renderActiveCard(null); } catch (_) { /* */ }
  try { if (typeof renderCampaignsBoard === 'function') renderCampaignsBoard(); } catch (_) { /* */ }
}

// The board strip for a launch-in-flight. Same normalized item shape the board
// builds for real campaigns, plus `launching` (suppresses every control — there
// is nothing on the VM yet to stop, pause or watch) and the `senders` /
// `awaiting_primary_accept` pair the strip's handshake panel already renders.
function cloudLaunchBoardItem() {
  const L = _cloudLaunch;
  if (!L) return null;
  const nameOf = (id) => (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || id;
  return {
    where: 'cloud', id: '__launching__', rawId: '__launching__',
    name: L.name, mode: 'connect_and_introduce', isFG: false,
    bucket: 'running', sent: 0, total: 0, accounts: L.profileIds.length,
    mine: true, owner: '', live: false, launching: true,
    launchPhase: L.phase,
    // Only a real handshake gets the handshake panel; a plain cloud launch falls
    // through to the normal strip body with the "handing over" status text.
    state: L.hasHandshake ? 'awaiting_primary_accept' : '',
    senders: L.profileIds.map((id) => ({
      name: nameOf(id),
      accepted: L.conn[id] === 'connected',
    })),
  };
}

// ── Cloud primary-handshake wizard (Path A) ─────────────────────────────────
// Before a cloud CC+IC campaign with a LOCAL-ONLY primary is dispatched, the app
// connects each GoLogin sender to the primary and accepts the invites in the
// local primary browser (the engine can't — no operator Chrome on the VM). This
// modal shows live per-sender progress by polling the status endpoint. Resolves
// { ok:true } on success, { ok:false, proceedAnyway:true } if the operator
// dispatches without the handshake, or { ok:false, proceedAnyway:false } on
// Cancel (dispatch is aborted). See feedback_two_live_status_cards / the Path A
// spec (docs/superpowers/specs/2026-07-11-cloud-handshake-path-a-...).
function _hsRowIconHtml(view) {
  if (view.icon === 'check') return '<span class="chk">✓</span>';
  if (view.icon === 'x') return '<span class="chk" style="color:#b23b3b">✕</span>';
  if (view.icon === 'spin') return '<span class="dotwait" style="background:var(--gold)"></span>';
  if (view.icon === 'dot') return '<span class="dotwait" style="background:var(--ink)"></span>';
  return '<span class="dotwait"></span>';
}
function runHandshakeWizard({ senderProfileIds = [], primaryUrl, primarySource = 'local-browser', autoAcceptAllPending = false }) {
  return new Promise((resolve) => {
    const nameOf = (id) => (typeof selectedProfileNames !== 'undefined' && selectedProfileNames && selectedProfileNames[id]) || id;
    const total = senderProfileIds.length;
    const back = document.createElement('div');
    back.className = 'modal-backdrop';
    back.innerHTML = `
      <div class="modal-card" role="dialog" aria-modal="true" aria-label="Connecting senders to the primary">
        <h3 class="modal-title">🤝 Connecting your senders to the primary</h3>
        <div class="modal-body">
          <div class="hs-panel">
            <div class="hs-eyebrow"><span class="lk">🔒</span> Phase 0 · Primary handshake<span class="cnt"><span class="hs-wiz-count">0</span> / ${total}</span></div>
            <div class="hs-head">Your Mac connects each sender to the primary, then accepts the invites in your local browser. The campaign moves to the cloud as soon as this finishes.</div>
            <div class="hs-bar"><i class="hs-wiz-bar" style="width:0%"></i></div>
            <div class="hs-list hs-wiz-list">
              ${senderProfileIds.map((id) => `<div class="hs-row" data-hid="${escHtml(String(id))}"><span class="ic"><span class="dotwait"></span></span><span class="who">${escHtml(nameOf(id))}</span><span class="st">Waiting</span></div>`).join('')}
            </div>
            <div class="hs-keep">◈ Keep this app open — this is the only local step this campaign needs.</div>
          </div>
          <div class="hs-wiz-error intro-config-error" hidden style="margin-top:12px"></div>
        </div>
        <div class="modal-actions hs-wiz-actions" style="display:flex; gap:10px; flex-wrap:wrap">
          <button type="button" class="btn btn-primary hs-wiz-retry" style="display:none">Retry</button>
          <button type="button" class="btn hs-wiz-anyway">Dispatch anyway</button>
          <button type="button" class="btn modal-cancel-link hs-wiz-cancel">Cancel</button>
        </div>
      </div>`;
    document.body.appendChild(back);

    const $ = (sel) => back.querySelector(sel);
    let poll = null;
    let done = false;
    const cleanup = () => { if (poll) { clearInterval(poll); poll = null; } try { back.remove(); } catch (_) { /* */ } };
    const finish = (result) => { if (done) return; done = true; cleanup(); resolve(result); };
    // Always dismissable: clicking the scrim cancels (aborts dispatch) so a hung
    // handshake can never trap the operator on a button-less spinner.
    back.addEventListener('click', (e) => { if (e.target === back) finish({ ok: false, proceedAnyway: false }); });

    const paint = (senders) => {
      let connected = 0;
      for (const s of (senders || [])) {
        const view = handshakeRowView(s.state);
        if (view.done) connected++;
        const row = $(`.hs-row[data-hid="${CSS.escape(String(s.profileId))}"]`);
        if (!row) continue;
        row.classList.toggle('done', view.done);
        const ic = row.querySelector('.ic'); if (ic) ic.innerHTML = _hsRowIconHtml(view);
        const st = row.querySelector('.st'); if (st) st.textContent = view.label;
        if (s.name) { const who = row.querySelector('.who'); if (who) who.textContent = s.name; }
      }
      const cnt = $('.hs-wiz-count'); if (cnt) cnt.textContent = String(connected);
      const bar = $('.hs-wiz-bar'); if (bar) bar.style.width = total ? `${Math.round((connected / total) * 100)}%` : '0%';
      // Mirror the same per-sender states onto the card + board so the modal is
      // no longer the ONLY place this is visible — and so closing it (or its
      // 700ms auto-close on success) doesn't drop the operator into a blank UI.
      try { updateCloudLaunchSenders(senders); } catch (_) { /* */ }
    };

    // On error, reveal Retry. When another handshake is already running (409),
    // hide "Dispatch anyway" — dispatching now would run the campaign with
    // un-handshaked senders while the other campaign drives the local browsers.
    const showError = (msg, { is409 = false } = {}) => {
      const err = $('.hs-wiz-error'); if (err) { err.hidden = false; err.textContent = msg; }
      const retry = $('.hs-wiz-retry'); if (retry) retry.style.display = '';
      const anyway = $('.hs-wiz-anyway'); if (anyway) anyway.style.display = is409 ? 'none' : '';
    };

    const start = async () => {
      const err = $('.hs-wiz-error'); if (err) { err.hidden = true; err.textContent = ''; }
      const retry = $('.hs-wiz-retry'); if (retry) retry.style.display = 'none';
      const anyway = $('.hs-wiz-anyway'); if (anyway) anyway.style.display = '';
      try {
        const res = await fetch('/api/campaign/cloud-preflight-handshake', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ senderProfileIds, primaryUrl, primarySource, autoAcceptAllPending }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) { showError(data.error || `Could not start the handshake (${res.status}).`, { is409: res.status === 409 }); return; }
      } catch (e) { showError('Could not reach the app to start the handshake: ' + e.message); return; }

      poll = setInterval(async () => {
        try {
          const snap = await fetch('/api/campaign/cloud-preflight-handshake/status').then((r) => r.json());
          if (snap && snap.active) paint(snap.senders);
          if (snap && snap.done) {
            clearInterval(poll); poll = null;
            if (snap.error) { showError('Handshake error: ' + snap.error); return; }
            // Success — brief beat so the operator sees the ✓s, then dispatch.
            setTimeout(() => finish({ ok: true }), 700);
          }
        } catch (_) { /* transient poll error — keep polling */ }
      }, 800);
    };

    $('.hs-wiz-retry').addEventListener('click', () => start());
    $('.hs-wiz-anyway').addEventListener('click', () => finish({ ok: false, proceedAnyway: true }));
    $('.hs-wiz-cancel').addEventListener('click', () => finish({ ok: false, proceedAnyway: false }));
    start();
  });
}
window.runHandshakeWizard = runHandshakeWizard;

// server reads the sheet into leads and hands off to the engine; the campaign
// then runs in the cloud and survives the laptop closing.
// Re-entrancy guard: a slow multi-account CC+IC start (it runs the primary
// handshake wizard, reads the sheet, builds leads, then POSTs) left the Start
// button looking dead, so operators re-clicked — spawning duplicate campaigns
// over the SAME leads + accounts, which then contended and stranded most leads
// in "pending" (Sam's 3× "Poop" incident, 2026-07-24). Set synchronously before
// the first await so JS's single thread makes it airtight against re-clicks.
let _cloudSubmitInFlight = false;
// "Fri 8 Aug, 09:00" — the operator's own timezone. The engine speaks UTC ISO
// everywhere; nothing operator-facing should.
function _fmtCloudStartAt(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso || '');
  return d.toLocaleString(undefined, { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
}
if (typeof window !== 'undefined') window._fmtCloudStartAt = _fmtCloudStartAt;

async function _submitCloudCampaign(body) {
  if (_cloudSubmitInFlight) return; // ignore re-clicks while a start is dispatching
  _cloudSubmitInFlight = true;
  // Idempotency backstop: a stable id per launch attempt so any duplicated POST
  // (network retry, second app window) collapses to ONE campaign engine-side.
  // The engine dedupes on `id`; the client always documented this — it was just
  // never wired through the server. Belt-and-suspenders on a double-outreach path.
  if (!body.launchId) {
    body.launchId = (globalThis.crypto && crypto.randomUUID)
      ? crypto.randomUUID()
      : ('lnch_' + Date.now() + '_' + Math.random().toString(36).slice(2));
  }
  if (typeof showCampaignToast === 'function') showCampaignToast('☁︎ Starting cloud campaign…', 4000);
  // Publish the launch on the card + board for its WHOLE duration — the
  // handshake AND the dispatch. Cleared in the finally below, by which point
  // either a real campaign row exists or the launch was abandoned.
  beginCloudLaunch({ name: body.name, profileIds: body.profileIds, handshake: needsHandshakeFromBody(body) });
  try {
    // Path A: run the primary handshake locally BEFORE dispatch when this is a
    // cloud CC+IC campaign with auto-accept and a local-only primary. Otherwise
    // the senders never connect to the primary (the engine's connect is lazy and
    // only fires after a lead is accepted — 0 accepted = primary gets nothing).
    if (needsHandshakeFromBody(body)) {
      const t = body.templates || {};
      const hs = await runHandshakeWizard({
        senderProfileIds: body.profileIds || [],
        primaryUrl: t.primaryUrl,
        primarySource: t.primarySource || 'local-browser',
        autoAcceptAllPending: !!t.autoAcceptAllPending,
      });
      if (!hs.ok && !hs.proceedAnyway) return; // operator cancelled → don't dispatch
    }
    // Handshake over (or never needed). The next step reads the whole lead sheet
    // and POSTs — the step that used to be two silent minutes with the modal gone
    // and the board still showing a draft.
    setCloudLaunchPhase('dispatching');
    const res = await fetch('/api/campaign/start-cloud', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const txt = await res.text();
    let data; try { data = JSON.parse(txt); } catch { data = { error: txt }; }
    if (res.status === 409 && txt.includes('OPERATOR_EMAIL_REQUIRED')) {
      openOperatorEmailModal({ mandatory: true }); return;
    }
    if (!res.ok || data.error) {
      alert(`Could not start cloud campaign:\n\n${data.error || txt}`); return;
    }
    // Draft consumed on launch, same as the local path.
    try {
      const draftId = getActiveDraftId();
      if (draftId) await fetch('/api/drafts/' + encodeURIComponent(draftId), { method: 'DELETE' }).catch(() => {});
      clearActiveDraft();
    } catch { /* non-fatal */ }
    // Scheduled on the VM: the engine holds it in 'scheduled' and wakes itself at
    // the chosen time. Nothing is live yet, so there's no live card to open —
    // land back on the dashboard where the campaign shows with its start time.
    if (data.scheduled) {
      if (typeof showCampaignToast === 'function') {
        showCampaignToast(`⏰ Scheduled on the VM for ${_fmtCloudStartAt(data.startAt)} — ${data.leadsAdded} lead(s) loaded. The laptop can stay shut.`, 7000);
      }
      if (typeof goDashboard === 'function') goDashboard();
      return;
    }
    if (typeof showCampaignToast === 'function') showCampaignToast(`☁︎ Cloud campaign started — ${data.leadsAdded} lead(s) dispatched. It keeps running in the cloud even if you close the app.`, 6000);
    // Parity with a local launch: drop straight onto the live status CAMPAIGN
    // card (card #2) for the new VM campaign. See feedback_two_live_status_cards.
    if (data.id) { try { await openCloudLive(data.id); } catch (_) { /* */ } }
  } catch (e) {
    alert('Could not reach the cloud engine:\n\n' + e.message);
  } finally {
    _cloudSubmitInFlight = false;
    // Runs on every exit path — success, cancel, and error — so the synthetic
    // strip/card can never outlive the launch and strand the board.
    endCloudLaunch();
  }
}

async function submitStartCampaign(body, opts = {}) {
  // Cloud edit mode: the wizard is re-launching an EDITED (paused) cloud
  // campaign — divert the body to edit-redispatch instead of a fresh launch.
  if (_cloudEdit && _cloudEdit.paused) return _submitCloudEditRedispatch(body);
  // "Run in cloud" toggle → hand off to the engine and return; local path below
  // stays exactly as-is for normal (local) launches.
  if (opts.cloud) return _submitCloudCampaign(body);
  // v2.59.x — Add to Queue routes to /api/campaign/queue-only, which always
  // queues and never auto-drains. The regular Start path is unchanged: it
  // hits /api/campaign/start which fires immediately if idle, queues if a
  // campaign is already running.
  const url = opts.queueOnly ? '/api/campaign/queue-only' : '/api/campaign/start';
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const txt = await res.text();
      // v2.106.0 — mandatory operator-identity gate. Server 409s with this code
      // when this machine's operator email isn't set; show the modal, not a raw alert.
      if (res.status === 409 && txt.includes('OPERATOR_EMAIL_REQUIRED')) {
        openOperatorEmailModal({ mandatory: true });
        return;
      }
      // Pre-flight gate: findings changed between preflight and launch (race). Ask operator to retry.
      let _parsed409; try { _parsed409 = JSON.parse(txt); } catch { _parsed409 = {}; }
      if (res.status === 409 && _parsed409.preflight) {
        showCampaignToast('Lead sheet changed since pre-flight check — press Start again to re-run the check.', 8000);
        return;
      }
      alert(`Could not ${opts.queueOnly ? 'queue' : 'start'} campaign:\n\n${txt}`);
      return;
    }

    const data = await res.json();
    if (data.error) { alert(`Error: ${data.error}`); return; }
    if (!data.ok) { alert(data.message || `Could not ${opts.queueOnly ? 'queue' : 'start'} campaign.`); return; }

    // Whether the campaign starts now or gets queued, the draft has been
    // consumed. Drop it from the Drafts list and clear the active id.
    // Also clear the new-campaign flag — once Start is pressed, the live
    // status / log gates should stop blanking and show the running data.
    try {
      const draftId = getActiveDraftId();
      if (draftId) {
        await fetch('/api/drafts/' + encodeURIComponent(draftId), { method: 'DELETE' }).catch(() => {});
      }
      clearActiveDraft();
      localStorage.removeItem('wizardStoppedFromContext');
      // v2.71: if we entered via Edit pencil on a stopped past row, that
      // source row is now superseded by the freshly-launched resume — drop
      // it from history so the dashboard doesn't accumulate duplicates.
      // Matches resumeWithSameSettings's same-FIFO behaviour.
      try {
        const srcRaw = localStorage.getItem('editResumeSourceIdx');
        const srcIdx = srcRaw != null ? parseInt(srcRaw, 10) : NaN;
        if (Number.isInteger(srcIdx) && srcIdx >= 0) {
          await fetch('/api/history/delete-batch', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ indexes: [srcIdx] }),
          }).catch(() => {});
        }
        localStorage.removeItem('editResumeSourceIdx');
      } catch {}
      // Hide the edit-resume banner now that the resume has launched.
      const banner = document.getElementById('wizard-resume-banner');
      if (banner) banner.style.display = 'none';
    } catch {}
    wizardDirty = false;
    _runningEditWarningShown = false;

    // Server queued the campaign — either explicit queue-only, or because
    // another campaign was already running on the regular start path.
    if (data.queued) {
      alert(data.message || 'Added to queue.');
      if (typeof saveLastUsedPreset === 'function') saveLastUsedPreset();
      goDashboard();
      return;
    }
    setCampaignButtons(true);
    if (typeof saveLastUsedPreset === 'function') saveLastUsedPreset();
    // Post-launch tips modal — fires once per mode after a successful start.
    // Operator can tick "Don't show again" to silence per-mode.
    try { maybeShowPostLaunchTipsModal(body); } catch (err) { console.warn('[tips] modal failed:', err.message); }
    startPolling();
    // ⑤+①: signal an immediate LOCAL start so startCampaign keeps the launch
    // popup up until pollStatus sees the new run flip `running` true.
    return { started: true };
  } catch (e) {
    alert(`Network error starting campaign:\n\n${e.message}`);
  }
}

// ── v2.106.0 — Mandatory per-machine operator identity ──────────────────
// Every operator's app logs in with the SAME shared dashboard credential, so
// the login can't say who's actually operating. This email is the authoritative
// reserver stamped into the SoO 'CC User App' column, and is REQUIRED before any
// campaign can start (the server gates start/queue; this UI mirrors that).
let _operatorEmailMandatory = false;

async function initOperatorIdentity() {
  try {
    const r = await fetch('/api/operator-identity');
    const d = await r.json();
    // Populate the SHARED operator identity app-wide, not just the sidebar chip.
    // snCurrentEmail is what the campaigns board's `mine` and the Team panel's
    // "You" badge key off — previously it was loaded ONLY on the Sales Nav route
    // (loadOperatorEmail), so on the dashboard it was empty and "You" fell back
    // to the LOGIN email (ortus@) instead of the operator (e.g. antonio@).
    if (d && d.email) snCurrentEmail = d.email;
    _setOperatorChip(d && d.email);
    if (!d || !d.set) openOperatorEmailModal({ mandatory: true });
  } catch { /* offline — the server-side start gate still protects it */ }
}

function _setOperatorChip(email) {
  const el = document.getElementById('operator-chip-email');
  if (el) el.textContent = email || 'not set — click to set';
  const chip = document.getElementById('operator-chip');
  if (chip) chip.classList.toggle('operator-chip--unset', !email);
}

function openOperatorEmailModal(opts = {}) {
  _operatorEmailMandatory = !!opts.mandatory;
  const modal = document.getElementById('operator-email-modal');
  if (!modal) return;
  const cancel = document.getElementById('operator-email-cancel');
  if (cancel) cancel.style.display = _operatorEmailMandatory ? 'none' : '';
  const err = document.getElementById('operator-email-error');
  if (err) { err.hidden = true; err.textContent = ''; }
  const input = document.getElementById('operator-email-input');
  // Pre-fill with the current value when editing (non-mandatory re-open).
  if (input && !_operatorEmailMandatory) {
    const cur = document.getElementById('operator-chip-email');
    const v = cur ? cur.textContent.trim() : '';
    input.value = /@/.test(v) ? v : '';
  }
  modal.classList.remove('hidden');
  if (input) setTimeout(() => input.focus(), 50);
}

function closeOperatorEmailModal() {
  if (_operatorEmailMandatory) return; // can't dismiss the mandatory gate
  const modal = document.getElementById('operator-email-modal');
  if (modal) modal.classList.add('hidden');
}

async function saveOperatorEmail() {
  const input = document.getElementById('operator-email-input');
  const err = document.getElementById('operator-email-error');
  const email = ((input && input.value) || '').trim();
  const showErr = (m) => { if (err) { err.textContent = m; err.hidden = false; } };
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showErr('Enter a valid email address.'); return; }
  try {
    const r = await fetch('/api/operator-identity', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) { showErr((d && d.error) || 'Could not save — try again.'); return; }
    if (d.email) snCurrentEmail = d.email;   // keep the shared operator identity in sync (board `mine` + Team "You")
    _setOperatorChip(d.email);
    _operatorEmailMandatory = false;
    const modal = document.getElementById('operator-email-modal');
    if (modal) modal.classList.add('hidden');
  } catch {
    showErr('Network error — try again.');
  }
}

document.addEventListener('DOMContentLoaded', initOperatorIdentity);
window.openOperatorEmailModal = openOperatorEmailModal;
window.closeOperatorEmailModal = closeOperatorEmailModal;
window.saveOperatorEmail = saveOperatorEmail;

// ─────────────────────────────────────────────────────────────────────────
// Post-launch tips — modal (Variant A) + sidebar card (Variant B).
// Data + token substitution live in /js/post-launch-tips.mjs. This block
// handles UI lifecycle (show, dismiss, silence, sidebar render, collapse).
// ─────────────────────────────────────────────────────────────────────────

// Build the substitution context from the wizard body / cockpit / wizard
// inputs. Called at modal-show AND on every sidebar render so dynamic tokens
// stay in sync if the operator changes cadence mid-run (not currently
// possible, but the helper is cheap and future-proof).
function _ptmContextFromBody(body) {
  const tpl = body?.templates || {};
  return {
    dailyLimit: body?.dailyLimit ?? 50,
    delayMin: body?.delayMin ?? 30,
    delayMax: body?.delayMax ?? 60,
    checkIntervalMinutes: body?.checkIntervalMinutes ?? 60,
    primaryName: tpl.primaryName || tpl.introName || '',
  };
}
function _ptmContextFromCockpit() {
  // Sidebar reads from __cockpit (populated by pollStatus). Falls back to
  // wizard inputs when the field isn't on the server status payload.
  const tpl = (__cockpit && __cockpit.templates) || {};
  const cadenceFromWizard = parseInt(document.getElementById('check-cadence-select')?.value, 10);
  return {
    dailyLimit: 50, // server status doesn't surface dailyLimit; default fits CC tip
    delayMin: 30,
    delayMax: 60,
    checkIntervalMinutes: (__cockpit && __cockpit.checkIntervalMinutes)
      || (Number.isFinite(cadenceFromWizard) ? cadenceFromWizard : 60),
    primaryName: tpl.primaryName || document.getElementById('primary-person-name')?.value || '',
  };
}

function maybeShowPostLaunchTipsModal(body) {
  const mode = body?.mode || '';
  if (!mode) return;
  if (isTipsSilenced(mode)) return;
  const set = getTipsForMode(mode, _ptmContextFromBody(body));
  if (!set) return; // unknown mode — no tip data, no modal
  const modal = document.getElementById('post-launch-tips-modal');
  if (!modal) return;
  const titleEl = document.getElementById('ptm-title');
  const bodyEl  = document.getElementById('ptm-body');
  const silenceCheck = document.getElementById('ptm-silence-check');
  if (titleEl) titleEl.textContent = set.modalTitle;
  if (bodyEl)  bodyEl.innerHTML    = renderModalTipsHtml(mode, _ptmContextFromBody(body));
  if (silenceCheck) silenceCheck.checked = false;
  modal.dataset.mode = mode;
  modal.classList.remove('hidden');
  // Esc dismisses — bound for this lifetime only, removed on close.
  const escHandler = (ev) => { if (ev.key === 'Escape') dismissPostLaunchTipsModal(); };
  modal._escHandler = escHandler;
  document.addEventListener('keydown', escHandler);
}

function closePostLaunchTipsModal() {
  const modal = document.getElementById('post-launch-tips-modal');
  if (!modal) return;
  modal.classList.add('hidden');
  if (modal._escHandler) {
    document.removeEventListener('keydown', modal._escHandler);
    modal._escHandler = null;
  }
}

function dismissPostLaunchTipsModal() {
  const modal = document.getElementById('post-launch-tips-modal');
  const mode = modal?.dataset?.mode || '';
  const silence = !!document.getElementById('ptm-silence-check')?.checked;
  if (silence && mode) silenceTipsForMode(mode);
  closePostLaunchTipsModal();
}

// Sidebar tips card — rendered alongside the cockpit during running OR
// monitoring. Reads mode from __cockpit (server status). Hidden when idle.
function renderPostLaunchSidebar() {
  const card = document.getElementById('post-launch-tips-card');
  if (!card) return;
  const mode = (__cockpit && __cockpit.mode) || '';
  const isRunning = !!(__cockpit && __cockpit.running);
  const isMonitoring = !!(__cockpit && __cockpit.state === 'monitoring');
  // Hide when idle. The modal handled the first-time read; the sidebar is a
  // mid-run reference so operators don't need to remember tips later.
  if (!isRunning && !isMonitoring) { card.classList.add('hidden'); return; }
  const set = getTipsForMode(mode, _ptmContextFromCockpit());
  if (!set) { card.classList.add('hidden'); return; }
  const titleEl = document.getElementById('pts-title');
  const bodyEl  = document.getElementById('pts-body');
  if (titleEl) titleEl.textContent = set.sidebarTitle;
  if (bodyEl)  bodyEl.innerHTML    = renderSidebarTipsHtml(mode, _ptmContextFromCockpit());
  card.classList.remove('hidden');
}

function togglePostLaunchTipsCard() {
  const card = document.getElementById('post-launch-tips-card');
  if (!card) return;
  card.classList.toggle('collapsed');
}

// ─────────────────────────────────────────────────────────────────────────
// Onboarding tour — sidebar Help popover + inline-onclick handlers.
// Tour engine lives in /js/tour.mjs. This block wires the UI.
// ─────────────────────────────────────────────────────────────────────────

function toggleHelpPopover(ev) {
  if (ev) ev.stopPropagation();
  const pop = document.getElementById('help-popover');
  if (!pop) return;
  const isHidden = pop.classList.contains('hidden');
  // Refresh "Replay tour" visibility every open — flag may have just changed.
  const replay = document.getElementById('help-pop-replay');
  if (replay) replay.style.display = isTourCompleted() ? '' : 'none';
  pop.classList.toggle('hidden', !isHidden);
  // First open after toggling: bind a one-shot outside-click listener to dismiss.
  if (isHidden) {
    const outsideHandler = (e) => {
      const wrapper = pop.closest('.nav-help-wrapper');
      if (wrapper && !wrapper.contains(e.target)) {
        pop.classList.add('hidden');
        document.removeEventListener('click', outsideHandler);
      }
    };
    setTimeout(() => document.addEventListener('click', outsideHandler), 0);
  }
}

function _closeHelpPopover() {
  const pop = document.getElementById('help-popover');
  if (pop) pop.classList.add('hidden');
}

function onHelpTakeTour() { _closeHelpPopover(); startTour(); }
function onHelpReplayTour() { _closeHelpPopover(); replayTour(); }
function onTourNext() { tourNext(); }
function onTourBack() { tourBack(); }
function onTourSkip() { tourSkip(); }

async function stopCampaign() {
  // v2.59 resume: snapshot the running campaign's identity + totals BEFORE
  // sending the stop so the wizard's next Start can route as a resume
  // instead of spawning a fresh run. Stored by name (since stable ids
  // don't exist yet); wizard Start matches by name comparison.
  try {
    if (typeof __cockpit !== 'undefined' && __cockpit && (__cockpit.running || __cockpit.paused)) {
      const ctx = {
        name: (__cockpit.name || '').trim(),
        totalProcessed: Number(__cockpit.totalProcessed) || 0,
        savedAt: Date.now(),
      };
      if (ctx.name) localStorage.setItem('wizardStoppedFromContext', JSON.stringify(ctx));
    }
  } catch {}
  // 2.9.7: Check DMs is a separate flow with its own stop endpoint. Stop
  // both — only the running one will react, and double-stop is harmless.
  try { await fetch('/api/campaign/stop', { method: 'POST' }); } catch { /* */ }
  try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
}

// Phase 2.8.9: Stop confirmation modal — guards against accidental clicks.
// v2.14.x: for connect_and_introduce campaigns, route to the choice modal
// (stop-sending-keep-monitoring vs. stop-everything) instead of the simple
// yes/no modal. Other modes keep the original single-question modal.
function confirmStopCampaign() {
  // Viewing a CLOUD campaign (wizard read-only Stop, runbar Stop, legacy
  // #btn-stop) → the choice belongs to the ENGINE, not the local cockpit.
  // Without this the VM campaign fell through to the local confirm modal
  // (__cockpit.mode is undefined for a cloud run) and never asked
  // "stop everything vs. keep monitoring". Same routing as dashStopActive.
  if (_viewingCloudId) { stopCloudCampaignUI(_viewingCloudId); return; }
  // v2.14.x: when the campaign is in monitoring state (sending finished,
  // watcher active), route to the dedicated stop-monitoring modal instead
  // of the running-campaign flow. Without this, the button was either
  // dead (the older disable rule) or would hit the wrong modal.
  if (__cockpit && !__cockpit.running && __cockpit.state === 'monitoring') {
    // v2.52.0: when a stop is already in flight, surface the same persistent
    // banner instead of letting the operator re-open the modal and fire a
    // racing second POST. The first call will finalize the sheet stamps in
    // a few seconds — the toast confirms work is happening.
    if (typeof _stoppingMonitoring !== 'undefined' && _stoppingMonitoring) {
      showCampaignToast('Still ending monitoring — hang tight, sheet stamping in progress…', 8000);
      return;
    }
    const modal = document.getElementById('confirm-stop-monitoring-modal');
    if (modal) modal.classList.remove('hidden');
    return;
  }
  // CC+IC and CC+DM both run a phase-2 monitoring loop after the
  // connection phase. Give the operator the choice between halting
  // everything vs. just stopping new sends and letting acceptances
  // continue to flow through auto-intro / auto-DM dispatch.
  if (__cockpit && (__cockpit.mode === 'connect_and_introduce' || __cockpit.mode === 'connect_and_message')) {
    const modal = document.getElementById('stop-choice-modal');
    if (modal) {
      const isDm = __cockpit.mode === 'connect_and_message';
      const eyebrow = modal.querySelector('.stop-choice-eyebrow');
      const monitorSub = modal.querySelector('.stop-choice-pill.is-monitor .stop-choice-pill-sub');
      if (eyebrow) {
        eyebrow.textContent = isDm
          ? 'Stop campaign · Connect + DM'
          : 'Stop campaign · Connect + Introduce Back';
      }
      if (monitorSub) {
        monitorSub.textContent = isDm
          ? 'Bulk-check fires now, then every 6 h for 7 days. Auto-DMs still fire on accept.'
          : 'Bulk-check fires now, then every 6 h for 7 days. Auto-intro DMs still fire on accept.';
      }
      modal.classList.remove('hidden');
    }
    return;
  }
  const modal = document.getElementById('confirm-stop-modal');
  if (modal) modal.classList.remove('hidden');
}

function closeStopModal() {
  const modal = document.getElementById('confirm-stop-modal');
  if (modal) modal.classList.add('hidden');
}

function closeStopChoiceModal() {
  const modal = document.getElementById('stop-choice-modal');
  if (modal) modal.classList.add('hidden');
  _stopChoiceTarget = { cloud: false, id: null }; // don't leak into a later stop
}
window.closeStopChoiceModal = closeStopChoiceModal;

// v2.14.x: Stop-monitoring modal helpers. Mirrors the stop-choice modal
// pattern so the in-app monochrome aesthetic stays consistent. The
// existing monitoringStop() in app.js:~6160 used a native browser
// confirm() — replaced by this modal when the operator hits the bottom-
// bar Stop button during monitoring.
function closeStopMonitoringModal() {
  const modal = document.getElementById('confirm-stop-monitoring-modal');
  if (modal) modal.classList.add('hidden');
}
window.closeStopMonitoringModal = closeStopMonitoringModal;

// v2.52.0 — client-side flag set true while /api/monitoring/stop is in
// flight. Suppresses re-opening the stop-monitoring modal during the
// 5–10s sheet-stamp window (so impatient operators can't fire a second
// POST and see the misleading 'not in monitoring state' alert). Cleared
// when the response lands OR after a 30s safety timeout.
let _stoppingMonitoring = false;
let _stoppingMonitoringStartedAt = 0;

async function confirmStopMonitoringNow() {
  closeStopMonitoringModal();
  if (_stoppingMonitoring) return; // already in flight — no-op
  _stoppingMonitoring = true;
  _stoppingMonitoringStartedAt = Date.now();
  // Persistent banner via the existing campaign toast — 30s duration covers
  // the worst-case sheet-stamp time. Cleared early when the fetch resolves.
  showCampaignToast('Ending monitoring — finalizing the sheet (this can take 5–10 s)…', 30000);
  try {
    const res = await fetch('/api/monitoring/stop', { method: 'POST' }).then((r) => r.json());
    if (res.ok) {
      // v2.52.0: optimistic state flip. Server confirms state='done' on
      // any ok=true response — push it into __cockpit immediately so the
      // cockpit panel stops rendering MONITORING / WATCHING FOR ACCEPTANCES
      // without waiting up to 2s for the next pollStatus tick. Then force
      // a poll so monitoringUntil/nextCheckAt clear too. The overlay fires
      // from updateCockpit's monitoring→done transition detector.
      if (typeof __cockpit !== 'undefined') {
        __cockpit.state = 'done';
        __cockpit.monitoringCheckInProgress = false;
        if (typeof renderCockpit === 'function') renderCockpit();
      }
      if (typeof pollStatus === 'function') pollStatus().catch(() => {});

      // alreadyStopped → operator double-clicked; first call already did the work.
      const msg = res.alreadyStopped
        ? 'Monitoring already ended.'
        : 'Monitoring ended. Still-pending leads kept as "Connection Request Sent".';
      showCampaignToast(msg, 6000);
      if (typeof refreshDashboardSchedules === 'function') refreshDashboardSchedules();
    } else {
      alert('Stop failed: ' + (res.error || 'unknown'));
    }
  } catch (err) {
    alert('Stop failed: ' + err.message);
  } finally {
    _stoppingMonitoring = false;
  }
}
window.confirmStopMonitoringNow = confirmStopMonitoringNow;

async function confirmStopCampaignNow() {
  closeStopModal();
  // Visual feedback while the server force-closes browsers (~1-2s).
  showCampaignToast('Stopping campaign — closing browsers…', 4000);
  await stopCampaign();
}

// v2.14.x: "Stop sending, keep monitoring" — CC+IC only. Fires the
// existing /api/campaign/stop with no body, which preserves the post-
// campaign bulk-check + auto-intro monitoring path (campaign.js falls
// through to end-of-list bulk-check + transitionToMonitoring as it would
// at natural end-of-list).
async function stopAndKeepMonitoring() {
  const target = _stopChoiceTarget; // capture before close resets it
  closeStopChoiceModal();
  if (target.cloud && target.id) {
    await _doStopCloud(target.id, { keepMonitoring: true });
    return;
  }
  showCampaignToast('Stopping new sends — monitoring stays active for 7 days.', 5000);
  try { await fetch('/api/campaign/stop', { method: 'POST' }); } catch { /* */ }
  try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
}
window.stopAndKeepMonitoring = stopAndKeepMonitoring;
window.closePostLaunchTipsModal   = closePostLaunchTipsModal;
window.dismissPostLaunchTipsModal = dismissPostLaunchTipsModal;
window.togglePostLaunchTipsCard   = togglePostLaunchTipsCard;
window.toggleHelpPopover          = toggleHelpPopover;
window.onHelpTakeTour             = onHelpTakeTour;
window.onHelpReplayTour           = onHelpReplayTour;
window.onTourNext                 = onTourNext;
window.onTourBack                 = onTourBack;
window.onTourSkip                 = onTourSkip;

// v2.14.x: "Stop everything" — CC+IC only. Posts { full: true } so the
// campaign loop skips the end-of-list bulk-check + monitoring transition
// + post-campaign sweep registration. Pending invitations stay pending;
// no auto-intros will fire.
async function stopEverything() {
  const target = _stopChoiceTarget; // capture before close resets it
  closeStopChoiceModal();
  if (target.cloud && target.id) {
    await _doStopCloud(target.id, { keepMonitoring: false });
    return;
  }
  showCampaignToast('Stopping campaign completely — no further checks or DMs.', 5000);
  try {
    await fetch('/api/campaign/stop', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ full: true }),
    });
  } catch { /* */ }
  try { await fetch('/api/check-dms/stop', { method: 'POST' }); } catch { /* */ }
}
window.stopEverything = stopEverything;

// v2.14.x: Restore — always-visible runbar panic button. Opens a confirm
// modal, then POSTs /api/campaign/restore. The backend force-kills
// browsers, force-resets in-memory state, and re-launches with the same
// settings. See restoreCampaign() in campaign.js for the full behaviour.
function confirmRestoreCampaign() {
  const modal = document.getElementById('restore-modal');
  if (modal) modal.classList.remove('hidden');
}
window.confirmRestoreCampaign = confirmRestoreCampaign;

function closeRestoreModal() {
  const modal = document.getElementById('restore-modal');
  if (modal) modal.classList.add('hidden');
}
window.closeRestoreModal = closeRestoreModal;

async function doRestoreCampaign() {
  closeRestoreModal();
  showCampaignToast('Restoring · force-closing browsers · resetting state…', 7000);
  try {
    const r = await fetch('/api/campaign/restore', { method: 'POST' });
    const data = await r.json().catch(() => ({}));
    if (!data.ok) {
      showCampaignToast(`Restore failed: ${data.error || r.statusText}`, 6000);
      return;
    }
    if (data.restartedFrom === null) {
      showCampaignToast('Engine restored — nothing to resume.', 4000);
    } else {
      const src = data.restartedFrom === 'running' ? 'live settings' : 'last campaign';
      showCampaignToast(`Engine restored — relaunching from ${src}.`, 4000);
    }
    // Refresh polling so the cockpit / runbar pick up the new state.
    if (typeof startPolling === 'function') startPolling();
  } catch (err) {
    showCampaignToast(`Restore failed: ${err.message}`, 6000);
  }
}
window.doRestoreCampaign = doRestoreCampaign;

// Phase 2.8.9: Pause/Resume toggle. Button label is driven by polled status,
// not local state, so the source of truth is the server.
async function pauseOrResumeCampaign() {
  const btn = document.getElementById('btn-pause');
  if (!btn) return;
  const label = (btn.textContent || '').trim();
  try {
    if (label === 'Resume') {
      btn.disabled = true;
      btn.textContent = 'Resuming…';
      await fetch('/api/campaign/resume', { method: 'POST' });
    } else {
      btn.disabled = true;
      btn.textContent = 'Pausing…';
      showCampaignToast('Pausing — current lead will finish first (~60–120s). Browsers stay open.', 8000);
      await fetch('/api/campaign/pause', { method: 'POST' });
    }
  } catch (err) {
    showCampaignToast(`Pause/Resume error: ${err.message}`, 5000);
  }
}

function showCampaignToast(msg, duration = 6000) {
  const toast = document.getElementById('campaign-toast');
  if (!toast) return;
  toast.textContent = msg;
  toast.classList.add('visible');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove('visible'), duration);
}

// ─────────────────────────────────────────────────────────────────────────
// Issue #5 Part B — Edit-while-paused panel.
// Backend (Part A) accepts edits via three POST routes, but ONLY while the
// campaign is running AND fully paused (__cockpit.paused === true). This
// panel surfaces those three knobs (daily limit, check cadence, and the one
// mode-relevant message body) and posts them on "Apply changes".
//
// Pre-fill happens once on the hidden→shown transition (so the 250ms render
// tick never stomps the operator's typing). The message-body source is
// /api/campaign/active-settings (status doesn't carry templates); daily
// limit + cadence come straight from __cockpit.
// ─────────────────────────────────────────────────────────────────────────
let _peFilled = false;   // true while pre-filled & shown — gate re-fill per pause
let _peWired = false;    // guard so the Apply handler binds exactly once

// Decide which template body field this campaign's mode edits.
// Returns { field, label }. Mirrors the wizard's field spellings so the
// backend's normalizeTemplates understands the payload.
function _pePickBodyField(mode) {
  if (mode === 'connect_and_introduce') return { field: 'primaryIntroBody', label: 'Introduction message' };
  if (mode === 'connect_and_message')   return { field: 'ccDmBody',         label: 'DM message' };
  return { field: 'connectionNote', label: 'Connection note' };
}

// Read the mode-appropriate body out of a templates object, tolerating the
// connectionNote/note alias the wizard uses interchangeably.
function _peReadBody(templates, field) {
  const t = templates || {};
  if (field === 'connectionNote') return t.connectionNote || t.note || '';
  return t[field] || '';
}

function renderPauseEditPanel() {
  const panel = document.getElementById('pause-edit-panel');
  if (!panel) return;

  // Not (fully) paused → hide and reset the pre-fill gate so the next pause
  // re-fills fresh from the live values.
  if (!__cockpit || __cockpit.paused !== true) {
    panel.hidden = true;
    panel.style.display = 'none';
    _peFilled = false;
    // Also hide the account-add section sibling. Both hidden AND display:none are needed —
    // .cockpit-panel is display:flex, which overrides [hidden] (same pattern as the panels above).
    const aas = document.getElementById('acct-add-section');
    if (aas) { aas.hidden = true; aas.style.display = 'none'; }
    return;
  }

  // Wire the Apply button once (idempotent across ticks).
  if (!_peWired) {
    const applyBtn = document.getElementById('pe-apply');
    if (applyBtn) {
      applyBtn.addEventListener('click', _peApplyChanges);
      _peWired = true;
    }
  }

  // First tick of this pause: pre-fill once, then unhide.
  if (!_peFilled) {
    _peFilled = true;
    _pePrefillFields();
    panel.hidden = false;
    panel.style.display = 'flex';
    // v2.112 (#2b): populate the Add account control on first pause tick.
    if (typeof renderPauseAccountAdd === 'function') renderPauseAccountAdd();
    return;
  }

  // Already filled + shown — ensure it's visible (no re-fill: don't stomp typing).
  if (panel.hidden) {
    panel.hidden = false;
    panel.style.display = 'flex';
  }
}

function _pePrefillFields() {
  const { field, label } = _pePickBodyField(__cockpit.mode);

  // Label reflects the mode-relevant body.
  const labelEl = document.getElementById('pe-template-label');
  if (labelEl) labelEl.textContent = label;

  // Daily limit — from the live status mirror; min 1.
  const dlEl = document.getElementById('pe-daily-limit');
  if (dlEl) {
    const dl = Number(__cockpit.dailyLimit);
    dlEl.value = Number.isFinite(dl) && dl > 0 ? String(dl) : '';
  }

  // Cadence — match the live value to one of the select options.
  const cadEl = document.getElementById('pe-cadence');
  if (cadEl) {
    const cad = Number(__cockpit.checkIntervalMinutes);
    cadEl.value = [60, 120, 240, 360, 720].includes(cad) ? String(cad) : '60';
  }

  // Message body — prefer the live templates snapshot already on __cockpit;
  // otherwise fetch the active-settings snapshot (best-effort, async). Guard
  // the async fill so it doesn't overwrite the operator if they've started
  // typing or the pause already ended by the time the fetch resolves.
  const bodyEl = document.getElementById('pe-template-body');
  if (bodyEl) {
    const fromCockpit = _peReadBody(__cockpit.templates, field);
    bodyEl.value = fromCockpit;
    if (!fromCockpit) {
      fetch('/api/campaign/active-settings')
        .then(r => r.json())
        .then(data => {
          if (!data || !data.ok || !data.settings) return;
          // Only apply if we're still mid pre-fill and the operator hasn’t typed.
          if (!_peFilled || __cockpit.paused !== true) return;
          if (bodyEl.value) return;
          bodyEl.value = _peReadBody(data.settings.templates, field);
        })
        .catch(() => { /* best-effort — operator can type the body */ });
    }
  }
}

async function _peApplyChanges() {
  if (!__cockpit || __cockpit.paused !== true) {
    showCampaignToast('Pause the campaign first — edits only apply while paused.', 4000);
    return;
  }

  const { field } = _pePickBodyField(__cockpit.mode);
  const dlEl = document.getElementById('pe-daily-limit');
  const cadEl = document.getElementById('pe-cadence');
  const bodyEl = document.getElementById('pe-template-body');

  const calls = [];   // [{ url, body, name }]

  // Daily limit — send only when it's a valid number that differs from live.
  const dl = parseInt(dlEl ? dlEl.value : '', 10);
  if (Number.isFinite(dl) && dl >= 1 && dl <= 1000 && dl !== Number(__cockpit.dailyLimit)) {
    calls.push({ url: '/api/campaign/live/daily-limit', body: { dailyLimit: dl }, name: 'Daily limit' });
  }

  // Cadence — send only when changed.
  const cad = parseInt(cadEl ? cadEl.value : '', 10);
  if (Number.isFinite(cad) && cad !== Number(__cockpit.checkIntervalMinutes)) {
    calls.push({ url: '/api/campaign/live/cadence', body: { checkIntervalMinutes: cad }, name: 'Cadence' });
  }

  // Message body — send the full templates object with the one edited field
  // overwritten, so the backend's normalizeTemplates sees the same shape the
  // wizard sends. Only send when non-empty and actually changed.
  const newBody = bodyEl ? bodyEl.value : '';
  const liveBody = _peReadBody(__cockpit.templates, field);
  if (newBody.trim() && newBody !== liveBody) {
    const templates = { ...(__cockpit.templates || {}) };
    templates[field] = newBody;
    // Keep the connectionNote/note alias consistent for the connect_only path.
    if (field === 'connectionNote') templates.note = newBody;
    calls.push({ url: '/api/campaign/live/templates', body: { templates }, name: 'Message' });
  }

  if (calls.length === 0) {
    showCampaignToast('No changes to apply.', 2500);
    return;
  }

  const applied = [];
  const failed = [];
  for (const c of calls) {
    try {
      const r = await fetch(c.url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(c.body),
      });
      let data = {};
      try { data = await r.json(); } catch { /* non-JSON → treat as failure below */ }
      if (data && data.ok) {
        applied.push(c.name);
        // Mirror the accepted value back onto __cockpit so the "changed?"
        // checks above don't re-fire it on the next Apply.
        if (c.url.endsWith('/daily-limit')) __cockpit.dailyLimit = c.body.dailyLimit;
        else if (c.url.endsWith('/cadence')) __cockpit.checkIntervalMinutes = c.body.checkIntervalMinutes;
        else if (c.url.endsWith('/templates')) __cockpit.templates = c.body.templates;
      } else {
        failed.push(`${c.name}: ${(data && data.reason) || 'failed'}`);
      }
    } catch (err) {
      failed.push(`${c.name}: ${err.message}`);
    }
  }

  if (failed.length) {
    showCampaignToast(`Couldn't apply — ${failed.join('; ')}`, 6000);
  } else {
    showCampaignToast(`Saved ${applied.join(' + ')} — applies on Resume.`, 4000);
  }
}

// ─────────────────────────────────────────────────────────────────────────
// Phase 2.8.12 — Live Cockpit panel (Concept B from sketches).
// pollStatus saves the latest snapshot into __cockpit; a 250ms tick reads
// it and computes the smooth countdown without re-hitting the network.
// ─────────────────────────────────────────────────────────────────────────
const __cockpit = {
  running: false,
  paused: false,
  pauseRequested: false,
  action: null,
  mode: null,
  pName: null,
  // v2.13.14 — monitoring overlay. Populated from /api/campaign/status.
  state: 'idle',
  monitoringUntil: null,
  nextCheckAt: null,
  participatingProfileIds: [],
  monitoringCheckInProgress: false,
  profileIds: [],
  profileNames: [],
  sheetUrl: '',
};
const COCKPIT_RING_CIRCUMFERENCE = 282.7; // 2πr where r=45

// Format a duration in ms as a human string ("6d 23h", "12h 4m", "8m").
// Matches the convention used by renderMonitoringCard so the cockpit,
// run-bar, and Schedule card all display the same string.
function _cockpitFmtRemaining(ms) {
  if (ms <= 0) return '0m';
  const days = Math.floor(ms / 86400000);
  const hours = Math.floor((ms % 86400000) / 3600000);
  const mins = Math.floor((ms % 3600000) / 60000);
  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${mins}m`;
  return `${mins}m`;
}
// v2.14.x: finer-grained countdown for the ring centre. Shows seconds
// when < 1 min remains so the operator sees the last 60s tick down,
// then mins/hours/days for longer ranges.
function _cockpitFmtCountdown(ms) {
  if (ms <= 0) return '0s';
  if (ms < 60_000) return `${Math.ceil(ms / 1000)}s`;
  return _cockpitFmtRemaining(ms);
}
function _cockpitHHMM(d) {
  return d ? `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` : '—';
}

// v2.52.0 — full-screen overlay shown when monitoring transitions to 'done'.
// Idempotent: a second call while the overlay is visible is a no-op.
// Auto-dismisses after 3s and navigates to dashboard so the operator gets
// closure on the campaign without manually closing.
let _monEndedOverlayShown = false;
function showMonitoringEndedOverlay() {
  if (_monEndedOverlayShown) return;
  _monEndedOverlayShown = true;
  let el = document.getElementById('monitoring-ended-overlay');
  if (!el) {
    el = document.createElement('div');
    el.id = 'monitoring-ended-overlay';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(20,20,20,0.86);z-index:9999;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);transition:opacity 200ms ease-out;opacity:0;';
    el.innerHTML = '<div style="background:#fafafa;color:#111;padding:40px 56px;border:1px solid #222;border-radius:0;text-align:center;font-family:inherit;max-width:520px;">'
      + '<div style="font-size:0.78rem;letter-spacing:0.18em;color:#c9a233;margin-bottom:12px;">● MONITORING ENDED</div>'
      + '<h2 style="margin:0 0 14px;font-size:1.6rem;letter-spacing:0.04em;">Campaign complete.</h2>'
      + '<p style="margin:0 0 22px;color:#444;font-size:0.95rem;line-height:1.45;">Still-pending invitations remain <i>Connection Request Sent</i> — they may still accept later. Returning to the dashboard…</p>'
      + '<button type="button" id="mon-ended-go-now" style="background:#111;color:#fff;border:0;padding:10px 22px;letter-spacing:0.12em;font-size:0.78rem;cursor:pointer;border-radius:9999px;">DASHBOARD NOW</button>'
      + '</div>';
    document.body.appendChild(el);
    requestAnimationFrame(() => { el.style.opacity = '1'; });
    const goNow = el.querySelector('#mon-ended-go-now');
    if (goNow) goNow.addEventListener('click', _dismissMonEndedOverlay);
  }
  setTimeout(_dismissMonEndedOverlay, 3000);
}
function _dismissMonEndedOverlay() {
  const el = document.getElementById('monitoring-ended-overlay');
  if (el) {
    el.style.opacity = '0';
    setTimeout(() => { el.remove(); }, 220);
  }
  _monEndedOverlayShown = false;
  // Navigate to dashboard so the cockpit is no longer in view. Past tab
  // will pick up the completed campaign on its next fetch.
  try { window.location.hash = '#/'; } catch { /* */ }
  try { if (typeof refreshDashboard === 'function') refreshDashboard(); } catch { /* */ }
}

function updateCockpit(s) {
  // v2.52.0: detect 'monitoring' → 'done' transition so the cockpit shows
  // a clear MONITORING ENDED confirmation + auto-redirect to dashboard.
  // Without this, the badge silently disappears and the operator can't
  // tell whether the stop landed. _prevState is module-local; reset on
  // navigate (page reload starts fresh).
  const prevState = __cockpit.state;
  const nextState = s.state || 'idle';
  const justEnded = prevState === 'monitoring' && nextState === 'done';

  __cockpit.running = !!s.running;
  __cockpit.paused = !!s.paused;
  __cockpit.pauseRequested = !!s.pauseRequested;
  __cockpit.action = s.currentAction || null;
  __cockpit.mode = s.mode || null;
  __cockpit.pName = s.currentProfile || null;
  // v2.58.x — runbar mirror reads __cockpit.name to populate the identity
  // slot. Without this assignment the runbar permanently showed
  // "Untitled · CC+IB" even when /api/campaign/status returned a real
  // campaign name (the dashboard active row was rendering correctly
  // because it reads from the fetch response directly).
  __cockpit.name = s.name || '';
  // v2.59 — mirror totalProcessed too. The wizard Stop→Start resume
  // path (stopCampaign at L3219, wizardStoppedFromContext.totalProcessed)
  // snapshots this off __cockpit, then ships it server-side as
  // resumeContext so campaign.js can seed the counter. Before this
  // mirror the snapshot was always 0 — counter-continuation silently
  // broke from the wizard path (the past-row RESUME chip path worked
  // because it reads from history, not __cockpit).
  __cockpit.totalProcessed = Number(s.totalProcessed) || 0;
  __cockpit.state = nextState;

  if (justEnded) {
    try { showMonitoringEndedOverlay(); } catch (e) { console.warn('[monitoring-ended] overlay failed:', e.message); }
  }
  __cockpit.monitoringUntil = s.monitoringUntil || null;
  __cockpit.nextCheckAt = s.nextCheckAt || null;
  __cockpit.monitoringCheckInProgress = !!s.monitoringCheckInProgress;
  __cockpit.participatingProfileIds = s.participatingProfileIds || [];
  __cockpit.profileIds = s.profileIds || [];
  __cockpit.profileNames = s.profileNames || [];
  __cockpit.skippedProfiles = s.skippedProfiles || [];
  __cockpit.sheetUrl = s.sheetUrl || '';
  // Issue #5 Part B: mirror the live-editable settings so renderPauseEditPanel
  // can pre-fill the daily-limit + cadence fields. (templates aren't on the
  // status payload — the pause panel fetches /api/campaign/active-settings for
  // the message body instead.)
  if (s.dailyLimit != null) __cockpit.dailyLimit = s.dailyLimit;
  if (s.checkIntervalMinutes != null) __cockpit.checkIntervalMinutes = s.checkIntervalMinutes;
  // v2.72: track the "finished" state so the wizard keeps the Live Status card
  // (log + Run reply check) visible after a campaign ends, not just while it runs.
  __cockpit.endNotice = s.endNotice || null;
  __cockpit.hasLogs = Array.isArray(s.logs) && s.logs.length > 0;
  _refreshOpenSheetButtons();
  renderCockpit();
  // Issue #5 Part B: keep the edit-while-paused panel in sync with paused state.
  if (typeof renderPauseEditPanel === 'function') renderPauseEditPanel();
  // Sidebar tips card lives in the Live Status right column. Re-render on
  // every poll so mode/state transitions (idle → running → monitoring → idle)
  // flip visibility + title without extra plumbing.
  try { renderPostLaunchSidebar(); } catch (err) { console.warn('[tips] sidebar failed:', err.message); }
}

// v2.14.x: defensive stale-state detector. When in monitoring mode and the
// cached nextCheckAt is more than 30s in the past AND no check is mid-fire,
// the backend should have rescheduled by now. Force a fresh pollStatus()
// to pull the new nextCheckAt. This catches the case where:
//   - Mac slept and woke (powerMonitor.resume is unreliable on macOS)
//   - Renderer was suspended longer than backend (setInterval lag after wake)
//   - Any other reason the cached state diverged from the truth
// Throttled: at most once every 5s, so the 250ms render tick can't hammer
// the server. Idempotent — pollStatus has its own guard against overlap.
let _lastStaleForcePoll = 0;
function _maybeForcePollOnStale() {
  if (__cockpit.state !== 'monitoring') return;
  if (__cockpit.monitoringCheckInProgress) return;
  if (!__cockpit.nextCheckAt) return;
  const next = new Date(__cockpit.nextCheckAt).getTime();
  const now = Date.now();
  if (next > now - 30_000) return; // not stale yet
  if (now - _lastStaleForcePoll < 5_000) return; // throttle
  _lastStaleForcePoll = now;
  if (typeof pollStatus === 'function') {
    pollStatus().catch(() => { /* best-effort */ });
  }
}

function renderCockpit() {
  _maybeForcePollOnStale();
  const ring = document.querySelector('.cockpit-ring');
  const ringFg = document.getElementById('cockpit-ring-fg');
  const num = document.getElementById('cockpit-ring-num');
  const unit = document.getElementById('cockpit-ring-unit');
  const footer = document.getElementById('cockpit-ring-footer');
  // v2.14.x: footer is only populated in the monitoring branch.
  // Clear it on every render so it doesn't leak into idle/paused/running.
  if (footer) footer.textContent = '';
  const tag = document.getElementById('cockpit-status-tag');
  const dot = document.getElementById('cockpit-pulse-dot');
  const action = document.getElementById('cockpit-action');
  const lead = document.getElementById('cockpit-lead');
  const account = document.getElementById('cockpit-account');
  const modeEl = document.getElementById('cockpit-mode-meta');
  if (!ring || !ringFg || !num || !unit || !tag || !dot || !action) return;

  // Blank the entire Live Status cockpit when the operator is composing a
  // new, unstarted campaign — that tab represents zero activity regardless
  // of what's running globally. Full per-campaign scoping comes with the
  // isolation refactor.
  if (typeof isOnNewCampaignView === 'function' && isOnNewCampaignView()) {
    ring.classList.remove('indeterminate', 'paused', 'monitoring');
    ringFg.style.strokeDashoffset = COCKPIT_RING_CIRCUMFERENCE;
    num.textContent = '—';
    unit.textContent = 'idle';
    if (footer) footer.textContent = '';
    tag.textContent = 'IDLE';
    dot.classList.remove('live', 'paused-dot', 'monitoring');
    action.textContent = 'No activity for this campaign';
    if (lead) lead.textContent = '—';
    if (account) account.textContent = '—';
    if (modeEl) modeEl.textContent = '—';
    const _leadLabel = document.querySelector('.cockpit-meta-label[data-cockpit-row="lead"]') || lead?.previousElementSibling;
    if (_leadLabel) _leadLabel.textContent = 'Lead';
    const _accountLabel = document.querySelector('.cockpit-meta-label[data-cockpit-row="account"]') || account?.previousElementSibling;
    if (_accountLabel) _accountLabel.textContent = 'Account';
    const stToday = document.getElementById('st-today');
    const stTotal = document.getElementById('st-total');
    const stErrors = document.getElementById('st-errors');
    const stBar = document.getElementById('st-bar');
    if (stToday) stToday.textContent = '0';
    if (stTotal) stTotal.textContent = '0';
    if (stErrors) stErrors.textContent = '0';
    if (stBar) stBar.style.width = '0%';
    const acctQueue = document.getElementById('account-queue');
    if (acctQueue) { acctQueue.classList.add('hidden'); acctQueue.innerHTML = ''; }
    const bcl = document.querySelector('.bulk-check-live');
    if (bcl) bcl.hidden = true;
    return;
  }

  // v2.13.14 — Monitoring overlay. running=false but state='monitoring'
  // means the campaign has finished sending and is now watching for
  // acceptances. Surface the timing info so the operator doesn't have
  // to scroll to the Schedule card to know when the next check is.
  if (!__cockpit.running && __cockpit.state === 'monitoring') {
    ring.classList.remove('indeterminate', 'paused');
    ring.classList.add('monitoring');
    const until = __cockpit.monitoringUntil ? new Date(__cockpit.monitoringUntil) : null;
    const next = __cockpit.nextCheckAt ? new Date(__cockpit.nextCheckAt) : null;
    const now = Date.now();
    const remainingMs = until ? until.getTime() - now : 0;
    // Window-elapsed fraction → static-looking dashed ring for the visual cue.
    // (No animated countdown — the dashed pattern signals "watching", and
    // the centre text shows the live remainder.)
    ringFg.style.strokeDashoffset = COCKPIT_RING_CIRCUMFERENCE * 0.15;
    // v2.14.x ring redesign (Variant A): big number = live countdown to
    // next check, small label = "NEXT CHECK", tiny footer = window left.
    // Operator feedback: the slowly-changing window figure shouldn't
    // dominate; the live countdown is what matters minute-to-minute.
    const nextCountdownMs = next ? Math.max(0, next.getTime() - now) : 0;
    num.textContent = next ? _cockpitFmtCountdown(nextCountdownMs) : '—';
    unit.textContent = 'next check';
    if (footer) footer.textContent = until ? _cockpitFmtRemaining(remainingMs) : '';
    tag.textContent = 'MONITORING';
    dot.classList.remove('live', 'paused-dot');
    dot.classList.add('monitoring');
    action.textContent = __cockpit.monitoringCheckInProgress ? 'Checking now…' : 'Watching for acceptances';
    if (lead) {
      lead.textContent = next
        ? `${_cockpitHHMM(next)} · in ${_cockpitFmtRemaining(Math.max(0, next.getTime() - now))}`
        : '—';
    }
    const _leadLabel = document.querySelector('.cockpit-meta-label[data-cockpit-row="lead"]')
      || lead?.previousElementSibling;
    if (_leadLabel) _leadLabel.textContent = 'Next check';
    if (account) {
      account.textContent = until
        ? `${until.toLocaleDateString([], { month: 'short', day: 'numeric' })}, ${_cockpitHHMM(until)} · in ${_cockpitFmtRemaining(remainingMs)}`
        : '—';
    }
    const _accountLabel = document.querySelector('.cockpit-meta-label[data-cockpit-row="account"]')
      || account?.previousElementSibling;
    if (_accountLabel) _accountLabel.textContent = 'Ends';
    if (modeEl) {
      const ids = __cockpit.participatingProfileIds || [];
      const names = ids.map((pid) => {
        const idx = (__cockpit.profileIds || []).indexOf(pid);
        return idx >= 0 ? (__cockpit.profileNames[idx] || pid) : pid;
      });
      modeEl.textContent = names.length === 0 ? '—'
        : names.length === 1 ? names[0]
        : `${names[0]} (+${names.length - 1})`;
    }
    const _modeLabel = document.querySelector('.cockpit-meta-label[data-cockpit-row="mode"]')
      || modeEl?.previousElementSibling;
    if (_modeLabel) _modeLabel.textContent = 'Profiles';
    return;
  }

  // Idle — no campaign running.
  if (!__cockpit.running) {
    ring.classList.remove('indeterminate', 'paused', 'monitoring');
    ringFg.style.strokeDashoffset = COCKPIT_RING_CIRCUMFERENCE;
    num.textContent = '—';
    unit.textContent = 'idle';
    tag.textContent = 'IDLE';
    dot.classList.remove('live', 'paused-dot', 'monitoring');
    action.textContent = 'No campaign running';
    if (lead)    lead.textContent    = '—';
    if (account) account.textContent = '—';
    if (modeEl)  modeEl.textContent  = '—';
    // Restore default meta labels (in case we came back from monitoring state).
    const _leadLabel = lead?.previousElementSibling;
    const _accountLabel = account?.previousElementSibling;
    const _modeLabel = modeEl?.previousElementSibling;
    if (_leadLabel) _leadLabel.textContent = 'Lead';
    if (_accountLabel) _accountLabel.textContent = 'Account';
    if (_modeLabel) _modeLabel.textContent = 'Mode';
    return;
  }

  // Paused — distinct visual.
  if (__cockpit.paused) {
    ring.classList.remove('indeterminate', 'monitoring');
    ring.classList.add('paused');
    dot.classList.remove('monitoring');
    ringFg.style.strokeDashoffset = COCKPIT_RING_CIRCUMFERENCE * 0.3;
    num.textContent = '||';
    unit.textContent = 'paused';
    tag.textContent = 'PAUSED';
    dot.classList.remove('live'); dot.classList.add('paused-dot');
    action.textContent = 'Paused — press Resume to continue';
    if (lead)    lead.textContent    = (__cockpit.action && __cockpit.action.lead)    || '—';
    if (account) account.textContent = (__cockpit.action && __cockpit.action.account) || __cockpit.pName || '—';
    if (modeEl)  modeEl.textContent  = formatMode(__cockpit.mode);
    return;
  }

  // Running — countdown if action has endsAt, else indeterminate arc.
  ring.classList.remove('paused', 'monitoring');
  tag.textContent = __cockpit.pauseRequested ? 'PAUSING…' : 'LIVE';
  dot.classList.remove('paused-dot', 'monitoring'); dot.classList.add('live');

  const a = __cockpit.action;
  if (!a) {
    ring.classList.add('indeterminate');
    num.textContent = '◐';
    unit.textContent = 'working';
    action.textContent = 'Running…';
    if (lead)    lead.textContent    = '—';
    if (account) account.textContent = __cockpit.pName || '—';
    if (modeEl)  modeEl.textContent  = formatMode(__cockpit.mode);
    return;
  }

  action.textContent = a.label || 'Running…';
  if (lead)    lead.textContent    = a.lead    || '—';
  if (account) account.textContent = a.account || __cockpit.pName || '—';
  if (modeEl)  modeEl.textContent  = formatMode(a.mode || __cockpit.mode);

  if (a.endsAt && a.startedAt) {
    ring.classList.remove('indeterminate');
    const total = a.endsAt - a.startedAt;
    const remainingMs = Math.max(0, a.endsAt - Date.now());
    const pct = total > 0 ? Math.min(1, (total - remainingMs) / total) : 0;
    ringFg.style.strokeDashoffset = COCKPIT_RING_CIRCUMFERENCE * (1 - pct);
    const remainingSec = Math.ceil(remainingMs / 1000);
    if (remainingSec >= 60) {
      num.textContent = Math.ceil(remainingSec / 60);
      unit.textContent = 'minutes';
    } else {
      num.textContent = remainingSec;
      unit.textContent = 'seconds';
    }
  } else {
    ring.classList.add('indeterminate');
    num.textContent = '◐';
    unit.textContent = 'working';
  }
}

function formatMode(m) {
  if (!m) return '—';
  // v2.57.7: added connect_and_introduce + introduce_back so the runbar
  // doesn't leak raw enums into the UI (was rendering as
  // "CONNECT_AND_INTRODUCE" — uppercased + wrapping the action strip).
  const map = {
    connect_only: 'Connect',
    connect_and_introduce: 'CC+IB',
    connect_and_message: 'CC+DM',
    introduce_back: 'IC',
    message_only: 'Message',
    inmail_only: 'InMail',
    open_profile_only: 'Open Profile',
    check_status: 'Check Status',
    check_dms: 'Check DMs',
    post_amplification: 'Post amp',
    auto: 'Auto',
  };
  return map[m] || m;
}

// 250ms client-side tick keeps the countdown smooth without re-polling.
setInterval(renderCockpit, 250);

// Phase 11.2 (D-18): un-hide all active browser processes (debug aid).
// Calls the session-gated POST /api/browsers/show shipped in Plan 01.
async function showBrowsers() {
  try {
    const res = await fetch('/api/browsers/show', { method: 'POST' });
    const data = await res.json();
    if (data.platform === 'other') {
      alert('Window hiding only runs on macOS. Nothing to show.');
      return;
    }
    alert(`Shown ${data.shown} browser${data.shown === 1 ? '' : 's'}${data.skipped ? ` (${data.skipped} skipped)` : ''}.`);
  } catch (err) {
    alert(`Could not show browsers: ${err.message}`);
  }
}

// v2.59.x — Swap the gold class between Start and Add to Queue based on
// whether a campaign is currently running. Idle: Start is gold, Queue is
// outlined. Running: Start is dimmed/outlined, Queue is gold. Called from
// setCampaignButtons (status-driven) and updateWizardQueueState (wizard
// entry, before polling kicks in).
function _applyLaunchButtonClasses(running) {
  const startBtn = document.getElementById('btn-start');
  const queueBtn = document.getElementById('btn-queue');
  if (!startBtn || !queueBtn) return;
  if (running) {
    startBtn.classList.remove('btn-start');
    startBtn.classList.add('btn-secondary');
    queueBtn.classList.remove('btn-secondary');
    queueBtn.classList.add('btn-start');
  } else {
    startBtn.classList.remove('btn-secondary');
    startBtn.classList.add('btn-start');
    queueBtn.classList.remove('btn-start');
    queueBtn.classList.add('btn-secondary');
  }
}

function setCampaignButtons(running, paused = false, pauseRequested = false) {
  // v2.59.x — Side-by-side Start + Add to Queue pills (Variant A). Start
  // is always present and shows the campaign-can-fire intent (gold when
  // idle, dimmed when one is already running). btn-queue is always enabled
  // — the operator can stage a queued campaign regardless of state — and
  // takes the gold treatment while something is running, so it's the
  // visually-active action in that moment. _applyLaunchButtonClasses
  // handles the gold class swap so the wizard-poller and the status-poller
  // both stay in sync.
  ['btn-start', 'btn-start-rb'].forEach(id => {
    const b = document.getElementById(id);
    if (!b) return;
    b.disabled = running;
  });
  const queueBtn = document.getElementById('btn-queue');
  if (queueBtn) queueBtn.disabled = false;
  _applyLaunchButtonClasses(running);
  // v2.14.x: Stop button is now enabled during monitoring too, not just
  // while sending. The bottom-bar Stop was previously dead during monitoring,
  // and the only way to halt was a hidden "✕ Stop monitoring" button buried
  // inside the collapsed monitoring-card details. confirmStopCampaign routes
  // the click based on state (running → existing flow, monitoring → new
  // stop-monitoring modal).
  const _monitoring = !running && __cockpit && __cockpit.state === 'monitoring';
  ['btn-stop',  'btn-stop-rb' ].forEach(id => { const b = document.getElementById(id); if (b) b.disabled = !running && !_monitoring; });
  // Disable Check DMs while a campaign runs (mutex — both need the same browsers)
  const btnCheck = document.getElementById('btn-check-dms');
  if (btnCheck) btnCheck.disabled = running;
  // Phase 2.8.9: pause/resume button state mirrors server-reported status.
  ['btn-pause', 'btn-pause-rb'].forEach(id => {
    const b = document.getElementById(id);
    if (!b) return;
    if (!running) {
      b.disabled = true;
      b.textContent = 'Pause';
    } else if (paused) {
      b.disabled = false;
      b.textContent = 'Resume';
    } else if (pauseRequested) {
      b.disabled = true;
      b.textContent = 'Pausing…';
    } else {
      b.disabled = false;
      b.textContent = 'Pause';
    }
  });
  // Bug 15: keep the editor's launch rail in sync with live campaign state every
  // poll — swaps "+ Launch options" for the Pause/Stop/Save control bar while a
  // campaign runs/monitors, and back once it's fully stopped.
  if (typeof window.updateEditingBanner === 'function') {
    try { window.updateEditingBanner(); } catch (_) {}
  }
  // v2.112.x: re-apply the viewing-active lock AFTER the base button states are
  // set, every poll. This keeps the lock/hint in sync and — because the lock
  // now gates on real live state — auto-releases the launch buttons the instant
  // a campaign finishes/stops, so the Start button can never be left disabled
  // (or, with the old code, hidden) on a campaign that's no longer running.
  if (typeof applyViewingActiveLock === 'function') {
    try { applyViewingActiveLock(); } catch (_) {}
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Phase 11.3 — Check DMs
// ─────────────────────────────────────────────────────────────────────────────
let checkDmsPollTimer = null;

async function startCheckDms() {
  try {
    // 2.9.7: Auto-routed — no profile picker. Server reads the sheet,
    // groups Sent-stage rows by Account Used, opens each sender's browser
    // and per-lead navigates to /messaging/thread/?recipient=<publicId>.
    const sheetUrl = document.getElementById('sheet-url')?.value?.trim();
    if (!sheetUrl) {
      alert('Enter a Google Sheet URL first.');
      return;
    }
    const linkedinColumn = document.getElementById('linkedin-column')?.value?.trim() || 'Linkedin URL';

    const btn = document.getElementById('btn-check-dms');
    if (btn) btn.disabled = true;

    // Expand the Replies section so the operator sees progress
    const section = document.getElementById('replies-section');
    if (section) section.classList.remove('collapsed');

    const res = await fetch('/api/check-dms/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sheetUrl, linkedinColumn }),
    });
    const data = await res.json();
    if (!res.ok) {
      alert(`Check DMs could not start: ${data.error || res.statusText}`);
      if (btn) btn.disabled = false;
      return;
    }
    startCheckDmsPolling();
  } catch (err) {
    alert(`Check DMs error: ${err.message}`);
    const btn = document.getElementById('btn-check-dms');
    if (btn) btn.disabled = false;
  }
}

function startCheckDmsPolling() {
  if (checkDmsPollTimer) clearInterval(checkDmsPollTimer);
  checkDmsPollTimer = setInterval(pollCheckDmsStatus, 2000);
  pollCheckDmsStatus();
  // 2.9.7: Check DMs orchestrator pushes diagnostic lines into
  // campaign.logs so the Live Status log feed picks them up. That feed
  // is updated by pollStatus() (separate from pollCheckDmsStatus), so
  // we kick the campaign poller too. Both stop on their own when idle.
  startPolling();
}

function stopCheckDmsPolling() {
  if (checkDmsPollTimer) {
    clearInterval(checkDmsPollTimer);
    checkDmsPollTimer = null;
  }
}

async function pollCheckDmsStatus() {
  try {
    const res = await fetch('/api/check-dms/status');
    if (!res.ok) return;
    const status = await res.json();

    const statusEl = document.getElementById('replies-status');
    if (statusEl) {
      if (status.running) {
        const active = status.currentProfile ? ` — scanning ${status.currentProfile}` : '';
        statusEl.textContent = `Scanning${active}…  (${status.repliesFound || 0} new replies so far)`;
      } else if (status.startedAt) {
        statusEl.textContent = '';
      } else {
        statusEl.textContent = '';
      }
    }

    if (!status.running) {
      stopCheckDmsPolling();
      await fetchCheckDmsReplies();
      const btn = document.getElementById('btn-check-dms');
      if (btn) btn.disabled = !!document.getElementById('btn-stop')?.disabled === false;
    }
  } catch {
    // ignore transient fetch errors; next tick retries
  }
}

async function fetchCheckDmsReplies() {
  try {
    const res = await fetch('/api/check-dms/replies');
    if (!res.ok) return;
    const result = await res.json();
    const container = document.getElementById('replies-body');
    if (container) renderRepliesPanel(container, result);
  } catch { /* */ }
}

// ─────────────────────────────────────────────────────────────────────────────
// Account queue display
// ─────────────────────────────────────────────────────────────────────────────
function renderAccountQueue(names, currentName, status, profileIds) {
  const el = document.getElementById('account-queue');
  if (!names || names.length === 0) { el.classList.add('hidden'); return; }
  el.classList.remove('hidden');
  // Per-row Open Browser / Try Again buttons need profile IDs. Fall back to
  // the IDs in status when not passed (poll path), and to selectedProfileIds
  // in scope when no status (wizard preview path).
  const ids = profileIds
    || (status && Array.isArray(status.profileIds) ? status.profileIds : null)
    || (Array.isArray(selectedProfileIds) ? selectedProfileIds : null)
    || [];

  // Pull per-profile state out of the status payload when available. Both
  // arrays are emitted by getCampaignStatus (parkedProfiles + softWarnings)
  // and may carry profileName/name + a reason/kind we can surface.
  const parked = (status && (status.parkedProfiles || status.parked)) || [];
  const warnings = (status && status.softWarnings) || [];
  const endReasons = (status && status.profileEndReasons) || [];
  const cooldown429 = (status && status.cooldown429) || {};
  // pName is the key parkedProfiles uses; profileName / name / account cover
  // softWarnings + profileEndReasons + future shapes.
  const findIn = (arr, name) => {
    if (!Array.isArray(arr)) return null;
    return arr.find(x => (
      x?.profileName === name ||
      x?.pName === name ||
      x?.name === name ||
      x?.account === name
    )) || null;
  };

  // Resolve a row's state to one of 10 distinct chips. Each chip is its own
  // label + stateClass; visual differentiation lives in style.css. Per-lead
  // issues (email_required etc.) no longer surface here — they're just sheet
  // stamps + log lines.
  function resolveChip({ isActive, isPastCurrent, parkedHit, cooldownHit, warningHit, endHit }) {
    if (isActive) {
      return { label: 'Sending', stateClass: 'chip-sending', detail: '' };
    }
    if (parkedHit) {
      const r = parkedHit.reason;
      if (r === 'session_expired') {
        return { label: 'Needs login', stateClass: 'chip-needs-login', detail: 'Session expired' };
      }
      if (r === 'weekly_limit_429') {
        return { label: 'LinkedIn cap · invites', stateClass: 'chip-li-invites', detail: 'Weekly invite cap reached' };
      }
      if (r === 'consecutive_skips') {
        const n = parkedHit.skipCount ? `${parkedHit.skipCount} consecutive skips` : 'too many consecutive skips';
        return { label: 'Parked · too many skips', stateClass: 'chip-parked', detail: n };
      }
      return { label: 'Parked', stateClass: 'chip-parked', detail: r || '' };
    }
    if (cooldownHit) {
      const m = Math.max(1, Math.ceil((cooldownHit.until - Date.now()) / 60000));
      return { label: 'Cooling down — 429', stateClass: 'chip-cooling', detail: `retry in ${m} min` };
    }
    if (warningHit) {
      const k = warningHit.kind;
      if (k === 'weekly_limit') {
        return { label: 'LinkedIn cap · invites', stateClass: 'chip-li-invites', detail: 'Weekly invite cap reached' };
      }
      if (k === 'note_limit') {
        return { label: 'Out of note credits', stateClass: 'chip-li-invites', detail: 'Out of free custom notes (monthly cap) — benched for noted invites' };
      }
      if (k === 'rate_limited') {
        return { label: 'Rate limited', stateClass: 'chip-rate-limited', detail: 'LinkedIn rate-limit page shown' };
      }
      // Unknown future kind — fall through to a generic action chip rather than hiding it.
      return { label: 'Action required', stateClass: 'chip-needs-login', detail: warningHit.message || k || '' };
    }
    if (endHit) {
      const r = String(endHit.reason || '');
      if (/InMail/i.test(r)) {
        return { label: 'LinkedIn cap · InMail', stateClass: 'chip-li-inmail', detail: r };
      }
      if (/weekly|429/i.test(r)) {
        return { label: 'LinkedIn cap · invites', stateClass: 'chip-li-invites', detail: r };
      }
      if (/session expired/i.test(r)) {
        return { label: 'Needs login', stateClass: 'chip-needs-login', detail: r };
      }
      if (/bulk|sweep|Check Status/i.test(r)) {
        return { label: 'Status sweep done', stateClass: 'chip-bulk-done', detail: r };
      }
      if (/campaign limit|Reached campaign/i.test(r)) {
        return { label: 'Batch done', stateClass: 'chip-batch', detail: r };
      }
      // Default terminal — treat as clean batch end.
      return { label: 'Batch done', stateClass: 'chip-batch', detail: r };
    }
    if (isPastCurrent) {
      return { label: 'Batch done', stateClass: 'chip-batch', detail: '' };
    }
    return { label: 'Queued', stateClass: 'chip-queued', detail: '' };
  }

  // Header + legend get rendered ONCE above the rows so the operator can
  // always reach the chip glossary without scrolling.
  const headerHtml = `
    <div class="account-queue-header">
      <span class="account-queue-title">Account queue</span>
      <button type="button" class="queue-help-ico" onclick="toggleAccountQueueLegend()" title="What do these chips mean?">?</button>
    </div>
    <div class="account-queue-legend" id="account-queue-legend" hidden>
      ${_renderAccountQueueLegend()}
    </div>
  `;

  const rowsHtml = names.map((name, i) => {
    const isActive = currentName && name === currentName;
    const isPastCurrent = currentName && names.indexOf(currentName) > i;
    const parkedHit = findIn(parked, name);
    const warningHit = findIn(warnings, name);
    const endHit = findIn(endReasons, name);
    // Derive cooldown hit: keyed by profileId first, then pName fallback.
    // Guard until > Date.now() in case the poll is stale.
    const profileId = ids[i] || '';
    const _cd429ById = profileId && cooldown429[profileId];
    const _cd429ByName = !_cd429ById && Object.values(cooldown429).find(x => x?.pName === name);
    const _cd429 = _cd429ById || _cd429ByName || null;
    const cooldownHit = (_cd429 && _cd429.until > Date.now()) ? _cd429 : null;

    const { label, stateClass, detail } = resolveChip({
      isActive, isPastCurrent, parkedHit, cooldownHit, warningHit, endHit,
    });

    // Try Again only for parked rows; Open Browser is always available so
    // the operator can manually inspect a profile mid-run.
    const tryAgainBtn = (parkedHit && profileId)
      ? `<button type="button" class="queue-row-btn" onclick="tryAgainProfile('${escHtml(profileId)}')" title="Clear the parked state and reopen this profile's browser so you can log in / fix the issue">Try again</button>`
      : '';
    const openBtn = profileId
      ? `<button type="button" class="queue-row-btn queue-row-btn--ghost" onclick="openProfileBrowser('${escHtml(profileId)}')" title="Open or focus the GoLogin browser for this profile">Open browser</button>`
      : '';
    return `
      <div class="queue-row ${stateClass}">
        <span class="queue-row-num">${i + 1}</span>
        <span class="queue-row-name">${escHtml(name)}</span>
        <span class="queue-row-status">${escHtml(label)}</span>
        <span class="queue-row-detail">${detail ? escHtml(detail) : ''}</span>
        <span class="queue-row-actions">${tryAgainBtn}${openBtn}</span>
      </div>
    `;
  }).join('');

  el.innerHTML = headerHtml + rowsHtml;
}

function toggleAccountQueueLegend() {
  const panel = document.getElementById('account-queue-legend');
  if (!panel) return;
  panel.hidden = !panel.hidden;
}
window.toggleAccountQueueLegend = toggleAccountQueueLegend;

function _renderAccountQueueLegend() {
  const groups = [
    { title: 'Active', rows: [
      ['Queued', 'chip-queued', 'Waiting its turn. Will run when an earlier account finishes.'],
      ['Sending', 'chip-sending', 'Sending right now. Progress shown in the detail column.'],
    ]},
    { title: 'Finished — nothing to do', rows: [
      ['Batch done', 'chip-batch', "Hit today's target. Picks up again on the next scheduled run."],
      ['Status sweep done', 'chip-bulk-done', 'Bulk Connection-Status check finished. Informational only.'],
    ]},
    { title: 'LinkedIn put a ceiling on you', rows: [
      ['Cooling down — 429', 'chip-cooling', 'Hit a temporary LinkedIn rate-limit. Retries automatically when the countdown ends — no action needed.'],
      ['LinkedIn cap · invites', 'chip-li-invites', 'Weekly invite cap reached (~200/wk; lower on some accounts). LinkedIn rule, not ours.'],
      ['LinkedIn cap · InMail', 'chip-li-inmail', 'Out of InMail credits. Waits for LinkedIn to top them up.'],
    ]},
    { title: 'Needs you · 1-click in the browser', rows: [
      ['Needs login', 'chip-needs-login', 'Session expired. Open the GoLogin browser and sign back in.'],
      ['Rate limited', 'chip-rate-limited', 'LinkedIn showed a rate-limit page. Open browser to verify.'],
    ]},
    { title: 'Out of rotation', rows: [
      ['Parked · too many skips', 'chip-parked', 'Auto-pulled after consecutive skips. "Try again" puts it back.'],
    ]},
  ];
  return groups.map(g => `
    <div class="legend-group">
      <div class="legend-group-title">${escHtml(g.title)}</div>
      ${g.rows.map(([label, cls, desc]) => `
        <div class="legend-row">
          <span class="legend-chip ${cls}">${escHtml(label)}</span>
          <span class="legend-desc">${escHtml(desc)}</span>
        </div>
      `).join('')}
    </div>
  `).join('');
}

async function openProfileBrowser(profileId) {
  if (!profileId) return;
  try {
    const r = await fetch(`/api/profile/${encodeURIComponent(profileId)}/open-browser`, { method: 'POST' });
    const data = await r.json();
    if (!r.ok) throw new Error(data.error || `HTTP ${r.status}`);
    const verb = data.action === 'launched' ? 'Opening' : 'Focused';
    showCampaignToast(`${verb} browser for this profile.`, 4000);
  } catch (err) {
    showCampaignToast(`Could not open browser: ${err.message}`, 6000);
  }
}
window.openProfileBrowser = openProfileBrowser;

async function tryAgainProfile(profileId) {
  if (!profileId) return;
  try {
    const r = await fetch(`/api/campaign/profile/${encodeURIComponent(profileId)}/retry`, { method: 'POST' });
    const data = await r.json();
    if (!r.ok) throw new Error(data.error || `HTTP ${r.status}`);
    const browserNote = data.browser?.action === 'launched'
      ? ' Browser opening — log in there.'
      : (data.browser?.action === 'focused-existing' ? ' Browser focused.' : '');
    showCampaignToast(`Retrying ${data.profileName || 'profile'} on next rotation.${browserNote}`, 6000);
  } catch (err) {
    showCampaignToast(`Could not retry: ${err.message}`, 6000);
  }
}
window.tryAgainProfile = tryAgainProfile;

// ─────────────────────────────────────────────────────────────────────────────
// Launch feedback popup (Issues ⑤ + ①)
// Instant "Launching…" modal shown the moment Start is pressed. It covers the
// multi-second pre-flight + start-fetch dead-air (⑤) and, by staying up until
// the new run actually boots, stops the PREVIOUS finished campaign from
// lingering in the Live Status card during that window (①). Dismissed by:
//   • startCampaign() when the launch resolves cloud / queued / failed,
//   • pollStatus() the instant the new local run flips `running` true,
//   • a 30s watchdog so it can never get stuck.
// ─────────────────────────────────────────────────────────────────────────────
let _launchWatchdog = null;
function beginLaunching(label) {
  window.__launching = true;
  let scrim = document.getElementById('launch-scrim');
  if (!scrim) {
    scrim = document.createElement('div');
    scrim.id = 'launch-scrim';
    scrim.className = 'modal-scrim';
    scrim.innerHTML =
      '<div class="modal-card solid" role="status" aria-live="polite">'
      + '<div class="modal-eyebrow">Launching</div>'
      + '<div class="launch-spinner"></div>'
      + '<div class="modal-title" id="launch-scrim-title">Starting campaign…</div>'
      + '<div class="launch-sub">Preparing your accounts and lead sheet — this can take a few seconds.</div>'
      + '</div>';
    document.body.appendChild(scrim);
  }
  const t = document.getElementById('launch-scrim-title');
  if (t) t.textContent = label ? `Starting “${label}”…` : 'Starting campaign…';
  scrim.classList.add('open');
  if (_launchWatchdog) clearTimeout(_launchWatchdog);
  _launchWatchdog = setTimeout(() => { endLaunching(); }, 30000);
}
function endLaunching() {
  window.__launching = false;
  if (_launchWatchdog) { clearTimeout(_launchWatchdog); _launchWatchdog = null; }
  const scrim = document.getElementById('launch-scrim');
  if (scrim) scrim.classList.remove('open');
}
if (typeof window !== 'undefined') { window.beginLaunching = beginLaunching; window.endLaunching = endLaunching; }

// ─────────────────────────────────────────────────────────────────────────────
// Status polling
// ─────────────────────────────────────────────────────────────────────────────
function startPolling() {
  if (pollInterval) return;
  pollInterval = setInterval(pollStatus, 2000);
  pollStatus();
  // v2.129: the unified Campaigns board (local + cloud strips) replaces the
  // hero + Up Next + Past as the top-level view.
  try { if (typeof startCampaignsBoard === 'function') startCampaignsBoard(); } catch (_) { /* */ }
}

function stopPolling() {
  if (pollInterval) clearInterval(pollInterval);
  pollInterval = null;
}

async function pollStatus() {
  try {
    const res = await fetch('/api/campaign/status');
    const s = await res.json();

    // 2.9.7: Check DMs runs as a separate flow with its own state. When a
    // Check DMs scan is active, overlay its status onto the cockpit so the
    // operator sees Live progress instead of "No campaign running". Resolve
    // the profile id → display name via the cached profileNameCache (filled
    // by /api/profiles).
    try {
      const cdRes = await fetch('/api/check-dms/status');
      if (cdRes.ok) {
        const cd = await cdRes.json();
        if (cd.running) {
          const matched = (allProfilesData || []).find(p => p.id === cd.currentProfile);
          const accountName = cd.currentProfile === 'local-browser'
            ? 'You'
            : (matched?.name || cd.currentProfile || '—');
          s.running = true;
          s.mode = 'check_dms';
          s.currentProfile = accountName;
          s.currentAction = {
            label: `Scanning DMs — ${cd.repliesFound || 0} new repl${cd.repliesFound === 1 ? 'y' : 'ies'} found`,
            account: accountName,
            lead: '—',
            mode: 'check_dms',
            startedAt: cd.startedAt || Date.now(),
          };
        }
      }
    } catch { /* check-dms overlay is best-effort */ }

    // v2.12.x: same overlay pattern for Post Amplification — paint live
    // progress (current account · index/total) into the cockpit using the
    // shape renderCockpit expects.
    try {
      const paRes = await fetch('/api/post-amplification/status');
      if (paRes.ok) {
        const pa = await paRes.json();
        if (pa.running) {
          s.running = true;
          s.mode = 'post_amplification';
          s.currentProfile = pa.currentProfile || '';
          s.processedToday = pa.engaged || 0;
          s.totalProcessed = pa.completed || 0;
          s.totalTargets = pa.total || 0;
          s.currentAction = {
            label: pa.currentProfile
              ? `Engaging ${pa.currentIndex}/${pa.total} · ${pa.currentProfile}`
              : 'Starting…',
            account: pa.currentProfile || '—',
            lead: pa.postUrl ? '(amplifying post)' : '—',
            mode: 'post_amplification',
            startedAt: pa.startedAt || Date.now(),
          };
          s.errors = (pa.errors || []).map(e => ({ message: e }));
        }
      }
    } catch { /* post-amp overlay is best-effort */ }

    // Cloud campaigns run on the VM, so the LOCAL status is idle even while a
    // cloud campaign is actively sending. Keep a lightweight running/queued count
    // (throttled ~6s so we don't hammer the engine) so the dashboard hero can say
    // "running in the cloud" instead of contradicting the cloud board with
    // "No campaign running". Only relevant when no local campaign is running.
    if (!s.running) {
      const now = Date.now();
      if (now - (window.__cloudSummaryAt || 0) > 6000) {
        window.__cloudSummaryAt = now;
        fetch('/api/campaign/cloud-list').then((r) => r.json()).then((cd) => {
          const cs = (cd && cd.campaigns) || [];
          window.__cloudHeroSummary = {
            running: cs.filter((c) => c.status === 'running').length,
            queued: cs.filter((c) => c.status === 'pending' || c.status === 'queued').length,
          };
        }).catch(() => {});
      }
    } else {
      window.__cloudHeroSummary = { running: 0, queued: 0 };
    }

    // ⑤+①: the new local run has booted (running flipped true) — retire the
    // launch popup now, in the same tick the card repaints below, so it reveals
    // the NEW campaign with no flash of the previous one.
    if (window.__launching && s.running) endLaunching();

    // Phase 2.8.12: feed the cockpit panel with the latest status snapshot
    // (renderCockpit + tick handle the smooth countdown without re-polling).
    updateCockpit(s);

    // v0.3 dashboard renderers — paint the Active + Monitoring cards from the
    // same status snapshot. Guard with typeof check so the call is a no-op
    // until the renderers are defined (and survives partial reloads).
    if (typeof window.renderActiveCard === 'function') window.renderActiveCard(s);
    if (typeof window.renderMonitoringCard === 'function') window.renderMonitoringCard(s);
    if (typeof maybeShowCampaignDoneModal === 'function') maybeShowCampaignDoneModal(s);
    if (typeof maybeShowLoginModal === 'function') maybeShowLoginModal(s);

    // Detect campaign completion and refresh history
    if (wasRunning && !s.running) {
      fetchHistory();
      notify('Campaign finished', `${s.processedToday} connections sent. ${(s.errors || []).length} errors.`);
    }
    // Detect new errors
    if (s.running && (s.errors || []).length > (wasErrorCount || 0)) {
      const latest = s.errors[s.errors.length - 1];
      notify('Campaign error', latest?.message || 'Unknown error');
    }
    wasErrorCount = (s.errors || []).length;
    wasRunning = s.running;
    renderParkedProfiles(s.parked);
    renderSoftWarnings(s.softWarnings);
    renderDiskBanner(s.disk);

    // Phase 2.8.13: status / mode / profile pills moved INTO the cockpit panel
    // (handled by renderCockpit). The legacy st-running/st-mode/st-profile
    // tiles are gone — guard their setters in case any are still in the DOM
    // (e.g. older cached HTML).
    const runEl = document.getElementById('st-running');
    const warningEl = document.getElementById('campaign-warnings');
    if (s.running) {
      if (runEl) {
        if (s.paused) { runEl.textContent = 'Paused'; runEl.className = 'value paused'; }
        else if (s.pauseRequested) { runEl.textContent = 'Pausing…'; runEl.className = 'value pausing'; }
        else { runEl.textContent = 'Running'; runEl.className = 'value running'; }
      }
      if (warningEl) warningEl.style.display = '';
      // On the new-campaign view, force the button state to idle — the
      // running campaign is somebody else's, not this draft. Start should
      // be live so the operator can launch (or queue) this draft;
      // Pause/Stop/Force-restart should be disabled because they'd act on
      // the other campaign, not this one. The actual one-at-a-time backend
      // constraint is enforced server-side (queue-or-409); UI just reflects
      // the per-tab story.
      const _isNewView = typeof isOnNewCampaignView === 'function' && isOnNewCampaignView();
      if (_isNewView) setCampaignButtons(false);
      else setCampaignButtons(true, !!s.paused, !!s.pauseRequested);
    } else {
      if (runEl) { runEl.textContent = 'Idle'; runEl.className = 'value stopped'; }
      if (warningEl) warningEl.style.display = 'none';
      setCampaignButtons(false);
      // v2.14.x: keep polling during monitoring so the cockpit's nextCheckAt
      // countdown stays in sync when the backend reschedules after each
      // hourly bulk-check. Without this, the Live Status panel and run-bar
      // freeze on the previous check's timestamp (operator saw "16:30 · 0s"
      // while Schedules card correctly showed 17:30 — same `campaign.nextCheckAt`
      // value, but the cockpit-fed endpoint stopped being polled).
      // v2.72: keep polling while the operator is on the wizard so the finished
      // Live Status card (log + Run reply check) stays rendered there. Stop only
      // when they're off the wizard (the dashboard has its own poll).
      const _onWizardRoute = (typeof document !== 'undefined' && document.body.classList.contains('route-wizard'))
        || (typeof location !== 'undefined' && location.hash === '#/new');
      if (s.logs?.length > 0 && !s.running && s.state !== 'monitoring' && !_onWizardRoute) stopPolling();
    }

    const profEl = document.getElementById('st-profile');
    if (profEl) profEl.textContent = s.currentProfile || '—';
    const modeEl = document.getElementById('st-mode');
    if (modeEl) {
      const modeLabels = {
        connect_only: 'Connect Only',
        message_only: 'Direct Messages', inmail_only: 'InMail Only', check_status: 'Check Status',
        open_profile_only: 'Open Profile',
      };
      modeEl.textContent = modeLabels[s.mode] || s.mode || '—';
    }

    const todayEl = document.getElementById('st-today');     if (todayEl)  todayEl.textContent  = s.processedToday;
    const totalEl = document.getElementById('st-total');     if (totalEl)  totalEl.textContent  = s.totalTargets;
    const errEl   = document.getElementById('st-errors');    if (errEl)    errEl.textContent    = (s.errors || []).length;

    const pct = s.totalTargets > 0 ? Math.min(100, Math.round((s.processedToday / s.totalTargets) * 100)) : 0;
    const barEl = document.getElementById('st-bar');         if (barEl)    barEl.style.width = pct + '%';

    // Phase 11.1: resource tiles + slow-mode banner
    renderHeaderResources(s.resources || null);
    renderThrottleBanner(s.throttle || null);

    // Update account queue if we have profile names. Suppress on the
    // new-campaign view so the running campaign's queue doesn't flash in
    // between renderCockpit's blanking ticks. renderCockpit already hides
    // #account-queue; this stops the repaint from undoing that.
    const _isNewView = typeof isOnNewCampaignView === 'function' && isOnNewCampaignView();
    if (!_isNewView && s.profileNames && s.profileNames.length > 0) {
      renderAccountQueue(s.profileNames, s.currentProfile, s, s.profileIds);
    }

    // Blank the main log on new-campaign view so a globally-running
    // campaign's lines don't bleed into a freshly-opened wizard tab.
    if (typeof isOnNewCampaignView === 'function' && isOnNewCampaignView()) {
      const panel = document.getElementById('log-panel');
      if (panel) panel.innerHTML = '<div class="entry info">No activity for this campaign.</div>';
    } else if (s.logs?.length > 0) {
      const panel = document.getElementById('log-panel');
      // Honor a user-chosen "clear log" cutoff so reloads/polls don't resurrect old entries.
      let cutoff = 0;
      try {
        const raw = localStorage.getItem('ortus-log-cleared-at');
        if (raw) cutoff = new Date(raw).getTime();
      } catch (_) {}
      const visible = s.logs.filter((line) => {
        if (!cutoff) return true;
        const m = line.match(/^\[(.*?)\]/);
        if (!m) return true;
        const t = new Date(m[1]).getTime();
        return !isNaN(t) && t > cutoff;
      });
      if (visible.length === 0) {
        panel.innerHTML = '<div class="entry info">Log cleared.</div>';
      } else {
        panel.innerHTML = visible.map(line => {
          let cls = '';
          if (line.includes('✓') || line.includes('connection_sent') || line.includes('message_sent') || line.includes('status_accepted')) cls = 'success';
          else if (line.includes('✗') || line.includes('Error') || line.includes('FAILED')) cls = 'error';
          else if (line.includes('⚠') || line.includes('SKIPPED')) cls = 'warn';
          else if (line.includes('===') || line.includes('▶') || line.includes('■')) cls = 'info';
          return `<div class="entry ${cls}">${escHtml(line)}</div>`;
        }).join('');
        panel.scrollTop = panel.scrollHeight;
      }
    }

    // v2.14.x: feed the in-flight bulk-check panel from the campaign
    // logs we just polled. Catches the campaign's own in-batch bulk-
    // checks (📡 'In-batch ... (5-min cooldown elapsed)…' lines) so the
    // operator gets the same graphical treatment whether they pressed
    // the button or the campaign auto-triggered the sweep.
    // renderBulkCheckLive auto-hides when activity is >30s old, so this
    // is a no-op during the dormant phases of a long campaign. The
    // manual bulkCheckNow flow uses __keepAlive to override the timeout
    // while the operator-initiated sweep is in flight.
    try {
      if (Array.isArray(s.logs) && s.logs.length > 0) {
        const bcLive = parseBulkCheckFromLogs(s.logs);
        renderBulkCheckLive(bcLive);
      }
    } catch { /* */ }

    // Floating live console — runs on every poll tick. Idempotent; only
    // writes DOM when values change (see _lcWriteCache).
    try { renderLiveConsole(s); } catch (err) { console.warn('[live-console] render failed:', err.message); }

    // v2.61: Live Status section visibility — only renders when we're on
    // the wizard view of the currently-running campaign. Hidden for
    // drafts/queue/schedule views so the Launch section becomes the last
    // visible section (no blank space underneath).
    try { syncLiveStatusVisibility(); } catch (err) { console.warn('[live-status] sync failed:', err.message); }
  } catch { /* */ }
}

// v2.61: Live Status section visibility. The section (#nav-status) and its
// sidebar nav item are display:none unless:
//   - we're on the wizard view (#/new)
//   - AND a campaign is currently running (__cockpit.running) OR monitoring
//     (__cockpit.state === 'monitoring')
//   - AND we are NOT editing a draft (isOnNewCampaignView() === false)
// v2.59.16: the monitoring clause was missing — during the post-send
// monitoring phase __cockpit.running is false, so the Live Status section
// (and its log) AND the "Open log" / "Live Status" nav buttons were hidden.
// That's why the log "disappeared" in monitoring and "Open log" did nothing
// (it scrolled to a display:none element). Monitoring is a live phase too.
// The "editing a draft" check leverages the existing heuristic: clicking
// "View running" from the dashboard clears activeDraftId, so navigating
// into a running campaign satisfies the third condition.
// v2.86.1 (port): set true when the operator clicks the sidebar "Open log" so
// the Live Status section is revealed even when idle (no campaign ran this
// session). Without it, "Open log" was a no-op when nothing was running — it
// scrolled to a display:none element. Reset on leaving the wizard (applyRoute).
let liveStatusForcedOpen = false;
function syncLiveStatusVisibility() {
  const sec = document.getElementById('nav-status');
  if (!sec) return;
  const onNew = typeof location !== 'undefined' && location.hash === '#/new';
  const editingDraft = (typeof isOnNewCampaignView === 'function') && isOnNewCampaignView();
  const running = !!(typeof __cockpit !== 'undefined' && __cockpit && __cockpit.running);
  const monitoring = !!(typeof __cockpit !== 'undefined' && __cockpit && __cockpit.state === 'monitoring');
  // v2.72: also keep the section visible once a campaign has FINISHED (not
  // running, not monitoring, but it ran this session — endNotice/logs present)
  // so the operator can still read the log and hit "Run reply check now".
  const finished = !!(typeof __cockpit !== 'undefined' && __cockpit && !__cockpit.running
    && __cockpit.state !== 'monitoring' && (__cockpit.endNotice || __cockpit.hasLogs));
  // Running/monitoring are hidden while editing an unrelated draft; a FINISHED
  // campaign's log is shown regardless (the wizard resets to a fresh draft on
  // finish, so editingDraft is true — but the operator still wants the log).
  // Follower Growth has its OWN self-contained log card (#fgtl-card); the generic
  // campaign Live Status (#nav-status) must never appear in FG view, else a prior
  // finished campaign's card lingers underneath the FG board (v2.119.2).
  // ...UNLESS we've deliberately opened a cloud campaign's live card (_viewingCloudId
  // set). A cloud FG run's card #2 must show exactly like any other VM campaign; the
  // FG-board suppression only applies when we're actually on the board (no cloud view).
  const inFollowerGrowth = (document.getElementById('campaign-mode')?.value === 'follower_growth') && !_viewingCloudId;
  // Viewing a cloud campaign in the wizard → its Live Status (section 7) must show
  // regardless of the local __cockpit state (which is idle for a VM campaign) and
  // even if liveStatusForcedOpen was reset by an unrelated re-render.
  const cloudView = !!(_viewingCloudId && window.__cloudActiveStatus);
  const show = !inFollowerGrowth && onNew && (liveStatusForcedOpen || cloudView || ((running || monitoring) && !editingDraft) || finished);
  sec.style.display = show ? '' : 'none';
  const navBtn = document.querySelector('[data-nav="nav-status"]');
  if (navBtn) navBtn.style.display = show ? '' : 'none';
  // v2.59.22: relocate the live card into / out of the wizard slot.
  try { placeLiveCard(); } catch (_) { /* */ }
}
if (typeof window !== 'undefined') window.syncLiveStatusVisibility = syncLiveStatusVisibility;

// v2.59.22: move the single #active-card between its dashboard home and the
// wizard Live Status slot so both routes show the IDENTICAL card (zero drift —
// renderActiveCard drives the same element wherever it lives). In the wizard
// it gets full width + a taller, always-open log via .in-wizard.
let _activeCardHome = null;
function placeLiveCard() {
  const card = document.getElementById('active-card');
  const slot = document.getElementById('wiz-live-slot');
  const sec = document.getElementById('nav-status');
  if (!card) return;
  // Capture the dashboard home (parent + next sibling) once, before any move.
  if (!_activeCardHome && card.parentElement && card.parentElement.id !== 'wiz-live-slot') {
    _activeCardHome = { parent: card.parentElement, next: card.nextElementSibling };
  }
  const liveVisible = !!sec && sec.style.display !== 'none';
  // v2.142: the Live Status section's own visibility is the single source of
  // truth for whether the card belongs in the wizard slot. Previously this
  // also required document.body.route-wizard, which disagreed with the
  // hash-based test in syncLiveStatusVisibility() on a local/native run —
  // the header showed but #active-card was never relocated (empty box).
  const wantWizard = liveVisible && !!slot;
  if (wantWizard && slot) {
    if (card.parentElement !== slot) {
      slot.appendChild(card);
      // Expand the section once on first placement so the card is visible —
      // not every poll, so a manual collapse afterwards still sticks.
      if (sec) sec.classList.remove('collapsed');
    }
    // v2.146: the dashboard board renderer (_hideLegacyDashboardSections) may
    // have set an inline display:none on this shared element while it lived on
    // the dashboard. Clear it now that the wizard owns the card, else it stays
    // invisible in the slot even though it's correctly placed and populated.
    if (card.style.display === 'none') card.style.display = '';
    card.classList.add('in-wizard', 'is-detailed');
    if (sec) sec.classList.add('is-card-live');
  } else {
    if (card.classList.contains('in-wizard')) {
      card.classList.remove('in-wizard');
      if (_activeCardHome && _activeCardHome.parent) {
        _activeCardHome.parent.insertBefore(card, _activeCardHome.next || null);
      }
    }
    if (sec) sec.classList.remove('is-card-live');
  }
}
if (typeof window !== 'undefined') window.placeLiveCard = placeLiveCard;

// ─── Phase 11.1: resource tiles + slow-mode banner ─────────────────────────
// Populated every 2s by pollStatus(). Thresholds match src/resource-monitor.js
// defaults (RAM_THROTTLE_PCT=80 / RAM_RELEASE_PCT=70 etc). If operator overrides
// env vars, tile colors stay tied to the 70/80 visual bands — see RESEARCH
// Open Question in 11.1-RESEARCH.md.

function classifyRam(pct) {
  if (pct >= 90) return 'err';
  if (pct >= 80) return 'warn';
  return '';
}

function classifyCpu(load1, cpuPct, cpuCount) {
  const effectiveLoad = load1 > 0 ? load1 : (cpuPct / 100) * cpuCount;
  if (effectiveLoad >= cpuCount * 0.9) return 'err';
  if (effectiveLoad >= cpuCount * 0.7) return 'warn';
  return '';
}

function renderHeaderResources(resources) {
  const ramTile = document.getElementById('hero-ram');
  const cpuTile = document.getElementById('hero-cpu');
  const brTile  = document.getElementById('hero-browsers');
  if (!ramTile || !cpuTile || !brTile) return;

  if (!resources) {
    ramTile.textContent = '—';  ramTile.className = 'v';
    cpuTile.textContent = '—';  cpuTile.className = 'v';
    brTile.textContent  = '—';  brTile.className  = 'v';
    return;
  }

  // RAM
  ramTile.textContent = `${Math.round(resources.ramPct)}%`;
  const ramCls = classifyRam(resources.ramPct);
  ramTile.className = ramCls ? `v ${ramCls}` : 'v';

  // CPU — display as % of total cores so non-Unix users aren't confused by
  // raw load averages. load1 on Unix is scaled by cpuCount; cpuPct on Windows
  // is already a percentage.
  if (resources.load1 > 0 && resources.cpuCount > 0) {
    cpuTile.textContent = `${Math.round((resources.load1 / resources.cpuCount) * 100)}%`;
  } else if (resources.cpuPct > 0) {
    cpuTile.textContent = `${Math.round(resources.cpuPct)}%`;
  } else {
    cpuTile.textContent = '—';
  }
  const cpuCls = classifyCpu(resources.load1, resources.cpuPct, resources.cpuCount);
  cpuTile.className = cpuCls ? `v ${cpuCls}` : 'v';

  // Browsers — count · total RSS
  const count = (resources.browsers || []).length;
  const rssGB = ((resources.totalBrowserRssMb || 0) / 1024).toFixed(1);
  brTile.textContent = `${count}·${rssGB}GB`;
  brTile.className = 'v';
}

function renderThrottleBanner(throttle) {
  const banner = document.getElementById('throttle-banner');
  if (!banner) return;
  if (throttle?.active) {
    banner.textContent = `⚠ SLOW MODE — ${throttle.reason}, delays ${throttle.multiplier}x`;
    banner.setAttribute('aria-live', 'polite');
    banner.style.display = '';
  } else {
    banner.textContent = '';
    banner.style.display = 'none';
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────────────────────────────────────
function escHtml(str) {
  const div = document.createElement('div');
  div.textContent = str || '';
  return div.innerHTML;
}

// ─────────────────────────────────────────────────────────────────────────────
// Templates
// ─────────────────────────────────────────────────────────────────────────────
async function fetchTemplateList() {
  try {
    const res = await fetch('/api/templates');
    const data = await res.json();
    const sel = document.getElementById('tpl-select');
    // Preserve the default option, clear the rest
    sel.innerHTML = '<option value="">-- Select a template --</option>';
    Object.keys(data).forEach(name => {
      const opt = document.createElement('option');
      opt.value = name;
      opt.textContent = name; // textContent is XSS-safe
      sel.appendChild(opt);
    });
  } catch (err) {
    console.error('Failed to fetch templates:', err);
  }
}

// Enable/disable the Save (in-place) button based on whether a template is
// selected — there's nothing to save TO when the dropdown is on the placeholder.
function syncTemplateSaveButton() {
  const sel = document.getElementById('tpl-select');
  const btn = document.getElementById('btn-save-tpl');
  if (!sel || !btn) return;
  btn.disabled = !sel.value;
}

async function loadSelectedTemplate() {
  const sel = document.getElementById('tpl-select');
  const name = sel.value;
  syncTemplateSaveButton();
  // Selecting the placeholder ("-- Select a template --") is a no-op now that
  // the dropdown auto-loads on change. No alert — that would fire every time
  // the operator deselects.
  if (!name) return;
  try {
    const res = await fetch('/api/templates');
    const data = await res.json();
    const tpl = data[name];
    if (!tpl) { alert('Template not found.'); return; }
    document.getElementById('tpl-note').value = tpl.connectionNote || '';
    document.getElementById('tpl-followup').value = tpl.followUp1 || '';
    document.getElementById('tpl-inmail-subject').value = tpl.inmailSubject || '';
    document.getElementById('tpl-inmail-body').value = tpl.inmailBody || '';
    const opSubj = document.getElementById('tpl-op-subject');
    const opBody = document.getElementById('tpl-op-body');
    if (opSubj) opSubj.value = tpl.openProfileSubject || '';
    if (opBody) opBody.value = tpl.openProfileBody || '';
    // v2.72: restore Open Profile send channel + InMail fallback
    const opChannel = document.getElementById('tpl-op-channel');
    if (opChannel) opChannel.value = tpl.opChannel || 'sn_first';
    const opSpendInMail = document.getElementById('tpl-op-spend-inmail');
    if (opSpendInMail) opSpendInMail.checked = !!tpl.opSpendInMail;
    const introBody = document.getElementById('primary-intro-body');
    if (introBody) {
      introBody.value = tpl.primaryIntroBody || '';
      if (typeof savePrimaryPersonFields === 'function') savePrimaryPersonFields();
    }
  } catch (err) {
    alert('Failed to load template: ' + err.message);
  }
}

// Save in-place — overwrites the currently selected template with the form's
// current values. POSTs to the same /api/templates endpoint that creates new
// ones; server keys by name so a same-name POST overwrites.
async function saveExistingTemplate() {
  const sel = document.getElementById('tpl-select');
  const name = sel.value;
  if (!name) { alert('Select a template first to save changes.'); return; }
  const templates = {
    connectionNote: document.getElementById('tpl-note').value,
    followUp1: document.getElementById('tpl-followup').value,
    inmailSubject: document.getElementById('tpl-inmail-subject').value,
    inmailBody: document.getElementById('tpl-inmail-body').value,
    openProfileSubject: document.getElementById('tpl-op-subject')?.value || '',
    openProfileBody: document.getElementById('tpl-op-body')?.value || '',
    opChannel: document.getElementById('tpl-op-channel')?.value || 'sn_first',
    opSpendInMail: !!document.getElementById('tpl-op-spend-inmail')?.checked,
    primaryIntroBody: document.getElementById('primary-intro-body')?.value || '',
    ccDmBody: document.getElementById('tpl-cc-dm-body')?.value || '',
  };
  try {
    const res = await fetch('/api/templates', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, templates }),
    });
    const data = await res.json();
    if (data.saved) {
      showCampaignToast(`Saved changes to "${name}".`, 2500);
    } else {
      alert('Failed to save template.');
    }
  } catch (err) {
    alert('Failed to save template: ' + err.message);
  }
}

async function saveCurrentTemplate() {
  // Electron disables window.prompt() — use our modal helper so Save As… works
  // in both the web dashboard and the packaged DMG.
  const name = await promptModal({ label: 'Template name:' });
  if (!name) return; // null = cancel / ESC / empty
  const templates = {
    connectionNote: document.getElementById('tpl-note').value,
    followUp1: document.getElementById('tpl-followup').value,
    inmailSubject: document.getElementById('tpl-inmail-subject').value,
    inmailBody: document.getElementById('tpl-inmail-body').value,
    openProfileSubject: document.getElementById('tpl-op-subject')?.value || '',
    openProfileBody: document.getElementById('tpl-op-body')?.value || '',
    opChannel: document.getElementById('tpl-op-channel')?.value || 'sn_first',
    opSpendInMail: !!document.getElementById('tpl-op-spend-inmail')?.checked,
    primaryIntroBody: document.getElementById('primary-intro-body')?.value || '',
    ccDmBody: document.getElementById('tpl-cc-dm-body')?.value || '',
  };
  try {
    const res = await fetch('/api/templates', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, templates }),
    });
    const data = await res.json();
    if (data.saved) {
      await fetchTemplateList();
      document.getElementById('tpl-select').value = name;
    } else {
      alert('Failed to save template.');
    }
  } catch (err) {
    alert('Failed to save template: ' + err.message);
  }
}

async function deleteSelectedTemplate() {
  const sel = document.getElementById('tpl-select');
  const name = sel.value;
  if (!name) { alert('Select a template first.'); return; }
  if (!confirm('Delete template "' + name + '"?')) return;
  try {
    const res = await fetch('/api/templates/' + encodeURIComponent(name), { method: 'DELETE' });
    const data = await res.json();
    if (data.deleted) {
      await fetchTemplateList();
    } else {
      alert('Failed to delete template.');
    }
  } catch (err) {
    alert('Failed to delete template: ' + err.message);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Campaign History
// ─────────────────────────────────────────────────────────────────────────────
async function fetchHistory() {
  const panel = document.getElementById('history-panel');
  if (!panel) return;
  try {
    const res = await fetch('/api/history');
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) {
      panel.innerHTML = '<p class="empty-state">No campaigns yet.</p>';
      return;
    }

    const modeLabels = {
      connect_only: 'Connect Only',
      message_only: 'Direct Messages', inmail_only: 'InMail Only', check_status: 'Check Status',
      open_profile_only: 'Open Profile',
    };

    // Sort newest first
    data.sort((a, b) => new Date(b.startedAt || b.date) - new Date(a.startedAt || a.date));

    // Hero metrics: Today / This week / Errors 24h
    populateHeroMetrics(data);

    let html = '<table class="history-table"><thead><tr>';
    html += '<th>Date</th><th>Mode</th><th>Profiles</th><th>Success</th><th>Errors</th><th>Duration</th>';
    html += '</tr></thead><tbody>';

    data.forEach((c, idx) => {
      const dt = c.startedAt || c.date || '';
      const dateStr = dt ? new Date(dt).toISOString().replace('T', ' ').substring(0, 16) : '--';
      const modeLabel = modeLabels[c.mode] || escHtml(c.mode || '--');
      const profiles = (c.profileNames || c.profiles || []).join(', ');
      const profileDisplay = profiles.length > 30 ? escHtml(profiles.substring(0, 27)) + '...' : escHtml(profiles);
      const success = c.successCount != null ? c.successCount : (c.totalProcessed || 0);
      const errors = c.errorCount != null ? c.errorCount : 0;

      // Duration calculation
      let durationStr = '--';
      if (c.duration != null) {
        durationStr = c.duration >= 60 ? Math.round(c.duration / 60) + 'm' : c.duration + 's';
      } else if (c.startedAt && c.endedAt) {
        const mins = Math.round((new Date(c.endedAt) - new Date(c.startedAt)) / 60000);
        durationStr = mins + 'm';
      }

      // Summary row
      html += '<tr data-idx="' + idx + '">';
      html += '<td>' + escHtml(dateStr) + '</td>';
      html += '<td>' + modeLabel + '</td>';
      html += '<td>' + profileDisplay + '</td>';
      html += '<td class="success-count">' + success + '</td>';
      html += '<td class="error-count">' + errors + '</td>';
      html += '<td>' + escHtml(durationStr) + '</td>';
      html += '</tr>';

      // Detail row (hidden by default)
      const tplNote = (c.templates && c.templates.connectionNote) || '';
      const tplDisplay = tplNote.length > 50 ? escHtml(tplNote.substring(0, 47)) + '...' : escHtml(tplNote);
      html += '<tr class="history-detail" data-detail-idx="' + idx + '">';
      html += '<td colspan="6"><dl>';
      html += '<dt>Templates</dt><dd>' + (tplDisplay || 'None') + '</dd>';
      html += '<dt>Campaign limit per account</dt><dd>' + escHtml(String(c.dailyLimit || '--')) + '</dd>';
      html += '<dt>Total Processed</dt><dd>' + escHtml(String(c.totalProcessed || 0)) + '</dd>';
      html += '</dl></td></tr>';
    });

    html += '</tbody></table>';
    panel.innerHTML = html;

    // Add click handlers for expanding detail rows
    panel.querySelectorAll('tr[data-idx]').forEach(tr => {
      tr.onclick = function() {
        const idx = this.getAttribute('data-idx');
        const detail = panel.querySelector('tr[data-detail-idx="' + idx + '"]');
        if (detail) detail.classList.toggle('expanded');
      };
    });
  } catch (err) {
    panel.innerHTML = '<p class="empty-state">Failed to load history.</p>';
  }
}

function downloadCsv() {
  const a = document.createElement('a');
  a.href = '/api/export/csv';
  a.download = 'campaign-export.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

async function clearHistory() {
  if (!confirm('Clear all campaign history? This cannot be undone.')) return;
  try {
    const res = await fetch('/api/history', { method: 'DELETE' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    await fetchHistory();
  } catch (err) {
    alert('Failed to clear history: ' + (err.message || 'Unknown error'));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Campaign Schedules
// ─────────────────────────────────────────────────────────────────────────────
function setLaunchMode(mode) {
  // v2.61: Launch section's Now/Schedule toggle was replaced by 4 inline
  // buttons (Start / Queue / Schedule / Save as draft). The toggle and its
  // two panels no longer exist in the DOM, so each getElementById can
  // legitimately return null. Guard each access so any stale caller
  // (autosave restore, preset load) becomes a no-op instead of a throw.
  const isSchedule = mode === 'schedule';
  const tabNow = document.getElementById('launch-mode-now');
  const tabSched = document.getElementById('launch-mode-schedule');
  if (tabNow) tabNow.classList.toggle('active', !isSchedule);
  if (tabSched) tabSched.classList.toggle('active', isSchedule);
  const now = document.getElementById('launch-now-panel');
  const sched = document.getElementById('launch-schedule-panel');
  if (now) {
    now.classList.toggle('panel-active', !isSchedule);
    now.classList.toggle('panel-inactive', isSchedule);
  }
  if (sched) {
    sched.classList.toggle('panel-active', isSchedule);
    sched.classList.toggle('panel-inactive', !isSchedule);
  }
}

function buildQuickCron() {
  const time = document.getElementById('quick-sched-time').value || '09:00';
  const [hoursStr, minutesStr] = time.split(':');
  const hours = parseInt(hoursStr, 10);
  const minutes = parseInt(minutesStr, 10);
  if (isNaN(hours) || isNaN(minutes)) return null;
  const checked = Array.from(document.querySelectorAll('.quick-sched-day:checked')).map((cb) => cb.value);
  if (checked.length === 0) return null;
  const days = checked.length === 7 ? '*' : checked.join(',');
  return `${minutes} ${hours} * * ${days}`;
}

async function saveQuickSchedule() {
  const name = document.getElementById('quick-sched-name').value.trim();
  if (!name) { alert('Give the schedule a name.'); return; }

  const cronExpr = buildQuickCron();
  if (!cronExpr) { alert('Pick at least one day and a valid time.'); return; }

  // Same validation as startCampaign
  if (selectedProfileIds.length === 0) { alert('Select at least one GoLogin account on the page first.'); return; }
  const sheetUrl = document.getElementById('sheet-url').value.trim();
  if (!sheetUrl) { alert('Enter the Google Sheet URL on the page first.'); return; }
  const dailyLimit = parseInt(document.getElementById('daily-limit').value, 10);
  if (!dailyLimit || dailyLimit < 1) { alert('Campaign limit per account must be at least 1.'); return; }

  const mode = document.getElementById('campaign-mode').value || 'connect_only';

  // Phase 11.2 (D-02, D-07): schedule form mirrors the main campaign form for
  // within-batch gap — explicit steppers for non-message modes.
  let delayMin, delayMax;
  if (mode === 'message_only') {
    const gap = parseInt(document.getElementById('message-gap')?.value, 10) || 60;
    delayMin = Math.max(5, Math.round(gap * 0.8));
    delayMax = Math.max(delayMin + 5, Math.round(gap * 1.3));
  } else {
    delayMin = parseInt(document.getElementById('within-batch-min')?.value, 10) || 30;
    delayMax = parseInt(document.getElementById('within-batch-max')?.value, 10) || 60;
    if (delayMax < delayMin) [delayMin, delayMax] = [delayMin, delayMin + 5];
  }

  // v2.11.0: batchesPerHour removed from schedules too — pacing is now the
  // 6-min turn floor + queue rotation, no per-schedule throughput knob.

  const addNoteOn = localStorage.getItem('ortus-add-note') === '1';
  const templates = {
    // v2.59: drop addNoteOn gate — textarea value IS the note.
    connectionNote: document.getElementById('tpl-note').value,
    followUp1: document.getElementById('tpl-followup').value,
    inmailSubject: document.getElementById('tpl-inmail-subject').value,
    inmailBody: document.getElementById('tpl-inmail-body').value,
    openProfileSubject: document.getElementById('tpl-op-subject')?.value || '',
    openProfileBody: document.getElementById('tpl-op-body')?.value || '',
    opChannel: document.getElementById('tpl-op-channel')?.value || 'sn_first',
    opSpendInMail: !!document.getElementById('tpl-op-spend-inmail')?.checked,
  };

  try {
    const res = await fetch('/api/schedules', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        cron: cronExpr,
        profileIds: selectedProfileIds,
        sheetUrl,
        mode,
        templates,
        dailyLimit,
        delayMin,
        delayMax,
        enabled: true,
      }),
    });
    const data = await res.json();
    if (!res.ok || !data.saved) { alert('Failed to save schedule: ' + (data.error || res.status)); return; }
    alert(`Schedule "${name}" saved. Notifications will go to your email.`);
    document.getElementById('quick-sched-name').value = '';
    fetchSchedules();
  } catch (err) {
    alert('Failed to save schedule: ' + err.message);
  }
}

async function fetchSchedules() {
  const panel = document.getElementById('schedule-list');
  if (!panel) return;
  try {
    const res = await fetch('/api/schedules');
    const data = await res.json();
    updateNextScheduleWidget(Array.isArray(data) ? data : []);
    if (!Array.isArray(data) || data.length === 0) {
      panel.innerHTML = '<p class="empty-state">No schedules yet. Create one from the <strong>Launch</strong> section → toggle to <em>Schedule</em>.</p>';
      return;
    }
    panel.innerHTML = data.map(s => {
      const lastRun = s.lastRun ? new Date(s.lastRun).toISOString().replace('T', ' ').substring(0, 16) : 'Never';
      const modeLabels = { connect_only: 'Connect', message_only: 'Message', inmail_only: 'InMail', check_status: 'Check', open_profile_only: 'Open Profile' };
      const modeLabel = modeLabels[s.mode] || s.mode;
      // Parse cron into friendly format
      const cronParts = (s.cron || '').split(' ');
      let cronFriendly = s.cron;
      if (cronParts.length === 5) {
        const min = cronParts[0].padStart(2, '0');
        const hr = cronParts[1].padStart(2, '0');
        const dayMap = { '0': 'Sun', '1': 'Mon', '2': 'Tue', '3': 'Wed', '4': 'Thu', '5': 'Fri', '6': 'Sat' };
        const daysPart = cronParts[4];
        const days = daysPart === '*' ? 'Every day' : daysPart.split(',').map(d => dayMap[d] || d).join(', ');
        cronFriendly = hr + ':' + min + ' — ' + days;
      }
      return '<div class="schedule-item">' +
        '<div class="sched-info">' +
          '<div class="sched-name">' + escHtml(s.name) + '</div>' +
          '<div class="sched-meta">' + escHtml(cronFriendly) + ' &middot; ' + modeLabel + ' &middot; limit ' + (s.dailyLimit || 5) + ' &middot; last: ' + escHtml(lastRun) + '</div>' +
        '</div>' +
        '<div class="sched-actions">' +
          // P-06 fix (2.8.18): defense-in-depth — escape single-quotes/backslashes in s.id
          // before embedding in the single-quoted onclick string. Server-side validation
          // (sched_<digits>) is the primary guard; this closes the injection sink even
          // if a malformed id ever survives the server check.
          ((safeId) => (
            '<button class="schedule-toggle ' + (s.enabled ? 'on' : 'off') + '" onclick="toggleScheduleEnabled(\'' + safeId + '\', ' + !s.enabled + ')" title="' + (s.enabled ? 'Disable' : 'Enable') + '"></button>' +
            '<button class="btn-remove" onclick="deleteSchedule(\'' + safeId + '\')" title="Delete">&times;</button>'
          ))(String(s.id || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'")) +
        '</div>' +
      '</div>';
    }).join('');
  } catch (err) {
    panel.innerHTML = '<p class="empty-state">Failed to load schedules.</p>';
  }
}

// createSchedule / buildCronFromUI removed — schedules are now created from the
// Launch section (saveQuickSchedule) using the live page state. See index.html.

async function toggleScheduleEnabled(id, enabled) {
  try {
    // Fetch current schedule data first, then update
    const listRes = await fetch('/api/schedules');
    const schedules = await listRes.json();
    const sched = schedules.find(s => s.id === id);
    if (!sched) { alert('Schedule not found.'); return; }
    sched.enabled = enabled;
    const res = await fetch('/api/schedules', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...sched, id }),
    });
    const data = await res.json();
    if (data.saved) await fetchSchedules();
  } catch (err) {
    alert('Failed to update schedule: ' + err.message);
  }
}

async function deleteSchedule(id) {
  if (!confirm('Delete this schedule?')) return;
  // v2.57.7: optimistic removal so the row disappears immediately from
  // both the Schedules panel and the ALL-tab clone.
  document.querySelectorAll(`.campaign-row[data-campaign-id="${CSS.escape(id)}"]`)
    .forEach((el) => el.remove());
  try {
    const res = await fetch('/api/schedules/' + encodeURIComponent(id), { method: 'DELETE' });
    const data = await res.json();
    if (data.deleted) {
      if (typeof fetchSchedules === 'function') await fetchSchedules();
      if (typeof refreshDashboardSchedules === 'function') await refreshDashboardSchedules();
      if (typeof renderDashboardAll === 'function') renderDashboardAll();
    }
  } catch (err) {
    alert('Failed to delete schedule: ' + err.message);
  }
}
window.deleteSchedule = deleteSchedule;

// ─────────────────────────────────────────────────────────────────────────────
// Collapsible sections
// ─────────────────────────────────────────────────────────────────────────────
function toggleSection(sectionId) {
  if (document.body.classList.contains('edit-mode')) return;
  const section = document.getElementById(sectionId);
  if (!section) return;
  section.classList.toggle('collapsed');
  try {
    localStorage.setItem(`section-collapsed:${sectionId}`, section.classList.contains('collapsed') ? '1' : '0');
  } catch (_) {}
}

// ─────────────────────────────────────────────────────────────────────────────
// Inline label editor — persists custom text to localStorage under 'ortus-edits'
// ─────────────────────────────────────────────────────────────────────────────
const EDITS_KEY = 'ortus-edits';
let editSnapshot = null;

function loadEditsFromStorage() {
  try { return JSON.parse(localStorage.getItem(EDITS_KEY) || '{}'); }
  catch (_) { return {}; }
}

function applySavedEdits() {
  const saved = loadEditsFromStorage();
  document.querySelectorAll('[data-edit]').forEach(el => {
    const key = el.dataset.edit;
    if (key && Object.prototype.hasOwnProperty.call(saved, key)) {
      el.textContent = saved[key];
    }
  });
}

function enterEditMode() {
  editSnapshot = {};
  document.querySelectorAll('[data-edit]').forEach(el => {
    editSnapshot[el.dataset.edit] = el.textContent;
    el.setAttribute('contenteditable', 'true');
    el.setAttribute('spellcheck', 'false');
    el.addEventListener('keydown', preventEditEnter);
  });
  document.body.classList.add('edit-mode');
  document.getElementById('edit-btn-enter').style.display = 'none';
  document.getElementById('edit-btn-save').style.display = '';
  document.getElementById('edit-btn-cancel').style.display = '';
  document.getElementById('edit-btn-reset').style.display = '';
}

function preventEditEnter(e) {
  if (e.key === 'Enter') { e.preventDefault(); e.target.blur(); }
}

function exitEditMode() {
  document.querySelectorAll('[data-edit]').forEach(el => {
    el.removeAttribute('contenteditable');
    el.removeAttribute('spellcheck');
    el.removeEventListener('keydown', preventEditEnter);
  });
  document.body.classList.remove('edit-mode');
  document.getElementById('edit-btn-enter').style.display = '';
  document.getElementById('edit-btn-save').style.display = 'none';
  document.getElementById('edit-btn-cancel').style.display = 'none';
  document.getElementById('edit-btn-reset').style.display = 'none';
  editSnapshot = null;
}

function saveEdits() {
  // Merge with any previously saved edits — preserves per-mode edits made
  // while a different mode was active (data-edit keys are mode-scoped).
  const edits = loadEditsFromStorage();
  document.querySelectorAll('[data-edit]').forEach(el => {
    edits[el.dataset.edit] = el.textContent.trim();
  });
  try { localStorage.setItem(EDITS_KEY, JSON.stringify(edits)); } catch (_) {}
  exitEditMode();
  // Re-render any surfaces that depend on saved edits (mode picker chips, etc.)
  renderModeSelector();
}

function cancelEdits() {
  if (editSnapshot) {
    document.querySelectorAll('[data-edit]').forEach(el => {
      const key = el.dataset.edit;
      if (key && Object.prototype.hasOwnProperty.call(editSnapshot, key)) {
        el.textContent = editSnapshot[key];
      }
    });
  }
  exitEditMode();
}

function resetEdits() {
  if (!confirm('Reset all label edits to defaults? This cannot be undone.')) return;
  try { localStorage.removeItem(EDITS_KEY); } catch (_) {}
  location.reload();
}

function restoreCollapsedSections() {
  document.querySelectorAll('.collapsible').forEach((el) => {
    if (!el.id) return;
    try {
      if (localStorage.getItem(`section-collapsed:${el.id}`) === '1') {
        el.classList.add('collapsed');
      }
    } catch (_) {}
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Theme toggle
// ─────────────────────────────────────────────────────────────────────────────
function setTheme(mode) {
  const isLight = mode === 'light';
  document.body.classList.toggle('theme-light', isLight);
  // Dashboard v0.3 CSS uses .theme-dark as its override convention; keep it
  // in sync so v0.3 follows the same theme button as the rest of the app.
  document.body.classList.toggle('theme-dark', !isLight);
  try { localStorage.setItem('ortus-theme', mode); } catch (_) {}
  const d = document.getElementById('theme-btn-dark');
  const l = document.getElementById('theme-btn-light');
  if (d) d.classList.toggle('active', !isLight);
  if (l) l.classList.toggle('active', isLight);
}

function initTheme() {
  let saved = null;
  try { saved = localStorage.getItem('ortus-theme'); } catch (_) {}
  if (!saved) {
    // First visit — follow OS preference
    const prefersLight = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
    saved = prefersLight ? 'light' : 'dark';
  }
  setTheme(saved);
}

// ─────────────────────────────────────────────────────────────────────────────
// Sidebar nav scrolling + scroll-spy
// ─────────────────────────────────────────────────────────────────────────────
function scrollToSection(id) {
  const el = document.getElementById(id);
  if (!el) return;

  // If we're on the dashboard route, the wizard view is display:none — switching
  // first (and waiting two RAF ticks for the route swap) makes scrollIntoView
  // actually land somewhere visible. Without this, View Status / Open log were
  // no-ops from the dashboard.
  const wasDashboard = document.body.classList.contains('route-dashboard');
  if (wasDashboard) window.location.hash = '#/new';

  const doScroll = () => {
    if (el.classList.contains('collapsible') && el.classList.contains('collapsed')) {
      el.classList.remove('collapsed');
      try { localStorage.setItem(`section-collapsed:${id}`, '0'); } catch (_) {}
    }
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveNav(id);
  };

  if (wasDashboard) {
    requestAnimationFrame(() => requestAnimationFrame(doScroll));
  } else {
    doScroll();
  }
}

function setActiveNav(id) {
  document.querySelectorAll('.nav-item').forEach((n) => n.classList.remove('active'));
  const trigger = document.querySelector(`.nav-item[data-nav="${id}"]`);
  if (trigger) trigger.classList.add('active');
  // A3 — re-run sidebar glyphs when scroll-spy changes the active section
  if (typeof updateSidebarGlyphs === 'function') updateSidebarGlyphs();
}

function initScrollSpy() {
  const ids = ['nav-accounts', 'nav-sheet', 'nav-settings', 'nav-templates', 'nav-launch', 'nav-status', 'history-section', 'schedules-section'];
  const sections = ids.map((id) => document.getElementById(id)).filter(Boolean);
  if (!sections.length || !('IntersectionObserver' in window)) return;
  const io = new IntersectionObserver((entries) => {
    // Pick the entry closest to the top of the viewport that is intersecting
    const visible = entries.filter((e) => e.isIntersecting)
      .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
    if (visible[0]) setActiveNav(visible[0].target.id);
  }, { rootMargin: '-40% 0px -55% 0px', threshold: 0 });
  sections.forEach((s) => io.observe(s));
}

// ─────────────────────────────────────────────────────────────────────────────
// Run bar mirror — Phase 2.8.13: now reads from __cockpit (the cockpit panel
// owns the canonical running/paused state since the legacy st-running tile
// was removed). Polled on the same 2s cadence as pollStatus.
// ─────────────────────────────────────────────────────────────────────────────
function initRunBarMirror() {
  const bar = document.getElementById('run-bar-status');
  const txt = document.getElementById('run-bar-text');
  // v2.57.7: top line of the two-line status stack — shows the running
  // campaign's name. Empty in idle state (CSS hides empty via :empty).
  const nameEl = document.getElementById('run-bar-name');
  const statusSection = document.getElementById('nav-status');
  if (!bar || !txt) return;
  let wasRunning = false;
  const sync = () => {
    // Force idle state for the bottom runbar when composing a new campaign
    // — the global running campaign's identity/stats shouldn't leak in.
    const newView = (typeof isOnNewCampaignView === 'function') && isOnNewCampaignView();
    const running = !newView && !!__cockpit.running;
    const monitoring = !newView && !running && __cockpit.state === 'monitoring';
    bar.classList.toggle('running', running);
    bar.classList.toggle('monitoring', monitoring);
    const mode = formatMode(__cockpit.mode);
    const today = document.getElementById('st-today')?.textContent || '0';
    const total = document.getElementById('st-total')?.textContent || '0';
    const cName = (__cockpit.name || '').trim();
    // v2.57.7: when no campaign name is set, fold the mode into the
    // identity slot ("Untitled · CC+IB") and drop it from the status
    // text. Avoids duplication and gives a hint of what kind of campaign
    // is live even when it's nameless.
    const identity = cName || `Untitled · ${mode}`;
    if (running) {
      const label = __cockpit.paused ? 'Paused' : (__cockpit.pauseRequested ? 'Pausing…' : 'Running');
      if (nameEl) nameEl.textContent = identity;
      // Status text strips the profile name (was too long, wrapped the
      // action strip) and only shows mode when a real name is set —
      // otherwise the mode already sits in the identity slot.
      const modePart = cName ? `${mode} · ` : '';
      txt.innerHTML = `<strong>${label}</strong> · ${modePart}${today}/${total}`;
    } else if (monitoring) {
      // v2.13.14 — surface monitoring countdown in the sticky toolbar.
      // v2.14.x — when a bulk-check is mid-fire, swap to "checking now…".
      // v2.57.7 — also surface the campaign name on the top line so the
      // operator sees which campaign is being monitored.
      if (nameEl) nameEl.textContent = identity;
      if (__cockpit.monitoringCheckInProgress) {
        txt.innerHTML = `<strong>Monitoring</strong> <span class="run-bar-meta-mono">checking now…</span>`;
      } else {
        const now = Date.now();
        const next = __cockpit.nextCheckAt ? new Date(__cockpit.nextCheckAt) : null;
        const until = __cockpit.monitoringUntil ? new Date(__cockpit.monitoringUntil) : null;
        const nextStr = _cockpitHHMM(next);
        const endsStr = until ? _cockpitFmtRemaining(until.getTime() - now) : '—';
        txt.innerHTML = `<strong>Monitoring</strong> <span class="run-bar-meta-mono">next ${nextStr} · ends in ${endsStr}</span>`;
      }
    } else {
      // v2.57.7 — idle: clear the name line so the status stack collapses
      // to the single "Idle · no campaign" row.
      if (nameEl) nameEl.textContent = '';
      txt.textContent = 'Idle · no campaign';
    }

    // Right-pane status mirror
    const rpDot = document.getElementById('rp-dot');
    const rpStatusText = document.getElementById('rp-status-text');
    const rpStatusSub = document.getElementById('rp-status-sub');
    // When the operator is composing a brand-new campaign, the right-pane
    // should look idle regardless of what other campaigns are doing — that
    // tab represents an unstarted campaign. Full per-campaign live scoping
    // comes with the isolation refactor.
    const onNewCampaignView = (typeof isOnNewCampaignView === 'function') && isOnNewCampaignView();
    if (rpDot) {
      rpDot.classList.toggle('running', !onNewCampaignView && running);
      rpDot.classList.toggle('monitoring', !onNewCampaignView && monitoring);
    }
    if (rpStatusText) rpStatusText.textContent = onNewCampaignView ? 'Idle' : (running ? 'Running' : (monitoring ? 'Monitoring' : 'Idle'));
    if (rpStatusSub) {
      if (onNewCampaignView) {
        rpStatusSub.textContent = 'No activity for this campaign';
      } else if (running) {
        rpStatusSub.textContent = `${mode} · ${__cockpit.pName || '—'} · ${today}/${total}`;
      } else if (monitoring) {
        if (__cockpit.monitoringCheckInProgress) {
          rpStatusSub.textContent = 'checking now…';
        } else {
          const now = Date.now();
          const next = __cockpit.nextCheckAt ? new Date(__cockpit.nextCheckAt) : null;
          const until = __cockpit.monitoringUntil ? new Date(__cockpit.monitoringUntil) : null;
          rpStatusSub.textContent = `next ${_cockpitHHMM(next)} · ends in ${until ? _cockpitFmtRemaining(until.getTime() - now) : '—'}`;
        }
      } else {
        rpStatusSub.textContent = 'No campaign running';
      }
    }

    // Right-pane activity feed — mirror the last ~10 log entries
    syncActivityFeed();

    // Auto-expand Live Status when running OR monitoring, auto-collapse when truly idle.
    if (statusSection && statusSection.classList.contains('collapsible')) {
      const active = running || monitoring;
      if (active && statusSection.classList.contains('collapsed')) {
        statusSection.classList.remove('collapsed');
      } else if (!active && wasRunning) {
        statusSection.classList.add('collapsed');
      }
    }
    wasRunning = running || monitoring;
  };
  setInterval(sync, 2000);
  sync();
}

// ─────────────────────────────────────────────────────────────────────────────
// Hero metrics
// ─────────────────────────────────────────────────────────────────────────────
function populateHeroMetrics(history) {
  if (!Array.isArray(history)) return;
  const now = Date.now();
  const DAY = 24 * 60 * 60 * 1000;
  const WEEK = 7 * DAY;

  const startOfTodayPH = (() => {
    // PH midnight = UTC 16:00 prior day
    const n = new Date();
    const phNow = new Date(n.getTime() + (8 * 60 * 60 * 1000) + (n.getTimezoneOffset() * 60 * 1000));
    phNow.setHours(0, 0, 0, 0);
    return phNow.getTime() - (8 * 60 * 60 * 1000) - (n.getTimezoneOffset() * 60 * 1000);
  })();

  let todaySuccess = 0, weekSuccess = 0, errors24h = 0;
  history.forEach((c) => {
    const t = new Date(c.startedAt || c.date || 0).getTime();
    if (isNaN(t)) return;
    const success = c.successCount != null ? c.successCount : (c.totalProcessed || 0);
    const errs = c.errorCount != null ? c.errorCount : 0;
    if (t >= startOfTodayPH) todaySuccess += success;
    if (now - t <= WEEK) weekSuccess += success;
    if (now - t <= DAY) errors24h += errs;
  });

  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = String(v); };
  setVal('hero-today', todaySuccess);
  setVal('hero-week', weekSuccess);
  setVal('hero-errors', errors24h);

  const errSub = document.getElementById('hero-errors-sub');
  if (errSub) errSub.textContent = errors24h === 0 ? 'No errors' : `${errors24h} across ${history.filter((c) => now - new Date(c.startedAt || c.date || 0).getTime() <= DAY).length} runs`;

  // Next schedule — pull from /api/schedules if available
  fetch('/api/schedules').then((r) => r.ok ? r.json() : []).then((schedules) => {
    // no hero slot for next schedule; keep for future or skip
  }).catch(() => {});
}

// ─────────────────────────────────────────────────────────────────────────────
// Right-pane — live activity feed (mirrors #log-panel)
// ─────────────────────────────────────────────────────────────────────────────
function syncActivityFeed() {
  const feed = document.getElementById('rp-feed-list');
  const src = document.getElementById('log-panel');
  if (!feed || !src) return;
  if (typeof isOnNewCampaignView === 'function' && isOnNewCampaignView()) {
    feed.innerHTML = '<div class="rp-feed-item"><span class="rp-feed-time">—</span><span class="rp-feed-text">No activity for this campaign</span></div>';
    return;
  }
  const entries = Array.from(src.querySelectorAll('.entry')).slice(-10).reverse();
  if (entries.length === 0 || (entries.length === 1 && /waiting to start/i.test(entries[0].textContent))) {
    feed.innerHTML = '<div class="rp-feed-item"><span class="rp-feed-time">—</span><span class="rp-feed-text">Waiting for campaign…</span></div>';
    return;
  }
  const now = new Date();
  const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  feed.innerHTML = entries.map((e) => {
    const txt = e.textContent.trim().replace(/^\[\d{1,2}:\d{2}(:\d{2})?\]\s*/, '');
    const m = e.textContent.match(/\[(\d{1,2}:\d{2}(?::\d{2})?)\]/);
    const t = m ? m[1].substring(0, 5) : timeStr;
    const cls = e.className.includes('success') ? 'success'
              : e.className.includes('error') ? 'error'
              : '';
    return `<div class="rp-feed-item"><span class="rp-feed-time">${escHtml(t)}</span><span class="rp-feed-text ${cls}">${escHtml(txt.substring(0, 80))}</span></div>`;
  }).join('');
}

// ─────────────────────────────────────────────────────────────────────────────
// Right-pane — next schedule widget
// ─────────────────────────────────────────────────────────────────────────────
function updateNextScheduleWidget(schedules) {
  const nameEl = document.getElementById('rp-next-schedule-name');
  const timeEl = document.getElementById('rp-next-schedule-time');
  if (!nameEl || !timeEl) return;

  const enabled = (schedules || []).filter((s) => s.enabled && s.cron);
  if (!enabled.length) {
    nameEl.textContent = 'None';
    timeEl.textContent = 'No upcoming runs';
    return;
  }

  // Compute next fire time for a 5-part cron (m h dom mon dow) in local time
  const nextForCron = (cron) => {
    const p = cron.split(' ');
    if (p.length !== 5) return null;
    const [mn, hr, , , dow] = p;
    const min = parseInt(mn, 10);
    const hour = parseInt(hr, 10);
    if (isNaN(min) || isNaN(hour)) return null;
    const days = dow === '*' ? [0, 1, 2, 3, 4, 5, 6] : dow.split(',').map((d) => parseInt(d, 10)).filter((x) => !isNaN(x));
    const now = new Date();
    for (let offset = 0; offset < 14; offset++) {
      const cand = new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset, hour, min, 0, 0);
      if (!days.includes(cand.getDay())) continue;
      if (cand.getTime() > now.getTime()) return cand;
    }
    return null;
  };

  let best = null;
  enabled.forEach((s) => {
    const t = nextForCron(s.cron);
    if (t && (!best || t < best.time)) best = { time: t, schedule: s };
  });

  if (!best) {
    nameEl.textContent = 'None';
    timeEl.textContent = 'No upcoming runs';
    return;
  }

  nameEl.textContent = best.schedule.name || 'Scheduled run';
  const now = new Date();
  const isToday = best.time.toDateString() === now.toDateString();
  const tomorrow = new Date(now); tomorrow.setDate(now.getDate() + 1);
  const isTomorrow = best.time.toDateString() === tomorrow.toDateString();
  const timeOfDay = best.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const prefix = isToday ? 'Today' : isTomorrow ? 'Tomorrow' : best.time.toLocaleDateString([], { weekday: 'short', day: 'numeric', month: 'short' });
  timeEl.textContent = `${prefix} · ${timeOfDay}`;
}

async function initUserChip() {
  const dateEl = document.getElementById('user-chip-date');
  if (dateEl) {
    const now = new Date();
    const opts = { day: 'numeric', month: 'short', year: 'numeric' };
    dateEl.textContent = now.toLocaleDateString('en-GB', opts);
  }

  const emailEl = document.getElementById('user-chip-email');
  if (emailEl) {
    try {
      const res = await fetch('/api/me');
      if (res.status === 401) { window.location.href = '/login.html'; return; }
      const data = await res.json();
      if (data.email) {
        emailEl.textContent = data.email;
        // Also default the identifier input to the logged-in email (unless
        // the operator explicitly saved a different value).
        const idInput = document.getElementById('my-identifier');
        if (idInput && !idInput.value) idInput.value = data.email;
      }
    } catch { /* */ }
  }
  updateGreeting();
}

// Greeting line in page header — "Good evening, Antonio" + date/time/city.
// Time-of-day bucket chooses morning/afternoon/evening/night; city pulled
// from the browser's IANA timezone.
function updateGreeting() {
  const greetEl = document.getElementById('greeting-wordmark');
  const subEl = document.getElementById('greeting-subtitle');
  if (!greetEl && !subEl) return;

  if (greetEl) {
    const emailEl = document.getElementById('user-chip-email');
    const email = (emailEl ? emailEl.textContent.trim() : '').toLowerCase();

    // Prefer the operator's real first name from column D of the State of
    // Operations sheet; fall back to the local part of the email only if SoO
    // isn't loaded yet or the email isn't listed there.
    let first = '';
    const sooEntry = sooData && sooData[email];
    if (sooEntry && sooEntry.firstName) {
      const raw = sooEntry.firstName.trim();
      first = raw.charAt(0).toUpperCase() + raw.slice(1);
    } else {
      const local = (email.split('@')[0] || '').trim();
      const firstRaw = local.split(/[._+-]/)[0] || 'there';
      first = firstRaw.charAt(0).toUpperCase() + firstRaw.slice(1).toLowerCase();
    }

    const h = new Date().getHours();
    const greet = h >= 5 && h < 12 ? 'Good morning'
      : h >= 12 && h < 17 ? 'Good afternoon'
      : h >= 17 && h < 22 ? 'Good evening'
      : 'Good night';
    greetEl.textContent = `${greet}, ${first}`;
  }

  if (subEl) {
    const now = new Date();
    const day = now.toLocaleDateString('en-US', { weekday: 'long' });
    const date = now.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
    const time = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false });
    let city = 'local';
    try {
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      if (tz && tz.includes('/')) city = tz.split('/').pop().replace(/_/g, ' ');
    } catch (_) {}
    subEl.textContent = `${day} · ${date} · ${time} ${city}`;
  }
}

// Refresh greeting every 30s so the time ticks without a reload.
setInterval(() => { try { updateGreeting(); } catch (_) {} }, 30_000);

// Dashboard scrape-queue strip: refresh on a modest cadence (the in-wizard scrape
// poll only runs in scrape view, so the strip needs its own tick). Skipped while
// the tab is hidden (renderDashScrapeStrip guards on document.hidden).
setInterval(() => { try { renderDashScrapeStrip(); } catch (_) {} }, 5000);
try { renderDashScrapeStrip(); } catch (_) {}

async function signOut() {
  try { await fetch('/api/auth/logout', { method: 'POST' }); } catch {}
  window.location.href = '/login.html';
}

// ─────────────────────────────────────────────────────────────────────────────
// Scheduled campaign notifier — 5-min heads-up + start ping
// ─────────────────────────────────────────────────────────────────────────────
const scheduleNotifiedKey = 'ortus-notified-fires';

function loadNotifiedFires() {
  try { return new Set(JSON.parse(localStorage.getItem(scheduleNotifiedKey) || '[]')); }
  catch { return new Set(); }
}

function saveNotifiedFires(set) {
  try {
    const arr = Array.from(set);
    // Prune entries older than 24h so the set stays small
    const cutoff = Date.now() - 24 * 60 * 60 * 1000;
    const kept = arr.filter((key) => {
      const parts = key.split(':');
      const ts = Number(parts[parts.length - 1]);
      return !isNaN(ts) && ts > cutoff;
    });
    localStorage.setItem(scheduleNotifiedKey, JSON.stringify(kept));
  } catch { /* */ }
}

function nextFireFromCron(cronExpr) {
  const p = (cronExpr || '').split(' ');
  if (p.length !== 5) return null;
  const [mn, hr, , , dow] = p;
  const min = parseInt(mn, 10);
  const hour = parseInt(hr, 10);
  if (isNaN(min) || isNaN(hour)) return null;
  const days = dow === '*' ? [0, 1, 2, 3, 4, 5, 6] : dow.split(',').map((d) => parseInt(d, 10)).filter((x) => !isNaN(x));
  const now = new Date();
  for (let offset = 0; offset < 14; offset++) {
    const cand = new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset, hour, min, 0, 0);
    if (!days.includes(cand.getDay())) continue;
    if (cand.getTime() > now.getTime()) return cand;
  }
  return null;
}

async function pollScheduleNotifications() {
  try {
    const res = await fetch('/api/schedules');
    const schedules = await res.json();
    if (!Array.isArray(schedules)) return;

    const notified = loadNotifiedFires();
    const now = Date.now();

    schedules.filter((s) => s.enabled && s.cron).forEach((s) => {
      const next = nextFireFromCron(s.cron);
      if (!next) return;
      const fireMs = next.getTime();
      const msUntil = fireMs - now;
      const timeStr = next.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      // 5-min heads-up (fire once when within the 4:30–5:30 window)
      if (msUntil > 4.5 * 60 * 1000 && msUntil <= 5.5 * 60 * 1000) {
        const key = `pre:${s.id}:${fireMs}`;
        if (!notified.has(key)) {
          notified.add(key);
          notify('Scheduled campaign starting soon', `${s.name} will start at ${timeStr} (in ~5 min).`);
        }
      }

      // Start ping (fire when within the -30s to +30s window)
      if (msUntil > -30 * 1000 && msUntil <= 30 * 1000) {
        const key = `start:${s.id}:${fireMs}`;
        if (!notified.has(key)) {
          notified.add(key);
          notify('Scheduled campaign started', `${s.name} is running now.`);
        }
      }
    });

    saveNotifiedFires(notified);
  } catch { /* */ }
}

function initScheduleNotifier() {
  // Check once at load, then every 30 seconds
  pollScheduleNotifications();
  setInterval(pollScheduleNotifications, 30 * 1000);
}

// Pull server-side desktop notifications (e.g. "about to launch connection
// check") and surface them as browser-push popups. Audience filtering is
// done server-side via req.user, so we just receive items meant for us.
let _lastDesktopNotifTs = (() => {
  try { return Number.parseInt(localStorage.getItem('ortus-last-notif-ts') || '0', 10) || 0; }
  catch { return 0; }
})();
async function pollServerDesktopNotifications() {
  try {
    const res = await fetch(`/api/notifications/recent?since=${_lastDesktopNotifTs}`);
    if (!res.ok) return;
    const data = await res.json();
    const items = Array.isArray(data?.items) ? data.items : [];
    for (const item of items) {
      notify(item.title, item.body);
    }
    if (items.length > 0) {
      _lastDesktopNotifTs = items[items.length - 1].ts;
      try { localStorage.setItem('ortus-last-notif-ts', String(_lastDesktopNotifTs)); } catch { /* */ }
    } else if (typeof data?.now === 'number' && data.now > _lastDesktopNotifTs) {
      _lastDesktopNotifTs = data.now;
      try { localStorage.setItem('ortus-last-notif-ts', String(_lastDesktopNotifTs)); } catch { /* */ }
    }
  } catch { /* */ }
}
async function loadNotificationPrefs() {
  try {
    const res = await fetch('/api/notification-prefs');
    if (!res.ok) return;
    const data = await res.json();
    const prefs = data?.prefs || {};
    const cb = document.getElementById('notif-pref-conn-check');
    if (cb) cb.checked = !!prefs.connectionCheckReminders;
    const rcb = document.getElementById('notif-pref-reply-alerts');
    if (rcb) rcb.checked = !!prefs.replyAlerts;
  } catch { /* */ }
}
async function onNotifPrefChange(key, value) {
  try {
    await fetch('/api/notification-prefs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ [key]: !!value }),
    });
  } catch { /* */ }
}
window.onNotifPrefChange = onNotifPrefChange;

// ── v2.113 — pre-send identity safeguard toggle ────────────────────────
// Sticky per-operator pref. ON (default) verifies each profile matches the
// sheet row before connecting; OFF connects straight to the sheet URL (the
// 404 dead-profile skip stays on regardless). Persisted via /api/operator-prefs
// and read by startCampaign() into campaign.identityGateEnabled.
function _renderIdentityGateState(on) {
  const st = document.getElementById('op-identity-gate-state');
  if (!st) return;
  st.textContent = on ? 'On' : 'Off';
  st.classList.toggle('ok', on);
  st.classList.toggle('bad', !on);
}
async function onIdentityGateChange(value) {
  _renderIdentityGateState(!!value);
  try {
    await fetch('/api/operator-prefs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ identityGate: !!value }),
    });
  } catch (err) {
    console.warn('[identity-gate] save failed:', err?.message || err);
  }
}
window.onIdentityGateChange = onIdentityGateChange;

// ── v2.58.x — Per-operator timezone ────────────────────────────────────
// Confirms on first launch after this update lands (skippable; re-prompts
// next launch). Saving stores the choice via /api/operator-prefs and the
// bot then sends `tz` on every Apps Script write so timestamps land in
// the launcher's local time.

function _detectLocalTz() {
  try { return Intl.DateTimeFormat().resolvedOptions().timeZone || ''; }
  catch { return ''; }
}

// Featured zones surfaced at the top of the dropdown so the three operator
// locations are one click away. Label is the city name the operator thinks
// in; value is the canonical IANA zone (Kosovo has no Europe/Pristina —
// Europe/Belgrade is the IANA-blessed zone for the region).
const _FEATURED_TZS = [
  { label: 'Rome',     value: 'Europe/Rome' },
  { label: 'Pristina', value: 'Europe/Belgrade' },
  { label: 'Manila',   value: 'Asia/Manila' },
];

// Sidebar label resolver: friendly city name for featured zones, raw IANA
// for everything else. Keeps the "Pristina" label consistent across modal
// and sidebar even though the persisted value is Europe/Belgrade.
function _tzDisplayLabel(tz) {
  if (!tz) return '—';
  const hit = _FEATURED_TZS.find(t => t.value === tz);
  return hit ? hit.label : tz;
}

function _populateTzSelect(selectedTz) {
  const sel = document.getElementById('op-tz-select');
  if (!sel) return;
  let zones = [];
  try {
    // Intl.supportedValuesOf — available in Chromium 111+. Electron 33
    // ships Chromium 130 so this is safe per package.json.
    zones = Intl.supportedValuesOf('timeZone') || [];
  } catch { zones = []; }
  if (!zones.length) zones = [selectedTz || 'UTC'];
  // Defensive: include the saved value even if the runtime doesn't list it.
  if (selectedTz && !zones.includes(selectedTz)) zones.push(selectedTz);

  const featuredValues = new Set(_FEATURED_TZS.map(t => t.value));
  const others = zones.filter(z => !featuredValues.has(z)).sort();

  const featuredHtml = _FEATURED_TZS.map(t =>
    `<option value="${t.value}"${t.value === selectedTz ? ' selected' : ''}>${t.label}</option>`
  ).join('');
  const otherHtml = others.map(tz =>
    `<option value="${tz}"${tz === selectedTz ? ' selected' : ''}>${tz}</option>`
  ).join('');

  sel.innerHTML =
    `<optgroup label="Operator locations">${featuredHtml}</optgroup>` +
    `<optgroup label="Other">${otherHtml}</optgroup>`;
}

function openOpTzModal() {
  const modal = document.getElementById('op-tz-modal');
  if (!modal) return;
  // Read the stored IANA value off the sidebar's data attribute (set by
  // loadOperatorPrefs / saveOpTzFromModal). textContent holds the friendly
  // label which isn't an IANA name for the featured zones.
  const stored = document.getElementById('op-tz-current')?.dataset?.tz || '';
  const preselected = stored || _detectLocalTz();
  _populateTzSelect(preselected);
  modal.classList.remove('hidden');
}
function closeOpTzModal() {
  document.getElementById('op-tz-modal')?.classList.add('hidden');
}
async function saveOpTzFromModal() {
  const sel = document.getElementById('op-tz-select');
  const tz = sel?.value || '';
  if (!tz) { closeOpTzModal(); return; }
  try {
    const res = await fetch('/api/operator-prefs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tz }),
    });
    if (res.ok) {
      const data = await res.json();
      const stored = data?.prefs?.tz || tz;
      const cur = document.getElementById('op-tz-current');
      if (cur) {
        cur.textContent = _tzDisplayLabel(stored);
        cur.dataset.tz = stored;
      }
    }
  } catch (err) {
    console.warn('[op-tz] save failed:', err?.message || err);
  }
  closeOpTzModal();
}

async function loadOperatorPrefs() {
  try {
    const res = await fetch('/api/operator-prefs');
    if (!res.ok) return;
    const data = await res.json();
    const tz = data?.prefs?.tz || '';
    const cur = document.getElementById('op-tz-current');
    if (cur) {
      cur.textContent = _tzDisplayLabel(tz);
      cur.dataset.tz = tz;
    }
    // v2.113.x: reflect the stored identity-safeguard choice (default OFF —
    // only ON when the operator explicitly turned it on).
    const _ig = document.getElementById('op-identity-gate');
    if (_ig) {
      const _on = data?.prefs?.identityGate === true;
      _ig.checked = _on;
      _renderIdentityGateState(_on);
    }
    // First-launch behavior: blank stored tz → show modal pre-filled with
    // the detected OS zone. Skip-link in the modal just dismisses; nothing
    // gets persisted, so the modal re-fires on next launch (user's choice).
    if (!tz) {
      _populateTzSelect(_detectLocalTz());
      document.getElementById('op-tz-modal')?.classList.remove('hidden');
    }
  } catch { /* silent — feature stays unconfigured until next launch */ }
}

window.openOpTzModal = openOpTzModal;
window.closeOpTzModal = closeOpTzModal;
window.saveOpTzFromModal = saveOpTzFromModal;

function initServerDesktopNotifier() {
  // Poll every 60s — the post-campaign scheduler ticks every 30 min, so a
  // minute of latency on a popup is well within the user's tolerance and
  // doesn't add meaningful network load.
  pollServerDesktopNotifications();
  setInterval(pollServerDesktopNotifications, 60 * 1000);
}

// ─────────────────────────────────────────────────────────────────────────────
// Init
// ─────────────────────────────────────────────────────────────────────────────
initTheme();
initUserChip();
applySavedEdits();
initMyIdentifier();
restoreCollapsedSections();
restoreLastMode();
loadProfiles();
// Defer the first onModeChange to a microtask so the ENTIRE module finishes
// evaluating first. onModeChange -> initFollowerGrowth touches module state
// (fgChips et al.) that's declared far below this bootstrap; calling it inline
// during evaluation throws a TDZ "Cannot access 'fgChips' before initialization"
// whenever the restored mode is follower_growth — which the silent catch in the
// FG block swallowed, leaving the picker permanently empty until you switched
// modes and back. The microtask runs after evaluation completes, so all state
// is initialized and every mode (incl. follower_growth) sets up correctly.
queueMicrotask(onModeChange);
pollStatus();
fetchTemplateList();
fetchHistory();
loadPersistedErrors();
loadPersistedWarnings();
initRunBarMirror();
initScrollSpy();
fetchSchedules();
updatePlaceholderTags();
updateCampaignSummary();
// Silent on-load check — only sets the flag, never pops an alert. The sidebar
// "Enable" button (which calls requestNotificationPermission) is where we ask
// for permission explicitly.
if ('Notification' in window && Notification.permission === 'granted') {
  notificationsEnabled = true;
}
initScheduleNotifier();
initServerDesktopNotifier();
loadNotificationPrefs();
loadOperatorPrefs();

// Open Profile toggle listener
document.getElementById('open-profile-msg')?.addEventListener('change', () => {
  onModeChange();
});

const _lastFocusedField = new WeakMap();
document.addEventListener('focusin', (e) => {
  const el = e.target;
  if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA')) return;
  const section = el.closest('.section');
  if (section) _lastFocusedField.set(section, el);
});

// v2.59.x — Chip click was silently failing when the operator switched
// modes: _lastFocusedField cached the previously-focused INPUT/TEXTAREA,
// which may now live in a hidden .tpl-section. We'd write the chip text
// into the invisible element and the operator saw nothing happen. Now we
// only honor the cached field if it's still rendered AND visible, else
// fall through to data-target.
function _isElementVisible(el) {
  if (!el || !el.isConnected) return false;
  // offsetParent is null for elements with display:none (or any ancestor
  // hidden the same way). Cheap visibility test that catches the .tpl-
  // section mode-swap case.
  return el.offsetParent !== null;
}
document.addEventListener('click', (e) => {
  const tag = e.target.closest('.placeholder-tags .tag');
  if (!tag) return;
  const container = tag.closest('.placeholder-tags');
  const section = container?.closest('.section');
  const targetId = container?.dataset.target;
  const fallback = targetId ? document.getElementById(targetId) : null;
  const cached = section ? _lastFocusedField.get(section) : null;
  const field = _isElementVisible(cached) ? cached : fallback;
  if (!field) return;
  const val = tag.dataset.val;
  if (typeof field.selectionStart === 'number') {
    const start = field.selectionStart;
    field.value = field.value.substring(0, start) + val + field.value.substring(field.selectionEnd);
    field.selectionStart = field.selectionEnd = start + val.length;
  } else {
    field.value += val;
  }
  field.focus();
});

// ─────────────────────────────────────────────────────────────────────────────
// Campaign presets — save/load the entire form state (mode, accounts, sheet,
// templates, rate, limits) under a user-chosen name. Backed by /api/presets.
// ─────────────────────────────────────────────────────────────────────────────
function collectCurrentConfig() {
  const getV = (id) => document.getElementById(id)?.value ?? '';
  const getN = (id, fallback) => {
    const n = parseInt(getV(id), 10);
    return isNaN(n) ? fallback : n;
  };
  return {
    mode: getV('campaign-mode') || 'connect_only',
    sheetUrl: getV('sheet-url').trim(),
    profileIds: [...selectedProfileIds],
    // v2.11.0: ratePerHour / batchesPerHour removed from saved presets. Old
    // presets that still carry these fields are silently ignored on load.
    dailyLimit: getN('daily-limit', 50),
    messageGap: getN('message-gap', 60),
    delayMin: getN('within-batch-min', 30),
    delayMax: getN('within-batch-max', 60),
    pauseOnThrottle: document.getElementById('pause-on-throttle')?.checked === true,
    messageOpenProfiles: !!document.getElementById('open-profile-msg')?.checked,
    addNote: localStorage.getItem('ortus-add-note') === '1',
    linkedinColumn: getV('linkedin-col-select'),
    // v2.58.x — IC-only sheet-mapping overrides (saved & restored across runs).
    senderColumn: getV('ic-sender-col-select'),
    allLeadsConnected: !!document.getElementById('ic-all-connected-toggle')?.checked,
    // v2.160.44: monitoring cadence / auto-checks / concurrency — applyPresetConfig
    // restores these from the top level, so capture them for a faithful round-trip
    // (previously dropped → Re-run/draft/save silently reset them to defaults).
    checkIntervalMinutes: getN('check-cadence-select', 60),
    autoChecksEnabled: document.getElementById('auto-checks-toggle')?.checked !== false,
    concurrency: document.getElementById('concurrency-toggle')?.checked ? getN('concurrency-count', 2) : 1,
    templates: {
      connectionNote: getV('tpl-note'),
      followUp1: getV('tpl-followup'),
      inmailSubject: getV('tpl-inmail-subject'),
      inmailBody: getV('tpl-inmail-body'),
      openProfileSubject: getV('tpl-op-subject'),
      openProfileBody: getV('tpl-op-body'),
      // v2.160.44: intro-flow (CC+IC / ICB / CC+DM) fields. applyPresetConfig
      // restores every one of these from templates, so a faithful save must
      // capture them — previously omitted, which is why the Primary Person name,
      // intro title/body, auto-accept + follow-up toggles and the CC+DM body were
      // silently lost on Save / draft / preset. Raw field values (mirrors how
      // applyPresetConfig writes them back unconditionally); fields hidden for the
      // current mode are simply empty.
      primaryName: getV('primary-person-name').trim(),
      primaryUrl: getV('primary-person-url').trim(),
      primaryIntroBody: getV('primary-intro-body'),
      introTitle: getV('intro-title'),
      autoAcceptPrimary: document.getElementById('auto-accept-toggle')?.checked === true,
      autoAcceptAllPending: document.getElementById('auto-accept-all-toggle')?.checked === true,
      followUpEnabled: document.getElementById('follow-up-toggle')?.checked === true,
      followUpBody: getV('follow-up-body'),
      followUpDelayMinutes: getN('follow-up-delay', 10),
      primarySource: (typeof readPrimarySource === 'function') ? readPrimarySource() : 'local-browser',
      primaryCheckTiming: getV('primary-timing-select') || 'immediately',
      ccDmBody: getV('tpl-cc-dm-body'),
    },
  };
}

function applyPresetConfig(config) {
  if (!config || typeof config !== 'object') return;
  const setV = (id, v) => { const el = document.getElementById(id); if (el && v != null) el.value = v; };

  // v2.11.17: legacy presets had `mode: 'message_only'` + a separate
  // `templates.introMode: true` flag. The Introduce Back mode replaces
  // that combo. Auto-migrate so old presets keep working: if the saved
  // config carries the old shape, swap to the new mode here. Templates
  // (incl. introName, introTitle) carry over unchanged.
  if (config.mode === 'message_only' && config.templates && config.templates.introMode) {
    config = { ...config, mode: 'introduce_back' };
  }

  // Mode — triggers the rest of the mode-dependent UI
  if (config.mode) {
    setV('campaign-mode', config.mode);
    if (typeof onModeChange === 'function') onModeChange();
  }
  setV('sheet-url', config.sheetUrl || '');
  // v2.113: setV sets .value programmatically, which does NOT fire the
  // input/blur listeners that drive the multi-tab picker. The one-shot
  // auto-trigger in _wireTabPicker only runs at page load, so re-opening a
  // saved campaign left the tab picker stale/hidden for multi-tab workbooks.
  // Re-run it here (it self-hides for single-tab sheets, so always safe).
  if (config.sheetUrl && typeof refreshSheetTabPicker === 'function') {
    Promise.resolve(refreshSheetTabPicker()).catch(() => {});
  }

  // v2.11.0: pacing knobs (ratePerHour, batchesPerHour) removed. Old presets
  // carrying these fields silently lose them on load — backend pacing is now
  // a fixed 6-min per-account turn floor + queue rotation.
  setV('daily-limit', config.dailyLimit ?? 50);
  setV('message-gap', config.messageGap ?? 60);
  setV('within-batch-min', config.delayMin ?? 30);
  setV('within-batch-max', config.delayMax ?? 60);
  // Task 4 (2026-06-19): restore pause-on-throttle toggle; default OFF when absent
  // (v2.119.18 — operator wants throttling protection opt-in, not opt-out).
  {
    const _pot = document.getElementById('pause-on-throttle');
    if (_pot) _pot.checked = config.pauseOnThrottle === true;
    if (typeof syncPauseOnThrottleHelp === 'function') syncPauseOnThrottleHelp();
  }
  if (typeof checkDelayDanger === 'function') checkDelayDanger();
  // Render the sheet preview, THEN restore the column mapping. previewSheet()
  // is the only thing that fetches the sheet HTML and builds the column-select
  // dropdowns (#linkedin-col-select / #ic-sender-col-select) — without it the
  // table is blank and the saved column picks land on elements that don't exist
  // yet (the old requestAnimationFrame defer raced the dropdowns and lost). The
  // sheet-url field was set by setV above, so previewSheet reads the right URL.
  if (config.sheetUrl && typeof previewSheet === 'function') {
    Promise.resolve(previewSheet()).then(() => {
      if (config.linkedinColumn) {
        const sel = document.getElementById('linkedin-col-select');
        if (sel) sel.value = config.linkedinColumn;
      }
      if (config.senderColumn) {
        const sel = document.getElementById('ic-sender-col-select');
        if (sel) sel.value = config.senderColumn;
      }
      if (config.allLeadsConnected) {
        const tog = document.getElementById('ic-all-connected-toggle');
        if (tog) tog.checked = true;
      }
      if (typeof updateCampaignSummary === 'function') updateCampaignSummary();
    }).catch(() => { /* preview failed (bad URL / offline) — fields stay as set */ });
  }

  const opCheck = document.getElementById('open-profile-msg');
  if (opCheck) opCheck.checked = !!config.messageOpenProfiles;

  if (typeof setAddNote === 'function') setAddNote(!!config.addNote);

  const t = config.templates || {};
  setV('tpl-note', t.connectionNote || '');
  setV('tpl-followup', t.followUp1 || '');
  setV('tpl-inmail-subject', t.inmailSubject || '');
  setV('tpl-inmail-body', t.inmailBody || '');
  setV('tpl-op-subject', t.openProfileSubject || '');
  setV('tpl-op-body', t.openProfileBody || '');

  // v2.14.x: CC+IC fields. These live inside config.templates as
  // primaryName / primaryUrl / primaryIntroBody / introTitle. Without
  // these restores, Re-run loses the primary person and the operator
  // has to retype everything (screenshot 2026-05-16).
  setV('primary-person-name', t.primaryName || '');
  setV('primary-person-url', t.primaryUrl || '');
  setV('primary-intro-body', t.primaryIntroBody || '');
  // ICB legacy migration: older Introduction Campaigns stored the primary only as
  // introName (the retired intro-name field). Seed the Primary Person name from it
  // when primaryName is absent so the migrated campaign shows the primary.
  if (!t.primaryName && t.introName) setV('primary-person-name', t.introName);
  if (t.introTitle) setV('intro-title', t.introTitle);

  // v2.91: restore CC+IC auto-accept + automated first follow-up. Without these
  // a Re-run / preset load drops the toggles back to defaults.
  if (document.getElementById('auto-accept-toggle')) document.getElementById('auto-accept-toggle').checked = !!t.autoAcceptPrimary;
  if (document.getElementById('auto-accept-all-toggle')) document.getElementById('auto-accept-all-toggle').checked = !!t.autoAcceptAllPending;
  if (document.getElementById('follow-up-toggle')) document.getElementById('follow-up-toggle').checked = !!t.followUpEnabled;
  setV('follow-up-body', t.followUpBody || '');
  if (t.followUpDelayMinutes) setV('follow-up-delay', t.followUpDelayMinutes);
  // v2.94.x: restore the shared primary source. A profileId → GoLogin source;
  // 'local-browser'/absent → local. refreshAutoAcceptGate() below re-renders.
  {
    const src = t.primarySource || 'local-browser';
    const isGo = !!src && src !== 'local-browser';
    const hidden = document.getElementById('primary-source-profile-id');
    if (hidden) hidden.value = isGo ? src : '';
    const localR = document.querySelector('input[name="primary-source"][value="local-browser"]');
    const goR = document.querySelector('input[name="primary-source"][value="gologin"]');
    if (localR) localR.checked = !isGo;
    if (goR) goR.checked = isGo;
    if (typeof togglePrimarySource === 'function') togglePrimarySource();
  }
  if (typeof toggleFollowUpFields === 'function') toggleFollowUpFields();
  if (typeof refreshAutoAcceptGate === 'function') refreshAutoAcceptGate();

  // v2.62: CC+DM post-acceptance body — symmetric with the primary-intro-body
  // restore above. Without it, Re-run dropped the DM body and relaunched a
  // CC+DM campaign with an empty ccDmBody → no auto-DMs ever fired. Persist to
  // localStorage too, since setV() doesn't trigger the field's oninput=
  // saveCcDmFields handler (so the value survives a reload / restoreCcDmState).
  setV('tpl-cc-dm-body', t.ccDmBody || '');
  try { if (typeof saveCcDmFields === 'function') saveCcDmFields(); } catch (_) {}

  // Restore the monitoring cadence on Re-run. The value is persisted to history
  // (settings.checkIntervalMinutes → spread onto config), but applyPresetConfig
  // never wrote it back into the dropdown, so re-runs silently reset to the
  // HTML default (60 = 1 hour) regardless of what the original run used. Applies
  // to every monitoring mode (CC+IC + CC+DM).
  if (config.checkIntervalMinutes) setV('check-cadence-select', String(config.checkIntervalMinutes));

  // v2.112: restore the automatic-checks toggle on Re-run (default on when absent).
  {
    const _ac = document.getElementById('auto-checks-toggle');
    if (_ac) _ac.checked = config.autoChecksEnabled !== false;
  }

  // v2.154.1 (Manifest round-trip fix, Task 1.3): restore the primary check-timing
  // select on Re-run/duplicate. Previously this was read at launch (templates
  // payload, primaryCheckTiming) and persisted to history, but never written back
  // into #primary-timing-select here — so a Re-run silently reset it to the HTML
  // default ("immediately") regardless of what the original run used. Now that the
  // Manifest surfaces this value in its first readback line, the gap is visible —
  // fix it the same way checkIntervalMinutes/autoChecksEnabled are restored above.
  setV('primary-timing-select', t.primaryCheckTiming || 'immediately');
  // v2.154.2 (Manifest, Task 1.3 review fix): render once here, after ALL
  // restore fields above (including primaryCheckTiming just above) are set —
  // moved from right after refreshAutoAcceptGate() so the readback doesn't
  // render before the timing value it displays has been restored.
  if (typeof renderManifest === 'function') renderManifest();

  // v2.14.x: concurrency restore. concurrency=1 means single-worker
  // (toggle off); >1 means parallel mode (toggle on + count set).
  const _conc = Number(config.concurrency || 1);
  const _concTog = document.getElementById('concurrency-toggle');
  const _concCnt = document.getElementById('concurrency-count');
  if (_concTog && _concCnt) {
    _concTog.checked = _conc > 1;
    _concCnt.value = String(_conc > 1 ? _conc : 2);
    _concCnt.disabled = !(_conc > 1);
    if (typeof alphaSyncConcurrency === 'function') alphaSyncConcurrency();
  }

  // Restore selected profiles. If profiles haven't loaded yet the selection
  // will be re-applied by renderProfiles once they arrive.
  if (Array.isArray(config.profileIds)) {
    selectedProfileIds = [...config.profileIds];
    if (typeof renderProfiles === 'function' && Array.isArray(allProfilesData)) {
      renderProfiles(allProfilesData);
    }
    if (typeof renderSelectedPanel === 'function') renderSelectedPanel();
    if (typeof updateChipCounts === 'function') updateChipCounts();
  }

  if (typeof updateCampaignSummary === 'function') updateCampaignSummary();
}

// Mode label shown as a tag in the popover (short form).
const MODE_TAG = {
  connect_only: 'CC',
  message_only: 'DM',
  inmail_only: 'InMail',
  open_profile_only: 'OP',
  check_status: 'Status',
};

function relativeTime(iso) {
  if (!iso) return '—';
  const t = new Date(iso).getTime();
  if (isNaN(t)) return '—';
  const diff = Math.max(0, Date.now() - t);
  const s = Math.floor(diff / 1000);
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

async function refreshPresetList() {
  const listEl = document.getElementById('preset-pop-list');
  const countEl = document.getElementById('preset-pill-count');
  const lastTagEl = document.getElementById('preset-pop-last-tag');
  if (!listEl) return;

  // Fetch saved presets + last-used in parallel
  const [presetsData, lastUsedData] = await Promise.all([
    fetch('/api/presets').then(r => r.ok ? r.json() : {}).catch(() => ({})),
    fetch('/api/presets/_last_used').then(r => r.ok ? r.json() : null).catch(() => null),
  ]);

  // Count pill
  const names = Object.keys(presetsData).sort((a, b) => a.localeCompare(b));
  if (countEl) countEl.textContent = String(names.length);

  // Last used row
  if (lastTagEl) {
    if (lastUsedData && lastUsedData.config) {
      const mode = MODE_TAG[lastUsedData.config.mode] || (lastUsedData.config.mode || '—');
      lastTagEl.textContent = `${relativeTime(lastUsedData.savedAt)} · ${mode}`;
    } else {
      lastTagEl.textContent = 'None yet';
    }
  }

  // Saved list
  listEl.innerHTML = '';
  if (names.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'preset-pop-empty';
    empty.textContent = 'No saved presets yet';
    listEl.appendChild(empty);
    return;
  }
  for (const name of names) {
    const meta = presetsData[name] || {};
    const row = document.createElement('div');
    row.className = 'preset-pop-item';

    const nameEl = document.createElement('span');
    nameEl.className = 'preset-pop-name';
    nameEl.textContent = name;

    const tag = document.createElement('span');
    tag.className = 'preset-pop-tag';
    tag.textContent = MODE_TAG[meta.mode] || (meta.mode || '');

    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'preset-pop-delete';
    del.textContent = '✕';
    del.title = 'Delete preset';
    del.addEventListener('click', (e) => { e.stopPropagation(); deletePreset(name); });

    const right = document.createElement('span');
    right.style.display = 'inline-flex';
    right.style.alignItems = 'center';
    right.style.gap = '10px';
    right.appendChild(tag);
    right.appendChild(del);

    row.appendChild(nameEl);
    row.appendChild(right);
    row.addEventListener('click', () => { loadPresetByName(name); closePresetPopover(); });
    listEl.appendChild(row);
  }
}

async function loadPresetByName(name) {
  window.__viewingActiveCampaign = false;
  if (!name) return;
  try {
    const res = await fetch(`/api/presets/${encodeURIComponent(name)}`);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      alert(err.error || `Could not load "${name}"`);
      return;
    }
    const entry = await res.json();
    applyPresetConfig(entry.config || {});
    if (typeof applyViewingActiveLock === 'function') applyViewingActiveLock();
  } catch (err) {
    alert(`Load failed: ${err.message}`);
  }
}

async function loadLastUsedPreset() {
  window.__viewingActiveCampaign = false;
  try {
    const res = await fetch('/api/presets/_last_used');
    if (res.status === 404) { alert('No previous campaign to restore yet.'); return; }
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      alert(err.error || 'Could not load last-used settings');
      return;
    }
    const entry = await res.json();
    applyPresetConfig(entry.config || {});
    if (typeof applyViewingActiveLock === 'function') applyViewingActiveLock();
  } catch (err) {
    alert(`Load failed: ${err.message}`);
  }
}

async function saveCurrentAsPreset() {
  // window.prompt() is a no-op in Electron — use the modal helper instead.
  const name = await promptModal({ label: 'Name this preset (e.g. vonnyii_op, vonnyii_cc):' });
  if (!name) return; // null = cancel / ESC / empty
  const trimmed = name; // promptModal already trims + nulls empty
  const config = collectCurrentConfig();
  try {
    const res = await fetch('/api/presets', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: trimmed, config }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      alert(err.error || 'Save failed');
      return;
    }
    await refreshPresetList();
  } catch (err) {
    alert(`Save failed: ${err.message}`);
  }
}

async function deletePreset(name) {
  if (!name) return;
  if (!confirm(`Delete preset "${name}"? This cannot be undone.`)) return;
  try {
    const res = await fetch(`/api/presets/${encodeURIComponent(name)}`, { method: 'DELETE' });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      alert(err.error || 'Delete failed');
      return;
    }
    await refreshPresetList();
  } catch (err) {
    alert(`Delete failed: ${err.message}`);
  }
}

// Snapshot the current config as "last used" (called automatically when a
// campaign is kicked off). Silent — errors are logged, not surfaced.
async function saveLastUsedPreset() {
  try {
    await fetch('/api/presets/_last_used', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ config: collectCurrentConfig() }),
    });
  } catch (err) {
    console.warn('[presets] last-used save failed:', err.message);
  }
}

// Popover open/close + outside-click to dismiss.
function togglePresetPopover() {
  const pop = document.getElementById('preset-popover');
  if (!pop) return;
  if (pop.hidden) openPresetPopover();
  else closePresetPopover();
}
function openPresetPopover() {
  const pop = document.getElementById('preset-popover');
  if (!pop) return;
  pop.hidden = false;
  // Refresh on every open so times + list stay current
  refreshPresetList();
}
function closePresetPopover() {
  const pop = document.getElementById('preset-popover');
  if (pop) pop.hidden = true;
}
document.addEventListener('click', (e) => {
  const pill = document.getElementById('preset-pill');
  if (!pill) return;
  if (!pill.contains(e.target)) closePresetPopover();
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') closePresetPopover();
});

document.addEventListener('DOMContentLoaded', refreshPresetList);

